INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hummbl-dev/hummbl-agent/co15-combinatorial-design', 'co15-combinatorial-design', 'hummbl-dev', 'hummbl-agent', 'community', 'co15-combinatorial-design hummbl-dev hummbl-agent community The co15-combinatorial-design skill applies a systematic approach to explore option combinations, ideal for assembling components and designing systems with clear interfaces. This skill benefits developers and AI agents seeking to find optimal configurations. CO15组合设计工具是一种系统的方法，用于探索选项组合，找到最优配置。它使用HUMMBL（高度有用的心智模型基础语言） CO15組み合わせ設計ツールは、最適な構成を見つけるためのオプションの組み合わせを体系的に探索するための方法です。HUMMBL（高度に有用なメンタルモデルベース言語）を使用します CO15 조합 설계 도구는 최적의 구성 찾기 위한 옵션 조합을 체계적으로 탐색하는 방법입니다. HUMMBL（고도로 유용한 정신 모델 기반 언어）을 사용합니다 El diseño combinatorio CO15 es una técnica para explorar sistemáticamente combinaciones de opciones y encontrar configuraciones óptimas en Agentes de IA con HUMMBL La conception combinatoire CO15 est une technique pour explorer systématiquement les combinaisons d''options et trouver des configurations optimales pour les outils d''IA avec HUMMBL Der kombinatorische Entwurf CO15 ist eine Technik, um systematisch Kombinationen von Optionen zu erkunden und optimale Konfigurationen in KI-Agents mit HUMMBL zu finden O CO15 Combinatorial Design é uma técnica para explorar combinações de opções e encontrar configurações ótimas. Ele é útil para montar componentes em um todo coerente e integrar múltiplas soluções em uma abordagem unificada CO15 Комбинаторный Дизайн - это техника для систематического исследования комбинаций опций и нахождения оптимальных конфигураций. Он полезен для сборки компонентов в целостную систему и интеграции нескольких решений в единую подход تصميم التوليف CO15 هو تقنية لاستكشاف مجموعات الخيارات وإيجاد التكوينات المثلى. وهو مفيد لتركيب المكونات في كيان متكامل وتكامل حلول متعددة في نهج موحد how to use co15-combinatorial-design co15-combinatorial-design alternative co15-combinatorial-design setup guide what is co15-combinatorial-design co15-combinatorial-design vs other design systems co15-combinatorial-design install for AI agents CO15组合设计 HUMMBL 系统探索 最优配置 组装组件 集成多个解决方案 AI工具 AIエージェント Applies the CO15 Combinatorial Design transformation to explore option combinations Systematically assembles components into a coherent whole Integrates multiple solutions into a unified approach Designs systems that depend on clear interfaces and seams Utilizes the HUMMBL language for agentic orchestration co15-combinatorial-design is a systematic approach to explore option combinations, enabling the discovery of optimal configurations through the application of combinatorial design principles.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NextSpark-js/nextspark/design-system', 'community', 'NextSpark-js', 'nextspark', 'NextSpark-js/nextspark', 'design-system', 0, 0, 62, '2026-03-06T17:36:38Z', '2026-03-08T02:16:07.986Z', '32919c8c25389cc0e5064854d786ae547bba36ca7addf97420b852eccec27763', '{"id":"NextSpark-js/nextspark/design-system","name":"design-system","description":{"en":"The design-system skill provides a complete Next.js SaaS boilerplate, enabling developers to analyze design tokens and map between mocks and NextSpark themes. It benefits Next.js developers and designers.","zh":"设计系统技能为Next.js SaaS项目提供了一致的UI解决方案，包括主题依赖和设计令牌分析","ja":"デザインシステムスキルは、Next.js SaaSプロジェクトに一貫したUIソリューションを提供します。テーマ依存とデザイントークンの分析を含みます","ko":"디자인 시스템 스킬은 Next.js SaaS 프로젝트에 일관된 UI 솔루션을 제공합니다. 테마 종속성 및 디자인 토큰 분석을 포함합니다","es":"El design-system es una herramienta para analizar tokens de diseño y mapear entre mocks y temas de NextSpark","fr":"Le design-system est un outil pour analyser les jetons de conception et mapper entre les mocks et les thèmes NextSpark","de":"Das design-system ist ein Werkzeug zur Analyse von Design-Tokens und zum Abbilden zwischen Mocks und NextSpark-Themen","pt":"O design system é uma ferramenta poderosa para criar interfaces de usuário consistentes em projetos Next.js. Aprenda a configurá-lo com nosso guia","ru":"Система дизайна - это мощный инструмент для создания единообразных интерфейсов пользователя в проектах Next.js. Узнайте, как ее настроить с помощью нашего руководства","ar":"نظام التصميم هو أداة قوية لإنشاء واجهات مستخدم متسقة في مشاريع Next.js. تعرف على كيفية إعدادها باستخدام دليلنا"},"seo":{"title":{"en":"design-system: Next.js SaaS Boilerplate Setup Guide | AI ...","zh":"设计系统集成指南 - Next.js SaaS样板","ja":"デザインシステム設定ガイド - Next.js SaaSボイラープレート","ko":"디자인 시스템 설정 가이드 - Next.js SaaS 보일러 플레이트","es":"Guía de configuración de design-system para Next.js","fr":"Guide de mise en place de design-system pour Next.js","de":"Einrichtungsleitfaden für design-system mit Next.js","pt":"Guia de Configuração do Design System para Next.js","ru":"Настройка ИИ Агентов: Руководство по Design System для Ne...","ar":"دليل إعداد نظام التصميم مع Next.js لtools الإصطناعي"},"description":{"en":"Unlock the full potential of Next.js with design-system. Learn how to analyze design tokens and map mocks to NextSpark themes. Get started now!","zh":"了解如何使用设计系统技能为Next.js SaaS项目创建一致的UI，包括主题依赖和设计令牌分析","ja":"Next.js SaaSプロジェクトに一貫したUIを作成するためのデザインシステムスキルの使用方法について学びます。テーマ依存とデザイントークンの分析を含みます","ko":"Next.js SaaS 프로젝트에 일관된 UI를 생성하기 위한 디자인 시스템 스킬의 사용 방법을 배웁니다. 테마 종속성 및 디자인 토큰 분석을 포함합니다","es":"Aprende a analizar tokens de diseño y a mapear entre mocks y temas de NextSpark con nuestro design-system","fr":"Découvrez comment analyser les jetons de conception et mapper entre les mocks et les thèmes NextSpark avec notre design-system","de":"Erfahren Sie, wie Sie Design-Tokens analysieren und zwischen Mocks und NextSpark-Themen mit unserem design-system abbilden","pt":"Aprenda a configurar o design system para o seu projeto Next.js com nosso guia passo a passo e melhore a experiência do usuário","ru":"Узнайте, как настроить систему дизайна для вашего проекта Next.js с помощью нашего пошагового руководства и улучшите пользовательский опыт с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد نظام التصميم لمشروعك Next.js باستخدام دليلنا خطوة بخطوة وطور تجربة المستخدم مع أدوات الإصطناعي"},"definition":{"en":"design-system is a Next.js SaaS boilerplate that provides a theme-dependent design system for analyzing design tokens and mapping between mocks and NextSpark themes.","zh":"设计系统是一种为Next.js SaaS项目创建一致的UI的方法，包括主题依赖和设计令牌分析","ja":"デザインシステムは、Next.js SaaSプロジェクトに一貫したUIを作成するための方法であり、テーマ依存とデザイントークンの分析を含みます","ko":"디자인 시스템은 Next.js SaaS 프로젝트에 일관된 UI를 생성하기 위한 방법으로, 테마 종속성 및 디자인 토큰 분석을 포함합니다","es":"Un design-system es un conjunto de patrones y tokens de diseño para crear interfaces de usuario coherentes","fr":"Un design-system est un ensemble de modèles et de jetons de conception pour créer des interfaces utilisateur cohérentes","de":"Ein Design-System ist ein Satz von Mustern und Design-Tokens zur Erstellung konsistenter Benutzeroberflächen","pt":"O design system é um conjunto de padrões e diretrizes para criar interfaces de usuário consistentes em projetos Next.js","ru":"Система дизайна - это набор стандартов и руководств для создания единообразных интерфейсов пользователя в проектах Next.js","ar":"نظام التصميم هو مجموعة من المعايير والإرشادات لإنشاء واجهات مستخدم متسقة في مشاريع Next.js"},"features":{"en":["Analyzes design tokens using grep and cat commands","Maps between mocks and NextSpark themes","Reads theme tokens from globals.css files","Determines active theme using NEXT_PUBLIC_ACTIVE_THEME env variable","Supports theme-dependent design system"],"zh":["主题依赖的设计系统","设计令牌分析","Next.js SaaS样板集成","globals.css主题令牌读取","NEXT_PUBLIC_ACTIVE_THEME环境变量支持"],"ja":["テーマ依存のデザインシステム","デザイントークンの分析","Next.js SaaSボイラープレートの統合","globals.cssのテーマトークンの読み取り","NEXT_PUBLIC_ACTIVE_THEME環境変数のサポート"],"ko":["테마 종속성 디자인 시스템","디자인 토큰 분석","Next.js SaaS 보일러 플레이트 통합","globals.css 테마 토큰 읽기","NEXT_PUBLIC_ACTIVE_THEME 환경 변수 지원"],"es":["Análisis de tokens de diseño","Mapeo entre mocks y temas de NextSpark","Integración con Next.js","Compatibilidad con múltiples temas","Acceso a valores de tema a través de globals.css"],"fr":["Analyse des jetons de conception","Mappage entre les mocks et les thèmes NextSpark","Intégration avec Next.js","Compatibilité avec plusieurs thèmes","Accès aux valeurs de thème via globals.css"],"de":["Analyse von Design-Tokens","Abbildung zwischen Mocks und NextSpark-Themen","Integration mit Next.js","Kompatibilität mit mehreren Themen","Zugriff auf Theme-Werte über globals.css"],"pt":["Análise de tokens de design","Mapeamento entre mocks e temas NextSpark","Integração com o arquivo globals.css","Compatibilidade com o comando grep para determinar o tema ativo","Leitura de tokens de tema com o comando cat"],"ru":["Анализ токенов дизайна","Сопоставление между макетами и темами NextSpark","Интеграция с файлом globals.css","Совместимость с командой grep для определения активной темы","Чтение токенов темы с помощью команды cat"],"ar":["تحليل رموز التصميم","التطابق بين النماذج وسمات NextSpark","التكامل مع ملف globals.css","التوافق مع أمر grep لتحديد السمات النشطة","قراءة رموز السمات باستخدام أمر cat"]},"keywords":{"en":["how to use design-system","design-system setup guide","Next.js SaaS boilerplate","design-system vs NextSpark","design-system install","what is design-system","design-system alternative","Next.js design tokens","design-system tutorial"],"zh":["设计系统","Next.js SaaS","主题依赖","设计令牌分析","globals.css","NEXT_PUBLIC_ACTIVE_THEME","AIエージェント","前端开发"],"ja":["デザインシステム","Next.js SaaS","テーマ依存","デザイントークンの分析","globals.css","NEXT_PUBLIC_ACTIVE_THEME","AIエージェント","フロントエンド開発"],"ko":["디자인 시스템","Next.js SaaS","테마 종속성","디자인 토큰 분석","globals.css","NEXT_PUBLIC_ACTIVE_THEME","AI 에이전트","프론트엔드 개발"],"es":["design-system","Next.js","tokens de diseño","mapeo de temas","desarrollo de interfaces de usuario","creación de temas personalizados","integración con NextSpark"],"fr":["design-system","Next.js","jetons de conception","mappage de thèmes","développement d''interfaces utilisateur","création de thèmes personnalisés","intégration avec NextSpark"],"de":["Design-System","Next.js","Design-Tokens","Themenabbildung","Entwicklung von Benutzeroberflächen","Erstellung von benutzerdefinierten Themen","Integration mit NextSpark"],"pt":["design system","next.js","saas boilerplate","tokens de design","temas nextspark","globals.css","grep","cat","configuração do design system"],"ru":["система дизайна","next.js","saas boilerplate","токены дизайна","темы nextspark","globals.css","grep","cat","настройка системы дизайна","ИИ Агенты"],"ar":["نظام التصميم","next.js","saas boilerplate","رموز التصميم","سمات nextspark","globals.css","grep","cat","إعداد نظام التصميم","أدوات الإصطناعي"]}},"owner":"NextSpark-js","repo":"nextspark","repoPath":"NextSpark-js/nextspark","stars":0,"forks":0,"updatedAt":"2026-03-06T17:36:38Z","topics":[],"category":"community","skillMd":{"name":"design-system","description":"|","version":"1.0.0","bodyPreview":"# Design System Skill\n\nPatterns for analyzing design tokens and mapping between mocks and NextSpark themes.\n\n## Fundamental Principle\n\n**THE DESIGN SYSTEM IS THEME-DEPENDENT.**\n\nAll values in this skill are EXAMPLES from the default theme.\nYou MUST read the actual theme''s `globals.css` to get real values.\n\n```bash\n# Determine active theme\ngrep \"NEXT_PUBLIC_ACTIVE_THEME\" .env .env.local\n\n# Read theme tokens\ncat contents/themes/{THEME}/styles/globals.css\n```\n\n## Theme Token Locations\n\n```\ncontents","body":"# Design System Skill\n\nPatterns for analyzing design tokens and mapping between mocks and NextSpark themes.\n\n## Fundamental Principle\n\n**THE DESIGN SYSTEM IS THEME-DEPENDENT.**\n\nAll values in this skill are EXAMPLES from the default theme.\nYou MUST read the actual theme''s `globals.css` to get real values.\n\n```bash\n# Determine active theme\ngrep \"NEXT_PUBLIC_ACTIVE_THEME\" .env .env.local\n\n# Read theme tokens\ncat contents/themes/{THEME}/styles/globals.css\n```\n\n## Theme Token Locations\n\n```\ncontents/themes/{THEME}/\n├── styles/\n│   ├── globals.css      # CSS variables (:root and .dark)\n│   └── components.css   # Component-specific styles\n├── config/\n│   └── theme.config.ts  # Theme metadata\n```\n\n## CSS Variable Structure\n\n### Light Mode (:root)\n\n```css\n:root {\n  /* Surface Colors */\n  --background: oklch(1 0 0);           /* Page background */\n  --foreground: oklch(0.145 0 0);       /* Primary text */\n  --card: oklch(1 0 0);                 /* Card surfaces */\n  --card-foreground: oklch(0.145 0 0);  /* Card text */\n  --popover: oklch(1 0 0);              /* Dropdowns */\n  --popover-foreground: oklch(0.145 0 0);\n\n  /* Interactive Colors */\n  --primary: oklch(0.205 0 0);          /* Primary actions */\n  --primary-foreground: oklch(0.985 0 0);\n  --secondary: oklch(0.97 0 0);         /* Secondary actions */\n  --secondary-foreground: oklch(0.205 0 0);\n  --accent: oklch(0.97 0 0);            /* Highlights */\n  --accent-foreground: oklch(0.205 0 0);\n\n  /* State Colors */\n  --muted: oklch(0.97 0 0);             /* Muted backgrounds */\n  --muted-foreground: oklch(0.556 0 0); /* Placeholder text */\n  --destructive: oklch(0.577 0.245 27); /* Error/danger */\n  --destructive-foreground: oklch(1 0 0);\n\n  /* Border & Input */\n  --border: oklch(0.922 0 0);\n  --input: oklch(0.922 0 0);\n  --ring: oklch(0.708 0 0);             /* Focus rings */\n\n  /* Radius */\n  --radius: 0.5rem;\n}\n```\n\n### Dark Mode (.dark)\n\n```css\n.dark {\n  --background: oklch(0.145 0 0);       /* Inverted */\n  --foreground: oklch(0.985 0 0);\n  --card: oklch(0.145 0 0);\n  --card-foreground: oklch(0.985 0 0);\n\n  --primary: oklch(0.922 0 0);          /* Adjusted for dark */\n  --primary-foreground: oklch(0.205 0 0);\n\n  --muted: oklch(0.269 0 0);\n  --muted-foreground: oklch(0.708 0 0);\n\n  --border: oklch(0.269 0 0);\n  --input: oklch(0.269 0 0);\n}\n```\n\n## Color Format Conversion\n\nMocks often use HEX/RGB, themes use OKLCH.\n\n### HEX to OKLCH Mapping\n\n| Mock (HEX) | Approximate OKLCH | Notes |\n|------------|-------------------|-------|\n| `#ffffff` | `oklch(1 0 0)` | Pure white |\n| `#000000` | `oklch(0 0 0)` | Pure black |\n| `#137fec` | `oklch(0.55 0.2 250)` | Blue primary |\n| `#101922` | `oklch(0.15 0.02 260)` | Dark background |\n| `#00d4ff` | `oklch(0.75 0.15 200)` | Cyan accent |\n\n### Similarity Calculation\n\nCompare colors by:\n1. **Lightness** (L) - Most important, weight 0.5\n2. **Chroma** (C) - Saturation, weight 0.3\n3. **Hue** (H) - Color angle, weight 0.2\n\n```\nsimilarity = 1 - (\n  0.5 * |L1 - L2| +\n  0.3 * |C1 - C2| / maxChroma +\n  0.2 * |H1 - H2| / 360\n)\n```\n\n## Token Categories\n\n### Background Tokens\n\n| Token | Tailwind Class | Usage |\n|-------|----------------|-------|\n| `--background` | `bg-background` | Page background |\n| `--card` | `bg-card` | Card surfaces |\n| `--popover` | `bg-popover` | Dropdowns, menus |\n| `--muted` | `bg-muted` | Subtle backgrounds |\n| `--accent` | `bg-accent` | Hover states |\n| `--primary` | `bg-primary` | Primary buttons |\n| `--secondary` | `bg-secondary` | Secondary buttons |\n| `--destructive` | `bg-destructive` | Error states |\n\n### Foreground Tokens\n\n| Token | Tailwind Class | Usage |\n|-------|----------------|-------|\n| `--foreground` | `text-foreground` | Primary text |\n| `--card-foreground` | `text-card-foreground` | Card text |\n| `--muted-foreground` | `text-muted-foreground` | Secondary text |\n| `--primary-foreground` | `text-primary-foreground` | On primary bg |\n| `--destructive-foreground` | `text-destructive-foreground` | On error bg |\n\n### Border Tokens\n\n| Token | Tailwind Class | Usage |\n|-------|----------------|-------|\n| `--border` | `border-border` | Default borders |\n| `--input` | `border-input` | Input borders |\n| `--ring` | `ring-ring` | Focus rings |\n\n## Mapping Process\n\n### Step 1: Extract Mock Tokens\n\nFrom Tailwind config or inline styles:\n```javascript\n// From mock''s tailwind.config\nconst mockTokens = {\n  colors: {\n    primary: ''#137fec'',\n    ''bg-dark'': ''#101922'',\n    accent: ''#00d4ff''\n  }\n}\n```\n\n### Step 2: Read Theme Tokens\n\n```bash\n# Extract all CSS variables\ngrep -E \"^\\s*--\" contents/themes/{theme}/styles/globals.css\n```\n\n### Step 3: Create Mapping\n\nFor each mock token:\n1. Check exact match (hex → hex)\n2. Check semantic match (primary → --primary)\n3. Calculate color similarity\n4. Flag gaps if no good match\n\n### Step 4: Document Gaps\n\n```json\n{\n  \"gaps\": [\n    {\n      \"mockValue\": \"#ff5722\",\n      \"mockUsage\": \"accent icons\",\n      \"closestToken\": \"--destructive\",\n      \"similarity\": 0.72,\n      \"recommendation\": \"USE_CLOSEST or ADD_TOKEN\"\n    }\n  ]\n}\n```\n\n## Output Format: ds-mapping.json\n\n```json\n{\n  \"theme\": \"default\",\n  \"themeGlobalsPath\": \"contents/themes/default/styles/globals.css\",\n  \"analyzedAt\": \"2025-01-09T12:00:00Z\",\n\n  \"themeTokens\": {\n    \"colors\": {\n      \"--background\": \"oklch(1 0 0)\",\n      \"--foreground\": \"oklch(0.145 0 0)\",\n      \"--primary\": \"oklch(0.205 0 0)\",\n      \"--secondary\": \"oklch(0.97 0 0)\",\n      \"--accent\": \"oklch(0.97 0 0)\",\n      \"--muted\": \"oklch(0.97 0 0)\",\n      \"--destructive\": \"oklch(0.577 0.245 27.325)\"\n    },\n    \"radius\": \"0.5rem\",\n    \"fonts\": {\n      \"sans\": \"var(--font-sans)\",\n      \"mono\": \"var(--font-mono)\"\n    }\n  },\n\n  \"mockTokens\": {\n    \"colors\": {\n      \"primary\": \"#137fec\",\n      \"background-dark\": \"#101922\",\n      \"accent\": \"#00d4ff\",\n      \"text-light\": \"#ffffff\",\n      \"text-muted\": \"#94a3b8\"\n    }\n  },\n\n  \"colorMapping\": [\n    {\n      \"id\": \"color-1\",\n      \"mockValue\": \"#137fec\",\n      \"mockName\": \"primary\",\n      \"mockUsage\": [\"buttons\", \"links\", \"focus rings\"],\n      \"themeToken\": \"--primary\",\n      \"themeValue\": \"oklch(0.205 0 0)\",\n      \"tailwindClass\": \"bg-primary text-primary-foreground\",\n      \"matchType\": \"semantic\",\n      \"similarity\": 0.65,\n      \"notes\": \"Theme primary is darker, mock is more vibrant blue\"\n    },\n    {\n      \"id\": \"color-2\",\n      \"mockValue\": \"#101922\",\n      \"mockName\": \"background-dark\",\n      \"mockUsage\": [\"hero background\", \"footer\"],\n      \"themeToken\": \"--background\",\n      \"themeValue\": \"oklch(0.145 0 0)\",\n      \"tailwindClass\": \"bg-background\",\n      \"matchType\": \"closest\",\n      \"similarity\": 0.88,\n      \"notes\": \"Use dark mode or bg-gray-900\"\n    }\n  ],\n\n  \"typographyMapping\": [\n    {\n      \"mockFont\": \"Inter\",\n      \"themeToken\": \"--font-sans\",\n      \"tailwindClass\": \"font-sans\",\n      \"matchType\": \"exact\"\n    }\n  ],\n\n  \"spacingMapping\": [\n    {\n      \"mockValue\": \"24px\",\n      \"tailwindClass\": \"p-6\",\n      \"matchType\": \"exact\"\n    }\n  ],\n\n  \"radiusMapping\": [\n    {\n      \"mockValue\": \"8px\",\n      \"themeToken\": \"--radius\",\n      \"themeValue\": \"0.5rem\",\n      \"tailwindClass\": \"rounded-lg\",\n      \"matchType\": \"exact\"\n    }\n  ],\n\n  \"gaps\": [\n    {\n      \"type\": \"color\",\n      \"mockValue\": \"#00d4ff\",\n      \"mockName\": \"accent\",\n      \"mockUsage\": [\"terminal prompt\", \"code highlights\"],\n      \"closestToken\": \"--primary\",\n      \"similarity\": 0.45,\n      \"recommendations\": [\n        {\n          \"option\": \"A\",\n          \"action\": \"Use --primary\",\n          \"impact\": \"Loses cyan accent, uses theme primary\"\n        },\n        {\n          \"option\": \"B\",\n          \"action\": \"Add --accent-cyan to theme\",\n          \"impact\": \"Requires theme modification\"\n        },\n        {\n          \"option\": \"C\",\n          \"action\": \"Use inline text-[#00d4ff]\",\n          \"impact\": \"Not recommended, breaks theming\"\n        }\n      ]\n    }\n  ],\n\n  \"summary\": {\n    \"totalMockTokens\": 12,\n    \"mapped\": 10,\n    \"gaps\": 2,\n    \"overallCompatibility\": 0.83,\n    \"recommendation\": \"PROCEED_WITH_GAPS\"\n  }\n}\n```\n\n## Output Format: block-plan.json (BLOCKS workflow only)\n\nFor the BLOCKS workflow, an additional output is generated to guide block development:\n\n```json\n{\n  \"mockPath\": \"mocks/\",\n  \"analyzedAt\": \"2026-01-12T12:00:00Z\",\n  \"workflow\": \"BLOCKS\",\n\n  \"existingBlocks\": [\n    {\n      \"name\": \"hero-simple\",\n      \"similarity\": 0.85,\n      \"matchReason\": \"Similar layout and components\"\n    },\n    {\n      \"name\": \"hero-centered\",\n      \"similarity\": 0.72,\n      \"matchReason\": \"Centered text, different background\"\n    }\n  ],\n\n  \"decision\": {\n    \"type\": \"new\" | \"variant\" | \"existing\",\n    \"blockName\": \"hero-terminal\",\n    \"baseBlock\": \"hero-simple\",\n    \"reasoning\": \"Requires custom terminal animation component not in existing blocks\"\n  },\n\n  \"blockSpec\": {\n    \"name\": \"hero-terminal\",\n    \"category\": \"hero\",\n    \"fields\": [\n      {\"name\": \"title\", \"type\": \"text\", \"required\": true},\n      {\"name\": \"subtitle\", \"type\": \"text\", \"required\": false},\n      {\"name\": \"primaryCta\", \"type\": \"link\", \"required\": true},\n      {\"name\": \"secondaryCta\", \"type\": \"link\", \"required\": false},\n      {\"name\": \"terminalContent\", \"type\": \"textarea\", \"required\": true}\n    ],\n    \"customComponents\": [\"TerminalAnimation\"],\n    \"estimatedComplexity\": \"medium\"\n  },\n\n  \"developmentNotes\": [\n    \"Terminal animation requires custom React component\",\n    \"Use existing Button component for CTAs\",\n    \"Background gradient matches theme --background token\"\n  ]\n}\n```\n\n### Decision Types\n\n| Type | When to Use | Action |\n|------|-------------|--------|\n| `existing` | Mock matches existing block 90%+ | Use existing block, no changes |\n| `variant` | Mock matches but needs minor additions | Extend existing block with new variant |\n| `new` | Mock requires significant new functionality | Create new block from scratch |\n\n## Workflow Integration\n\n| Workflow | ds-mapping.json | block-plan.json | When Generated |\n|----------|-----------------|-----------------|----------------|\n| **BLOCKS** | Yes | Yes | Phase 1 (Mock Analysis) |\n| **TASK** | Yes (if mock) | No | Phase 0.6 (if mock selected) |\n| **STORY** | Yes (if mock) | No | Phase 0.6 (if mock selected) |\n| **TWEAK** | No | No | N/A |\n\n## Reusability\n\nThis skill applies to ANY design-to-code conversion:\n- Landing pages (mocks → blocks)\n- Email templates (design → HTML)\n- PDF templates (design → React-PDF)\n- Marketing materials\n\n---\n\n## Generating globals.css from Mock (One-Time Setup)\n\nUse this section when initializing a theme from a design mock. This is typically a **one-time setup task** during theme creation.\n\n### When to Use\n\n- New theme creation from design mock\n- Theme initialization via `how-to:customize-theme` command\n- Converting a purchased template to NextSpark theme\n\n### Step 1: Convert HEX to OKLCH\n\nFor each color in mock''s Tailwind config, convert from HEX to OKLCH:\n\n```javascript\nfunction hexToOklch(hex) {\n  // Remove # if present\n  hex = hex.replace(''#'', '''')\n\n  // Parse RGB\n  const r = parseInt(hex.substr(0, 2), 16) / 255\n  const g = parseInt(hex.substr(2, 2), 16) / 255\n  const b = parseInt(hex.substr(4, 2), 16) / 255\n\n  // Convert to linear RGB\n  const rL = r <= 0.04045 ? r / 12.92 : Math.pow((r + 0.055) / 1.055, 2.4)\n  const gL = g <= 0.04045 ? g / 12.92 : Math.pow((g + 0.055) / 1.055, 2.4)\n  const bL = b <= 0.04045 ? b / 12.92 : Math.pow((b + 0.055) / 1.055, 2.4)\n\n  // Approximate OKLCH\n  const L = 0.4122 * rL + 0.5363 * gL + 0.0514 * bL\n  const lightness = Math.cbrt(L)\n\n  // Chroma and hue calculation\n  const max = Math.max(r, g, b)\n  const min = Math.min(r, g, b)\n  const chroma = (max - min) * 0.3\n\n  let hue = 0\n  if (max !== min) {\n    if (max === r) hue = 60 * (((g - b) / (max - min)) % 6)\n    else if (max === g) hue = 60 * ((b - r) / (max - min) + 2)\n    else hue = 60 * ((r - g) / (max - min) + 4)\n    if (hue < 0) hue += 360\n  }\n\n  return `oklch(${lightness.toFixed(4)} ${chroma.toFixed(4)} ${hue.toFixed(0)})`\n}\n```\n\n### Step 2: Generate Dark Mode (Invert Lightness)\n\nFor dark mode, invert the lightness (L) value:\n\n```javascript\nfunction invertLightnessOklch(oklchValue) {\n  // Parse oklch(L C H)\n  const match = oklchValue.match(/oklch\\(([0-9.]+)\\s+([0-9.]+)\\s+([0-9.]+)\\)/)\n  if (!match) return oklchValue\n\n  const L = parseFloat(match[1])\n  const C = parseFloat(match[2])\n  const H = parseFloat(match[3])\n\n  // Invert lightness: L'' = 1 - L\n  const invertedL = 1 - L\n\n  return `oklch(${invertedL.toFixed(4)} ${C.toFixed(4)} ${H.toFixed(0)})`\n}\n```\n\n**Which tokens to invert:**\n- `--background` ↔ `--foreground` (swap)\n- `--card` ↔ `--card-foreground` (swap)\n- `--popover` ↔ `--popover-foreground` (swap)\n- `--muted` → invert\n- `--muted-foreground` → invert\n- `--border`, `--input` → invert\n- `--primary`, `--secondary`, `--accent` → typically keep similar or slightly adjust\n\n### Step 3: globals.css Template\n\n```css\n/**\n * Theme: {theme}\n * Generated from mock: {mockPath}\n * Date: {timestamp}\n *\n * NOTE: Dark mode was auto-generated by inverting lightness values.\n * Review and adjust .dark {} section as needed for your brand.\n */\n\n:root {\n  /* Surface Colors */\n  --background: {oklch from mock};\n  --foreground: {oklch from mock};\n  --card: {oklch from mock or default};\n  --card-foreground: {oklch from mock or default};\n  --popover: {oklch from mock or default};\n  --popover-foreground: {oklch from mock or default};\n\n  /* Interactive Colors */\n  --primary: {oklch from mock};\n  --primary-foreground: {calculated contrast};\n  --secondary: {oklch from mock or default};\n  --secondary-foreground: {calculated contrast};\n  --accent: {oklch from mock or default};\n  --accent-foreground: {calculated contrast};\n\n  /* State Colors */\n  --muted: {oklch from mock or default};\n  --muted-foreground: {oklch from mock or default};\n  --destructive: oklch(0.577 0.245 27.325);\n  --destructive-foreground: oklch(1 0 0);\n\n  /* Border & Input */\n  --border: {oklch from mock or default};\n  --input: {oklch from mock or default};\n  --ring: {oklch from mock or default};\n\n  /* Chart Colors */\n  --chart-1: oklch(0.81 0.1 252);\n  --chart-2: oklch(0.62 0.19 260);\n  --chart-3: oklch(0.55 0.22 263);\n  --chart-4: oklch(0.49 0.22 264);\n  --chart-5: oklch(0.42 0.18 266);\n\n  /* Sidebar */\n  --sidebar: {based on background};\n  --sidebar-foreground: {based on foreground};\n  --sidebar-primary: {based on primary};\n  --sidebar-primary-foreground: {based on primary-foreground};\n  --sidebar-accent: {based on accent};\n  --sidebar-accent-foreground: {based on accent-foreground};\n  --sidebar-border: {based on border};\n  --sidebar-ring: {based on ring};\n\n  /* Typography */\n  --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, ''Helvetica Neue'', Arial, sans-serif;\n  --font-serif: ui-serif, Georgia, Cambria, \"Times New Roman\", Times, serif;\n  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;\n\n  /* Design Tokens */\n  --radius: 0.625rem;\n  --spacing: 0.25rem;\n\n  /* Shadows */\n  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);\n  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);\n  --shadow-sm: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);\n  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);\n  --shadow-md: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 2px 4px -1px hsl(0 0% 0% / 0.10);\n  --shadow-lg: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 4px 6px -1px hsl(0 0% 0% / 0.10);\n  --shadow-xl: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 8px 10px -1px hsl(0 0% 0% / 0.10);\n  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);\n}\n\n/* =============================================\n   DARK MODE (Auto-generated by inverting lightness)\n   Review and adjust as needed for your brand\n   ============================================= */\n\n.dark {\n  --background: {inverted};\n  --foreground: {inverted};\n  --card: {inverted};\n  --card-foreground: {inverted};\n  --popover: {inverted};\n  --popover-foreground: {inverted};\n  --primary: {adjusted for dark};\n  --primary-foreground: {adjusted for dark};\n  --secondary: {inverted};\n  --secondary-foreground: {inverted};\n  --muted: {inverted};\n  --muted-foreground: {inverted};\n  --accent: {inverted};\n  --accent-foreground: {inverted};\n  --destructive: oklch(0.704 0.191 22.216);\n  --destructive-foreground: oklch(0.985 0 0);\n  --border: {inverted};\n  --input: {inverted};\n  --ring: {inverted};\n  --sidebar: {inverted};\n  --sidebar-foreground: {inverted};\n  --sidebar-primary: {adjusted};\n  --sidebar-primary-foreground: {adjusted};\n  --sidebar-accent: {inverted};\n  --sidebar-accent-foreground: {inverted};\n  --sidebar-border: {inverted};\n  --sidebar-ring: {inverted};\n}\n\n/* =============================================\n   TAILWIND v4 THEME MAPPING\n   ============================================= */\n\n@theme inline {\n  --color-background: var(--background);\n  --color-foreground: var(--foreground);\n  --color-card: var(--card);\n  --color-card-foreground: var(--card-foreground);\n  --color-popover: var(--popover);\n  --color-popover-foreground: var(--popover-foreground);\n  --color-primary: var(--primary);\n  --color-primary-foreground: var(--primary-foreground);\n  --color-secondary: var(--secondary);\n  --color-secondary-foreground: var(--secondary-foreground);\n  --color-muted: var(--muted);\n  --color-muted-foreground: var(--muted-foreground);\n  --color-accent: var(--accent);\n  --color-accent-foreground: var(--accent-foreground);\n  --color-destructive: var(--destructive);\n  --color-destructive-foreground: var(--destructive-foreground);\n  --color-border: var(--border);\n  --color-input: var(--input);\n  --color-ring: var(--ring);\n  --color-chart-1: var(--chart-1);\n  --color-chart-2: var(--chart-2);\n  --color-chart-3: var(--chart-3);\n  --color-chart-4: var(--chart-4);\n  --color-chart-5: var(--chart-5);\n  --color-sidebar: var(--sidebar);\n  --color-sidebar-foreground: var(--sidebar-foreground);\n  --color-sidebar-primary: var(--sidebar-primary);\n  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);\n  --color-sidebar-accent: var(--sidebar-accent);\n  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);\n  --color-sidebar-border: var(--sidebar-border);\n  --color-sidebar-ring: var(--sidebar-ring);\n\n  --font-sans: var(--font-sans);\n  --font-mono: var(--font-mono);\n  --font-serif: var(--font-serif);\n\n  --radius-sm: calc(var(--radius) - 4px);\n  --radius-md: calc(var(--radius) - 2px);\n  --radius-lg: var(--radius);\n  --radius-xl: calc(var(--radius) + 4px);\n\n  --shadow-2xs: var(--shadow-2xs);\n  --shadow-xs: var(--shadow-xs);\n  --shadow-sm: var(--shadow-sm);\n  --shadow: var(--shadow);\n  --shadow-md: var(--shadow-md);\n  --shadow-lg: var(--shadow-lg);\n  --shadow-xl: var(--shadow-xl);\n  --shadow-2xl: var(--shadow-2xl);\n}\n```\n\n### Generation Checklist\n\n- [ ] All mock colors converted to OKLCH\n- [ ] Dark mode generated with inverted lightness\n- [ ] Complete @theme inline section included\n- [ ] Font stacks included\n- [ ] Shadow definitions included\n- [ ] Clear comment indicating dark mode was auto-generated\n- [ ] Complete, valid CSS output\n\n---\n\n## Related Skills\n\n- `tailwind-theming` - Detailed Tailwind CSS patterns\n- `shadcn-theming` - shadcn/ui theme customization\n- `mock-analysis` - For extracting mock tokens\n- `page-builder-blocks` - For applying tokens to blocks\n- `block-decision-matrix` - For block new/variant/existing decisions\n"},"lastSynced":"2026-03-08T02:16:07.986Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing comprehensive Next.js SaaS boilerplate analysis and design token mapping.","zh":"非常适合需要全面Next.js SaaS样板分析和设计令牌映射的前端代理。","ja":"Next.jsの包括的なSaaSボイラープレート分析とデザイントークンのマッピングが必要なフロントエンドエージェントに最適。","ko":"전체적인 Next.js SaaS 보일러플레이트 분석 및 디자인 토큰 매핑이 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para agentes Frontend que necesitan un análisis y diseño de plantilla SaaS Next.js completo y un mapeo de tokens de diseño.","fr":"Parfait pour les agents Frontend qui ont besoin d''une analyse et d''une conception de modèle SaaS Next.js complète et d''un mappage de jetons de conception.","de":"Perfekt für Frontend-Agents, die eine umfassende Analyse und Gestaltung von Next.js SaaS-Boilerplate und Design-Token-Mapping benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de uma análise e design de boilerplate Next.js SaaS abrangente e mapeamento de tokens de design.","ru":"Идеально подходит для агентов Frontend, которым требуется комплексный анализ и проектирование шаблона Next.js SaaS, а также сопоставление токенов дизайна.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى تحليل وتصميم قوالب Next.js SaaS الشاملة وتحديد رموز التصميم."},"recommendation":{"en":"Empowers agents to analyze design tokens and map between mocks and NextSpark themes, utilizing Next.js and globals.css for theme-dependent design systems, and facilitating theme token analysis via grep and cat commands.","zh":"赋予代理分析设计令牌并在模拟和NextSpark主题之间映射的能力，利用Next.js和globals.css实现主题依赖的设计系统，并通过grep和cat命令实现主题令牌分析。","ja":"デザイントークンの分析とモックとNextSparkテーマ間のマッピングを可能にし、Next.jsとglobals.cssを使用してテーマ依存のデザインシステムを実現し、grepとcatコマンドを使用してテーマトークンの分析を容易にします。","ko":"에이전트가 디자인 토큰을 분석하고 모크와 NextSpark 테마 간 매핑을 수행할 수 있도록 하며, Next.js와 globals.css를 사용하여 테마 종속 디자인 시스템을 구현하고 grep 및 cat 명령을 사용하여 테마 토큰 분석을 용이하게 합니다.","es":"Habilita a los agentes a analizar tokens de diseño y mapear entre mocks y temas NextSpark, utilizando Next.js y globals.css para sistemas de diseño dependientes de temas, y facilitando el análisis de tokens de tema mediante comandos grep y cat.","fr":"Permet aux agents d''analyser les jetons de conception et de mapper entre les mocks et les thèmes NextSpark, en utilisant Next.js et globals.css pour les systèmes de conception dépendants de thèmes, et en facilitant l''analyse des jetons de thème via les commandes grep et cat.","de":"Ermächtigt Agenten, Design-Tokens zu analysieren und zwischen Mocks und NextSpark-Themen zu kartieren, indem Next.js und globals.css für themenabhängige Designs verwendet werden, und erleichtert die Analyse von Thema-Tokens über grep- und cat-Befehle.","pt":"Habilita os agentes a analisar os tokens de design e mapear entre mocks e temas NextSpark, utilizando Next.js e globals.css para sistemas de design dependentes de tema, e facilitando a análise de tokens de tema via comandos grep e cat.","ru":"Позволяет агентам анализировать токены дизайна и сопоставлять их между макетами и темами NextSpark, используя Next.js и globals.css для темо-зависимых систем дизайна, и упрощая анализ токенов темы с помощью команд grep и cat.","ar":"يسمح للعميل بتحليل رموز التصميم وربطها بين النماذج وسمات NextSpark، باستخدام Next.js وglobals.css لنظام التصميم التابع للسمة، ويسهم في تحليل رموز السمات من خلال أوامر grep وcat."},"useCases":{"en":["Analyzing design tokens for consistent UI implementation","Mapping mocks to NextSpark themes for streamlined design workflows","Debugging theme-dependent issues using globals.css"],"zh":["一致的UI实现的设计令牌分析","将模拟映射到NextSpark主题以简化设计工作流程","使用globals.css调试主题依赖问题"],"ja":["一貫したUI実装のためのデザイントークンの分析","モックをNextSparkテーマにマッピングしてデザインワークフローを合理化する","globals.cssを使用してテーマ依存の問題をデバッグする"],"ko":["일관된 UI 구현을 위한 디자인 토큰 분석","모크를 NextSpark 테마에 매핑하여 디자인 워크플ロー简化","globals.css를 사용하여 테마 종속 이슈 디버깅"],"es":["Análisis de tokens de diseño para una implementación de IU coherente","Asignación de mocks a temas NextSpark para flujos de diseño optimizados","Depuración de problemas dependientes de temas mediante globals.css"],"fr":["Analyse de jetons de conception pour une mise en œuvre d''IU cohérente","Mappage de mocks à des thèmes NextSpark pour des flux de conception optimisés","Débogage de problèmes dépendants de thèmes à l''aide de globals.css"],"de":["Analyse von Design-Tokens für eine konsistente UI-Implementierung","Zuordnung von Mocks zu NextSpark-Themen für optimierte Design-Workflows","Fehlerbehebung von themenabhängigen Problemen mithilfe von globals.css"],"pt":["Analisar tokens de design para implementação de UI consistente","Mapear mocks para temas NextSpark para fluxos de design otimizados","Depurar problemas dependentes de tema usando globals.css"],"ru":["Анализ токенов дизайна для последовательной реализации интерфейса пользователя","Сопоставление макетов с темами NextSpark для оптимизированных потоков дизайна","Отладка темо-зависимых проблем с помощью globals.css"],"ar":["تحليل رموز التصميم لتطبيق واجهة مستخدم متسقة","ربط النماذج بسمات NextSpark لتدفقات تصميم مجدية","تصحيح الأخطاء التابعة للسمة باستخدام globals.css"]},"limitations":{"en":["Requires Next.js environment","Theme-dependent design system","Needs access to globals.css and .env files"],"zh":["需要Next.js环境","主题依赖的设计系统","需要访问globals.css和.env文件"],"ja":["Next.js環境が必要","テーマ依存のデザインシステム","globals.cssと.envファイルへのアクセスが必要"],"ko":["Next.js 환경 필요","테마 종속 디자인 시스템","globals.css 및 .env 파일에 대한 액세스 필요"],"es":["Requiere entorno Next.js","Sistema de diseño dependiente de temas","Necesita acceso a archivos globals.css y .env"],"fr":["Nécessite un environnement Next.js","Système de conception dépendant de thèmes","Nécessite l''accès aux fichiers globals.css et .env"],"de":["Benötigt Next.js-Umgebung","Themenabhängiges Designsystem","Benötigt Zugriff auf globals.css- und .env-Dateien"],"pt":["Requer ambiente Next.js","Sistema de design dependente de tema","Necessita acesso a arquivos globals.css e .env"],"ru":["Требуется среда Next.js","Система дизайна, зависящая от темы","Требуется доступ к файлам globals.css и .env"],"ar":["يتطلب بيئة Next.js","نظام التصميم التابع للسمة","يحتاج إلى الوصول إلى ملفات globals.css و .env"]},"version":4},"contentHash":"32919c8c25389cc0e5064854d786ae547bba36ca7addf97420b852eccec27763","qualityScore":62}');
