INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ic-facet/gestion-programas-asignatura/jira-epic', 'jira-epic', 'ic-facet', 'gestion-programas-asignatura', 'community', 'jira-epic ic-facet gestion-programas-asignatura community Jira Epic是一个项目管理工具，使用AI技术提高团队协作和项目管理效率 Jira Epicはプロジェクト管理ツールで、AI技術を使用してチームコラボレーションとプロジェクト管理の効率を向上させます Jira Epic은 프로젝트 관리 도구로, AI 기술을 사용하여 팀 협업과 프로젝트 관리 효율을 향상 시킵니다 Jira Epic es un sistema de gestión de programas para la Facultad de Ciencias Exactas y Tecnología que utiliza inteligencia artificial para optimizar procesos Jira Epic est un système de gestion de programmes pour la Faculté des Sciences Exactes et de Technologie qui utilise l''intelligence artificielle pour optimiser les processus Jira Epic ist ein Programmmanagement-System für die Fakultät für Exacte Wissenschaften und Technologie, das künstliche Intelligenz nutzt, um Prozesse zu optimieren O jira-epic é um sistema de gestão de programas de assignatura para a Facultad de Ciencias Exactas y Tecnologia jira-epic - система управления программами для Факультета Exactas y Tecnologia جيرا-إيبك هو نظام لإدارة برامج المساقات للكلية التكنولوجية Sistema de Gestión de Programas de Asignatura para la Facultad de Ciencias Exactas y Tecnología de la Universidad Nacional de Tucumán Jira Epic教程 AIエージェント是什么 项目管理工具比较 Jira Epic安装 Jira Epic设置指南 如何使用Jira Epic Jira Epic替代品 Sistema de Gestión de Programas de Asignatura para la Facultad de Ciencias Exactas y Tecnología de la Universidad Nacional de Tucumán');
