INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nsyout/overseer/overseer-plan', 'overseer-plan', 'nsyout', 'overseer', 'community', 'overseer-plan nsyout overseer community overseer-plan是AI智能代理的任务编排工具，支持SQLite和native git集成，帮助开发者高效管理任务 overseer-planはAIエージェントのタスクオーケストレーションツールで、SQLiteとネイティブgit統合をサポートします overseer-plan은 AI 에이전트의 작업 오케스트레이션 도구로, SQLite 및 네이티브 git 통합을 지원하여 개발자의 작업을 효율적으로 관리합니다 Overseer-plan es una herramienta de orquestación de tareas para Agentes de IA que utiliza MCP y ofrece integración nativa con git y SQLite Overseer-plan est un outil d''orchestration de tâches pour les Agents d''IA qui utilise MCP et propose une intégration native avec git et SQLite Overseer-plan ist ein Werkzeug für die Aufgabenorchestrierung von KI-Agenten, das MCP verwendet und native Git- und SQLite-Integration bietet O overseer-plan é uma ferramenta de orquestração de tarefas para ferramentas de IA, com integração nativa com git e SQLite Overseer-plan - это инструмент для управления задачами для ИИ Агентов, с родной интеграцией с git и SQLite overseer-plan هو أداة لتوجيه المهام للوكلاء الذكيين، مع التكامل الأصلي مع git و SQLite Task orchestration for AI agents via MCP. SQLite-backed, native git integration (gix). AI智能代理 任务编排工具 SQLite数据库 native git集成 如何使用overseer-plan overseer-plan教程 AI代理工具比较 overseer-plan安装 overseer-plan设置指南 Task orchestration for AI agents via MCP. SQLite-backed, native git integration (gix).');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ashleytower/claude-code-workflow/schema-markup', 'community', 'ashleytower', 'claude-code-workflow', 'ashleytower/claude-code-workflow', 'schema-markup', 0, 0, 62, '2026-02-28T01:32:52.468Z', '2026-02-28T01:42:57.754Z', '1dc73cfc3de7466e84301bfc11a71b8a1a90b47aa842e2e181b61f34a187b2b3', '{"id":"ashleytower/claude-code-workflow/schema-markup","name":"schema-markup","description":{"zh":"Schema Markup是一个专为Claude代码设计的AI代理工作流自动化系统，通过多代理协调和学习机制实现高效的代码生成，并内置防幻觉强制执行功能确保输出质量。","ja":"Schema MarkupはClaudeコード向けのAIエージェントワークフロー自動化システムで、マルチエージェント連携と学習メカニズムにより効率的なコード生成を実現し、出力品質を保証する防幻觉機能を内蔵しています。","ko":"Schema Markup는 Claude 코드를 위한 AI 에이전트 워크플로우 자동화 시스템으로, 다중 에이전트 조정 및 학습 메커니즘을 통해 효율적인 코드 생성을 구현하고 출력 품질을 보장하는 방환각 기능을 내장했습니다.","es":"Schema Markup es un sistema de automatización de flujos de trabajo para Claude Code que combina coordinación multiagente, aprendizaje y prevención de alucinaciones","fr":"Schema Markup est un système d''automatisation de flux de travail pour Claude Code qui combine coordination multi-agent, apprentissage et prévention des hallucinations","de":"Schema Markup ist ein Workflow-Automatisierungssystem für Claude Code, das Multiagentenkoordination, Lernfunktion und Halluzinationsvermeidung kombiniert","pt":"O schema-markup é um sistema de automação de fluxo de trabalho para Claude Code com recursos avançados de coordenação multi-agente e aprendizado","ru":"Schema-markup - это комплексная система автоматизации рабочих процессов для Claude Code с функциями координации нескольких агентов и обучения","ar":"schema-markup هو نظام آلي شامل لتحسين تدفق العمل في Claude Code مع ميزات متقدمة لتنسيق متعدد الوكلاء وتعلم","en":"A comprehensive workflow automation system for Claude Code featuring multi-agent coordination, learning system, and anti-hallucination enforcement"},"seo":{"title":{"zh":"Schema Markup AI代理：多代理协调与防幻觉系统","ja":"Schema Markup AIエージェント：マルチエージェント連携と学習システム","ko":"Schema Markup AI 에이전트: 다중 에이전트 조정 및 학습 시스템","es":"Herramientas de AI: Schema Markup para Claude Code","fr":"Outils IA: Schema Markup pour Claude Code","de":"KI-Tools: Schema Markup für Claude Code","pt":"Ferramentas de IA: schema-markup para Claude Code","ru":"ИИ Агенты: schema-markup для Claude Code","ar":"أدوات الذكاء الاصطناعي: schema-markup ل Claude Code","en":"schema-markup"},"description":{"zh":"Schema Markup是一个专为Claude代码设计的AI代理工作流自动化系统，通过多代理协调和学习机制实现高效的代码生成，并内置防幻觉强制执行功能确保输出质量。","ja":"Schema MarkupはClaudeコード向けのAIエージェントワークフロー自動化システムで、マルチエージェント連携と学習メカニズムにより効率的なコード生成を実現し、出力品質を保証する防幻觉機能を内蔵しています。","ko":"Schema Markup는 Claude 코드를 위한 AI 에이전트 워크플로우 자동화 시스템으로, 다중 에이전트 조정 및 학습 메커니즘을 통해 효율적인 코드 생성을 구현하고 출력 품질을 보장하는 방환각 기능을 내장했습니다.","es":"Schema Markup es un sistema de automatización de flujos de trabajo para Claude Code que combina coordinación multiagente, aprendizaje y prevención de alucina...","fr":"Schema Markup est un système d''automatisation de flux de travail pour Claude Code qui combine coordination multi-agent, apprentissage et prévention des hallu...","de":"Schema Markup ist ein Workflow-Automatisierungssystem für Claude Code, das Multiagentenkoordination, Lernfunktion und Halluzinationsvermeidung kombiniert","pt":"O schema-markup é um sistema de automação de fluxo de trabalho para Claude Code com recursos avançados de coordenação multi-agente e aprendizado","ru":"Schema-markup - это комплексная система автоматизации рабочих процессов для Claude Code с функциями координации нескольких агентов и обучения","ar":"schema-markup هو نظام آلي شامل لتحسين تدفق العمل في Claude Code مع ميزات متقدمة لتنسيق متعدد الوكلاء وتعلم","en":"A comprehensive workflow automation system for Claude Code featuring multi-agent coordination, learning system, and anti-hallucination enforcement"},"definition":{"en":"A comprehensive workflow automation system for Claude Code featuring multi-agent coordination, learning system, and anti-hallucination enforcement"},"features":{"zh":["多代理协调工作流系统","持续学习与自适应机制","防幻觉强制执行技术","Claude代码专用优化","自动化代码生成管道","开发者友好的API接口"],"ja":["マルチエージェント連携ワークフローシステム","継続的学習と適応メカニズム","防幻觉強制実行技術","Claudeコード専用最適化","自動コード生成パイプライン","開発者向けAPIインターフェース"],"ko":["다중 에이전트 조정 워크플로우 시스템","지속적 학습 및 적응 메커니즘","방환각 강제 실행 기술","Claude 코드 전용 최적화","자동 코드 생성 파이프라인","개발자 친화적 API 인터페이스"],"es":["Coordinación multiagente","Sistema de aprendizaje","Prevención de alucinaciones","Automatización de flujos de trabajo","Integración con Claude Code"],"fr":["Coordination multi-agent","Système d''apprentissage","Prévention des hallucinations","Automatisation des flux de travail","Intégration avec Claude Code"],"de":["Multiagentenkoordination","Lernfunktion","Halluzinationsvermeidung","Workflow-Automatisierung","Integration mit Claude Code"],"pt":["Coordenação multi-agente","Sistema de aprendizado","Enforcement anti-hallucination","Automação de fluxo de trabalho","Integração com Claude Code"],"ru":["Координация нескольких агентов","Система обучения","Принудительное предотвращение зомбирования","Автоматизация рабочих процессов","Интеграция с Claude Code"],"ar":["تنسيق متعدد الوكلاء","نظام تعلم","تطبيق منع الوهم","آلية تحسين تدفق العمل","التكامل مع Claude Code"]},"keywords":{"zh":["AI代理工作流","Schema Markup安装指南","多代理协调系统","Claude代码自动化","防幻觉AI工具","how to use Schema Markup","AI代理开发工具","代码生成自动化"],"ja":["AIエージェントワークフロー","Schema Markupインストールガイド","マルチエージェント連携システム","Claudeコード自動化","防幻觉AIツール","how to use Schema Markup","AIエージェント開発ツール","コード生成自動化"],"ko":["AI 에이전트 워크플로우","Schema Markup 설치 가이드","다중 에이전트 조정 시스템","Claude 코드 자동화","방환각 AI 도구","how to use Schema Markup","AI 에이전트 개발 도구","코드 생성 자동화"],"es":["cómo usar Schema Markup","qué es Schema Markup","alternativas a Schema Markup","Schema Markup vs Claude Code","instalación de Schema Markup","guía de configuración de Schema Markup"],"fr":["comment utiliser Schema Markup","qu''est-ce que Schema Markup","alternatives à Schema Markup","Schema Markup vs Claude Code","installation de Schema Markup","guide de configuration de Schema Markup"],"de":["wie man Schema Markup verwendet","was ist Schema Markup","Alternativen zu Schema Markup","Schema Markup vs Claude Code","Installation von Schema Markup","Konfigurationsanleitung für Schema Markup"],"pt":["como usar schema-markup","o que é schema-markup","alternativa para Claude Code","schema-markup vs outros agentes","instalar schema-markup","guia de configuração do schema-markup"],"ru":["как использовать schema-markup","что такое schema-markup","альтернатива для Claude Code","schema-markup vs другие агенты","установить schema-markup","руководство по настройке schema-markup"],"ar":["كيفية استخدام schema-markup","ما هو schema-markup","بديل ل Claude Code","schema-markup مقابل وكلاء آخرين","تثبيت schema-markup","دليل إعداد schema-markup"]}},"owner":"ashleytower","repo":"claude-code-workflow","repoPath":"ashleytower/claude-code-workflow","stars":0,"forks":0,"updatedAt":"2026-02-28T01:32:52.468Z","topics":[],"category":"community","skillMd":{"name":"schema-markup","description":"When the user wants to add, fix, or optimize schema markup and structured data on their site. Also use when the user mentions schema markup, structured data, JSON-LD, rich snippets, schema.org, FAQ schema, product schema, review schema, or breadcrumb schema. For broader SEO issues, see seo-audit.","version":"1.0.0","bodyPreview":"# Schema Markup\n\nYou are an expert in structured data and schema markup. Your goal is to implement schema.org markup that helps search engines understand content and enables rich results in search.\n\n## Initial Assessment\n\n**Check for product marketing context first:**\nIf `.claude/product-marketing-context.md` exists, read it before asking questions. Use that context and only ask for information not already covered or specific to this task.\n\nBefore implementing schema, understand:\n\n1. **Page Type","body":"# Schema Markup\n\nYou are an expert in structured data and schema markup. Your goal is to implement schema.org markup that helps search engines understand content and enables rich results in search.\n\n## Initial Assessment\n\n**Check for product marketing context first:**\nIf `.claude/product-marketing-context.md` exists, read it before asking questions. Use that context and only ask for information not already covered or specific to this task.\n\nBefore implementing schema, understand:\n\n1. **Page Type** - What kind of page? What''s the primary content? What rich results are possible?\n\n2. **Current State** - Any existing schema? Errors in implementation? Which rich results already appearing?\n\n3. **Goals** - Which rich results are you targeting? What''s the business value?\n\n---\n\n## Core Principles\n\n### 1. Accuracy First\n- Schema must accurately represent page content\n- Don''t markup content that doesn''t exist\n- Keep updated when content changes\n\n### 2. Use JSON-LD\n- Google recommends JSON-LD format\n- Easier to implement and maintain\n- Place in `<head>` or end of `<body>`\n\n### 3. Follow Google''s Guidelines\n- Only use markup Google supports\n- Avoid spam tactics\n- Review eligibility requirements\n\n### 4. Validate Everything\n- Test before deploying\n- Monitor Search Console\n- Fix errors promptly\n\n---\n\n## Common Schema Types\n\n| Type | Use For | Required Properties |\n|------|---------|-------------------|\n| Organization | Company homepage/about | name, url |\n| WebSite | Homepage (search box) | name, url |\n| Article | Blog posts, news | headline, image, datePublished, author |\n| Product | Product pages | name, image, offers |\n| SoftwareApplication | SaaS/app pages | name, offers |\n| FAQPage | FAQ content | mainEntity (Q&A array) |\n| HowTo | Tutorials | name, step |\n| BreadcrumbList | Any page with breadcrumbs | itemListElement |\n| LocalBusiness | Local business pages | name, address |\n| Event | Events, webinars | name, startDate, location |\n\n**For complete JSON-LD examples**: See [references/schema-examples.md](references/schema-examples.md)\n\n---\n\n## Quick Reference\n\n### Organization (Company Page)\nRequired: name, url\nRecommended: logo, sameAs (social profiles), contactPoint\n\n### Article/BlogPosting\nRequired: headline, image, datePublished, author\nRecommended: dateModified, publisher, description\n\n### Product\nRequired: name, image, offers (price + availability)\nRecommended: sku, brand, aggregateRating, review\n\n### FAQPage\nRequired: mainEntity (array of Question/Answer pairs)\n\n### BreadcrumbList\nRequired: itemListElement (array with position, name, item)\n\n---\n\n## Multiple Schema Types\n\nYou can combine multiple schema types on one page using `@graph`:\n\n```json\n{\n  \"@context\": \"https://schema.org\",\n  \"@graph\": [\n    { \"@type\": \"Organization\", ... },\n    { \"@type\": \"WebSite\", ... },\n    { \"@type\": \"BreadcrumbList\", ... }\n  ]\n}\n```\n\n---\n\n## Validation and Testing\n\n### Tools\n- **Google Rich Results Test**: https://search.google.com/test/rich-results\n- **Schema.org Validator**: https://validator.schema.org/\n- **Search Console**: Enhancements reports\n\n### Common Errors\n\n**Missing required properties** - Check Google''s documentation for required fields\n\n**Invalid values** - Dates must be ISO 8601, URLs fully qualified, enumerations exact\n\n**Mismatch with page content** - Schema doesn''t match visible content\n\n---\n\n## Implementation\n\n### Static Sites\n- Add JSON-LD directly in HTML template\n- Use includes/partials for reusable schema\n\n### Dynamic Sites (React, Next.js)\n- Component that renders schema\n- Server-side rendered for SEO\n- Serialize data to JSON-LD\n\n### CMS / WordPress\n- Plugins (Yoast, Rank Math, Schema Pro)\n- Theme modifications\n- Custom fields to structured data\n\n---\n\n## Output Format\n\n### Schema Implementation\n```json\n// Full JSON-LD code block\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"...\",\n  // Complete markup\n}\n```\n\n### Testing Checklist\n- [ ] Validates in Rich Results Test\n- [ ] No errors or warnings\n- [ ] Matches page content\n- [ ] All required properties included\n\n---\n\n## Task-Specific Questions\n\n1. What type of page is this?\n2. What rich results are you hoping to achieve?\n3. What data is available to populate the schema?\n4. Is there existing schema on the page?\n5. What''s your tech stack?\n\n---\n\n## Related Skills\n\n- **seo-audit**: For overall SEO including schema review\n- **programmatic-seo**: For templated schema at scale\n"},"lastSynced":"2026-02-28T01:42:57.754Z","agentAnalysis":{"suitability":{"en":"Perfect for SEO-focused AI Agents needing structured data implementation for rich search results.","zh":"非常适合需要结构化数据实现以获得丰富搜索结果的SEO关注的AI代理。","ja":"SEOに焦点を当てた構造化データの実装が必要なAIエージェントに最適です。","ko":"豊富한 검색 결과를 얻기 위한 구조화된 데이터 구현이 필요한 SEO 중심의 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de inteligencia artificial enfocados en SEO que necesitan implementación de datos estructurados para resultados de búsqueda ricos.","fr":"Parfait pour les agents d''intelligence artificielle axés sur le SEO nécessitant une mise en œuvre de données structurées pour des résultats de recherche riches.","de":"Perfekt für SEO-fokussierte KI-Agents, die eine Implementierung von strukturierten Daten für reiche Suchergebnisse benötigen.","pt":"Perfeito para Agentes de IA com foco em SEO que necessitam de implementação de dados estruturados para resultados de busca ricos.","ru":"Идеально для агентов ИИ, ориентированных на SEO, требующих реализации структурированных данных для насыщенных результатов поиска.","ar":"مثالي لعمليات الويب الذكية التي تركز على تحسين محركات البحث وتحتاج إلى تنفيذ بيانات منظمة للحصول على نتائج بحث غنية."},"recommendation":{"en":"Empowers agents to generate schema.org markup for enhanced search engine understanding, enabling rich results and improved content discoverability using JSON-LD and microdata protocols.","zh":"赋予代理生成schema.org标记以增强搜索引擎的理解，从而实现丰富的结果和改进的内容发现，使用JSON-LD和microdata协议。","ja":"エージェントにschema.orgマークアップを生成する能力を与え、JSON-LDおよびmicrodataプロトコルを使用して検索エンジンの理解を強化し、リッチな結果とコンテンツの検出を改善します。","ko":"에이전트가 schema.org 마크업을 생성하여 검색 엔진의 이해를 향상시키고 JSON-LD 및 microdata 프로토콜을 사용하여 풍부한 결과와 콘텐츠 발견을 개선합니다.","es":"Habilita a los agentes a generar marcado schema.org para una mejor comprensión del motor de búsqueda, lo que permite resultados ricos y una mejor capacidad de descubrimiento de contenido utilizando los protocolos JSON-LD y microdata.","fr":"Permet aux agents de générer une balise schema.org pour une meilleure compréhension du moteur de recherche, permettant ainsi des résultats riches et une meilleure découverte de contenu en utilisant les protocoles JSON-LD et microdata.","de":"Ermächtigt Agenten, schema.org-Markup zu generieren, um das Verständnis der Suchmaschine zu verbessern, wodurch reiche Ergebnisse und eine verbesserte Inhaltsentdeckung mithilfe der JSON-LD- und Microdata-Protokolle ermöglicht werden.","pt":"Habilita os agentes a gerar marcação schema.org para uma compreensão aprimorada do mecanismo de busca, permitindo resultados ricos e uma melhor descoberta de conteúdo usando os protocolos JSON-LD e microdata.","ru":"Наделяет агентов возможностью генерировать маркировку schema.org для улучшенного понимания поисковыми системами, что позволяет получать насыщенные результаты и улучшать обнаруживаемость контента с помощью протоколов JSON-LD и microdata.","ar":"تمكين الوكلاء من إنشاء تعليمات schema.org لتحسين فهم محركات البحث، مما يسمح بالحصول على نتائج غنية وتحسين اكتشاف المحتوى باستخدام بروتوكولات JSON-LD وميكروداتا."},"useCases":{"en":["Implementing schema markup for product pages","Generating JSON-LD scripts for event calendars","Validating schema.org vocabulary for local business listings"],"zh":["为产品页面实现schema标记","为事件日历生成JSON-LD脚本","验证本地商业列表的schema.org词汇"],"ja":["製品ページのschemaマークアップを実装する","イベントカレンダーのJSON-LDスクリプトを生成する","ローカルビジネスリストのschema.org語彙を検証する"],"ko":["제품 페이지를 위한 schema 마크업 구현","이벤트 달력의 JSON-LD 스크립트 생성","로컬 비즈니스 목록의 schema.org 어휘 검