INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ashleytower/claude-code-workflow/schema-markup', 'schema-markup', 'ashleytower', 'claude-code-workflow', 'community', 'schema-markup ashleytower claude-code-workflow community Schema Markup是一个专为Claude代码设计的AI代理工作流自动化系统，通过多代理协调和学习机制实现高效的代码生成，并内置防幻觉强制执行功能确保输出质量。 Schema MarkupはClaudeコード向けのAIエージェントワークフロー自動化システムで、マルチエージェント連携と学習メカニズムにより効率的なコード生成を実現し、出力品質を保証する防幻觉機能を内蔵しています。 Schema Markup는 Claude 코드를 위한 AI 에이전트 워크플로우 자동화 시스템으로, 다중 에이전트 조정 및 학습 메커니즘을 통해 효율적인 코드 생성을 구현하고 출력 품질을 보장하는 방환각 기능을 내장했습니다. Schema Markup es un sistema de automatización de flujos de trabajo para Claude Code que combina coordinación multiagente, aprendizaje y prevención de alucinaciones Schema Markup est un système d''automatisation de flux de travail pour Claude Code qui combine coordination multi-agent, apprentissage et prévention des hallucinations Schema Markup ist ein Workflow-Automatisierungssystem für Claude Code, das Multiagentenkoordination, Lernfunktion und Halluzinationsvermeidung kombiniert O schema-markup é um sistema de automação de fluxo de trabalho para Claude Code com recursos avançados de coordenação multi-agente e aprendizado Schema-markup - это комплексная система автоматизации рабочих процессов для Claude Code с функциями координации нескольких агентов и обучения schema-markup هو نظام آلي شامل لتحسين تدفق العمل في Claude Code مع ميزات متقدمة لتنسيق متعدد الوكلاء وتعلم A comprehensive workflow automation system for Claude Code featuring multi-agent coordination, learning system, and anti-hallucination enforcement AI代理工作流 Schema Markup安装指南 多代理协调系统 Claude代码自动化 防幻觉AI工具 how to use Schema Markup AI代理开发工具 代码生成自动化 A comprehensive workflow automation system for Claude Code featuring multi-agent coordination, learning system, and anti-hallucination enforcement');
