INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('open-circle/formisch/repo-website-api-review', 'repo-website-api-review', 'open-circle', 'formisch', 'community', 'repo-website-api-review open-circle formisch community The repo-website-api-review skill provides a systematic approach to reviewing API documentation routes for accuracy and consistency, benefiting developers and API maintainers. It ensures that API documentation matches the source code, including function signatures, types, and JSDoc descriptions. repo-website-api-review 是一个用于审查 API 文档的工具，确保准确性和一致性。它提供了一种系统化的方法来比较源代码和文档 repo-website-api-review は API ドキュメントをレビューするためのツールで、正確性と一貫性を確保します。ソースコードとドキュメントを比較するための体系的な方法を提供します repo-website-api-review는 API 문서를 검토하여 정확성 및 일관성을 보장하는 도구입니다. 소스 코드와 문서를 비교하기 위한 체계적인 방법을 제공합니다 repo-website-api-review es una habilidad que proporciona un enfoque sistemático para revisar la documentación de API, comparando el código fuente y verificando la consistencia de las firmas de las funciones y los tipos. repo-website-api-review est une compétence qui offre une approche systématique pour réviser la documentation d''API, en comparant le code source et en vérifiant la cohérence des signatures de fonctions et des types. repo-website-api-review ist eine Fähigkeit, die einen systematischen Ansatz für die Überprüfung der API-Dokumentation bietet, indem sie den Quellcode vergleicht und die Konsistenz der FunktionsSignaturen und -typen überprüft. O repo-website-api-review é uma ferramenta para revisar a documentação da API de forma sistemática, verificando a precisão e consistência dos endpoints e parâmetros ИИ Агент repo-website-api-review предназначен для проверки документации API, обеспечивающей точность и последовательность маршрутов и параметров يتمثل repo-website-api-review في أداة لاستعراض وثائق واجهة برمجة التطبيقات بطرق منهجية، حيث يتم التحقق من الدقة والاتساق للنقاط النهائية والمعاملات how to use repo-website-api-review repo-website-api-review setup guide API documentation review best practices repo-website-api-review alternative repo-website-api-review vs API documentation tools repo-website-api-review install what is repo-website-api-review repo-website-api-review tutorial API review process with repo-website-api-review API 文档审查 repo-website-api-review AIエージェント API 文档比较 函数签名验证 类型检查 JSDoc 描述验证 Compares API documentation with source code for accuracy Verifies function signatures, including generics and parameters Checks JSDoc descriptions for consistency Reviews properties.ts for generic constants Ensures type safety, including return types and parameter types repo-website-api-review is a skill that provides a modular and type-safe approach to reviewing API documentation, ensuring accuracy and consistency with the source code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('piomin/course-spring-microservices/webapp-testing', 'community', 'piomin', 'course-spring-microservices', 'piomin/course-spring-microservices', 'webapp-testing', 156, 67, 61, '2026-03-03T15:52:19Z', '2026-03-06T06:29:40.061Z', '31e301853c09c350e8a55e8e078a1f6e5873f3cdda6cd05a46ddd3d1f0ab6c61', '{"id":"piomin/course-spring-microservices/webapp-testing","name":"webapp-testing","description":{"en":"The webapp-testing skill enables developers to test frontend functionality in a real browser, verify UI behavior, and debug web application issues using Playwright automation.","zh":"Web应用程序测试AIエージェント提供了自动化测试和调试Web应用的功能，支持Playwright和Spring Boot","ja":"WebアプリケーションテストAIエージェントは、PlaywrightとSpring Bootを使用したWebアプリケーションの自動テストとデバッグを提供します","ko":"웹애플리케이션 테스트 AI 도구는 Playwright와 Spring Boot를 사용하여 웹 애플리케이션의 자동 테스트와 디버깅을 제공합니다","es":"webapp-testing es una habilidad que permite probar y depurar aplicaciones web locales con Playwright automation","fr":"webapp-testing est une compétence qui permet de tester et de déboguer des applications web locales avec Playwright automation","de":"webapp-testing ist eine Fähigkeit, die das Testen und Debuggen lokaler Webanwendungen mit Playwright-Automatisierung ermöglicht","pt":"O webapp-testing é uma habilidade que permite testar e depurar aplicações web locais usando automação Playwright","ru":"ИИ Агент webapp-testing предназначен для комплексного тестирования и отладки локальных веб-приложений с помощью автоматизации Playwright","ar":"أداة اختبار التطبيقات الإلكترونية هي مهارة تمكن من اختبار وتحسين التطبيقات الإلكترونية المحلية باستخدام أتمتة Playwright"},"seo":{"title":{"en":"webapp-testing: Comprehensive Testing Setup Guide | AI Ag...","zh":"Web应用程序测试Setup Guide - 使用Playwright自动化","ja":"Webアプリケーションテストのベストプラクティス - Playwright自動化","ko":"웹애플리케이션 테스트 설정 가이드 - Playwright 자동화","es":"Guía de confi