INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('piomin/course-spring-microservices/webapp-testing', 'webapp-testing', 'piomin', 'course-spring-microservices', 'community', 'webapp-testing piomin course-spring-microservices community circuit-breaker consul eureka microservices openfeign rate-limiting redis resilience4j spring-boot spring-boot-actuator spring-cloud spring-cloud-config spring-cloud-gateway spring-cloud-loadbalancer spring-cloud-netflix vault webclient The webapp-testing skill enables developers to test frontend functionality in a real browser, verify UI behavior, and debug web application issues using Playwright automation. Web应用程序测试AIエージェント提供了自动化测试和调试Web应用的功能，支持Playwright和Spring Boot WebアプリケーションテストAIエージェントは、PlaywrightとSpring Bootを使用したWebアプリケーションの自動テストとデバッグを提供します 웹애플리케이션 테스트 AI 도구는 Playwright와 Spring Boot를 사용하여 웹 애플리케이션의 자동 테스트와 디버깅을 제공합니다 webapp-testing es una habilidad que permite probar y depurar aplicaciones web locales con Playwright automation webapp-testing est une compétence qui permet de tester et de déboguer des applications web locales avec Playwright automation webapp-testing ist eine Fähigkeit, die das Testen und Debuggen lokaler Webanwendungen mit Playwright-Automatisierung ermöglicht O webapp-testing é uma habilidade que permite testar e depurar aplicações web locais usando automação Playwright ИИ Агент webapp-testing предназначен для комплексного тестирования и отладки локальных веб-приложений с помощью автоматизации Playwright أداة اختبار التطبيقات الإلكترونية هي مهارة تمكن من اختبار وتحسين التطبيقات الإلكترونية المحلية باستخدام أتمتة Playwright how to use webapp-testing with Spring Boot webapp-testing vs Selenium webapp-testing setup guide for Playwright what is webapp-testing in microservices webapp-testing alternative to Cypress webapp-testing install with Spring Cloud webapp-testing tutorial for beginners webapp-testing best practices with Redis webapp-testing and Spring Cloud Loadbalancer webapp-testing with Vault for security Web应用程序测试 Playwright自动化 Spring Boot Spring Cloud UI测试 自动化测试 Web应用程序调试 AIエージェント Test frontend functionality in a real browser using Playwright Verify UI behavior and interactions with Spring Boot and Spring Cloud Debug web application issues using Spring Cloud Config and Spring Cloud Gateway Capture screenshots for documentation or debugging with Playwright Inspect browser console logs for issues with Spring Boot Actuator Validate form submissions and user flows with OpenFeign and Resilience4j webapp-testing is a skill that enables comprehensive testing and debugging of local web applications using Playwright automation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sherdotsh/sher/sher-deploy', 'community', 'sherdotsh', 'sher', 'sherdotsh/sher', 'sher-deploy', 140, 5, 61, '2026-02-28T17:59:58Z', '2026-03-06T06:30:10.742Z', 'abe73a234364fbf2e8ac7f3f785da936c38d1ec5e3e9f54fa876451f8c6c281b', '{"id":"sherdotsh/sher/sher-deploy","name":"sher-deploy","description":{"en":"sher-deploy is a CLI that builds and deploys frontend projects to a live preview URL. It benefits developers by providing a quick and easy way to share their work.","zh":"sher-deploy是一种CLI工具，能够快速部署您的前端项目到live preview URL","ja":"sher-deployは、フロントエンドプロジェクトをlive preview URLに迅速にデプロイできるCLIツールです","ko":"sher-deploy는 프론트엔드 프로젝트를 live preview URL에 빠르게 배포할 수 있는 CLI 도구입니다","es":"sher-deploy es una herramienta de línea de comandos que construye y sube tu proyecto frontend, devolviendo una URL de vista previa en vivo. Funciona con frameworks autodetectados.","fr":"sher-deploy est un outil en ligne de commande qui construit et télécharge votre projet frontend, renvoyant une URL de prévisualisation en direct. Il fonctionne avec des frameworks autodétectés.","de":"sher-deploy ist ein Kommandozeilen-Tool, das Ihr Frontend-Projekt baut und hochlädt, und eine Live-Vorschau-URL zurückgibt. Es funktioniert mit autodetektierten Frameworks.","pt":"O sher-deploy é uma CLI que constrói e publica projetos frontend, retornando um URL de visualização ao vivo. É fácil de usar e não requer configuração.","ru":"sher-deploy - это CLI, которая строит и публикует проекты frontend, возвращая живой URL-пレビュー. Легко использовать, без настройки.","ar":"sher-deploy هو CLI يبني وينشر مشاريع الواجهة الأمامية، ويعيد URL معاينة مباشرة. سهل الاستخدام، بدون إعدادات."},"seo":{"title":{"en":"sher-deploy: Setup Guide for AI Agents | AI Agent Skill","zh":"sher-deploy 快速部署指南 - AI工具","ja":"sher-deploy の設定ガイド - AIエージェント","ko":"sher-deploy 설정 가이드 - AI 도구","es":"sher-deploy: Guía de configuración para implementación en...","fr":"sher-deploy: Guide de mise en place pour l''hébergement live","de":"sher-deploy: Einrichtungsanleitung für Live-Preview","pt":"Guia de Configuração do sher-deploy - Ferramenta de Deplo...","ru":" sher-deploy: Руководство по настройке для ИИ Агентов","ar":"إعداد sher-deploy - أداة نشر لمشاريع الواجهة الأمامية"},"description":{"en":"Discover how to deploy your frontend project with sher-deploy. Learn how to install and use sher-deploy with one simple command, no accounts or config required.","zh":"使用sher-deploy快速部署您的前端项目，支持自动检测框架和一键上传","ja":"sher-deployを使用してフロントエンドプロジェクトを迅速にデプロイしましょう。フレームワークの自動検出と一括アップロードをサポート","ko":"sher-deploy를 사용하여 프론트엔드 프로젝트를 빠르게 배포하세요. 자동 프레임워크 감지 및 일括 업로드 지원","es":"Descubre cómo implementar tu proyecto frontend en vivo con sher-deploy, una herramienta de línea de comandos que te permite subir y compartir tu proyecto en ...","fr":"Découvrez comment déployer votre projet frontend en direct avec sher-deploy, un outil en ligne de commande qui vous permet de télécharger et de partager votr...","de":"Erfahren Sie, wie Sie Ihr Frontend-Projekt mit sher-deploy live deployen können, einem Kommandozeilen-Tool, das es Ihnen ermöglicht, Ihr Projekt hochzuladen ...","pt":"Aprenda a configurar o sher-deploy para deploy de projetos frontend em um URL de visualização ao vivo. Sem contas, sem configuração.","ru":"Узнайте, как настроить sher-deploy для деплоя проектов frontend на живой URL-пレビュー. Без аккаунтов, без конфигурации.","ar":"تعرف على كيفية إعداد sher-deploy لنشر مشاريع الواجهة الأمامية على URL معاينة مباشرة. بدون حسابات، بدون إعدادات."},"definition":{"en":"sher-deploy is a command-line interface (CLI) tool that auto-detects the framework, builds, and deploys frontend projects to a live preview URL.","zh":"sher-deploy是一种用于快速部署前端项目的CLI工具","ja":"sher-deployは、フロントエンドプロジェクトを迅速にデプロイできるCLIツールの一種です","ko":"sher-deploy는 프론트엔드 프로젝트를 빠르게 배포할 수 있는 CLI 도구の一種입니다","es":"sher-deploy es una herramienta de línea de comandos para implementar proyectos frontend en vivo","fr":"sher-deploy est un outil en ligne de commande pour déployer des projets frontend en direct","de":"sher-deploy ist ein Kommandozeilen-Tool zum Deployen von Frontend-Projekten in Echtzeit","pt":"O que é sher-deploy? É uma ferramenta de linha de comando para deploy de projetos frontend em um URL de visualização ao vivo.","ru":"Что такое sher-deploy? Это инструмент командной строки для деплоя проектов frontend на живой URL-пレビュー.","ar":"ما هو sher-deploy؟ هو أداة سطر أوامر لنشر مشاريع الواجهة الأمامية على URL معاينة مباشرة."},"features":{"en":["Auto-detects framework for seamless deployment","Builds and uploads frontend projects with one command","Returns a live preview URL for easy sharing","Supports global installation via npm","Can be used with npx for one-off deployments","Runs from the project root with the ''sher link'' command"],"zh":["支持自动检测框架","一键上传和部署","支持npm和npx安装","快速生成live preview URL","无需账号和配置"],"ja":["フレームワークの自動検出","一括アップロードとデプロイ","npmとnpxのインストールをサポート","live preview URLの迅速生成","アカウントと設定不要"],"ko":["자동 프레임워크 감지","일括 업로드 및 배포","npm과 npx 설치 지원","live preview URL 빠른 생성","계정 및 설정 불필요"],"es":["Construye y sube proyectos frontend con un solo comando","Autodetección de frameworks","No requiere cuentas ni configuración","Devuelve una URL de vista previa en vivo","Instalación global o uso con npx"],"fr":["Construit et télécharge des projets frontend avec une seule commande","Détection automatique des frameworks","Nécessite aucun compte ni configuration","Renvoie une URL de prévisualisation en direct","Installation globale ou utilisation avec npx"],"de":["Baut und lädt Frontend-Projekte mit einem einzigen Befehl","Autodetektion von Frameworks","Benötigt keine Konten oder Konfiguration","Gibt eine Live-Vorschau-URL zurück","Globale Installation oder Verwendung mit npx"],"pt":["Constrói e publica projetos frontend em um URL de visualização ao vivo","Auto-detecta o framework do projeto","Executa com um único comando: sher link","Não requer configuração ou contas","Suporta uso com npm ou npx"],"ru":["Строит и публикует проекты frontend на живой URL-пレビュー","Авто-определяет фреймворк проекта","Выполняется с одной командой: sher link","Не требует настройки или аккаунтов","Поддерживает использование с npm или npx"],"ar":["يبني وينشر مشاريع الواجهة الأمامية على URL معاينة مباشرة","يكتشف تلقائيًا إطار العمل للمشروع","يقوم بتنفيذ الأمر sher link","لا يتطلب إعدادات أو حسابات","يدعم استخدام npm أو npx"]},"keywords":{"en":["how to use sher-deploy","sher-deploy install","sher-deploy setup guide","what is sher-deploy","sher-deploy alternative","sher-deploy vs netlify","deploy frontend project","live preview URL","CLI tool for deployment"],"zh":["sher-deploy","AI工具","前端项目部署","CLI工具","自动检测框架","一键上传","live preview URL","npm安装","npx安装"],"ja":["sher-deploy","AIエージェント","フロントエンドプロジェクトデプロイ","CLIツール","フレームワークの自動検出","一括アップロード","live preview URL","npmインストール","npxインストール"],"ko":["sher-deploy","AI 도구","프론트엔드 프로젝트 배포","CLI 도구","자동 프레임워크 감지","일括 업로드","live preview URL","npm 설치","npx 설치"],"es":["sher-deploy","herramientas de línea de comandos","implementación en vivo","proyectos frontend","frameworks autodetectados","npm","npx","desarrollo web"],"fr":["sher-deploy","outils en ligne de commande","déployer en direct","projets frontend","frameworks autodétectés","npm","npx","développement web"],"de":["sher-deploy","Kommandozeilen-Tools","Live-Deploy","Frontend-Projekte","autodetektierte Frameworks","npm","npx","Webentwicklung"],"pt":["sher-deploy","deploy de projeto frontend","URL de visualização ao vivo","ferramenta de linha de comando","npm","npx","projeto frontend","desenvolvimento web"],"ru":["sher-deploy","деплой проекта frontend","живой URL-пレビュー","инструмент командной строки","npm","npx","проект frontend","веб-разработка","ИИ Агенты"],"ar":["sher-deploy","نشر مشروع الواجهة الأمامية","URL معاينة مباشرة","أداة سطر أوامر","npm","npx","مشروع الواجهة الأمامية","تطوير الويب","أدوات الذكاء الاصطناعي"]}},"owner":"sherdotsh","repo":"sher","repoPath":"sherdotsh/sher","stars":140,"forks":5,"updatedAt":"2026-02-28T17:59:58Z","topics":[],"category":"community","skillMd":{"name":"sher-deploy","description":"Deploy frontend projects to instant preview URLs using sher. After building a project, run sher link to get a live, shareable URL in seconds.","bodyPreview":"# sher — deploy to a live preview URL\n\nsher is a CLI that builds your frontend project, uploads it, and returns a live preview URL. One command. No accounts. No config.\n\nUse it after you''ve built or scaffolded a frontend project and the user wants to see it live.\n\n## Install\n\nGlobal (recommended for agents):\n\n```bash\nnpm i -g shersh\n```\n\nOr one-off with npx:\n\n```bash\nnpx shersh link\n```\n\n## Deploy\n\nFrom the project root:\n\n```bash\nsher link\n```\n\nThat''s it. sher auto-detects the framework, runs th","body":"# sher — deploy to a live preview URL\n\nsher is a CLI that builds your frontend project, uploads it, and returns a live preview URL. One command. No accounts. No config.\n\nUse it after you''ve built or scaffolded a frontend project and the user wants to see it live.\n\n## Install\n\nGlobal (recommended for agents):\n\n```bash\nnpm i -g shersh\n```\n\nOr one-off with npx:\n\n```bash\nnpx shersh link\n```\n\n## Deploy\n\nFrom the project root:\n\n```bash\nsher link\n```\n\nThat''s it. sher auto-detects the framework, runs the build, uploads the output, and returns a URL.\n\n### Options\n\n| Flag | Description |\n|------|-------------|\n| `--dir <path>` | Upload a specific directory (skips framework detection) |\n| `--ttl <hours>` | Set link expiry in hours (default: 24) |\n| `--no-build` | Skip the build step (use if already built) |\n| `--pass [password]` | Password-protect the preview (Pro only) |\n\n### Examples\n\n```bash\n# Standard deploy\nsher link\n\n# Deploy a pre-built project\nsher link --no-build\n\n# Deploy a specific output directory\nsher link --dir ./dist\n\n# Short-lived link (2 hours)\nsher link --ttl 2\n```\n\n## Parsing the output\n\nThe CLI prints the live URL to stdout in this format:\n\n```\n  https://a8xk2m1p.sher.sh  (copied)\n  expires 2/19/2026, 11:00 AM\n```\n\nThe URL always matches the pattern `https://[a-z0-9]{8}.sher.sh`. Extract it with:\n\n```\nhttps://[a-z0-9]{8}\\.sher\\.sh\n```\n\nThe URL is also automatically copied to the clipboard.\n\n## After deploying\n\nPresent the URL to the user:\n\n> Your preview is live at https://a8xk2m1p.sher.sh\n\nIf you set a `--ttl`, mention when it expires. If using `--pass`, share the password too.\n\n## Supported frameworks\n\nsher auto-detects and builds:\n\n- **Vite** — outputs to `dist/`\n- **Next.js** — auto-configures static export, outputs to `out/`\n- **Astro** — outputs to `dist/`\n- **Create React App** — outputs to `build/`\n- **Any project** with a build script that produces `dist/`, `build/`, or `out/`\n- **Static HTML** — no build needed, use `--dir .` to upload directly\n\n## Agent-friendly by default\n\n- No browser opens after deploy\n- No interactive prompts\n- No account required for basic usage (1 deploy, 10MB max, 6h TTL)\n- Authenticated users get 25 deploys, 50MB, 24h TTL\n- Exit code 0 on success, non-zero on failure\n\n## Troubleshooting\n\nIf `sher link` fails:\n\n1. **No build script** — the project needs a `build` script in `package.json`, or use `--dir` to point to pre-built output\n2. **Build error** — fix the build error first, then retry\n3. **Size limit** — the upload is too large (10MB anonymous, 50MB authenticated, 100MB Pro)\n4. **No output directory** — ensure the build produces `dist/`, `build/`, or `out/`, or specify `--dir`\n"},"lastSynced":"2026-03-06T06:30:10.742Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Development Agents needing rapid deployment and live preview capabilities for their projects.","zh":"非常适合需要快速部署和实时预览功能的前端开发代理。","ja":"フロントエンド開発エージェントがプロジェクトを迅速にデプロイしてライブプレビュー機能を使用するのに最適です。","ko":"프로젝트를 빠르게 배포하고 라이브 미리보기 기능을 사용해야 하는 프론트엔드 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo frontend que necesitan una implementación rápida y capacidades de vista previa en vivo para sus proyectos.","fr":"Parfait pour les agents de développement frontend qui ont besoin d''un déploiement rapide et de fonctionnalités d''aperçu en direct pour leurs projets.","de":"Perfekt für Frontend-Entwicklungsagenten, die eine schnelle Bereitstellung und Live-Vorschau-Funktionen für ihre Projekte benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Frontend que necessitam de implantação rápida e recursos de visualização ao vivo para seus projetos.","ru":"Идеально для агентов фронтенд-разработки, которым необходима быстрая развертка и возможности живой демонстрации для их проектов.","ar":"مثالي للوكلاء التطوير الأمامي الذين يحتاجون إلى نشر سريع وقدرات معاينة مباشرة لمشاريعهم."},"recommendation":{"en":"Empowers agents to deploy frontend projects to a live preview URL with a single command, utilizing CLI tools like npm and npx, and auto-detecting frameworks for seamless integration.","zh":"赋予代理将前端项目部署到实时预览URL的能力，只需一个命令，即可利用CLI工具如npm和npx，并自动检测框架以实现无缝集成。","ja":"エージェントがフロントエンドプロジェクトをライブプレビューURLにデプロイする能力を提供します。CLIツールのnpmとnpxを1つのコマンドで利用し、フレームワークを自動で検知して無縫に統合します。","ko":"에이전트가 프론트엔드 프로젝트를 라이브 미리보기 URL에 배포할 수 있는 기능을 제공합니다. CLI 도구인 npm과 npx를 하나의 명령으로 사용하며, 프레임워크를 자동으로 감지하여 무리 없이 통합합니다.","es":"Habilita a los agentes para implementar proyectos frontend en una URL de vista previa en vivo con un solo comando, utilizando herramientas de CLI como npm y npx, y detectando automáticamente los frameworks para una integración sin problemas.","fr":"Permet aux agents de déployer des projets frontend sur une URL d''aperçu en direct avec une seule commande, en utilisant des outils CLI tels que npm et npx, et en détectant automatiquement les frameworks pour une intégration transparente.","de":"Ermächtigt die Agenten, Frontend-Projekte mit einem einzigen Befehl auf eine Live-Vorschau-URL zu deployen, indem sie CLI-Tools wie npm und npx verwenden und Frameworks automatisch erkennen, um eine nahtlose Integration zu ermöglichen.","pt":"Habilita os agentes a implantar projetos frontend em uma URL de visualização ao vivo com um único comando, utilizando ferramentas CLI como npm e npx, e detectando automaticamente estruturas para integração sem problemas.","ru":"Наделяет агентов возможностью развертывать фронтенд-проекты на живую демонстрацию по URL с помощью одной команды, используя инструменты CLI, такие как npm и npx, и автоматически обнаруживая фреймворки для бесшовной интеграции.","ar":"يمكن للوكلاء نشر مشاريع FRONTEND في عنوان URL للمعاينة المباشرة باستخدام أمر واحد ، باستخدام أدوات CLI مثل npm و npx ، وتحديد الإطارات تلقائيًا من أجل التكامل السلس."},"useCases":{"en":["Deploying React applications for client review","Sharing live previews of Angular projects","Testing Vue.js projects on a live URL"],"zh":["为客户审查部署React应用程序","共享Angular项目的实时预览","在实时URL上测试Vue.js项目"],"ja":["クライアントレビュー用のReactアプリケーションのデプロイ","Angularプロジェクトのライブプレビューの共有","ライブURL上でのVue.jsプロジェクトのテスト"],"ko":["클라이언트 리뷰용 React 애플리케이션 배포","Angular 프로젝트의 라이브 미리보기 공유","라이브 URL에서 Vue.js 프로젝트 테스트"],"es":["Implementar aplicaciones React para revisión del cliente","Compartir vistas previas en vivo de proyectos Angular","Probar proyectos Vue.js en una URL en vivo"],"fr":["Déployer des applications React pour examen client","Partager des aperçus en direct de projets Angular","Tester des projets Vue.js sur une URL en direct"],"de":["React-Anwendungen für die Kundenprüfung bereitstellen","Live-Vorschauen von Angular-Projekten teilen","Vue.js-Projekte auf einer Live-URL testen"],"pt":["Implantação de aplicações React para revisão do cliente","Compartilhamento de visualizações ao vivo de projetos Angular","Teste de projetos Vue.js em uma URL ao vivo"],"ru":["Развертка приложений React для рассмотрения клиентом","Обмен живыми демонстрациями проектов Angular","Тестирование проектов Vue.js на живом URL"],"ar":["نشر تطبيقات React للمراجعة العميل","مشاركة معاينة مباشرة لمشاريع Angular","اختبار مشاريع Vue.js على عنوان URL مباشر"]},"limitations":{"en":["Requires npm or npx installation","Limited to frontend projects","No configuration options available"],"zh":["需要npm或npx安装","仅限于前端项目","没有可用配置选项"],"ja":["npmまたはnpxのインストールが必要","フロントエンドプロジェクトのみ","利用可能な構成オプションなし"],"ko":["npm 또는 npx 설치 필요","프론트엔드 프로젝트만 해당","사용 가능한 구성 옵션 없음"],"es":["Requiere la instalación de npm o npx","Limitado a proyectos frontend","No hay opciones de configuración disponibles"],"fr":["Nécessite l''installation de npm ou npx","Limité aux projets frontend","Aucune option de configuration disponible"],"de":["Benötigt die Installation von npm oder npx","Begrenzt auf Frontend-Projekte","Keine Konfigurationsoptionen verfügbar"],"pt":["Requer instalação do npm ou npx","Limitado a projetos frontend","Nenhuma opção de configuração disponível"],"ru":["Требуется установка npm или npx","Ограничен фронтенд-проектами","Нет доступных опций конфигурации"],"ar":["يتطلب تثبيت npm أو npx","محدود بمشاريع FRONTEND","لا تتوفر خيارات تكوين"]},"version":4},"contentHash":"abe73a234364fbf2e8ac7f3f785da936c38d1ec5e3e9f54fa876451f8c6c281b","qualityScore":61}');
