INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Rikinshah787/clawarmy/phantom', 'phantom', 'Rikinshah787', 'clawarmy', 'community', 'phantom Rikinshah787 clawarmy community Phantom is a stealth testing and debugging expert for AI Agent Specialists, enabling developers to systematically investigate and fix root causes of bugs. It helps developers discover untested paths and test what matters to users. Phantom AI工具是一种系统化的测试和调试专家，帮助开发者发现未测试的路径和隐藏的bug Phantom AIエージェントは、システム的なテストとデバッグの専門家であり、開発者が未テストのパスと隠れたバグを発見するのに役立ちます Phantom AI 에이전트는 체계적인 테스트와 디버깅 전문가로서, 개발자가 테스트되지 않은 경로와 숨겨진 버그를 발견하도록 도와줍니다 Phantom es una herramienta de pruebas y depuración de AI que ayuda a los desarrolladores a encontrar y solucionar errores de manera sistemática Phantom est un outil de test et de débogage d''IA qui aide les développeurs à trouver et à résoudre les erreurs de manière systématique Phantom ist ein AI-Testing- und -Debugging-Tool, das Entwicklern hilft, Fehler systematisch zu finden und zu beheben O Phantom é um especialista em testes e depuração que ajuda a identificar e resolver problemas no código, melhorando a qualidade do software Phantom - это эксперт по тестированию и отладке, который помогает выявить и решить проблемы в коде, улучшая качество ПО Phantom هو خبير اختبار وحل المشكلات الذي يساعد في تحديد ومعالجة مشاكل الشفرة، مما يحسن جودة البرمجيات how to use phantom for testing what is phantom AI Agent Skill phantom alternative for debugging phantom vs other testing tools phantom install guide for developers phantom setup for AI Agent Specialists AI工具 系统化测试 调试专家 未测试路径 行为驱动测试 证据驱动调试 根因分析 Phantom AI工具 Follows testing pyramid for systematic investigation Discovers untested paths and behavior-focused testing Uses evidence-based approach to follow data, not assumptions Focuses on root cause analysis to fix underlying problems Enables proactive testing to hunt bugs before they affect users Phantom is a specialized AI Agent Skill for stealth testing and debugging, following a systematic and evidence-based approach to identify and fix root causes of bugs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mohammedatiaa/ai-project-network/audiocraft-audio-generation', 'community', 'mohammedatiaa', 'ai-project-network', 'mohammedatiaa/ai-project-network', 'audiocraft-audio-generation', 0, 0, 61, '2026-02-27T16:35:45Z', '2026-03-07T04:05:00.230Z', '3f9efaebd7331bea86022a101329074c6eab8af2d33591e691c565fcba641a5f', '{"id":"mohammedatiaa/ai-project-network/audiocraft-audio-generation","name":"audiocraft-audio-generation","description":{"en":"Audiocraft-audio-generation is a tool for developers to generate music and audio from text descriptions, ideal for building music generation applications and creating sound effects.","zh":"AudioCraft是一种强大的音频生成工具，支持文本到音乐和音频的转换","ja":"AudioCraftは、音楽と音声の生成を可能にするAIエージェントです","ko":"AudioCraft는 텍스트를 음악이나 오디오로 변환하는 강력한 오디오 생성 도구입니다","es":"AudioCraft es una herramienta de generación de audio que permite crear música y sonidos a partir de descripciones de texto.","fr":"AudioCraft est un outil de génération audio qui permet de créer de la musique et des sons à partir de descriptions textuelles.","de":"AudioCraft ist ein Tool zur Audiogenerierung, mit dem Musik und Sounds aus Textbeschreibungen erstellt werden können.","pt":"O AudioCraft é uma ferramenta de geração de áudio que permite criar música e efeitos sonoros a partir de textos","ru":"AudioCraft - это инструмент генерации аудио, который позволяет создавать музыку и звуковые эффекты из текстов","ar":"AudioCraft هو أداة لإنشاء الصوت التي تمكن من إنشاء الموسيقى والأصوات من النصوص"},"seo":{"title":{"en":"audiocraft-audio-generation: Comprehensive Guide for AI A...","zh":"AudioCraft音频生成Setup Guide","ja":"AudioCraft音频生成ベストプラクティス - AIエージェント","ko":"AudioCraft 오디오 생성 튜토리얼 - AI 툴","es":"Guía de configuración de AudioCraft para la generación de...","fr":"Guide de démarrage rapide pour la génération audio avec A...","de":"Einrichtungsleitfaden für AudioCraft: Erstellung von Musi...","pt":"Guia de Configuração do AudioCraft para Geração de Áudio","ru":"ИИ Агенты: Руководство по настройке AudioCraft для генера...","ar":"دليل إعداد AudioCraft لإنشاء الموسيقى والصوت"},"description":{"en":"Discover how to generate music and audio with Audiocraft. Learn to use MusicGen, AudioGen, and EnCodec for text-to-music and text-to-audio generation. Get st...","zh":"了解AudioCraft音频生成的技术细节，包括MusicGen、AudioGen和EnCodec","ja":"AIエージェントを使用したAudioCraft音频生成のガイド。MusicGen、AudioGen、EnCodecの機能をチェック","ko":"AudioCraft 오디오 생성에 대한 전문가 가이드. MusicGen, AudioGen, EnCodec 기술을 익혀보세요","es":"Aprende a utilizar AudioCraft para generar música y audio a partir de texto con MusicGen, AudioGen y EnCodec. Descubre sus características clave.","fr":"Découvrez comment utiliser AudioCraft pour générer de la musique et du son à partir de texte avec MusicGen, AudioGen et EnCodec.","de":"Erfahren Sie, wie Sie mit AudioCraft Musik und Audio aus Text erstellen können. Mit MusicGen, AudioGen und EnCodec.","pt":"Aprenda a usar o AudioCraft para gerar música e áudio a partir de textos com MusicGen, AudioGen e EnCodec","ru":"Узнайте, как использовать AudioCraft для генерации музыки и аудио из текстов с помощью MusicGen, AudioGen и EnCodec","ar":"تعرف على كيفية استخدام AudioCraft لإنشاء الموسيقى والصوت من النصوص باستخدام MusicGen و AudioGen و EnCodec"},"definition":{"en":"audiocraft-audio-generation is a comprehensive guide to using Meta''s AudioCraft for text-to-music and text-to-audio generation with MusicGen, AudioGen, and EnCodec.","zh":"AudioCraft音频生成是一种使用MusicGen、AudioGen和EnCodec技术的音频生成方法","ja":"AudioCraft音频生成は、MusicGen、AudioGen、EnCodecを使用した音声生成技術です","ko":"AudioCraft 오디오 생성은 MusicGen, AudioGen, EnCodec 기술을 활용한 오디오 생성 방법입니다","es":"AudioCraft es una tecnología de generación de audio que utiliza MusicGen, AudioGen y EnCodec para crear audio a partir de texto.","fr":"AudioCraft est une technologie de génération audio qui utilise MusicGen, AudioGen et EnCodec pour créer de l''audio à partir de texte.","de":"AudioCraft ist eine Audiogenerierungstechnologie, die MusicGen, AudioGen und EnCodec nutzt, um Audio aus Text zu erstellen.","pt":"O que é AudioCraft? É uma ferramenta de geração de áudio que usa textos para criar música e efeitos sonoros","ru":"Что такое AudioCraft? Это инструмент генерации аудио, который использует тексты для создания музыки и звуковых эффектов","ar":"ما هو AudioCraft؟ إنه أداة لإنشاء الصوت التي تستخدم النصوص لإنشاء الموسيقى والأصوات"},"features":{"en":["Generates music from text descriptions using MusicGen","Creates sound effects and environmental audio with AudioGen","Supports melody-conditioned music generation","Produces stereo audio output","Allows controllable music generation with style transfer using EnCodec"],"zh":["支持文本到音乐的转换","支持创建音效和环境音","支持旋律条件音乐生成","支持立体声输出","支持可控音乐生成和风格转换"],"ja":["テキストから音楽への変換をサポート","サウンドエフェクトと環境音の作成をサポート","メロディー条件付き音楽生成をサポート","ステレオ音声出力をサポート","可制御音楽生成とスタイル転送をサポート"],"ko":["텍스트를 음악으로 변환하는 기능","사운드 이펙트와 환경음 생성 기능","旋律 조건부 음악 생성 기능","스테레오 음성 출력 지원","可제어 음악 생성과 스타일 전환 기능"],"es":["Generación de música a partir de descripciones de texto con MusicGen","Creación de efectos de sonido y audio ambiental con AudioGen","Generación de audio estéreo","Control de la generación de música con transferencia de estilo","Compatibilidad con EnCodec para la codificación de audio"],"fr":["Génération de musique à partir de descriptions textuelles avec MusicGen","Création d''effets sonores et d''audio environnemental avec AudioGen","Génération d''audio stéréo","Contrôle de la génération de musique avec transfert de style","Compatibilité avec EnCodec pour la codification audio"],"de":["Erstellung von Musik aus Textbeschreibungen mit MusicGen","Erstellung von Soundeffekten und Umgebungsaudio mit AudioGen","Erstellung von Stereo-Audio","Kontrolle der Musikgenerierung mit Stiltransfer","Kompatibilität mit EnCodec für die Audiocodierung"],"pt":["Geração de música a partir de textos com MusicGen","Criação de efeitos sonoros e áudio ambiental com AudioGen","Geração de música condicionada por melodia com EnCodec","Saída de áudio estéreo","Controle de geração de música com transferência de estilo"],"ru":["Генерация музыки из текстов с помощью MusicGen","Создание звуковых эффектов и аудио-окружения с помощью AudioGen","Генерация музыки с условной мелодией с помощью EnCodec","Стерео-аудио-выход","Контроль генерации музыки с помощью передачи стиля"],"ar":["إنشاء الموسيقى من النصوص باستخدام MusicGen","إنشاء الأصوات والصوت المحيط باستخدام AudioGen","إنشاء الموسيقى المشروطة باللحن مع EnCodec","إخراج الصوت الاستيريو","التحكم في إنشاء الموسيقى بنقل الأسلوب"]},"keywords":{"en":["how to use audiocraft-audio-generation","audiocraft-audio-generation alternative","audiocraft-audio-generation setup guide","what is audiocraft-audio-generation","audiocraft-audio-generation vs Amper Music","audiocraft-audio-generation install","text-to-music generation","audio generation tools","music generation applications"],"zh":["AudioCraft音频生成","MusicGen","AudioGen","EnCodec","文本到音乐","音频生成工具","AI音频生成"],"ja":["AudioCraft音频生成","MusicGen","AudioGen","EnCodec","テキストから音楽","音声生成ツール","AIエージェント音频生成"],"ko":["AudioCraft 오디오 생성","MusicGen","AudioGen","EnCodec","텍스트를 음악으로","오디오 생성 도구","AI 툴 오디오 생성"],"es":["generación de audio","AudioCraft","MusicGen","AudioGen","EnCodec","herramientas de AI para audio","generación de música","efectos de sonido","audio ambiental"],"fr":["génération audio","AudioCraft","MusicGen","AudioGen","EnCodec","outils d''IA pour l''audio","génération de musique","effets sonores","audio environnemental"],"de":["Audiogenerierung","AudioCraft","MusicGen","AudioGen","EnCodec","AI-Tools für Audio","Musikerstellung","Soundeffekte","Umgebungsaudio"],"pt":["geração de áudio","música gerada por texto","efeitos sonoros","áudio ambiental","MusicGen","AudioGen","EnCodec","geração de música condicionada por melodia"],"ru":["генерация аудио","музыка генерируемая из текста","звуковые эффекты","аудио-окружение","MusicGen","AudioGen","EnCodec","генерация музыки с условной мелодией"],"ar":["إنشاء الصوت","موسيقى منشأة من النص","الأصوات","الصوت المحيط","MusicGen","AudioGen","EnCodec","إنشاء الموسيقى المشروطة باللحن"]}},"owner":"mohammedatiaa","repo":"ai-project-network","repoPath":"mohammedatiaa/ai-project-network","stars":0,"forks":0,"updatedAt":"2026-02-27T16:35:45Z","topics":[],"category":"community","skillMd":{"name":"audiocraft-audio-generation","description":"PyTorch library for audio generation including text-to-music (MusicGen) and text-to-sound (AudioGen). Use when you need to generate music from text descriptions, create sound effects, or perform melody-conditioned music generation.","version":"1.0.0","tags":["Multimodal","Audio Generation","Text-to-Music","Text-to-Audio","MusicGen"],"bodyPreview":"# AudioCraft: Audio Generation\n\nComprehensive guide to using Meta''s AudioCraft for text-to-music and text-to-audio generation with MusicGen, AudioGen, and EnCodec.\n\n## When to use AudioCraft\n\n**Use AudioCraft when:**\n- Need to generate music from text descriptions\n- Creating sound effects and environmental audio\n- Building music generation applications\n- Need melody-conditioned music generation\n- Want stereo audio output\n- Require controllable music generation with style transfer\n\n**Key features","body":"# AudioCraft: Audio Generation\n\nComprehensive guide to using Meta''s AudioCraft for text-to-music and text-to-audio generation with MusicGen, AudioGen, and EnCodec.\n\n## When to use AudioCraft\n\n**Use AudioCraft when:**\n- Need to generate music from text descriptions\n- Creating sound effects and environmental audio\n- Building music generation applications\n- Need melody-conditioned music generation\n- Want stereo audio output\n- Require controllable music generation with style transfer\n\n**Key features:**\n- **MusicGen**: Text-to-music generation with melody conditioning\n- **AudioGen**: Text-to-sound effects generation\n- **EnCodec**: High-fidelity neural audio codec\n- **Multiple model sizes**: Small (300M) to Large (3.3B)\n- **Stereo support**: Full stereo audio generation\n- **Style conditioning**: MusicGen-Style for reference-based generation\n\n**Use alternatives instead:**\n- **Stable Audio**: For longer commercial music generation\n- **Bark**: For text-to-speech with music/sound effects\n- **Riffusion**: For spectogram-based music generation\n- **OpenAI Jukebox**: For raw audio generation with lyrics\n\n## Quick start\n\n### Installation\n\n```bash\n# From PyPI\npip install audiocraft\n\n# From GitHub (latest)\npip install git+https://github.com/facebookresearch/audiocraft.git\n\n# Or use HuggingFace Transformers\npip install transformers torch torchaudio\n```\n\n### Basic text-to-music (AudioCraft)\n\n```python\nimport torchaudio\nfrom audiocraft.models import MusicGen\n\n# Load model\nmodel = MusicGen.get_pretrained(''facebook/musicgen-small'')\n\n# Set generation parameters\nmodel.set_generation_params(\n    duration=8,  # seconds\n    top_k=250,\n    temperature=1.0\n)\n\n# Generate from text\ndescriptions = [\"happy upbeat electronic dance music with synths\"]\nwav = model.generate(descriptions)\n\n# Save audio\ntorchaudio.save(\"output.wav\", wav[0].cpu(), sample_rate=32000)\n```\n\n### Using HuggingFace Transformers\n\n```python\nfrom transformers import AutoProcessor, MusicgenForConditionalGeneration\nimport scipy\n\n# Load model and processor\nprocessor = AutoProcessor.from_pretrained(\"facebook/musicgen-small\")\nmodel = MusicgenForConditionalGeneration.from_pretrained(\"facebook/musicgen-small\")\nmodel.to(\"cuda\")\n\n# Generate music\ninputs = processor(\n    text=[\"80s pop track with bassy drums and synth\"],\n    padding=True,\n    return_tensors=\"pt\"\n).to(\"cuda\")\n\naudio_values = model.generate(\n    **inputs,\n    do_sample=True,\n    guidance_scale=3,\n    max_new_tokens=256\n)\n\n# Save\nsampling_rate = model.config.audio_encoder.sampling_rate\nscipy.io.wavfile.write(\"output.wav\", rate=sampling_rate, data=audio_values[0, 0].cpu().numpy())\n```\n\n### Text-to-sound with AudioGen\n\n```python\nfrom audiocraft.models import AudioGen\n\n# Load AudioGen\nmodel = AudioGen.get_pretrained(''facebook/audiogen-medium'')\n\nmodel.set_generation_params(duration=5)\n\n# Generate sound effects\ndescriptions = [\"dog barking in a park with birds chirping\"]\nwav = model.generate(descriptions)\n\ntorchaudio.save(\"sound.wav\", wav[0].cpu(), sample_rate=16000)\n```\n\n## Core concepts\n\n### Architecture overview\n\n```\nAudioCraft Architecture:\n┌──────────────────────────────────────────────────────────────┐\n│                    Text Encoder (T5)                          │\n│                         │                                     │\n│                    Text Embeddings                            │\n└────────────────────────┬─────────────────────────────────────┘\n                         │\n┌────────────────────────▼─────────────────────────────────────┐\n│              Transformer Decoder (LM)                         │\n│     Auto-regressively generates audio tokens                  │\n│     Using efficient token interleaving patterns               │\n└────────────────────────┬─────────────────────────────────────┘\n                         │\n┌────────────────────────▼─────────────────────────────────────┐\n│                EnCodec Audio Decoder                          │\n│        Converts tokens back to audio waveform                 │\n└──────────────────────────────────────────────────────────────┘\n```\n\n### Model variants\n\n| Model | Size | Description | Use Case |\n|-------|------|-------------|----------|\n| `musicgen-small` | 300M | Text-to-music | Quick generation |\n| `musicgen-medium` | 1.5B | Text-to-music | Balanced |\n| `musicgen-large` | 3.3B | Text-to-music | Best quality |\n| `musicgen-melody` | 1.5B | Text + melody | Melody conditioning |\n| `musicgen-melody-large` | 3.3B | Text + melody | Best melody |\n| `musicgen-stereo-*` | Varies | Stereo output | Stereo generation |\n| `musicgen-style` | 1.5B | Style transfer | Reference-based |\n| `audiogen-medium` | 1.5B | Text-to-sound | Sound effects |\n\n### Generation parameters\n\n| Parameter | Default | Description |\n|-----------|---------|-------------|\n| `duration` | 8.0 | Length in seconds (1-120) |\n| `top_k` | 250 | Top-k sampling |\n| `top_p` | 0.0 | Nucleus sampling (0 = disabled) |\n| `temperature` | 1.0 | Sampling temperature |\n| `cfg_coef` | 3.0 | Classifier-free guidance |\n\n## MusicGen usage\n\n### Text-to-music generation\n\n```python\nfrom audiocraft.models import MusicGen\nimport torchaudio\n\nmodel = MusicGen.get_pretrained(''facebook/musicgen-medium'')\n\n# Configure generation\nmodel.set_generation_params(\n    duration=30,          # Up to 30 seconds\n    top_k=250,            # Sampling diversity\n    top_p=0.0,            # 0 = use top_k only\n    temperature=1.0,      # Creativity (higher = more varied)\n    cfg_coef=3.0          # Text adherence (higher = stricter)\n)\n\n# Generate multiple samples\ndescriptions = [\n    \"epic orchestral soundtrack with strings and brass\",\n    \"chill lo-fi hip hop beat with jazzy piano\",\n    \"energetic rock song with electric guitar\"\n]\n\n# Generate (returns [batch, channels, samples])\nwav = model.generate(descriptions)\n\n# Save each\nfor i, audio in enumerate(wav):\n    torchaudio.save(f\"music_{i}.wav\", audio.cpu(), sample_rate=32000)\n```\n\n### Melody-conditioned generation\n\n```python\nfrom audiocraft.models import MusicGen\nimport torchaudio\n\n# Load melody model\nmodel = MusicGen.get_pretrained(''facebook/musicgen-melody'')\nmodel.set_generation_params(duration=30)\n\n# Load melody audio\nmelody, sr = torchaudio.load(\"melody.wav\")\n\n# Generate with melody conditioning\ndescriptions = [\"acoustic guitar folk song\"]\nwav = model.generate_with_chroma(descriptions, melody, sr)\n\ntorchaudio.save(\"melody_conditioned.wav\", wav[0].cpu(), sample_rate=32000)\n```\n\n### Stereo generation\n\n```python\nfrom audiocraft.models import MusicGen\n\n# Load stereo model\nmodel = MusicGen.get_pretrained(''facebook/musicgen-stereo-medium'')\nmodel.set_generation_params(duration=15)\n\ndescriptions = [\"ambient electronic music with wide stereo panning\"]\nwav = model.generate(descriptions)\n\n# wav shape: [batch, 2, samples] for stereo\nprint(f\"Stereo shape: {wav.shape}\")  # [1, 2, 480000]\ntorchaudio.save(\"stereo.wav\", wav[0].cpu(), sample_rate=32000)\n```\n\n### Audio continuation\n\n```python\nfrom transformers import AutoProcessor, MusicgenForConditionalGeneration\n\nprocessor = AutoProcessor.from_pretrained(\"facebook/musicgen-medium\")\nmodel = MusicgenForConditionalGeneration.from_pretrained(\"facebook/musicgen-medium\")\n\n# Load audio to continue\nimport torchaudio\naudio, sr = torchaudio.load(\"intro.wav\")\n\n# Process with text and audio\ninputs = processor(\n    audio=audio.squeeze().numpy(),\n    sampling_rate=sr,\n    text=[\"continue with a epic chorus\"],\n    padding=True,\n    return_tensors=\"pt\"\n)\n\n# Generate continuation\naudio_values = model.generate(**inputs, do_sample=True, guidance_scale=3, max_new_tokens=512)\n```\n\n## MusicGen-Style usage\n\n### Style-conditioned generation\n\n```python\nfrom audiocraft.models import MusicGen\n\n# Load style model\nmodel = MusicGen.get_pretrained(''facebook/musicgen-style'')\n\n# Configure generation with style\nmodel.set_generation_params(\n    duration=30,\n    cfg_coef=3.0,\n    cfg_coef_beta=5.0  # Style influence\n)\n\n# Configure style conditioner\nmodel.set_style_conditioner_params(\n    eval_q=3,          # RVQ quantizers (1-6)\n    excerpt_length=3.0  # Style excerpt length\n)\n\n# Load style reference\nstyle_audio, sr = torchaudio.load(\"reference_style.wav\")\n\n# Generate with text + style\ndescriptions = [\"upbeat dance track\"]\nwav = model.generate_with_style(descriptions, style_audio, sr)\n```\n\n### Style-only generation (no text)\n\n```python\n# Generate matching style without text prompt\nmodel.set_generation_params(\n    duration=30,\n    cfg_coef=3.0,\n    cfg_coef_beta=None  # Disable double CFG for style-only\n)\n\nwav = model.generate_with_style([None], style_audio, sr)\n```\n\n## AudioGen usage\n\n### Sound effect generation\n\n```python\nfrom audiocraft.models import AudioGen\nimport torchaudio\n\nmodel = AudioGen.get_pretrained(''facebook/audiogen-medium'')\nmodel.set_generation_params(duration=10)\n\n# Generate various sounds\ndescriptions = [\n    \"thunderstorm with heavy rain and lightning\",\n    \"busy city traffic with car horns\",\n    \"ocean waves crashing on rocks\",\n    \"crackling campfire in forest\"\n]\n\nwav = model.generate(descriptions)\n\nfor i, audio in enumerate(wav):\n    torchaudio.save(f\"sound_{i}.wav\", audio.cpu(), sample_rate=16000)\n```\n\n## EnCodec usage\n\n### Audio compression\n\n```python\nfrom audiocraft.models import CompressionModel\nimport torch\nimport torchaudio\n\n# Load EnCodec\nmodel = CompressionModel.get_pretrained(''facebook/encodec_32khz'')\n\n# Load audio\nwav, sr = torchaudio.load(\"audio.wav\")\n\n# Ensure correct sample rate\nif sr != 32000:\n    resampler = torchaudio.transforms.Resample(sr, 32000)\n    wav = resampler(wav)\n\n# Encode to tokens\nwith torch.no_grad():\n    encoded = model.encode(wav.unsqueeze(0))\n    codes = encoded[0]  # Audio codes\n\n# Decode back to audio\nwith torch.no_grad():\n    decoded = model.decode(codes)\n\ntorchaudio.save(\"reconstructed.wav\", decoded[0].cpu(), sample_rate=32000)\n```\n\n## Common workflows\n\n### Workflow 1: Music generation pipeline\n\n```python\nimport torch\nimport torchaudio\nfrom audiocraft.models import MusicGen\n\nclass MusicGenerator:\n    def __init__(self, model_name=\"facebook/musicgen-medium\"):\n        self.model = MusicGen.get_pretrained(model_name)\n        self.sample_rate = 32000\n\n    def generate(self, prompt, duration=30, temperature=1.0, cfg=3.0):\n        self.model.set_generation_params(\n            duration=duration,\n            top_k=250,\n            temperature=temperature,\n            cfg_coef=cfg\n        )\n\n        with torch.no_grad():\n            wav = self.model.generate([prompt])\n\n        return wav[0].cpu()\n\n    def generate_batch(self, prompts, duration=30):\n        self.model.set_generation_params(duration=duration)\n\n        with torch.no_grad():\n            wav = self.model.generate(prompts)\n\n        return wav.cpu()\n\n    def save(self, audio, path):\n        torchaudio.save(path, audio, sample_rate=self.sample_rate)\n\n# Usage\ngenerator = MusicGenerator()\naudio = generator.generate(\n    \"epic cinematic orchestral music\",\n    duration=30,\n    temperature=1.0\n)\ngenerator.save(audio, \"epic_music.wav\")\n```\n\n### Workflow 2: Sound design batch processing\n\n```python\nimport json\nfrom pathlib import Path\nfrom audiocraft.models import AudioGen\nimport torchaudio\n\ndef batch_generate_sounds(sound_specs, output_dir):\n    \"\"\"\n    Generate multiple sounds from specifications.\n\n    Args:\n        sound_specs: list of {\"name\": str, \"description\": str, \"duration\": float}\n        output_dir: output directory path\n    \"\"\"\n    model = AudioGen.get_pretrained(''facebook/audiogen-medium'')\n    output_dir = Path(output_dir)\n    output_dir.mkdir(exist_ok=True)\n\n    results = []\n\n    for spec in sound_specs:\n        model.set_generation_params(duration=spec.get(\"duration\", 5))\n\n        wav = model.generate([spec[\"description\"]])\n\n        output_path = output_dir / f\"{spec[''name'']}.wav\"\n        torchaudio.save(str(output_path), wav[0].cpu(), sample_rate=16000)\n\n        results.append({\n            \"name\": spec[\"name\"],\n            \"path\": str(output_path),\n            \"description\": spec[\"description\"]\n        })\n\n    return results\n\n# Usage\nsounds = [\n    {\"name\": \"explosion\", \"description\": \"massive explosion with debris\", \"duration\": 3},\n    {\"name\": \"footsteps\", \"description\": \"footsteps on wooden floor\", \"duration\": 5},\n    {\"name\": \"door\", \"description\": \"wooden door creaking and closing\", \"duration\": 2}\n]\n\nresults = batch_generate_sounds(sounds, \"sound_effects/\")\n```\n\n### Workflow 3: Gradio demo\n\n```python\nimport gradio as gr\nimport torch\nimport torchaudio\nfrom audiocraft.models import MusicGen\n\nmodel = MusicGen.get_pretrained(''facebook/musicgen-small'')\n\ndef generate_music(prompt, duration, temperature, cfg_coef):\n    model.set_generation_params(\n        duration=duration,\n        temperature=temperature,\n        cfg_coef=cfg_coef\n    )\n\n    with torch.no_grad():\n        wav = model.generate([prompt])\n\n    # Save to temp file\n    path = \"temp_output.wav\"\n    torchaudio.save(path, wav[0].cpu(), sample_rate=32000)\n    return path\n\ndemo = gr.Interface(\n    fn=generate_music,\n    inputs=[\n        gr.Textbox(label=\"Music Description\", placeholder=\"upbeat electronic dance music\"),\n        gr.Slider(1, 30, value=8, label=\"Duration (seconds)\"),\n        gr.Slider(0.5, 2.0, value=1.0, label=\"Temperature\"),\n        gr.Slider(1.0, 10.0, value=3.0, label=\"CFG Coefficient\")\n    ],\n    outputs=gr.Audio(label=\"Generated Music\"),\n    title=\"MusicGen Demo\"\n)\n\ndemo.launch()\n```\n\n## Performance optimization\n\n### Memory optimization\n\n```python\n# Use smaller model\nmodel = MusicGen.get_pretrained(''facebook/musicgen-small'')\n\n# Clear cache between generations\ntorch.cuda.empty_cache()\n\n# Generate shorter durations\nmodel.set_generation_params(duration=10)  # Instead of 30\n\n# Use half precision\nmodel = model.half()\n```\n\n### Batch processing efficiency\n\n```python\n# Process multiple prompts at once (more efficient)\ndescriptions = [\"prompt1\", \"prompt2\", \"prompt3\", \"prompt4\"]\nwav = model.generate(descriptions)  # Single batch\n\n# Instead of\nfor desc in descriptions:\n    wav = model.generate([desc])  # Multiple batches (slower)\n```\n\n### GPU memory requirements\n\n| Model | FP32 VRAM | FP16 VRAM |\n|-------|-----------|-----------|\n| musicgen-small | ~4GB | ~2GB |\n| musicgen-medium | ~8GB | ~4GB |\n| musicgen-large | ~16GB | ~8GB |\n\n## Common issues\n\n| Issue | Solution |\n|-------|----------|\n| CUDA OOM | Use smaller model, reduce duration |\n| Poor quality | Increase cfg_coef, better prompts |\n| Generation too short | Check max duration setting |\n| Audio artifacts | Try different temperature |\n| Stereo not working | Use stereo model variant |\n\n## References\n\n- **[Advanced Usage](references/advanced-usage.md)** - Training, fine-tuning, deployment\n- **[Troubleshooting](references/troubleshooting.md)** - Common issues and solutions\n\n## Resources\n\n- **GitHub**: https://github.com/facebookresearch/audiocraft\n- **Paper (MusicGen)**: https://arxiv.org/abs/2306.05284\n- **Paper (AudioGen)**: https://arxiv.org/abs/2209.15352\n- **HuggingFace**: https://huggingface.co/facebook/musicgen-small\n- **Demo**: https://huggingface.co/spaces/facebook/MusicGen\n"},"lastSynced":"2026-03-07T04:05:00.230Z","agentAnalysis":{"suitability":{"en":"Perfect for Creative Agents needing advanced music and audio generation capabilities from text descriptions","zh":"非常适合需要高级音乐和音频生成能力的创意代理，从文本描述中生成音乐和音频","ja":"テキストの説明から高度な音楽とオーディオ生成機能を必要とするクリエイティブエージェントに最適","ko":"텍스트 설명에서 고급 음악 및 오디오 생성 기능을 필요한 창의적 에이전트에 적합","es":"Perfecto para Agentes Creativos que necesitan capacidades avanzadas de generación de música y audio a partir de descripciones de texto","fr":"Parfait pour les agents créatifs ayant besoin de capacités avancées de génération de musique et d''audio à partir de descriptions de texte","de":"Perfekt für kreative Agenten, die erweiterte Musik- und Audioerzeugungsfähigkeiten aus Textbeschreibungen benötigen","pt":"Perfeito para Agentes Criativos que necessitam de capacidades avançadas de geração de música e áudio a partir de descrições de texto","ru":"Идеально для Креативных Агентов, которым необходимы расширенные возможности генерации музыки и аудио из текстовых описаний","ar":"مثالي للوكلاء الإبداعيين الذين يحتاجون إلى إمكانيات متقدمة لإنشاء الموسيقى والصوت من وصف النص"},"recommendation":{"en":"Empowers agents to generate music and audio from text descriptions using Meta''s AudioCraft, enabling melody-conditioned music generation, style transfer, and stereo audio output with MusicGen, AudioGen, and EnCodec","zh":"使代理能够使用Meta的AudioCraft从文本描述中生成音乐和音频，实现基于旋律的音乐生成、风格转换和MusicGen、AudioGen、EnCodec的立体音频输出","ja":"エージェントがMetaのAudioCraftを使用してテキストの説明から音楽とオーディオを生成できるようにし、メロディー条件付きの音楽生成、スタイル転送、およびMusicGen、AudioGen、EnCodecのステレオオーディオ出力を可能にします","ko":"에이전트가 Meta의 AudioCraft를 사용하여 텍스트 설명에서 음악 및 오디오를 생성할 수 있도록 하며, 멜로디 조건부 음악 생성, 스타일 전환 및 MusicGen, AudioGen, EnCodec의 스테레오 오디오 출력을 가능하게 합니다","es":"Habilita a los agentes a generar música y audio a partir de descripciones de texto utilizando AudioCraft de Meta, lo que permite la generación de música condicionada por melodía, la transferencia de estilo y la salida de audio estéreo con MusicGen, AudioGen y EnCodec","fr":"Permet aux agents de générer de la musique et de l''audio à partir de descriptions de texte en utilisant AudioCraft de Meta, ce qui permet la génération de musique conditionnée par mélodie, le transfert de style et la sortie audio stéréo avec MusicGen, AudioGen et EnCodec","de":"Ermöglicht es Agenten, Musik und Audio aus Textbeschreibungen zu generieren, indem sie Meta''s AudioCraft verwenden, was die Melodie-konditionierte Musikgenerierung, den Stiltransfer und die Stereo-Audio-Ausgabe mit MusicGen, AudioGen und EnCodec ermöglicht","pt":"Habilita os agentes a gerar música e áudio a partir de descrições de texto usando o AudioCraft da Meta, permitindo geração de música condicionada por melodia, transferência de estilo e saída de áudio estéreo com MusicGen, AudioGen e EnCodec","ru":"Наделяет агентов возможностью генерировать музыку и аудио из текстовых описаний с помощью AudioCraft от Meta, что позволяет осуществлять генерацию музыки, обусловленную мелодией, перенос стиля и стереоаудиовыход с MusicGen, AudioGen и EnCodec","ar":"تمكين الوكلاء من إنشاء الموسيقى والصوت من وصف النص باستخدام AudioCraft من Meta، مما يسمح بالتحكم في إنشاء الموسيقى الشرطي للملحن، ونقل الأسلوب، ومخرجات الصوت الاستريو مع MusicGen، AudioGen، و EnCodec"},"useCases":{"en":["Generating background music for videos from descriptive text","Creating sound effects and environmental audio for immersive experiences","Building music generation applications with controllable style transfer"],"zh":["为视频从描述性文本生成背景音乐","为沉浸式体验创建音效和环境音频","使用可控风格转换构建音乐生成应用程序"],"ja":["ビデオの説明的なテキストからバックグラウンドミュージックを生成する","没入型体験のために音効と環境オーディオを作成する","制御可能なスタイル転送を使用して音楽生成アプリケーションを構築する"],"ko":["비디오의 설명적 텍스트에서 배경 음악을 생성하는 것","몰입형 경험을 위한 사운드 이펙트와 환경 오디오를 생성하는 것","제어 가능한 스타일 전환을 사용하여 음악 생성 애플리케이션을 구축하는 것"],"es":["Generar música de fondo para videos a partir de texto descriptivo","Crear efectos de sonido y audio ambiental para experiencias inmersivas","Construir aplicaciones de generación de música con transferencia de estilo controlable"],"fr":["Générer de la musique de fond pour des vidéos à partir de texte descriptif","Créer des effets sonores et de l''audio environnemental pour des expériences immersives","Construire des applications de génération de musique avec un transfert de style contrôlable"],"de":["Erzeugen von Hintergrundmusik für Videos aus beschreibendem Text","Erstellen von Soundeffekten und Umgebungsaudio für immersive Erfahrungen","Aufbau von Musikgenerierungsanwendungen mit steuerbarer Stilübertragung"],"pt":["Gerar música de fundo para vídeos a partir de texto descritivo","Criar efeitos sonoros e áudio ambiental para experiências imersivas","Construir aplicações de geração de música com transferência de estilo controlável"],"ru":["Генерация фоновой музыки для видео из описательного текста","Создание звуковых эффектов и ambiente аудио для погружающих trải nghiệm","Построение приложений для генерации музыки с контролируемым переносом стиля"],"ar":["إنشاء موسيقى الخلفية للفيديوهات من النص الوصفي","إنشاء الأصوات والصوت البيئي للتجارب الغامرة","بناء تطبيقات إنشاء الموسيقى بنقل الأسلوب القابل للتحكم"]},"limitations":{"en":["Requires text descriptions as input","Limited to music and audio generation tasks","Dependent on Meta''s AudioCraft and its supported libraries"],"zh":["需要文本描述作为输入","仅限音乐和音频生成任务","依赖于Meta的AudioCraft及其支持的库"],"ja":["入力としてテキストの説明が必要","音楽とオーディオ生成タスクのみ","MetaのAudioCraftとそのサポートライブラリに依存"],"ko":["입력으로서 텍스트 설명이 필요","음악 및 오디오 생성 작업에만 한정","Meta의 AudioCraft 및 지원 라이브러리에 의존"],"es":["Requiere descripciones de texto como entrada","Limitado a tareas de generación de música y audio","Dependiente de AudioCraft de Meta y sus bibliotecas compatibles"],"fr":["Nécessite des descriptions de texte comme entrée","Limité aux tâches de génération de musique et d''audio","Dépendant d''AudioCraft de Meta et de ses bibliothèques prises en charge"],"de":["Benötigt Textbeschreibungen als Eingabe","Begrenzt auf Musik- und Audioerzeugungsaufgaben","Abhängig von Meta''s AudioCraft und seinen unterstützten Bibliotheken"],"pt":["Requer descrições de texto como entrada","Limitado a tarefas de geração de música e áudio","Dependente do AudioCraft da Meta e suas bibliotecas suportadas"],"ru":["Требует текстовых описаний в качестве входных данных","Ограничен задачами генерации музыки и аудио","Зависит от AudioCraft от Meta и его поддерживаемых библиотек"],"ar":["يتطلب وصف النص作为 مدخلات","محدود بمهام إنشاء الموسيقى والصوت","يعتمد على AudioCraft من Meta ومكتباتها المدعومة"]},"version":4},"contentHash":"3f9efaebd7331bea86022a101329074c6eab8af2d33591e691c565fcba641a5f","qualityScore":61}');
