INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mohammedatiaa/ai-project-network/audiocraft-audio-generation', 'audiocraft-audio-generation', 'mohammedatiaa', 'ai-project-network', 'community', 'audiocraft-audio-generation mohammedatiaa ai-project-network community Audiocraft-audio-generation is a tool for developers to generate music and audio from text descriptions, ideal for building music generation applications and creating sound effects. AudioCraft是一种强大的音频生成工具，支持文本到音乐和音频的转换 AudioCraftは、音楽と音声の生成を可能にするAIエージェントです AudioCraft는 텍스트를 음악이나 오디오로 변환하는 강력한 오디오 생성 도구입니다 AudioCraft es una herramienta de generación de audio que permite crear música y sonidos a partir de descripciones de texto. AudioCraft est un outil de génération audio qui permet de créer de la musique et des sons à partir de descriptions textuelles. AudioCraft ist ein Tool zur Audiogenerierung, mit dem Musik und Sounds aus Textbeschreibungen erstellt werden können. O AudioCraft é uma ferramenta de geração de áudio que permite criar música e efeitos sonoros a partir de textos AudioCraft - это инструмент генерации аудио, который позволяет создавать музыку и звуковые эффекты из текстов AudioCraft هو أداة لإنشاء الصوت التي تمكن من إنشاء الموسيقى والأصوات من النصوص how to use audiocraft-audio-generation audiocraft-audio-generation alternative audiocraft-audio-generation setup guide what is audiocraft-audio-generation audiocraft-audio-generation vs Amper Music audiocraft-audio-generation install text-to-music generation audio generation tools music generation applications AudioCraft音频生成 MusicGen AudioGen EnCodec 文本到音乐 音频生成工具 AI音频生成 Generates music from text descriptions using MusicGen Creates sound effects and environmental audio with AudioGen Supports melody-conditioned music generation Produces stereo audio output Allows controllable music generation with style transfer using EnCodec audiocraft-audio-generation is a comprehensive guide to using Meta''s AudioCraft for text-to-music and text-to-audio generation with MusicGen, AudioGen, and EnCodec.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('agentuity/sdk-explorer/agentuity-cli-cloud-deploy', 'community', 'agentuity', 'sdk-explorer', 'agentuity/sdk-explorer', 'agentuity-cli-cloud-deploy', 0, 0, 61, '2026-03-08T01:57:15.331Z', '2026-03-08T02:03:12.872Z', 'c31af1d7dd8bd3eba2cb61aced17b3a6ef4f3a106809dbc907576f5c11e26212', '{"id":"agentuity/sdk-explorer/agentuity-cli-cloud-deploy","name":"agentuity-cli-cloud-deploy","description":{"en":"The agentuity-cli-cloud-deploy skill enables developers to deploy projects to the Agentuity Cloud. It requires authentication with `agentuity auth login` and a project context.","zh":"Agentuity CLI 云部署是一种将项目部署到 Agentuity 云的方法，需要身份验证和项目上下文","ja":"Agentuity CLI クラウドデプロイは、プロジェクトを Agentuity クラウドにデプロイする方法であり、認証とプロジェクトコンテキストが必要です","ko":"Agentuity CLI 클라우드 배포는 프로젝트를 Agentuity 클라우드에 배포하는 방법으로 인증과 프로젝트 컨텍스트가 필요합니다","es":"El proyecto de demostración Agentuity CLI Cloud Deploy muestra cómo desplegar proyectos en la nube de Agentuity.","fr":"Le projet de démonstration Agentuity CLI Cloud Deploy montre comment déployer des projets sur le cloud Agentuity.","de":"Das Demo-Projekt Agentuity CLI Cloud Deploy zeigt, wie man Projekte in der Agentuity-Cloud bereitstellt.","pt":"O Agentuity CLI Cloud Deploy é uma ferramenta de demonstração que mostra como implantar projetos no Agentuity Cloud. Requer autenticação e contexto de projeto","ru":"Agentuity CLI Cloud Deploy — это демонстрационный проект, показывающий, как развернуть проекты в Agentuity Cloud. Требуется аутентификация и контекст проекта для ИИ Агентов","ar":"Agentuity CLI Cloud Deploy هو مشروع تجريبي يظهر كيفية نشر مشاريع على Agentuity Cloud. يتطلب المصادقة وسياق المشروع لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"agentuity-cli-cloud-deploy: Cloud Deployment Setup Guide ...","zh":"Agentuity CLI 云部署设置指南 - AIエージェント工具","ja":"Agentuity CLI クラウドデプロイセットアップガイド - AIエージェント","ko":"Agentuity CLI 클라우드 배포 설정 가이드 - AI 에이전트","es":"Guía de configuración de Agentuity CLI Cloud Deploy","fr":"Guide de mise en place d''Agentuity CLI Cloud Deploy","de":"Einrichtungsleitfaden für Agentuity CLI Cloud Deploy","pt":"Guia de Configuração do Agentuity CLI Cloud Deploy","ru":"Руководство по настройке Agentuity CLI Cloud Deploy для И...","ar":"دليل إعداد Agentuity CLI Cloud Deploy لأدوات الذكاء الاصط..."},"description":{"en":"Discover how to deploy projects to the Agentuity Cloud with the agentuity-cli-cloud-deploy skill. Learn more and get started with our setup guide.","zh":"了解如何使用 Agentuity CLI 云部署功能将项目部署到云端，包括身份验证、项目上下文和 CI 日志 URL","ja":"Agentuity CLI クラウドデプロイ機能を使用してプロジェクトをクラウドにデプロイする方法について説明します。認証、プロジェクトコンテキスト、CI ログ URL を含みます","ko":"Agentuity CLI 클라우드 배포 기능을 사용하여 프로젝트를 클라우드에 배포하는 방법에 대해 설명합니다. 인증, 프로젝트 컨텍스트, CI 로그 URL을 포함합니다","es":"Despliegue de proyectos en la nube de Agentuity con la CLI. Obtenga información sobre los requisitos previos y las opciones de implementación.","fr":"Déployez des projets sur le cloud Agentuity avec la CLI. Découvrez les prérequis et les options de déploiement.","de":"Bereitstellen von Projekten in der Agentuity-Cloud mit der CLI. Erfahren Sie mehr über die Voraussetzungen und Bereitstellungsoptionen.","pt":"Aprenda a implantar projetos no Agentuity Cloud com o CLI Cloud Deploy. Veja como autenticar e configurar o ambiente de desenvolvimento","ru":"Узнайте, как развернуть проекты в Agentuity Cloud с помощью CLI Cloud Deploy. См. как аутентифицироваться и настроить среду разработки для ИИ Агентов","ar":"تعلم كيفية نشر مشاريع على Agentuity Cloud باستخدام CLI Cloud Deploy. انظر كيفية المصادقة وتكوين بيئة التطوير لأدوات الذكاء الاصطناعي"},"definition":{"en":"agentuity-cli-cloud-deploy is a demo project showcasing the Agentuity platform''s SDK, tools, and runtime for cloud deployment.","zh":"Agentuity CLI 云部署是 Agentuity 平台的一部分，用于将项目部署到云端","ja":"Agentuity CLI クラウドデプロイは、Agentuity プラットフォームの一部であり、プロジェクトをクラウドにデプロイするために使用されます","ko":"Agentuity CLI 클라우드 배포는 Agentuity 플랫폼의 일부로 프로젝트를 클라우드에 배포하는 데 사용됩니다","es":"Agentuity CLI Cloud Deploy es una herramienta de línea de comandos para desplegar proyectos en la nube de Agentuity.","fr":"Agentuity CLI Cloud Deploy est un outil en ligne de commande pour déployer des projets sur le cloud Agentuity.","de":"Agentuity CLI Cloud Deploy ist ein Befehlszeilen-Tool zum Bereitstellen von Projekten in der Agentuity-Cloud.","pt":"O que é Agentuity CLI Cloud Deploy? É uma ferramenta de linha de comando para implantar projetos no Agentuity Cloud","ru":"Что такое Agentuity CLI Cloud Deploy? Это командная строка для развертывания проектов в Agentuity Cloud для ИИ Агентов","ar":"ما هو Agentuity CLI Cloud Deploy؟ إنه أداة سطر الأوامر لنشر مشاريع على Agentuity Cloud لأدوات الذكاء الاصطناعي"},"features":{"en":["Deploys projects to the Agentuity Cloud using `agentuity cloud deploy` command","Requires authentication with `agentuity auth login` for secure deployment","Supports project context via `--project-id` option","Accepts CI build logs URL via `--logsUrl` option","Allows specification of trigger type via `--trigger` option","Defaults to `cli` trigger type if not specified"],"zh":["支持身份验证和项目上下文","可以指定 CI 日志 URL","支持触发器配置","使用 CLI 命令进行云部署","需要项目目录或项目 ID","支持多种选项配置"],"ja":["認証とプロジェクトコンテキストをサポート","CI ログ URL を指定可能","トリガー設定をサポート","CLI コマンドを使用したクラウドデプロイ","プロジェクトディレクトリまたはプロジェクト ID が必要","複数のオプション設定をサポート"],"ko":["인증과 프로젝트 컨텍스트를 지원","CI 로그 URL을 지정할 수 있음","트리거 설정을 지원","CLI 명령어를 사용한 클라우드 배포","프로젝트 디렉토리 또는 프로젝트 ID가 필요","다수의 옵션 설정을 지원"],"es":["Despliegue de proyectos en la nube de Agentuity","Autenticación con `agentuity auth login`","Requisitos de contexto de proyecto","Opción `--logsUrl` para la URL de los registros de construcción de CI","Opción `--trigger` para el desencadenador de implementación","Compatibilidad con la plataforma Agentuity (SDK, herramientas y tiempo de ejecución)"],"fr":["Déploiement de projets sur le cloud Agentuity","Authentification avec `agentuity auth login`","Exigences de contexte de projet","Option `--logsUrl` pour l''URL des journaux de construction de CI","Option `--trigger` pour le déclencheur de déploiement","Compatibilité avec la plateforme Agentuity (SDK, outils et runtime)"],"de":["Bereitstellung von Projekten in der Agentuity-Cloud","Authentifizierung mit `agentuity auth login`","Voraussetzungen für den Projekt-Kontext","Option `--logsUrl` für die URL der CI-Build-Protokolle","Option `--trigger` für den Bereitstellungs-Trigger","Kompatibilität mit der Agentuity-Plattform (SDK, Tools und Laufzeit)"],"pt":["Autenticação com `agentuity auth login`","Requer contexto de projeto (executar a partir do diretório do projeto ou usar `--project-id`)","Opção `--logsUrl` para URL dos logs de build do CI","Opção `--trigger` para gatilho de implantação","Suporte à implantação de projetos no Agentuity Cloud","Interface de linha de comando para implantação simplificada"],"ru":["Аутентификация с `agentuity auth login`","Требуется контекст проекта (выполнить из директории проекта или использовать `--project-id`)","Опция `--logsUrl` для URL логов сборки CI","Опция `--trigger` для триггера развертывания","Поддержка развертывания проектов в Agentuity Cloud для ИИ Агентов","Интерфейс командной строки для упрощенного развертывания"],"ar":["المصادقة مع `agentuity auth login`","يتطلب سياق المشروع (تشغيل من دليل المشروع أو استخدام `--project-id`)","خيار `--logsUrl` لعنوان URL لسجلات بناء CI","خيار `--trigger` للتحفيز على النشر","دعم نشر المشاريع على Agentuity Cloud لأدوات الذكاء الاصطناعي","واجهة سطر الأوامر لنشر مبسط"]},"keywords":{"en":["how to use agentuity-cli-cloud-deploy","agentuity-cli-cloud-deploy setup guide","agentuity-cli-cloud-deploy alternative","agentuity-cli-cloud-deploy vs AWS","agentuity-cli-cloud-deploy install","what is agentuity-cli-cloud-deploy","agentuity-cli-cloud-deploy documentation","agentuity-cli-cloud-deploy tutorial","agentuity cloud deployment","agentuity cli commands"],"zh":["Agentuity CLI 云部署","AIエージェント工具","云部署设置","项目部署","身份验证","项目上下文","CI 日志 URL","触发器配置","CLI 命令"],"ja":["Agentuity CLI クラウドデプロイ","AIエージェント","クラウドデプロイセットアップ","プロジェクトデプロイ","認証","プロジェクトコンテキスト","CI ログ URL","トリガー設定","CLI コマンド"],"ko":["Agentuity CLI 클라우드 배포","AI 에이전트","클라우드 배포 설정","프로젝트 배포","인증","프로젝트 컨텍스트","CI 로그 URL","트리거 설정","CLI 명령어"],"es":["Agentuity CLI","despliegue en la nube","herramientas de línea de comandos","desarrollo de proyectos","plataforma Agentuity","SDK Agentuity","herramientas de desarrollo","despliegue de proyectos en la nube","autenticación en la nube","registros de construcción de CI"],"fr":["Agentuity CLI","déploiement sur le cloud","outils en ligne de commande","développement de projets","plateforme Agentuity","SDK Agentuity","outils de développement","déploiement de projets sur le cloud","authentification sur le cloud","journaux de construction de CI"],"de":["Agentuity CLI","Bereitstellung in der Cloud","Befehlszeilen-Tools","Projektentwicklung","Agentuity-Plattform","Agentuity-SDK","Entwicklungstools","Bereitstellung von Projekten in der Cloud","Authentifizierung in der Cloud","CI-Build-Protokolle"],"pt":["Agentuity CLI Cloud Deploy","implantação de projetos no Agentuity Cloud","autenticação com Agentuity","contexto de projeto Agentuity","opções de implantação Agentuity","ferramentas de desenvolvimento Agentuity","Agentuity para desenvolvedores","guias de configuração Agentuity","implantação de projetos com CLI"],"ru":["Agentuity CLI Cloud Deploy","развертывание проектов в Agentuity Cloud","аутентификация с Agentuity","контекст проекта Agentuity","опции развертывания Agentuity","инструменты разработки Agentuity","Agentuity для разработчиков","руководства по настройке Agentuity","развертывание проектов с помощью CLI для ИИ Агентов"],"ar":["Agentuity CLI Cloud Deploy","نشر مشاريع على Agentuity Cloud","المصادقة مع Agentuity","سياق المشروع Agentuity","خيارات نشر Agentuity","أدوات تطوير Agentuity","Agentuity للمطورين","دلائل إعداد Agentuity","نشر مشاريع باستخدام CLI لأدوات الذكاء الاصطناعي"]}},"owner":"agentuity","repo":"sdk-explorer","repoPath":"agentuity/sdk-explorer","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.331Z","topics":[],"category":"community","skillMd":{"name":"agentuity-cli-cloud-deploy","description":"Deploy project to the Agentuity Cloud. Requires authentication. Use for Agentuity cloud platform operations","version":"0.1.2","tags":"mutating creates-resource slow api-intensive requires-auth requires-project","bodyPreview":"# Cloud Deploy\n\nDeploy project to the Agentuity Cloud\n\n## Prerequisites\n\n- Authenticated with `agentuity auth login`\n- Project context required (run from project directory or use `--project-id`)\n- auth login\n\n## Usage\n\n```bash\nagentuity cloud deploy [options]\n```\n\n## Options\n\n| Option | Type | Required | Default | Description |\n|--------|------|----------|---------|-------------|\n| `--logsUrl` | string | Yes | - | The url to the CI build logs |\n| `--trigger` | string | No | `\"cli\"` | The trigger","body":"# Cloud Deploy\n\nDeploy project to the Agentuity Cloud\n\n## Prerequisites\n\n- Authenticated with `agentuity auth login`\n- Project context required (run from project directory or use `--project-id`)\n- auth login\n\n## Usage\n\n```bash\nagentuity cloud deploy [options]\n```\n\n## Options\n\n| Option | Type | Required | Default | Description |\n|--------|------|----------|---------|-------------|\n| `--logsUrl` | string | Yes | - | The url to the CI build logs |\n| `--trigger` | string | No | `\"cli\"` | The trigger that caused the build |\n| `--commitUrl` | string | Yes | - | The url to the CI commit |\n| `--message` | string | Yes | - | The message to associate with this deployment |\n| `--commit` | string | Yes | - | The commit SHA for this deployment |\n| `--branch` | string | Yes | - | The git branch for this deployment |\n| `--provider` | string | Yes | - | The CI provider name (attempts to autodetect) |\n| `--repo` | string | Yes | - | The repo url |\n| `--event` | string | No | `\"manual\"` | The event that triggered the deployment |\n| `--pullRequestNumber` | number | Yes | - | the pull request number |\n| `--pullRequestUrl` | string | Yes | - | the pull request url |\n| `--reportFile` | string | Yes | - | file path to save build report JSON with errors, warnings, and diagnostics |\n| `--childMode` | boolean | No | `false` | Internal: run as forked child process |\n\n## Examples\n\nDeploy current project:\n\n```bash\nbunx @agentuity/cli cloud deploy\n```\n\nDeploy with verbose output:\n\n```bash\nbunx @agentuity/cli cloud deploy --log-level=debug\n```\n\n## Output\n\nReturns JSON object:\n\n```json\n{\n  \"success\": \"boolean\",\n  \"deploymentId\": \"string\",\n  \"projectId\": \"string\",\n  \"logs\": \"array\",\n  \"urls\": \"object\"\n}\n```\n\n| Field | Type | Description |\n|-------|------|-------------|\n| `success` | boolean | Whether deployment succeeded |\n| `deploymentId` | string | Deployment ID |\n| `projectId` | string | Project ID |\n| `logs` | array | The deployment startup logs |\n| `urls` | object | Deployment URLs |\n"},"lastSynced":"2026-03-08T02:03:12.872Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Deployment Agents needing streamlined project deployment to the Agentuity Cloud.","zh":"适合需要将项目部署流程简化到 Agentuity Cloud 的云部署代理。","ja":"Agentuity Cloud へのプロジェクトのデプロイを簡素化する必要があるクラウドデプロイエージェントに最適です。","ko":"프로젝트 배포 과정을 Agentuity Cloud로 단순화해야 하는 클라우드 배포 에이전트에 적합합니다.","es":"Perfecto para Agentes de Despliegue en la Nube que necesitan un despliegue de proyecto optimizado en la Nube de Agentuity.","fr":"Parfait pour les Agents de déploiement Cloud nécessitant un déploiement de projet simplifié sur le Cloud d''Agentuity.","de":"Perfekt für Cloud-Deployment-Agents, die ein optimiertes Projekt-Deployment in der Agentuity-Cloud benötigen.","pt":"Perfeito para Agentes de Implantação em Nuvem que necessitam de implantação de projeto otimizada para a Nuvem da Agentuity.","ru":"Идеально подходит для агентов облачной развертки, которым требуется оптимизированная развертка проекта в облаке Agentuity.","ar":"مثالي للوكلاء النشر السحابي الذين يحتاجون إلى نشر مشروع مبسط إلى سحابة Agentuity."},"recommendation":{"en":"Empowers agents to deploy projects to the Agentuity Cloud using the `agentuity cloud deploy` command, providing options for specifying logs URL and trigger, while requiring authentication with `agentuity auth login` and a project context.","zh":"赋予代理部署项目到 Agentuity Cloud 的能力，使用 `agentuity cloud deploy` 命令，并提供指定日志 URL 和触发器的选项，同时需要使用 `agentuity auth login` 进行身份验证和项目上下文。","ja":"エージェントが `agentuity cloud deploy` コマンドを使用して Agentuity Cloud にプロジェクトをデプロイできるようにし、ログ URL とトリガーの指定オプションを提供しながら、`agentuity auth login` とプロジェクト コンテキストによる認証を要求します。","ko":"에이전트가 `agentuity cloud deploy` 명령을 사용하여 Agentuity Cloud에 프로젝트를 배포할 수 있도록 하며, 로그 URL 및 트리거를 지정하는 옵션을 제공同时, `agentuity auth login` 및 프로젝트 컨텍스트를 통한 인증을 요구합니다.","es":"Habilita a los agentes a implementar proyectos en la Nube de Agentuity utilizando el comando `agentuity cloud deploy`, que ofrece opciones para especificar la URL de los registros y el disparador, y que requiere autenticación con `agentuity auth login` y un contexto de proyecto.","fr":"Permet aux agents de déployer des projets sur le Cloud d''Agentuity en utilisant la commande `agentuity cloud deploy`, qui offre des options pour spécifier l''URL des journaux et le déclencheur, tout en nécessitant une authentification avec `agentuity auth login` et un contexte de projet.","de":"Ermöglicht es Agenten, Projekte in der Agentuity-Cloud mithilfe des Befehls `agentuity cloud deploy` zu deployen, der Optionen zum Festlegen der Protokoll-URL und des Triggers bietet und eine Authentifizierung mit `agentuity auth login` sowie einen Projekt-Kontext erfordert.","pt":"Habilita os agentes a implantarem projetos na Nuvem da Agentuity usando o comando `agentuity cloud deploy`, fornecendo opções para especificar URL de logs e gatilho, enquanto requer autenticação com `agentuity auth login` e um contexto de projeto.","ru":"Позволяет агентам развертывать проекты в облаке Agentuity с помощью команды `agentuity cloud deploy`, предоставляя опции для указания URL журналов и триггера, при этом требуя аутентификации с помощью `agentuity auth login` и контекста проекта.","ar":"تمكين الوكلاء من نشر المشاريع إلى سحابة Agentuity باستخدام الأمر `agentuity cloud deploy` ، مع خيارات لتحديد URL السجلات والزناد ، مع الحاجة إلى مصادقة باستخدام `agentuity auth login` وسياق المشروع."},"useCases":{"en":["Deploying projects to the Agentuity Cloud from a project directory","Specifying custom logs URL for CI build logs","Triggering deployments from the command line interface"],"zh":["从项目目录将项目部署到 Agentuity Cloud","为 CI 构建日志指定自定义日志 URL","从命令行界面触发部署"],"ja":["プロジェクト ディレクトリから Agentuity Cloud にプロジェクトをデプロイする","CI ビルド ログのカスタム ログ URL を指定する","コマンドライン インターフェイスからデプロイをトリガーする"],"ko":["프로젝트 디렉토리에서 Agentuity Cloud로 프로젝트를 배포하는 것","CI 빌드 로그를 위한 사용자 지정 로그 URL을 지정하는 것","명령줄 인터페이스에서 배포를 트리거하는 것"],"es":["Implementar proyectos en la Nube de Agentuity desde un directorio de proyecto","Especificar una URL de registros personalizada para registros de compilación de CI","Disparar implementaciones desde la interfaz de línea de comandos"],"fr":["Déployer des projets sur le Cloud d''Agentuity à partir d''un répertoire de projet","Spécifier une URL de journaux personnalisée pour les journaux de build de CI","Déclencher des déploiements depuis l''interface de ligne de commande"],"de":["Projekte in der Agentuity-Cloud aus einem Projektverzeichnis bereitzustellen","Eine benutzerdefinierte Protokoll-URL für CI-Build-Protokolle anzugeben","Deployments über die Befehlszeilen-Schnittstelle auszulösen"],"pt":["Implantação de projetos na Nuvem da Agentuity a partir de um diretório de projeto","Especificar URL de logs personalizados para logs de build de CI","Disparar implantações a partir da interface de linha de comando"],"ru":["Развертка проектов в облаке Agentuity из каталога проекта","Указание настраиваемого URL журналов для журналов сборки CI","Запуск развертки из командной строки"],"ar":["نشر المشاريع إلى سحابة Agentuity من مجلد المشروع","تحديد URL السجلات المخصصة لسجلات بناء CI","تشغيل النشر من واجهة سطر الأوامر"]},"limitations":{"en":["Requires authentication with `agentuity auth login`","Project context required","Limited to deploying to the Agentuity Cloud"],"zh":["需要使用 `agentuity auth login` 进行身份验证","需要项目上下文","仅限部署到 Agentuity Cloud"],"ja":["`agentuity auth login` による認証が必要","プロジェクト コンテキストが必要","Agentuity Cloud へのデプロイのみに限定される"],"ko":["`agentuity auth login`을 통한 인증이 필요","프로젝트 컨텍스트가 필요","Agentuity Cloud로의 배포만 가능"],"es":["Requiere autenticación con `agentuity auth login`","Se requiere un contexto de proyecto","Limitado a la implementación en la Nube de Agentuity"],"fr":["Nécessite une authentification avec `agentuity auth login`","Un contexte de projet est requis","Limité au déploiement sur le Cloud d''Agentuity"],"de":["Erfordert Authentifizierung mit `agentuity auth login`","Ein Projekt-Kontext ist erforderlich","Begrenzt auf die Bereitstellung in der Agentuity-Cloud"],"pt":["Exige autenticação com `agentuity auth login`","Contexto de projeto necessário","Limitado à implantação na Nuvem da Agentuity"],"ru":["Требует аутентификации с помощью `agentuity auth login`","Требуется контекст проекта","Ограничен разверткой в облаке Agentuity"],"ar":["يتطلب مصادقة باستخدام `agentuity auth login`","مطلوب سياق المشروع","محدود بنشر إلى سحابة Agentuity"]},"version":4},"contentHash":"c31af1d7dd8bd3eba2cb61aced17b3a6ef4f3a106809dbc907576f5c11e26212","qualityScore":61}');
