INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('catlog22/Claude-Code-Workflow/workflow-multi-cli-plan', 'workflow-multi-cli-plan', 'catlog22', 'Claude-Code-Workflow', 'community', 'workflow-multi-cli-plan catlog22 Claude-Code-Workflow community claude claude-code cli-tools codex context-management gemini-cli json-driven qwen-code task-orchestration workflow-automation workflow-multi-cli-plan是一个JSON驱动的多代理开发框架，具有智能CLI编排和自动化工作流执行 workflow-multi-cli-planはJSON駆動のマルチエージェント開発フレームワーク、智能CLIオーケストレーション、自動化ワークフロー実行 workflow-multi-cli-plan은 JSON으로 구동되는 멀티 에이전트 개발 프레임워크로 지능형 CLI 오케스트레이션 및 자동화 워크플로 실행을 제공합니다 Marco de desarrollo de equipo cadence con orquestación de CLI inteligente y ejecución de flujos de trabajo automatizada Cadre de développement d''équipe cadence avec orchestration de CLI intelligente et exécution de flux de travail automatisée Entwicklungsrahmen für Teams mit intelligenter CLI-Orchestrierung und automatisierter Workflow-Ausführung O workflow-multi-cli-plan é um framework de desenvolvimento de equipe de cadência JSON-driven com orquestração de CLI inteligente e automação de fluxo de trabalho ИИ Агенты: workflow-multi-cli-plan - фреймворк командной разработки с интеллектуальной оркестрацией CLI и автоматизацией рабочих процессов أدوات العميل الذكي: workflow-multi-cli-plan هو إطار عمل تطوير الفريق الإيقاعي مع توجيه CLI الذكي وتutomatisation تدفق العمل JSON-driven multi-agent cadence-team development framework with intelligent CLI orchestration (Gemini/Qwen/Codex), context-first architecture, and automated workflow execution AIエージェント工具 工作流开发框架 智能CLI编排 自动化工作流执行 JSON驱动的开发 Gemini、Qwen、Codex 上下文优先架构 如何使用workflow-multi-cli-plan workflow-multi-cli-plan安装指南 JSON-driven multi-agent cadence-team development framework with intelligent CLI orchestration (Gemini/Qwen/Codex), context-first architecture, and automated workflow execution');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers/executing-plans', 'official', 'obra', 'superpowers', 'obra/superpowers', 'executing-plans', 71924, 5546, 61, '2026-03-06T03:26:30Z', '2026-03-06T03:29:28.755Z', 'd099fa42fd7518f4dafa9f2d51c1c08fce970490d57682b6acd3e7a57bb55b52', '{"id":"obra/superpowers/executing-plans","name":"executing-plans","description":{"en":"The executing-plans skill enables AI agents to systematically implement a written plan by executing tasks in batches and pausing for architect review between them. It is designed for developers and architects who require a controlled, review-driven development process.","zh":"executing-plans 是一项AI代理技能，专为执行书面技术实施方案而设计。其核心是在分批次执行任务的过程中，设置架构审查检查点，以确保实施质量并与人类伙伴协作。","ja":"executing-plansは、書かれた実装計画を実行するためのAIエージェントスキルです。バッチ単位でのタスク実行とアーキテクトレビューのチェックポイントを設け、実施品質を確保し人間パートナーと協力することを原則とします。","ko":"executing-plans는 작성된 구현 계획을 실행하기 위한 AI 에이전트 스킬입니다. 배치별 작업 실행과 아키텍트 리뷰를 위한 체크포인트를 설정하여 구현 품질을 보장하고 인간 파트너와 협력하는 것을 핵심 원칙으로 합니다.","es":"La habilidad executing-plans permite a un agente de IA implementar un plan escrito ejecutando tareas en lotes con puntos de control integrados para una revisión crítica por parte de un arquitecto humano. El proceso incluye cargar el plan, identificar problemas potenciales y reportar después de ca...","fr":"La compétence executing-plans permet à un agent IA d''exécuter un plan écrit en traitant les tâches par lots avec des points de contrôle pour une revue critique par un architecte humain. Le processus comprend le chargement du plan, l''identification des problèmes et le reporting après chaque lot.","de":"Die executing-plans-Fähigkeit ermöglicht es einem KI-Agenten, einen schriftlichen Plan durchzuführen, indem Aufgaben in Batches mit integrierten Checkpoints für ein kritisches Review durch einen menschlichen Architekten ausgeführt werden. Der Prozess umfasst das Laden des Plans, das Identifiziere...","pt":"O skill Executing-Plans permite executar planos de implementação em lotes com checkpoints de revisão","ru":"Навык Executing-Plans позволяет выполнять планы реализации партиями с контрольными точками","ar":"تمكن مهارة Executing-Plans من تنفيذ خطط التنفيذ بشكل محظوظ مع نقاط فحص"},"owner":"obra","repo":"superpowers","repoPath":"obra/superpowers","stars":71924,"forks":5546,"updatedAt":"2026-03-06T03:26:30Z","topics":[],"skillMd":{"name":"executing-plans","description":"Use when you have a written implementation plan to execute in a separate session with review checkpoints","bodyPreview":"# Executing Plans\n\n## Overview\n\nLoad plan, review critically, execute tasks in batches, report for review between batches.\n\n**Core principle:** Batch execution with checkpoints for architect review.\n\n**Announce at start:** \"I''m using the executing-plans skill to implement this plan.\"\n\n## The Process\n\n### Step 1: Load and Review Plan\n1. Read plan file\n2. Review critically - identify any questions or concerns about the plan\n3. If concerns: Raise them with your human partner before starting\n4. If n","body":"# Executing Plans\n\n## Overview\n\nLoad plan, review critically, execute tasks in batches, report for review between batches.\n\n**Core principle:** Batch execution with checkpoints for architect review.\n\n**Announce at start:** \"I''m using the executing-plans skill to implement this plan.\"\n\n## The Process\n\n### Step 1: Load and Review Plan\n1. Read plan file\n2. Review critically - identify any questions or concerns about the plan\n3. If concerns: Raise them with your human partner before starting\n4. If no concerns: Create TodoWrite and proceed\n\n### Step 2: Execute Batch\n**Default: First 3 tasks**\n\nFor each task:\n1. Mark as in_progress\n2. Follow each step exactly (plan has bite-sized steps)\n3. Run verifications as specified\n4. Mark as completed\n\n### Step 3: Report\nWhen batch complete:\n- Show what was implemented\n- Show verification output\n- Say: \"Ready for feedback.\"\n\n### Step 4: Continue\nBased on feedback:\n- Apply changes if needed\n- Execute next batch\n- Repeat until complete\n\n### Step 5: Complete Development\n\nAfter all tasks complete and verified:\n- Announce: \"I''m using the finishing-a-development-branch skill to complete this work.\"\n- **REQUIRED SUB-SKILL:** Use superpowers:finishing-a-development-branch\n- Follow that skill to verify tests, present options, execute choice\n\n## When to Stop and Ask for Help\n\n**STOP executing immediately when:**\n- Hit a blocker mid-batch (missing dependency, test fails, instruction unclear)\n- Plan has critical gaps preventing starting\n- You don''t understand an instruction\n- Verification fails repeatedly\n\n**Ask for clarification rather than guessing.**\n\n## When to Revisit Earlier Steps\n\n**Return to Review (Step 1) when:**\n- Partner updates the plan based on your feedback\n- Fundamental approach needs rethinking\n\n**Don''t force through blockers** - stop and ask.\n\n## Remember\n- Review plan critically first\n- Follow plan steps exactly\n- Don''t skip verifications\n- Reference skills when plan says to\n- Between batches: just report and wait\n- Stop when blocked, don''t guess\n- Never start implementation on main/master branch without explicit user consent\n\n## Integration\n\n**Required workflow skills:**\n- **superpowers:using-git-worktrees** - REQUIRED: Set up isolated workspace before starting\n- **superpowers:writing-plans** - Creates the plan this skill executes\n- **superpowers:finishing-a-development-branch** - Complete development after all tasks\n"},"category":"official","lastSynced":"2026-03-06T03:29:28.755Z","seo":{"title":{"en":"executing-plans: Batch Execution with Checkpoints | AI Ag...","zh":"executing-plans AI代理技能：批量执行与架构审查指南","ja":"executing-plans AIエージェントスキル：バッチ実行とレビューチェックポイント","ko":"executing-plans AI 에이전트 스킬: 배치 실행 및 아키텍트 리뷰 가이드","es":"executing-plans: Guía de Implementación con Puntos de Con...","fr":"executing-plans: Guide de Mise en Œuvre par Lots","de":"executing-plans: Leitfaden zur Batch-Ausführung mit Reviews","pt":"Guia de Configuração do Executing-Plans: Implementação de...","ru":"ИИ Агенты: Руководство по Настройке Executing-Plans для В...","ar":"دليل تنفيذ خطط Executing-Plans: تطبيق الخطط مع نقاط فحص"},"description":{"en":"Master the executing-plans AI agent skill for structured, batch-by-batch implementation. Learn how to load plan files, execute tasks in batches, and request ...","zh":"学习如何利用executing-plans AI代理技能，通过批量执行和架构师审查检查点来高效实施技术计划。包含计划加载、关键审查和分批次执行工作流程。","ja":"executing-plans AIエージェントスキルを使用して、バッチ実行とアーキテクトレビューチェックポイントで技術計画を効率的に実装する方法。計画の読み込み、批判的レビュー、バッチ処理のワークフローを解説。","ko":"executing-plans AI 에이전트 스킬을 사용하여 배치 실행과 아키텍트 리뷰 체크포인트로 기술 계획을 효율적으로 구현하는 방법. 계획 로드, 비판적 검토, 배치 작업 실행 워크플로우를 포함합니다.","es":"Habilidad de agente IA para ejecutar planes técnicos en lotes con puntos de revisión crítica. Aprende a cargar un plan, ejecutar tareas y reportar para revis...","fr":"Compétence d''agent IA pour exécuter des plans techniques par lots avec des points de contrôle. Apprenez à charger un plan, exécuter des tâches et rapporter p...","de":"KI-Agenten-Fähigkeit zur Batch-Ausführung von technischen Plänen mit kritischen Review-Punkten. Laden Sie einen Plan, führen Sie Aufgaben aus und berichten S...","pt":"Aprenda a usar o skill Executing-Plans para executar planos de implementação com checkpoints de revisão","ru":"Узнайте, как использовать навык Executing-Plans для выполнения планов реализации с контрольными точками","ar":"تعرف على كيفية استخدام مهارة Executing-Plans لتنفيذ خطط التنفيذ بنقاط فحص"},"definition":{"en":"executing-plans is an AI agent skill for executing a pre-written implementation plan. Its core principle is batch execution with checkpoints, requiring the agent to load a plan file, review it critically, and report for human partner review between batches.","zh":"executing-plans 是一种AI代理操作技能，用于在独立的会话中加载并执行书面技术计划。其工作流程包括加载计划、进行批判性审查、分批次执行任务，并在各批次之间设置报告审查点。","ja":"executing-plansは、別セッションで書かれた技術計画を実行するためのAIエージェント操作スキルです。計画の読み込み、批判的レビュー、バッチ単位でのタスク実行、バッチ間の報告レビューチェックポイントを含むワークフローです。","ko":"executing-plans는 별도 세션에서 작성된 기술 계획을 실행하기 위한 AI 에이전트 운영 스킬입니다. 계획 로드, 비판적 검토, 배치별 작업 실행, 배치 간 리뷰 체크포인트 보고를 포함하는 워크플로우입니다.","es":"executing-plans es una habilidad técnica de agente de IA diseñada para la implementación automatizada de planes. Opera cargando un archivo de plan, ejecutando tareas en lotes discretos y solicitando revisiones humanas entre lotes para garantizar la precisión y alineación con los objetivos del proyecto.","fr":"executing-plans est une compétence technique d''agent IA conçue pour l''exécution automatisée de plans. Elle fonctionne en chargeant un fichier de plan, en exécutant des tâches par lots distincts et en demandant des révisions humaines entre les lots pour garantir la précision et l''alignement sur les objectifs du projet.","de":"executing-plans ist eine technische KI-Agenten-Fähigkeit zur automatisierten Ausführung von Plänen. Sie arbeitet, indem eine Plan datei geladen, Aufgaben in diskreten Batches ausgeführt und zwischen den Batches menschliche Überprüfungen angefordert werden, um Genauigkeit und Projektzielausrichtung sicherzustellen.","pt":"O que é Executing-Plans? É um skill que executa planos de implementação em lotes com checkpoints de revisão","ru":"Что такое Executing-Plans? Это навык, который выполняет планы реализации партиями с контрольными точками","ar":"ما هي مهارة Executing-Plans؟ هي مهارة تنفذ خطط التنفيذ بشكل محظوظ مع نقاط فحص"},"features":{"en":["Loads and reads from a dedicated plan file","Performs a critical review to identify questions or concerns about the plan","Executes implementation tasks in distinct batches","Reports for architect review between each batch of executed tasks","Announces skill usage at the start of a session"],"zh":["从文件加载书面实施计划","对计划进行批判性审查并识别潜在问题","在开始执行前与人类伙伴沟通疑虑","将任务分批次执行以提高效率","在批次之间设置架构师审查检查点","执行开始时明确声明使用 executing-plans 技能"],"ja":["ファイルからの書かれた実装計画の読み込み","計画の批判的レビューと潜在的問題の特定","実行前の人間パートナーへの懸念事項の報告","効率化のためのバッチ単位でのタスク実行","バッチ間のアーキテクトレビューチェックポイントの設定","実行開始時の executing-plans スキル使用の明確な宣言"],"ko":["파일에서 작성된 구현 계획 로드","계획에 대한 비판적 검토 및 잠재적 문제 식별","실행 전 인간 파트너와의疑虑 사항 커뮤니케이션","효율성을 위한 배치별 작업 실행","배치 간 아키텍트 리뷰 체크포인트 설정","실행 시작 시 executing-plans 스킬 사용 명시적 선언"],"es":["Carga y revisión crítica de archivos de plan de implementación","Ejecución por lotes (batches) de tareas técnicas","Puntos de control integrados para revisión del arquitecto","Anuncio de habilidad al inicio: \"I''m using the executing-plans skill\"","Identificación proactiva de problemas y preocupaciones en el plan","Reporte estructurado después de la ejecución de cada lote"],"fr":["Chargement et revue critique des fichiers de plan d''implémentation","Exécution par lots (batches) de tâches techniques","Points de contrôle intégrés pour la révision de l''architecte","Annonce de la compétence au début : \"I''m using the executing-plans skill\"","Identification proactive des problèmes et préoccupations dans le plan","Reporting structuré après l''exécution de chaque lot"],"de":["Laden und kritische Überprüfung von Implementierungsplan dateien","Batch-Ausführung technischer Aufgaben","Integrierte Checkpoints für Architekten-Reviews","Skill-Ankündigung zu Beginn: \"I''m using the executing-plans skill\"","Proaktive Identifizierung von Plan bedenken und Problemen","Strukturierte Berichterstattung nach jedem Ausführungs-Batch"],"pt":["Carga de planos de implementação","Revisão crítica de planos","Execução de tarefas em lotes","Checkpoints de revisão entre lotes","Integração com arquitetos para revisão"],"ru":["Загрузка планов реализации","Критическая проверка планов","Выполнение задач партиями","Контрольные точки между партиями","Интеграция с архитекторами для проверки"],"ar":["تحميل خطط التنفيذ","المراجعة النقدية للخطط","تنفيذ المهام بشكل محظوظ","نقاط فحص بين المحظوظات","التكامل مع المصممين للفحص"]},"keywords":{"en":["what is executing-plans","how to use executing-plans skill","executing-plans batch execution","executing-plans vs manual implementation","executing-plans setup guide","AI agent plan file format","architect review checkpoints","executing-plans implementation best practices"],"zh":["executing-plans AI代理","批量执行计划","架构审查检查点","AI代理技能指南","技术计划实施","分批次任务执行","计划加载与审查","AI开发工作流"],"ja":["executing-plans AIエージェント","バッチ実行計画","アーキテクトレビューチェックポイント","AIエージェントスキルガイド","技術計画実装","バッチ単位タスク実行","計画読み込みとレビュー","AI開発ワークフロー"],"ko":["executing-plans AI 에이전트","배치 실행 계획","아키텍트 리뷰 체크포인트","AI 에이전트 스킬 가이드","기술 계획 구현","배치별 작업 실행","계획 로드 및 검토","AI 개발 워크플로우"],"es":["agente IA executing-plans","ejecución de planes técnicos","batch processing IA","puntos de control revisión arquitecto","implementación plan automatizada","revisión crítica plan IA","herramientas IA desarrollo","automatización tareas técnicas"],"fr":["agent IA executing-plans","exécution de plans techniques","traitement par lots IA","points de contrôle révision architecte","implémentation plan automatisée","revue critique plan IA","outils IA développement","automatisation tâches techniques"],"de":["KI Agent executing-plans","Ausführung technischer Pläne","Batch-Verarbeitung KI","Checkpoints Architekten-Review","automatisierte Plan implementation","kritische Planprüfung KI","KI Tools Entwicklung","Automatisierung technischer Aufgaben"],"pt":["executing-plans","implantação de planos","checkpoints de revisão","desenvolvimento de software","engenharia de software","ferramentas de ai","ai agents","execução de planos"],"ru":["executing-plans","выполнение планов","контрольные точки","разработка программного обеспечения","инженерия программного обеспечения","инструменты ИИ","ИИ Агенты","выполнение планов реализации"],"ar":["executing-plans","تنفيذ خطط","نقاط فحص","تطوير البرمجيات","هندسة البرمجيات","أدوات الاصطناع","وكلاء الاصطناع","تنفيذ خطط التنفيذ"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Implementation Agents needing structured batch execution with architectural oversight.","zh":"非常适合需要结构化批量执行且具有架构监督的实施Agent。","ja":"構造化されたバッチ実行とアーキテクチャ監視を必要とするImplementation Agentに最適です。","ko":"구조화된 배치 실행과 아키텍처 감독이 필요한 Implementation Agent에 완벽합니다.","es":"Ideal para Implementation Agents que necesitan ejecución por lotes estructurada con supervisión arquitectónica.","fr":"Parfait pour les Implementation Agents nécessitant une exécution par lots structurée avec supervision architecturale.","de":"Perfekt für Implementation Agents, die strukturierte Batch-Ausführung mit architektonischer Aufsicht benötigen.","pt":"Perfeito para Implementation Agents que necessitam de execução estruturada em lote com supervisão arquitetural.","ru":"Идеально подходит для Implementation Agents, которым требуется структурированное пакетное выполнение с архитектурным контролем.","ar":"مثالي لوكلاء التنفيذ الذين يحتاجون إلى تنفيذ منظم على دفعات مع إشراف معماري."},"recommendation":{"en":"Enables batch execution of implementation plans with critical review checkpoints, providing plan file loading, task batching, and architect review reporting capabilities.","zh":"支持对实施计划进行批量执行，并提供关键审查检查点，具备计划文件加载、任务批处理和架构师审查报告功能。","ja":"計画ファイルの読み込み、タスクのバッチ処理、アーキテクトレビュー報告機能を提供し、重要なレビューチェックポイントを含む実装計画のバッチ実行を可能にします。","ko":"중요한 검토 체크포인트를 통해 구현 계획의 배치 실행을 가능하게 하며, 계획 파일 로딩, 작업 배치 처리 및 아키텍트 검토 보고 기능을 제공합니다.","es":"Permite la ejecución por lotes de planes de implementación con puntos de control de revisión crítica, proporcionando capacidades de carga de archivos de plan, procesamiento por lotes de tareas y generación de informes de revisión del arquitecto.","fr":"Permet l''exécution par lots de plans d''implémentation avec des points de contrôle de revue critique, offrant des capacités de chargement de fichiers de plan, de traitement par lots de tâches et de génération de rapports de revue d''architecte.","de":"Ermöglicht die Batch-Ausführung von Implementierungsplänen mit kritischen Überprüfungspunkten und bietet Funktionen zum Laden von Plan-Dateien, zur Batch-Verarbeitung von Aufgaben und zur Erstellung von Architekten-Überprüfungsberichten.","pt":"Permite a execução em lote de planos de implementação com pontos de verificação de revisão crítica, fornecendo capacidades de carregamento de arquivos de plano, criação de lotes de tarefas e relatórios de revisão do arquiteto.","ru":"Обеспечивает пакетное выполнение планов реализации с критическими контрольными точками проверки, предоставляя возможности загрузки файлов планов, пакетирования задач и создания отчетов для проверки архитектором.","ar":"يمكن من التنفيذ على دفعات لخطط التنفيذ مع نقاط مراجعة حرجة، مما يوفر قدرات تحميل ملف الخطة، تجميع المهام في دفعات، وإعداد تقارير مراجعة المهندس المعماري."},"useCases":{"en":["Executing multi-step development plans in batches","Implementing architectural designs with review cycles","Processing complex technical specifications systematically"],"zh":["批量执行多步骤开发计划","通过审查周期实施架构设计","系统化处理复杂技术规范"],"ja":["複数ステップの開発計画のバッチ実行","レビューサイクルを含むアーキテクチャ設計の実装","複雑な技術仕様の体系的な処理"],"ko":["다단계 개발 계획의 배치 실행","검토 주기를 통한 아키텍처 설계 구현","복잡한 기술 사양의 체계적 처리"],"es":["Ejecutar planes de desarrollo de múltiples pasos en lotes","Implementar diseños arquitectónicos con ciclos de revisión","Procesar especificaciones técnicas complejas de manera sistemática"],"fr":["Exécuter des plans de développement à multiples étapes par lots","Mettre en œuvre des conceptions architecturales avec cycles de revue","Traiter des spécifications techniques complexes de manière systématique"],"de":["Ausführung von mehrstufigen Entwicklungsplänen in Batches","Implementierung von Architekturentwürfen mit Überprüfungszyklen","Systematische Verarbeitung komplexer technischer Spezifikationen"],"pt":["Executar planos de desenvolvimento de múltiplas etapas em lotes","Implementar designs arquiteturais com ciclos de revisão","Processar especificações técnicas complexas de forma sistemática"],"ru":["Выполнение многоэтапных планов разработки пакетами","Реализация архитектурных проектов с циклами проверки","Систематическая обработка сложных технических спецификаций"],"ar":["تنفيذ خطط تطوير متعددة المراحل على دفعات","تنفيذ التصاميم المعمارية مع دورات مراجعة","معالجة المواصفات التقنية المعقدة بشكل منهجي"]},"limitations":{"en":["Requires pre-written implementation plan file","Needs human architect review between batches","Depends on separate session execution context"],"zh":["需要预先编写的实施计划文件","批次之间需要人类架构师进行审查","依赖于单独的会话执行上下文"],"ja":["事前に作成された実装計画ファイルが必要","バッチ間での人間のアーキテクトレビューが必要","別個のセッション実行コンテキストに依存"],"ko":["사전 작성된 구현 계획 파일 필요","배치 간 인간 아키텍트 검토 필요","별도의 세션 실행 컨텍스트에 의존"],"es":["Requiere un archivo de plan de implementación preescrito","Necesita revisión humana del arquitecto entre lotes","Depende de un contexto de ejecución de sesión separada"],"fr":["Nécessite un fichier de plan d''implémentation pré-écrit","Requiert une revue humaine de l''architecte entre les lots","Dépend d''un contexte d''exécution de session séparée"],"de":["Erfordert eine vorab geschriebene Implementierungsplan-Datei","Benötigt menschliche Architekten-Überprüfung zwischen Batches","Ist abhängig vom separaten Sitzungsausführungskontext"],"pt":["Requer um arquivo de plano de implementação pré-escrito","Necessita de revisão humana do arquiteto entre os lotes","Depende de um contexto de execução de sessão separada"],"ru":["Требует предварительно написанного файла плана реализации","Требует проверки человеком-архитектором между пакетами","Зависит от контекста выполнения отдельной сессии"],"ar":["يتطلب ملف خطة تنفيذ مكتوب مسبقًا","يحتاج إلى مراجعة من قبل مهندس معماري بشري بين الدفعات","يعتمد على سياق جلسة تنفيذ منفصلة"]},"version":4},"contentHash":"d099fa42fd7518f4dafa9f2d51c1c08fce970490d57682b6acd3e7a57bb55b52","repoEtag":"W/\"a8a266458ca9bbf6c9312a7647f733e0f1891eedfa2dde0bddcec7f7d186089e\"","qualityScore":61}');
