INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('obra/superpowers/executing-plans', 'executing-plans', 'obra', 'superpowers', 'official', 'executing-plans obra superpowers official The executing-plans skill enables AI agents to systematically implement a written plan by executing tasks in batches and pausing for architect review between them. It is designed for developers and architects who require a controlled, review-driven development process. executing-plans 是一项AI代理技能，专为执行书面技术实施方案而设计。其核心是在分批次执行任务的过程中，设置架构审查检查点，以确保实施质量并与人类伙伴协作。 executing-plansは、書かれた実装計画を実行するためのAIエージェントスキルです。バッチ単位でのタスク実行とアーキテクトレビューのチェックポイントを設け、実施品質を確保し人間パートナーと協力することを原則とします。 executing-plans는 작성된 구현 계획을 실행하기 위한 AI 에이전트 스킬입니다. 배치별 작업 실행과 아키텍트 리뷰를 위한 체크포인트를 설정하여 구현 품질을 보장하고 인간 파트너와 협력하는 것을 핵심 원칙으로 합니다. La habilidad executing-plans permite a un agente de IA implementar un plan escrito ejecutando tareas en lotes con puntos de control integrados para una revisión crítica por parte de un arquitecto humano. El proceso incluye cargar el plan, identificar problemas potenciales y reportar después de ca... La compétence executing-plans permet à un agent IA d''exécuter un plan écrit en traitant les tâches par lots avec des points de contrôle pour une revue critique par un architecte humain. Le processus comprend le chargement du plan, l''identification des problèmes et le reporting après chaque lot. Die executing-plans-Fähigkeit ermöglicht es einem KI-Agenten, einen schriftlichen Plan durchzuführen, indem Aufgaben in Batches mit integrierten Checkpoints für ein kritisches Review durch einen menschlichen Architekten ausgeführt werden. Der Prozess umfasst das Laden des Plans, das Identifiziere... O skill Executing-Plans permite executar planos de implementação em lotes com checkpoints de revisão Навык Executing-Plans позволяет выполнять планы реализации партиями с контрольными точками تمكن مهارة Executing-Plans من تنفيذ خطط التنفيذ بشكل محظوظ مع نقاط فحص what is executing-plans how to use executing-plans skill executing-plans batch execution executing-plans vs manual implementation executing-plans setup guide AI agent plan file format architect review checkpoints executing-plans implementation best practices executing-plans AI代理 批量执行计划 架构审查检查点 AI代理技能指南 技术计划实施 分批次任务执行 计划加载与审查 AI开发工作流 Loads and reads from a dedicated plan file Performs a critical review to identify questions or concerns about the plan Executes implementation tasks in distinct batches Reports for architect review between each batch of executed tasks Announces skill usage at the start of a session executing-plans is an AI agent skill for executing a pre-written implementation plan. Its core principle is batch execution with checkpoints, requiring the agent to load a plan file, review it critically, and report for human partner review between batches.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/article-writing', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'article-writing', 61988, 7678, 61, '2026-03-06T03:39:20Z', '2026-03-06T03:45:10.906Z', '6ab082c7850e8e46e471026ea388024b1b9a574d84eb210fcb7391c15aa6b51a', '{"id":"affaan-m/everything-claude-code/article-writing","name":"article-writing","description":{"en":"The article-writing skill enables AI agents to generate long-form technical content like tutorials, guides, and blog posts while maintaining a consistent brand voice derived from supplied examples. It''s designed for developers and technical writers creating structured, credible documentation.","zh":"文章写作技能允许您生成高质量的长篇内容，包括文章、博客和教程，具有独特的语音和一致的结构","ja":"記事作成スキルを使用すると、高品質の長文コンテンツを生成できます。記事、ブログ、チュートリアルなど、独自の音声と一貫した構造を備えています","ko":"기사 작성 기능을 사용하면 높은 품질의 장문 콘텐츠를 생성할 수 있습니다. 기사, 블로그 및 튜토리얼과 같은 독특한 음색과 일관된 구조를 갖추고 있습니다","es":"La habilidad de escritura de artículos permite crear contenido largo y personalizado, como blog posts, tutoriales y newsletters, con una voz distintiva derivada de ejemplos o directrices de marca","fr":"La capacité d''écriture d''articles permet de créer du contenu long et personnalisé, comme des billets de blog, des didacticiels et des newsletters, avec une voix distincte dérivée d''exemples ou de directives de marque","de":"Die Fähigkeit zum Schreiben von Artikeln ermöglicht die Erstellung von langem und personalisiertem Inhalt, wie Blog-Beiträgen, Anleitungen und Newslettern, mit einer einzigartigen Stimme, die aus Beispielen oder Markenrichtlinien abgeleitet wird","pt":"A habilidade de escrita de artigos permite criar conteúdo personalizado com exemplos e orientações de marca. Use quando precisar de conteúdo de longa forma","ru":"ИИ Агенты позволяют создавать качественный контент с уникальным голосом и структурой. Используйте при необходимости создания контента длинной формы","ar":"أدوات الذكاء الاصطناعي تمكنك من إنشاء محتوى متميز مع صوت وструктура متسقة. استخدمها عند الحاجة إلى محتوى طويل الأمد"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"article-writing","description":"Write articles, guides, blog posts, tutorials, newsletter issues, and other long-form content in a distinctive voice derived from supplied examples or brand guidance. Use when the user wants polished written content longer than a paragraph, especially when voice consistency, structure, and credibility matter.","bodyPreview":"# Article Writing\n\nWrite long-form content that sounds like a real person or brand, not generic AI output.\n\n## When to Activate\n\n- drafting blog posts, essays, launch posts, guides, tutorials, or newsletter issues\n- turning notes, transcripts, or research into polished articles\n- matching an existing founder, operator, or brand voice from examples\n- tightening structure, pacing, and evidence in already-written long-form copy\n\n## Core Rules\n\n1. Lead with the concrete thing: example, output, anecd","body":"# Article Writing\n\nWrite long-form content that sounds like a real person or brand, not generic AI output.\n\n## When to Activate\n\n- drafting blog posts, essays, launch posts, guides, tutorials, or newsletter issues\n- turning notes, transcripts, or research into polished articles\n- matching an existing founder, operator, or brand voice from examples\n- tightening structure, pacing, and evidence in already-written long-form copy\n\n## Core Rules\n\n1. Lead with the concrete thing: example, output, anecdote, number, screenshot description, or code block.\n2. Explain after the example, not before.\n3. Prefer short, direct sentences over padded ones.\n4. Use specific numbers when available and sourced.\n5. Never invent biographical facts, company metrics, or customer evidence.\n\n## Voice Capture Workflow\n\nIf the user wants a specific voice, collect one or more of:\n- published articles\n- newsletters\n- X / LinkedIn posts\n- docs or memos\n- a short style guide\n\nThen extract:\n- sentence length and rhythm\n- whether the voice is formal, conversational, or sharp\n- favored rhetorical devices such as parentheses, lists, fragments, or questions\n- tolerance for humor, opinion, and contrarian framing\n- formatting habits such as headers, bullets, code blocks, and pull quotes\n\nIf no voice references are given, default to a direct, operator-style voice: concrete, practical, and low on hype.\n\n## Banned Patterns\n\nDelete and rewrite any of these:\n- generic openings like \"In today''s rapidly evolving landscape\"\n- filler transitions such as \"Moreover\" and \"Furthermore\"\n- hype phrases like \"game-changer\", \"cutting-edge\", or \"revolutionary\"\n- vague claims without evidence\n- biography or credibility claims not backed by provided context\n\n## Writing Process\n\n1. Clarify the audience and purpose.\n2. Build a skeletal outline with one purpose per section.\n3. Start each section with evidence, example, or scene.\n4. Expand only where the next sentence earns its place.\n5. Remove anything that sounds templated or self-congratulatory.\n\n## Structure Guidance\n\n### Technical Guides\n- open with what the reader gets\n- use code or terminal examples in every major section\n- end with concrete takeaways, not a soft summary\n\n### Essays / Opinion Pieces\n- start with tension, contradiction, or a sharp observation\n- keep one argument thread per section\n- use examples that earn the opinion\n\n### Newsletters\n- keep the first screen strong\n- mix insight with updates, not diary filler\n- use clear section labels and easy skim structure\n\n## Quality Gate\n\nBefore delivering:\n- verify factual claims against provided sources\n- remove filler and corporate language\n- confirm the voice matches the supplied examples\n- ensure every section adds new information\n- check formatting for the intended platform\n"},"category":"official","lastSynced":"2026-03-06T03:45:10.906Z","seo":{"title":{"en":"Article-Writing Skill: Voice-Consistent Long-Form Content...","zh":"文章写作设置指南 - 使用AI Agents生成高质量内容","ja":"記事作成ベストプラクティス - AIエージェントを活用する","ko":"기사 작성 가이드 - AI 도구로 높은 품질의 콘텐츠 생성","es":"Guía de configuración de escritura de artículos con Agent...","fr":"Guide de démarrage rapide pour l''écriture d''articles avec...","de":"Einrichtungsleitfaden für Artikel-Schreiben mit KI-Agenten","pt":"Guia de Configuração de Escrita de Artigos com AI Agents","ru":"ИИ Агенты: Руководство по Настройке Автоматической Писани","ar":"دليل إعداد كتابة المقالات باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Master Claude AI''s article-writing skill for developers. Generate tutorials, blog posts & newsletters with brand-aligned voice & structure. Learn to transfor...","zh":"了解如何使用AI Agents生成高质量的文章、博客和教程，提高内容的可读性和一致性","ja":"AIエージェントを使用して、高品質の記事、ブログ、チュートリアルを生成し、コンテンツの可読性と一貫性を向上させる","ko":"AI 도구를 사용하여 높은 품질의 기사, 블로그 및 튜토리얼을 생성하고 콘텐츠의 가독성 및 일관성을 향상시키는 방법을 알아보세요","es":"Aprende a utilizar la habilidad de escritura de artículos con Agentes de IA para crear contenido de alta calidad y personalizado","fr":"Découvrez comment utiliser la capacité d''écriture d''articles des Agents IA pour créer du contenu de haute qualité et personnalisé","de":"Erfahren Sie, wie Sie die Fähigkeit zum Schreiben von Artikeln mit KI-Agenten nutzen, um hochwertigen und personalisierten Inhalt zu erstellen","pt":"Aprenda a usar a habilidade de escrita de artigos para criar conteúdo de longa forma personalizado com exemplos e orientações de marca","ru":"Откройте для себя, как использовать ИИ Агентов для создания качественного контента с уникальным голосом и структурой","ar":"اكتشف كيفية استخدام أدوات الذكاء الاصطناعي لإنشاء محتوى طويل الأمد مع صوت متميز وструктура متسقة"},"definition":{"en":"article-writing is an AI agent skill that generates long-form content including blog posts, tutorials, and newsletter issues using a distinctive voice derived from brand examples. It structures content with concrete examples, anecdotes, and evidence while maintaining voice consistency.","zh":"文章写作是使用AI Agents生成高质量长篇内容的技能，具有独特的语音和一致的结构","ja":"記事作成は、独自の音声と一貫した構造を持つ高品質の長文コンテンツを生成するためのAIエージェントスキルです","ko":"기사 작성은 독특한 음색과 일관된 구조를 갖춘 높은 품질의 장문 콘텐츠를 생성하기 위한 AI 도구의 기능입니다","es":"La escritura de artículos es una habilidad de Agentes de IA que permite crear contenido largo y personalizado con una voz distintiva","fr":"L''écriture d''articles est une capacité des Agents IA qui permet de créer du contenu long et personnalisé avec une voix distincte","de":"Das Schreiben von Artikeln ist eine Fähigkeit von KI-Agenten, die die Erstellung von langem und personalisiertem Inhalt mit einer einzigartigen Stimme ermöglicht","pt":"O que é escrita de artigos? É uma habilidade que permite criar conteúdo de longa forma personalizado","ru":"Что такое автоматическая писани? Это способность создавать качественный контент длинной формы","ar":"ما هي كتابة المقالات؟ إنها قدرة على إنشاء محتوى طويل الأمد مع صوت متميز"},"features":{"en":["Generates blog posts, essays, launch posts, and guides with brand-specific voice","Transforms notes, transcripts, or research into polished articles","Matches existing founder, operator, or brand voice from supplied examples","Tightens structure and pacing in already-written long-form copy","Uses concrete examples, outputs, and anecdotes as lead elements","Produces content longer than paragraph-length with credible evidence"],"zh":["生成独特的语音和一致的结构","支持多种长篇内容格式，包括文章、博客和教程","使用实例和品牌指导来匹配现有的语音","提高内容的可读性和一致性","支持从笔记、录音稿或研究中生成高质量的内容"],"ja":["独自の音声と一貫した構造を生成","記事、ブログ、チュートリアルなど、多様な長文コンテンツ形式をサポート","実例とブランドガイダンスを使用して既存の音声をマッチ","コンテンツの可読性と一貫性を向上","ノート、トランスクリプト、または研究から高品質のコンテンツを生成することをサポート"],"ko