INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/article-writing', 'article-writing', 'affaan-m', 'everything-claude-code', 'official', 'article-writing affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The article-writing skill enables AI agents to generate long-form technical content like tutorials, guides, and blog posts while maintaining a consistent brand voice derived from supplied examples. It''s designed for developers and technical writers creating structured, credible documentation. 文章写作技能允许您生成高质量的长篇内容，包括文章、博客和教程，具有独特的语音和一致的结构 記事作成スキルを使用すると、高品質の長文コンテンツを生成できます。記事、ブログ、チュートリアルなど、独自の音声と一貫した構造を備えています 기사 작성 기능을 사용하면 높은 품질의 장문 콘텐츠를 생성할 수 있습니다. 기사, 블로그 및 튜토리얼과 같은 독특한 음색과 일관된 구조를 갖추고 있습니다 La habilidad de escritura de artículos permite crear contenido largo y personalizado, como blog posts, tutoriales y newsletters, con una voz distintiva derivada de ejemplos o directrices de marca La capacité d''écriture d''articles permet de créer du contenu long et personnalisé, comme des billets de blog, des didacticiels et des newsletters, avec une voix distincte dérivée d''exemples ou de directives de marque Die Fähigkeit zum Schreiben von Artikeln ermöglicht die Erstellung von langem und personalisiertem Inhalt, wie Blog-Beiträgen, Anleitungen und Newslettern, mit einer einzigartigen Stimme, die aus Beispielen oder Markenrichtlinien abgeleitet wird A habilidade de escrita de artigos permite criar conteúdo personalizado com exemplos e orientações de marca. Use quando precisar de conteúdo de longa forma ИИ Агенты позволяют создавать качественный контент с уникальным голосом и структурой. Используйте при необходимости создания контента длинной формы أدوات الذكاء الاصطناعي تمكنك من إنشاء محتوى متميز مع صوت وструктура متسقة. استخدمها عند الحاجة إلى محتوى طويل الأمد how to use article-writing skill article-writing vs generic AI content article-writing install guide Claude AI article generation MCP article-writing setup technical writing with AI agents brand voice consistency AI article-writing skill tutorial long-form content generation AI Claude-Code writing assistant AI Agents 文章写作 长篇内容生成 独特语音 一致结构 高质量内容 内容可读性 内容一致性 笔记转文章 研究转文章 Generates blog posts, essays, launch posts, and guides with brand-specific voice Transforms notes, transcripts, or research into polished articles Matches existing founder, operator, or brand voice from supplied examples Tightens structure and pacing in already-written long-form copy Uses concrete examples, outputs, and anecdotes as lead elements Produces content longer than paragraph-length with credible evidence article-writing is an AI agent skill that generates long-form content including blog posts, tutorials, and newsletter issues using a distinctive voice derived from brand examples. It structures content with concrete examples, anecdotes, and evidence while maintaining voice consistency.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/content-engine', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'content-engine', 61988, 7678, 61, '2026-03-06T03:39:20Z', '2026-03-06T03:51:20.957Z', '057a610eab12e16bf447a46dd91de867ea450ce541fddc956d1abd55be5ec2cc', '{"id":"affaan-m/everything-claude-code/content-engine","name":"content-engine","description":{"en":"The content-engine MCP skill for AI agents like Claude creates platform-native content systems. It repurposes source assets into tailored posts, threads, scripts, and content calendars for developers and content teams.","zh":"Content Engine是一种AI驱动的内容系统，能够为不同平台生成原生内容，包括X、LinkedIn、TikTok、YouTube等","ja":"Content Engineは、X、LinkedIn、TikTok、YouTubeなどの複数のプラットフォーム向けのネイティブコンテンツを生成するAI駆動のコンテンツシステム","ko":"Content Engine은 X, LinkedIn, TikTok, YouTube 등 여러 플랫폼에 대한 네이티브 콘텐츠를 생성하는 AI 기반 콘텐츠 시스템","es":"Content Engine es una herramienta que permite a los desarrolladores crear contenido nativo para múltiples plataformas","fr":"Content Engine est un outil qui permet aux développeurs de créer du contenu natif pour plusieurs plateformes","de":"Content Engine ist ein Tool, mit dem Entwickler native Inhalte für mehrere Plattformen erstellen können","pt":"O Content Engine é uma ferramenta que permite criar conteúdo nativo para várias plataformas, incluindo X, LinkedIn, TikTok e YouTube","ru":"Content Engine - это инструмент, позволяющий создавать платформенно-родный контент для X, LinkedIn, TikTok и YouTube","ar":"محرك المحتوى هو أداة تمكنك من إنشاء محتوى أصلي لمنصات متعددة، بما في ذلك X و LinkedIn و TikTok و YouTube"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"content-engine","description":"Create platform-native content systems for X, LinkedIn, TikTok, YouTube, newsletters, and repurposed multi-platform campaigns. Use when the user wants social posts, threads, scripts, content calendars, or one source asset adapted cleanly across platforms.","bodyPreview":"# Content Engine\n\nTurn one idea into strong, platform-native content instead of posting the same thing everywhere.\n\n## When to Activate\n\n- writing X posts or threads\n- drafting LinkedIn posts or launch updates\n- scripting short-form video or YouTube explainers\n- repurposing articles, podcasts, demos, or docs into social content\n- building a lightweight content plan around a launch, milestone, or theme\n\n## First Questions\n\nClarify:\n- source asset: what are we adapting from\n- audience: builders, i","body":"# Content Engine\n\nTurn one idea into strong, platform-native content instead of posting the same thing everywhere.\n\n## When to Activate\n\n- writing X posts or threads\n- drafting LinkedIn posts or launch updates\n- scripting short-form video or YouTube explainers\n- repurposing articles, podcasts, demos, or docs into social content\n- building a lightweight content plan around a launch, milestone, or theme\n\n## First Questions\n\nClarify:\n- source asset: what are we adapting from\n- audience: builders, investors, customers, operators, or general audience\n- platform: X, LinkedIn, TikTok, YouTube, newsletter, or multi-platform\n- goal: awareness, conversion, recruiting, authority, launch support, or engagement\n\n## Core Rules\n\n1. Adapt for the platform. Do not cross-post the same copy.\n2. Hooks matter more than summaries.\n3. Every post should carry one clear idea.\n4. Use specifics over slogans.\n5. Keep the ask small and clear.\n\n## Platform Guidance\n\n### X\n- open fast\n- one idea per post or per tweet in a thread\n- keep links out of the main body unless necessary\n- avoid hashtag spam\n\n### LinkedIn\n- strong first line\n- short paragraphs\n- more explicit framing around lessons, results, and takeaways\n\n### TikTok / Short Video\n- first 3 seconds must interrupt attention\n- script around visuals, not just narration\n- one demo, one claim, one CTA\n\n### YouTube\n- show the result early\n- structure by chapter\n- refresh the visual every 20-30 seconds\n\n### Newsletter\n- deliver one clear lens, not a bundle of unrelated items\n- make section titles skimmable\n- keep the opening paragraph doing real work\n\n## Repurposing Flow\n\nDefault cascade:\n1. anchor asset: article, video, demo, memo, or launch doc\n2. extract 3-7 atomic ideas\n3. write platform-native variants\n4. trim repetition across outputs\n5. align CTAs with platform intent\n\n## Deliverables\n\nWhen asked for a campaign, return:\n- the core angle\n- platform-specific drafts\n- optional posting order\n- optional CTA variants\n- any missing inputs needed before publishing\n\n## Quality Gate\n\nBefore delivering:\n- each draft reads natively for its platform\n- hooks are strong and specific\n- no generic hype language\n- no duplicated copy across platforms unless requested\n- the CTA matches the content and audience\n"},"category":"official","lastSynced":"2026-03-06T03:51:20.957Z","seo":{"title":{"en":"content-engine: Multi-Platform Content Repurposing | AI A...","zh":"Content Engine.Setup Guide - 跨平台内容系统","ja":"Content Engine ベストプラクティス - AIエージェント","ko":"Content Engine 설정 가이드 - 멀티 플랫폼 캠페인","es":"Guía de configuración de Content Engine para desarrolladores","fr":"Guide de mise en place de Content Engine pour les dévelop...","de":"Einrichtungsleitfaden für Content Engine-Entwickler","pt":"Guia de Configuração do Content Engine para Desenvolvedores","ru":"Настройка ИИ Агентов: Content Engine для Разработчиков","ar":"دليل إعداد محرك المحتوى لل مطورين"},"description":{"en":"Stop cross-posting the same content. Learn how the content-engine MCP skill transforms source assets like docs, podcasts, and demos into platform-native cont...","zh":"使用Content Engine创建平台原生内容系统，适用于X、LinkedIn、TikTok、YouTube、新闻稿和复用多平台_campaign","ja":"Content Engineを使用して、X、LinkedIn、TikTok、YouTube、ニュースレターなど、複数のプラットフォーム向けのネイティブコンテンツシステムを作成","ko":"Content Engine을 사용하여 X, LinkedIn, TikTok, YouTube, 뉴스레터 및 복수 플랫폼 캠페인에 대한 플랫폼 네이티브 콘텐츠 시스템을 생성","es":"Aprende a crear sistemas de contenido nativos para plataformas como X, LinkedIn, TikTok y YouTube con Content Engine","fr":"Découvrez comment créer des systèmes de contenu natifs pour les plateformes X, LinkedIn, TikTok et YouTube avec Content Engine","de":"Erfahren Sie, wie Sie mit Content Engine native Inhaltsysteme für Plattformen wie X, LinkedIn, TikTok und YouTube erstellen","pt":"Aprenda a criar sistemas de conteúdo nativos para plataformas como X, LinkedIn, TikTok e YouTube com o Content Engine","ru":"Создайте платформенно-родные контент-системы для X, LinkedIn, TikTok и YouTube с помощью Content Engine и ИИ Агентов","ar":"تعلم كيفية إنشاء أنظمة محتوى أصلية لل منصات مثل X و LinkedIn و TikTok و YouTube باستخدام محرك المحتوى"},"definition":{"en":"content-engine is an MCP (Model Context Protocol) skill that enables AI agents to generate platform-native content from a single source asset. It specializes in adapting content for X threads, LinkedIn posts, TikTok scripts, YouTube explainers, and multi-platform campaigns.","zh":"Content Engine是一种跨平台内容系统，能够为不同平台生成原生内容","ja":"Content Engineは、複数のプラットフォーム向けのネイティブコンテンツを生成するコンテンツシステム","ko":"Content Engine은 여러 플랫폼에 대한 네이티브 콘텐츠를 생성하는 콘텐츠 시스템","es":"Content Engine es un motor de contenido que adapta activos de origen a plataformas como X, LinkedIn y YouTube","fr":"Content Engine est un moteur de contenu qui adapte les actifs de source aux plateformes X, LinkedIn et YouTube","de":"Content Engine ist ein Inhaltsmotor, der Quellassets an Plattformen wie X, LinkedIn und YouTube anpasst","pt":"O Content Engine é uma ferramenta de criação de conteúdo que adapta conteúdo para várias plataformas","ru":"Content Engine - это инструмент создания контента, адаптирующий контент для различных платформ","ar":"محرك المحتوى هو أداة لإنشاء المحتوى التي تكيّف المحتوى لمنصات متعددة"},"features":{"en":["Generates X posts and threads from source assets","Drafts LinkedIn posts and launch updates","Creates scripts for short-form video and YouTube explainers","Repurposes articles, podcasts, demos, or docs into social content","Builds lightweight content plans around launches or themes"],"zh":["支持X、LinkedIn、TikTok、YouTube等多个平台","能够生成平台原生内容","支持复用多平台_campaign","能够创建内容日历","支持脚本和社交帖子生成"],"ja":["X、LinkedIn、TikTok、YouTubeなどの複数のプラットフォームをサポート","プラットフォームネイティブコンテンツを生成","複数のプラットフォーム向けのキャンペーンをリユース","コンテンツカレンダーを作成","スクリプトとソーシャルポストの生成をサポート"],"ko":["X, LinkedIn, TikTok, YouTube 등 여러 플랫폼 지원","플랫폼 네이티브 콘텐츠 생성","複수 플랫폼 캠페인 리유즈","콘텐츠 캘린더 생성","스크립트 및 소셜 포스트 생성 지원"],"es":["Crea sistemas de contenido nativos para X, LinkedIn, TikTok y YouTube","Adapta activos de origen a múltiples plataformas","Genera publicaciones, hilos, guiones y calendarios de contenido","Permite la reutilización de contenido en varias plataformas","Es compatible con herramientas de desarrollo como CLI y API","Soporta la creación de campañas multiplataforma"],"fr":["Crée des systèmes de contenu natifs pour X, LinkedIn, TikTok et YouTube","Adapte les actifs de source à plusieurs plateformes","Génère des publications, des fils, des scripts et des calendriers de contenu","Permet la réutilisation de contenu sur plusieurs plateformes","Est compatible avec des outils de développement tels que CLI et API","Prend en charge la création de campagnes multiplateformes"],"de":["Erstellt native Inhaltsysteme für X, LinkedIn, TikTok und YouTube","Passt Quellassets an mehrere Plattformen an","Generiert Beiträge, Threads, Skripte und Inhaltskalender","Ermöglicht die Wiederverwendung von Inhalten auf mehreren Plattformen","Ist kompatibel mit Entwicklungstools wie CLI und API","Unterstützt die Erstellung von Multiplattform-Kampagnen"],"pt":["Criação de conteúdo nativo para X, LinkedIn, TikTok e YouTube","Adaptação de conteúdo para várias plataformas","Criação de calendários de conteúdo e scripts para vídeos","Repurposing de artigos, podcasts e demos para conteúdo social","Integração com ferramentas de desenvolvimento para aumentar a produtividade"],"ru":["Создание платформенно-родного контента для X, LinkedIn, TikTok и YouTube","Адаптация контента для различных платформ","Создание контент-календарей и скриптов для видео","Переработка статей, подкастов и демонстраций в социальный контент","Интеграция с инструментами разработки для повышения производительности"],"ar":["إنشاء محتوى أصلي لمنصات مثل X و LinkedIn و TikTok و YouTube","تكيف المحتوى لمنصات متعددة","إنشاء تقويمات المحتوى وخطوط سيرية للفيديوهات","إعادة استخدام المقالات والبودكاست والأدلة للتوعية الاجتماعية","دمج أدوات التطوير لزيادة الإنتاجية"]},"keywords":{"en":["what is content-engine","how to use content-engine MCP","content-engine vs repurpose.ai","content-engine alternative","content-engine install for Claude","content-engine setup guide","multi-platform content repurposing tool","AI agent content generation skill"],"zh":["Content Engine","AI驱动的内容系统","跨平台内容系统","平台原生内容","复用多平台_campaign","内容日历","脚本生成","社交帖子生成"],"ja":["Content Engine","AI駆動のコンテンツシステム","複数のプラットフォーム向けのコンテンツシステム","プラットフォームネイティブコンテンツ","複数のプラットフォーム向けのキャンペーンリユース","コンテンツカレンダー","スクリプト生成","ソーシャルポスト生成"],"ko":["Content Engine","AI 기반 콘텐츠 시스템","複수 플랫폼 콘텐츠 시스템","플랫폼 네이티브 콘텐츠","複수 플랫폼 캠페인 리유즈","콘텐츠 캘린더","스크립트 생성","소셜 포스트 생성"],"es":["Content Engine","desarrollo de contenido","plataformas de redes sociales","X","LinkedIn","TikTok","YouTube","herramientas de desarrollo","CLI","API","Agente de IA","Herramientas de IA"],"fr":["Content Engine","développement de contenu","plateformes de réseaux sociaux","X","LinkedIn","TikTok","YouTube","outils de développement","CLI","API","Agent d''IA","Outils d''IA"],"de":["Content Engine","Inhaltsentwicklung","Plattformen für soziale Medien","X","LinkedIn","TikTok","YouTube","Entwicklungstools","CLI","API","IA-Agent","IA-Tools"],"pt":["Content Engine","criação de conteúdo","plataformas de mídia social","X","LinkedIn","TikTok","YouTube","desenvolvimento de software","produtividade"],"ru":["Content Engine","создание контента","платформы социальных медиа","X","LinkedIn","TikTok","YouTube","разработка программного обеспечения","производительность"],"ar":["محرك المحتوى","إنشاء المحتوى","منصات الإعلام الاجتماعي","X","LinkedIn","TikTok","YouTube","تطوير البرمجيات","النتاجية"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Content Creation Agents specializing in multi-platform social media strategy and content repurposing.","zh":"非常适合专门从事多平台社交媒体策略和内容再利用的内容创作智能体。","ja":"マルチプラットフォームのソーシャルメディア戦略とコンテンツの再利用を専門とするコンテンツ作成エージェントに最適です。","ko":"다중 플랫폼 소셜 미디어 전략 및 콘텐츠 재활용에 특화된 콘텐츠 제작 에이전트에 완벽합니다.","es":"Ideal para Agentes de Creación de Contenido especializados en estrategias de redes sociales multiplataforma y reutilización de contenido.","fr":"Idéal pour les Agents de Création de Contenu spécialisés dans la stratégie de médias sociaux multi-plateformes et la réutilisation de contenu.","de":"Perfekt für Content Creation Agents, die sich auf Multi-Plattform-Social-Media-Strategien und das Repurposing von Inhalten spezialisiert haben.","pt":"Perfeito para Agentes de Criação de Conteúdo especializados em estratégia de mídia social multiplataforma e reutilização de conteúdo.","ru":"Идеально подходит для агентов по созданию контента, специализирующихся на многоплатформенной социальной медиа-стратегии и переиспользовании контента.","ar":"مثالي للوكلاء الذين يختصون في إنشاء المحتوى في استراتيجية وسائل الإعلام الاجتماعية متعددة المنصات وإعادة استخدام المحتوى."},"recommendation":{"en":"Enables agents to transform single source assets into platform-native content systems across X, LinkedIn, TikTok, YouTube, and newsletters, ensuring optimal format and tone adaptation for each channel while maintaining cohesive campaign messaging.","zh":"使智能体能够将单一来源素材转换为跨 X、LinkedIn、TikTok、YouTube 和新闻通讯的平台原生内容系统，确保每个渠道的最佳格式和语调适应，同时保持连贯的营销活动讯息。","ja":"エージェントが単一のソース資産を、X、LinkedIn、TikTok、YouTube、およびニュースレターにわたるプラットフォームネイティブなコンテンツシステムに変換することを可能にし、結束力のあるキャンペーンメッセージングを維持しながら、各チャネルに最適な形式とトーンの適応を保証します。","ko":"에이전트가 단일 소스 자산을 X, LinkedIn, TikTok, YouTube 및 뉴스레터에 걸친 플랫폼 네이티브 콘텐츠 시스템으로 변환할 수 있게 하여, 각 채널에 대한 최적의 형식과 톤 적응을 보장하면서도 일관된 캠페인 메시징을 유지합니다.","es":"Permite a los agentes transformar activos de una sola fuente en sistemas de contenido nativos de la plataforma en X, LinkedIn, TikTok, YouTube y boletines informativos, garantizando una adaptación óptima del formato y el tono para cada canal mientras se mantiene un mensaje de campaña cohesivo.","fr":"Permet aux agents de transformer des actifs source uniques en systèmes de contenu natifs de la plateforme sur X, LinkedIn, TikTok, YouTube et les newsletters, garantissant une adaptation optimale du format et du ton pour chaque canal tout en maintenant un message de campagne cohérent.","de":"Ermöglicht Agents, einzelne Quellen-Assets in plattformeigene Content-Systeme auf X, LinkedIn, TikTok, YouTube und in Newslettern zu transformieren, wobei eine optimale Anpassung von Format und Ton für jeden Kanal gewährleistet wird, während eine zusammenhängende Kampagnenbotschaft beibehalten wird.","pt":"Permite que os agentes transformem ativos de fonte única em sistemas de conteúdo nativos da plataforma em X, LinkedIn, TikTok, YouTube e boletins, garantindo a adaptação ótima de formato e tom para cada canal, mantendo a mensagem de campanha coesa.","ru":"Позволяет агентам преобразовывать единичные источники активов в системы контента, родные для платформ X, LinkedIn, TikTok, YouTube и рассылок, обеспечивая оптимальное соответствие формата и тона для каждого канала при сохранении сплоченной кампании.","ar":"يمكن للوكلاء تحويل الأصول المصدر الفردية إلى أنظمة المحتوى الأصلية للمنصة عبر X و LinkedIn و TikTok و YouTube والنشرة الإخبارية، مع ضمان التكيف الأمثل للتنسيق والتوكيد لكل قناة مع الحفاظ على رسالة الحملة المتكاملة."},"useCases":{"en":["Repurposing podcast transcripts into X threads","Adapting technical documentation into LinkedIn launch updates","Transforming demo videos into TikTok scripts","Creating content calendars from milestone themes","Converting articles into YouTube explainer scripts"],"zh":["将播客文字记录改写成 X 帖子串","将技术文档调整为 LinkedIn 发布更新","将演示视频转换为 TikTok 脚本","从里程碑主题创建内容日历","将文章转换为 YouTube 解说脚本"],"ja":["ポッドキャストの文字起こしを X のスレッドに再利用する","技術文書を LinkedIn のローンチアップデートに適応させる","デモ動画を TikTok スクリプトに変換する","マイルストーンテーマからコンテンツカレンダーを作成する","記事を YouTube の解説スクリプトに変換する"],"ko":["팟캐스트 대본을 X 스레드로 재활용하기","기술 문서를 LinkedIn 출시 업데이트로 적용하기","데모 비디오를 TikTok 스크립트로 변환하기","마일스톤 테마에서 콘텐츠 캘린더 만들기","기사를 YouTube 설명 스크립트로 전환하기"],"es":["Reutilizar transcripciones de podcasts en hilos de X","Adaptar documentación técnica en actualizaciones de lanzamiento para LinkedIn","Transformar vídeos de demostración en guiones para TikTok","Crear calendarios de contenido a partir de temas de hitos","Convertir artículos en guiones de explicación para YouTube"],"fr":["Réutiliser les transcriptions de podcasts en threads X","Adapter la documentation technique en mises à jour de lancement LinkedIn","Transformer des vidéos de démonstration en scripts TikTok","Créer des calendriers de contenu à partir de thèmes de jalons","Convertir des articles en scripts d''explication YouTube"],"de":["Umwandeln von Podcast-Transkripten in X-Threads","Anpassen von technischer Dokumentation in LinkedIn-Launch-Updates","Umgestalten von Demo-Videos in TikTok-Skripte","Erstellen von Content-Kalendern aus Meilenstein-Themen","Konvertieren von Artikeln in YouTube-Erklärskripte"],"pt":["Reutilizar transcrições de podcasts em threads do X","Adaptar documentação técnica em atualizações de lançamento do LinkedIn","Transformar vídeos de demonstração em scripts do TikTok","Criar calendários de conteúdo a partir de temas de marcos","Converter artigos em scripts de explicação do YouTube"],"ru":["Переиспользовать транскрипты подкастов в нитях X","Адаптировать техническую документацию в обновления запуска LinkedIn","Преобразовать демонстрационные видеоролики в скрипты TikTok","Создать календари контента из тем вех","Преобразовать статьи в сценарии объяснения YouTube"],"ar":["إعادة استخدام نسخ المخطوطات الصوتية في خيوط X","تكييف الوثائق الفنية في تحديثات إطلاق LinkedIn","تحويل مقاطع الفيديو التوضيحية إلى نصوص TikTok","إنشاء تقويم المحتوى من موضوعات المراحل","تحويل المقالات إلى نصوص شرح YouTube"]},"limitations":{"en":["Requires clear source asset input","Needs audience targeting parameters","Platform-specific formatting knowledge dependent on input quality"],"zh":["需要清晰的源素材输入","需要受众定位参数","平台特定格式知识取决于输入质量"],"ja":["明確なソース資産の入力が必要","オーディエンスターゲティングパラメータが必要","プラットフォーム固有のフォーマット知識は入力品質に依存"],"ko":["명확한 소스 자산 입력이 필요함","청중 타겟팅 매개변수가 필요함","플랫폼별 형식 지식은 입력 품질에 따라 다름"],"es":["Requiere una entrada clara de activos fuente","Necesita parámetros de orientación al público objetivo","El conocimiento del formato específico de la plataforma depende de la calidad de la entrada"],"fr":["Nécessite une saisie claire des actifs source","Requiert des paramètres de ciblage d''audience","Les connaissances en formatage spécifique à la plateforme dépendent de la qualité de la saisie"],"de":["Erfordert klare Eingabe der Quellen-Assets","Benötigt Parameter zur Zielgruppenausrichtung","Plattformspezifisches Formatierungswissen ist von der Qualität der Eingabe abhängig"],"pt":["Exige entrada de ativo de fonte clara","Necessita parâmetros de direcionamento de audiência","Conhecimento de formatação específico da plataforma dependente da qualidade da entrada"],"ru":["Требует четкого ввода источника актива","Требует параметров нацеливания на аудиторию","Знание форматирования, специфичное для платформы, зависит от качества ввода"],"ar":["يتطلب إدخال ممتاز لصيغة المصدر","يحتاج إلى معايير استهداف الجمهور","معرفة تنسيق محددة بالمنصة تعتمد على جودة الإدخال"]},"version":4},"contentHash":"057a610eab12e16bf447a46dd91de867ea450ce541fddc956d1abd55be5ec2cc","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":61}');
