INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/content-engine', 'content-engine', 'affaan-m', 'everything-claude-code', 'official', 'content-engine affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The content-engine MCP skill for AI agents like Claude creates platform-native content systems. It repurposes source assets into tailored posts, threads, scripts, and content calendars for developers and content teams. Content Engine是一种AI驱动的内容系统，能够为不同平台生成原生内容，包括X、LinkedIn、TikTok、YouTube等 Content Engineは、X、LinkedIn、TikTok、YouTubeなどの複数のプラットフォーム向けのネイティブコンテンツを生成するAI駆動のコンテンツシステム Content Engine은 X, LinkedIn, TikTok, YouTube 등 여러 플랫폼에 대한 네이티브 콘텐츠를 생성하는 AI 기반 콘텐츠 시스템 Content Engine es una herramienta que permite a los desarrolladores crear contenido nativo para múltiples plataformas Content Engine est un outil qui permet aux développeurs de créer du contenu natif pour plusieurs plateformes Content Engine ist ein Tool, mit dem Entwickler native Inhalte für mehrere Plattformen erstellen können O Content Engine é uma ferramenta que permite criar conteúdo nativo para várias plataformas, incluindo X, LinkedIn, TikTok e YouTube Content Engine - это инструмент, позволяющий создавать платформенно-родный контент для X, LinkedIn, TikTok и YouTube محرك المحتوى هو أداة تمكنك من إنشاء محتوى أصلي لمنصات متعددة، بما في ذلك X و LinkedIn و TikTok و YouTube what is content-engine how to use content-engine MCP content-engine vs repurpose.ai content-engine alternative content-engine install for Claude content-engine setup guide multi-platform content repurposing tool AI agent content generation skill Content Engine AI驱动的内容系统 跨平台内容系统 平台原生内容 复用多平台_campaign 内容日历 脚本生成 社交帖子生成 Generates X posts and threads from source assets Drafts LinkedIn posts and launch updates Creates scripts for short-form video and YouTube explainers Repurposes articles, podcasts, demos, or docs into social content Builds lightweight content plans around launches or themes content-engine is an MCP (Model Context Protocol) skill that enables AI agents to generate platform-native content from a single source asset. It specializes in adapting content for X threads, LinkedIn posts, TikTok scripts, YouTube explainers, and multi-platform campaigns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/nanoclaw-repl', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'nanoclaw-repl', 61988, 7678, 61, '2026-03-06T03:39:20Z', '2026-03-06T04:22:40.244Z', 'a917d56baef854638fd6a33c9d9ce4f819d3dd128286514ed28807d911935d27', '{"id":"affaan-m/everything-claude-code/nanoclaw-repl","name":"nanoclaw-repl","description":{"en":"NanoClaw REPL is a zero-dependency, session-aware CLI for operating and extending AI agents built on Claude. It provides developers with persistent markdown-backed sessions, dynamic skill loading, and advanced session management capabilities.","pt":"O nanoclaw-repl é um REPL de sessões persistentes baseado em markdown, construído sobre Claude para desenvolvedores. Permite operar e estender o scripts/claw.js com capacidades avançadas de gerenciamento de sessão e produtividade.","ru":"nanoclaw-repl — это сессионный REPL с поддержкой Markdown, построенный на основе Claude для разработчиков. Позволяет управлять и расширять scripts/claw.js с расширенными возможностями управления сессиями и повышения продуктивности.","ar":"nanoclaw-repl هي أداة REPL مع جلسات مستديمة مدعومة بـ Markdown، مبنية على Claude للمطورين. تتيح تشغيل وتوسيع scripts/claw.js بإمكانيات متقدمة لإدارة الجلسات والإنتاجية."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"nanoclaw-repl","description":"Operate and extend NanoClaw v2, ECCs zero-dependency session-aware REPL built on claude -p.","bodyPreview":"# NanoClaw REPL\n\nUse this skill when running or extending `scripts/claw.js`.\n\n## Capabilities\n\n- persistent markdown-backed sessions\n- model switching with `/model`\n- dynamic skill loading with `/load`\n- session branching with `/branch`\n- cross-session search with `/search`\n- history compaction with `/compact`\n- export to md/json/txt with `/export`\n- session metrics with `/metrics`\n\n## Operating Guidance\n\n1. Keep sessions task-focused.\n2. Branch before high-risk changes.\n3. Compact after major m","body":"# NanoClaw REPL\n\nUse this skill when running or extending `scripts/claw.js`.\n\n## Capabilities\n\n- persistent markdown-backed sessions\n- model switching with `/model`\n- dynamic skill loading with `/load`\n- session branching with `/branch`\n- cross-session search with `/search`\n- history compaction with `/compact`\n- export to md/json/txt with `/export`\n- session metrics with `/metrics`\n\n## Operating Guidance\n\n1. Keep sessions task-focused.\n2. Branch before high-risk changes.\n3. Compact after major milestones.\n4. Export before sharing or archival.\n\n## Extension Rules\n\n- keep zero external runtime dependencies\n- preserve markdown-as-database compatibility\n- keep command handlers deterministic and local\n"},"category":"official","lastSynced":"2026-03-06T04:22:40.244Z","seo":{"title":{"en":"NanoClaw REPL: Session-Aware CLI Best Practices | AI Agen...","pt":"nanoclaw-repl: Guia de Configuração para REPL com Sessões...","ru":"nanoclaw-repl: Руководство по настройке сессионного REPL ...","ar":"nanoclaw-repl: دليل الإعداد لأداة REPL مع جلسات مدعومة بـ..."},"description":{"en":"Master the NanoClaw REPL for persistent, markdown-backed AI agent sessions. Learn to branch, compact history, load skills dynamically, and export to MD/JSON/...","pt":"Aprenda a operar e estender o nanoclaw-repl, REPL com sessões persistentes em markdown para Claude. Inclui troca de modelo, branch de sessão, carregamento di...","ru":"Узнайте, как использовать и расширять nanoclaw-repl, сессионный REPL с поддержкой Markdown для Claude. Включает смену моделей, ветвление сессий, динамическую...","ar":"تعرف على كيفية تشغيل وتوسيع nanoclaw-repl، أداة REPL مع جلسات مستديمة مدعومة بـ Markdown لـ Claude. تتضمن تبديل النماذج، تفرع الجلسات، تحميل المهارات ديناميك..."},"definition":{"en":"nanoclaw-repl is a zero-dependency, session-aware REPL built on Claude for operating and extending the NanoClaw v2 AI agent. It features persistent markdown-backed sessions, dynamic skill loading, session branching, history compaction, and export capabilities to MD, JSON, and TXT formats.","pt":"O nanoclaw-repl é um REPL (Read-Eval-Print Loop) com consciência de sessão, sem dependências, construído sobre Claude. Ele utiliza markdown para sessões persistentes, permitindo que desenvolvedores operem e estendam o scripts/claw.js com funcionalidades avançadas de produtividade.","ru":"nanoclaw-repl — это сессионный REPL (Read-Eval-Print Loop) без зависимостей, построенный на основе Claude. Он использует Markdown для постоянных сессий, позволяя разработчикам управлять и расширять scripts/claw.js с расширенными функциями продуктивности.","ar":"nanoclaw-repl هي أداة REPL (حلقة القراءة-التقييم-الطباعة) مع جلسات مستديمة، خالية من التبعيات، مبنية على Claude. تستخدم Markdown للجلسات المستديمة، مما يسمح للمطورين بتشغيل وتوسيع scripts/claw.js بميزات إنتاجية متقدمة."},"features":{"en":["Persistent markdown-backed sessions for continuity","Dynamic skill loading via `/load` command","Session branching with `/branch` for risk management","Cross-session search using `/search` command","Export functionality to MD/JSON/TXT with `/export`","History compaction via `/compact` for efficiency"],"pt":["Sessões persistentes apoiadas por markdown","Troca de modelo com comando /model","Carregamento dinâmico de skills com /load","Branching de sessão com /branch","Busca entre sessões com /search","Exportação para md/json/txt com /export"],"ru":["Постоянные сессии с поддержкой Markdown","Смена модели с помощью команды /model","Динамическая загрузка навыков с /load","Ветвление сессий с /branch","Межсессионный поиск с /search","Экспорт в md/json/txt с /export"],"ar":["جلسات مستديمة مدعومة بـ Markdown","تبديل النموذج باستخدام الأمر /model","تحميل المهارات ديناميكيًا بـ /load","تفرع الجلسات مع /branch","بحث عبر الجلسات بـ /search","تصدير إلى md/json/txt بـ /export"]},"keywords":{"en":["how to use nanoclaw-repl","what is nanoclaw-repl","nanoclaw-repl session branching","nanoclaw-repl vs traditional repl","nanoclaw-repl install guide","nanoclaw-repl setup claude","nanoclaw-repl markdown sessions","nanoclaw-repl dynamic skill loading"],"pt":["nanoclaw-repl setup","REPL Claude sessions","markdown persistent sessions","dynamic skill loading","session branching","cross-session search","export md json txt","claude-code REPL","AI Agents developer tools"],"ru":["nanoclaw-repl настройка","REL Claude сессии","Markdown постоянные сессии","динамическая загрузка навыков","ветвление сессий","межсессионный поиск","экспорт md json txt","claude-code REPL","ИИ Агенты инструменты разработчика"],"ar":["nanoclaw-repl إعداد","REPL Claude جلسات","جلسات مستديمة Markdown","تحميل المهارات ديناميكيًا","تفرع الجلسات","بحث عبر الجلسات","تصدير md json txt","claude-code REPL","أدوات مطوري وكلاء الذكاء الاصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Essential for Claude-based REPL Agents requiring persistent, session-aware development environments with zero dependencies.","zh":"对于需要零依赖的持久性、会话感知开发环境的基于Claude的REPL代理至关重要。","ja":"ゼロ依存関係で永続的かつセッションを認識する開発環境を必要とするClaudeベースのREPLエージェントに不可欠です。","ko":"영구적이고 세션 인식 개발 환경이 필요하며 종속성이 전혀 없는 Claude 기반 REPL 에이전트에 필수적입니다.","es":"Esencial para los Agent REPL basados en Claude que requieren entornos de desarrollo persistentes, conscientes de la sesión y con cero dependencias.","fr":"Essentiel pour les Agents REPL basés sur Claude nécessitant des environnements de développement persistants, conscients de la session et sans aucune dépendance.","de":"Essenziell für Claude-basierte REPL-Agents, die persistente, sitzungsbewusste Entwicklungsumgebungen ohne Abhängigkeiten erfordern.","pt":"Essencial para Agentes REPL baseados no Claude que exigem ambientes de desenvolvimento persistentes e com consciência de sessão, sem dependências.","ru":"Необходимо для REPL-агентов на основе Claude, требующих постоянных сред разработки с осведомленностью о сеансах и нулевыми зависимостями.","ar":"أساسي لوكلاء REPL القائمة على Claude التي تتطلب بيئات تطوير دائمة وواعية بالجلسة بدون تبعيات."},"recommendation":{"en":"Enables persistent markdown-backed sessions with model switching, dynamic skill loading, and session branching capabilities. Provides cross-session search functionality and history compaction for efficient REPL management.","zh":"支持具有模型切换、动态技能加载和会话分支功能的持久性markdown支持会话。提供跨会话搜索功能和历史压缩，以实现高效的REPL管理。","ja":"モデル切り替え、動的スキルローディング、セッションブランチング機能を備えた永続的なmarkdownベースのセッションを可能にします。効率的なREPL管理のためのクロスセッション検索機能と履歴圧縮を提供します。","ko":"모델 전환, 동적 스킬 로딩 및 세션 분기 기능을 갖춘 지속적인 markdown 기반 세션을 가능하게 합니다. 효율적인 REPL 관리를 위한 크로스 세션 검색 기능 및 기록 압축을 제공합니다.","es":"Permite sesiones persistentes respaldadas por markdown con capacidades de cambio de modelo, carga dinámica de skills y bifurcación de sesiones. Proporciona funcionalidad de búsqueda entre sesiones y compactación del historial para una gestión eficiente del REPL.","fr":"Permet des sessions persistantes basées sur markdown avec changement de modèle, chargement dynamique de compétences et capacités de branchement de session. Fournit une fonctionnalité de recherche inter-sessions et une compaction de l''historique pour une gestion efficace du REPL.","de":"Ermöglicht persistente, markdown-gestützte Sitzungen mit Modellwechsel, dynamischem Skill-Laden und Sitzungsverzweigungsfähigkeiten. Bietet funktionsübergreifende Suchfunktionalität und History-Kompaktierung für ein effizientes REPL-Management.","pt":"Permite sessões persistentes apoiadas por markdown com alternância de modelos, carregamento dinâmico de habilidades e capacidades de ramificação de sessão. Fornece funcionalidade de pesquisa entre sessões e compactação de histórico para gerenciamento eficiente de REPL.","ru":"Обеспечивает постоянные сеансы на основе markdown с переключением моделей, динамической загрузкой навыков и возможностями ветвления сеансов. Предоставляет функциональность межсеансового поиска и сжатия истории для эффективного управления REPL.","ar":"يمكن من جلسات دائمة مدعومة بـ markdown مع تبديل النماذج، وتحميل المهارات الديناميكية، وإمكانيات تفرع الجلسة. يوفر وظيفة البحث عبر الجلسات وضغط السجل للإدارة الفعالة لـ REPL."},"useCases":{"en":["Operating NanoClaw v2 REPL sessions","Branching sessions before high-risk changes","Compacting history after major milestones","Exporting sessions to md/json/txt formats","Switching between AI models dynamically"],"zh":["运行NanoClaw v2 REPL会话","高风险更改前的会话分支","主要里程碑后的历史压缩","将会话导出为md/json/txt格式","动态切换AI模型"],"ja":["NanoClaw v2 REPLセッションの操作","高リスク変更前のセッションブランチング","主要マイルストーン後の履歴圧縮","セッションのmd/json/txt形式へのエクスポート","AIモデルの動的切り替え"],"ko":["NanoClaw v2 REPL 세션 운영","고위험 변경 전 세션 분기","주요 마일스톤 이후 기록 압축","세션을 md/json/txt 형식으로 내보내기","AI 모델 간 동적 전환"],"es":["Operación de sesiones REPL de NanoClaw v2","Bifurcación de sesiones antes de cambios de alto riesgo","Compactación del historial después de hitos importantes","Exportación de sesiones a formatos md/json/txt","Cambio dinámico entre modelos de AI"],"fr":["Exploitation des sessions REPL NanoClaw v2","Branchement de sessions avant des changements à haut risque","Compaction de l''historique après des jalons majeurs","Exportation de sessions vers les formats md/json/txt","Changement dynamique entre modèles d''IA"],"de":["Betrieb von NanoClaw v2 REPL-Sitzungen","Verzweigen von Sitzungen vor hochriskanten Änderungen","Kompaktieren des Verlaufs nach wichtigen Meilensteinen","Exportieren von Sitzungen in md/json/txt-Formate","Dynamisches Wechseln zwischen AI-Modellen"],"pt":["Operação de sessões REPL do NanoClaw v2","Ramificação de sessões antes de alterações de alto risco","Compactação do histórico após marcos importantes","Exportação de sessões para formatos md/json/txt","Alternância entre modelos de AI dinamicamente"],"ru":["Работа с сеансами REPL NanoClaw v2","Ветвление сеансов перед изменениями с высоким риском","Сжатие истории после основных этапов","Экспорт сеансов в форматы md/json/txt","Динамическое переключение между моделями AI"],"ar":["تشغيل جلسات NanoClaw v2 REPL","تفرع الجلسات قبل إجراء تغييرات عالية المخاطر","ضغط السجل بعد المعالم الرئيسية","تصدير الجلسات إلى صيغ md/json/txt","التبديل بين نماذج AI ديناميكيًا"]},"limitations":{"en":["Built specifically for claude -p environment","Requires running scripts/claw.js","Task-focused session management required","Zero-dependency design limits external integrations"],"zh":["专为claude -p环境构建","需要运行scripts/claw.js","需要任务导向的会话管理","零依赖设计限制了外部集成"],"ja":["claude -p環境専用に構築","scripts/claw.jsの実行が必要","タスクフォーカス型セッション管理が必要","ゼロ依存関係設計が外部連携を制限"],"ko":["claude -p 환경 전용으로 구축됨","scripts/claw.js 실행 필요","작업 중심 세션 관리 필요","제로 종속성 설계로 외부 통합 제한"],"es":["Construido específicamente para el entorno claude -p","Requiere la ejecución de scripts/claw.js","Se requiere una gestión de sesión centrada en tareas","El diseño de cero dependencias limita las integraciones externas"],"fr":["Conçu spécifiquement pour l''environnement claude -p","Nécessite l''exécution de scripts/claw.js","Une gestion de session axée sur les tâches est requise","La conception zéro dépendance limite les intégrations externes"],"de":["Speziell für die claude -p Umgebung gebaut","Erfordert das Ausführen von scripts/claw.js","Aufgabenfokussierte Sitzungsverwaltung erforderlich","Zero-Dependency-Design schränkt externe Integrationen ein"],"pt":["Construído especificamente para o ambiente claude -p","Requer a execução de scripts/claw.js","Requer gerenciamento de sessão focado em tarefas","O design de zero dependências limita integrações externas"],"ru":["Создан специально для среды claude -p","Требует запуска scripts/claw.js","Требуется управление сеансом, ориентированное на задачи","Дизайн с нулевыми зависимостями ограничивает внешние интеграции"],"ar":["مُصمم خصيصًا لبيئة claude -p","يتطلب تشغيل scripts/claw.js","يتطلب إدارة جلسة تركز على المهمة","يحد تصميم عدم وجود تبعيات من التكاملات الخارجية"]},"version":4},"contentHash":"a917d56baef854638fd6a33c9d9ce4f819d3dd128286514ed28807d911935d27","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":61}');
