INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/nanoclaw-repl', 'nanoclaw-repl', 'affaan-m', 'everything-claude-code', 'official', 'nanoclaw-repl affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity NanoClaw REPL is a zero-dependency, session-aware CLI for operating and extending AI agents built on Claude. It provides developers with persistent markdown-backed sessions, dynamic skill loading, and advanced session management capabilities. O nanoclaw-repl é um REPL de sessões persistentes baseado em markdown, construído sobre Claude para desenvolvedores. Permite operar e estender o scripts/claw.js com capacidades avançadas de gerenciamento de sessão e produtividade. nanoclaw-repl — это сессионный REPL с поддержкой Markdown, построенный на основе Claude для разработчиков. Позволяет управлять и расширять scripts/claw.js с расширенными возможностями управления сессиями и повышения продуктивности. nanoclaw-repl هي أداة REPL مع جلسات مستديمة مدعومة بـ Markdown، مبنية على Claude للمطورين. تتيح تشغيل وتوسيع scripts/claw.js بإمكانيات متقدمة لإدارة الجلسات والإنتاجية. how to use nanoclaw-repl what is nanoclaw-repl nanoclaw-repl session branching nanoclaw-repl vs traditional repl nanoclaw-repl install guide nanoclaw-repl setup claude nanoclaw-repl markdown sessions nanoclaw-repl dynamic skill loading Persistent markdown-backed sessions for continuity Dynamic skill loading via `/load` command Session branching with `/branch` for risk management Cross-session search using `/search` command Export functionality to MD/JSON/TXT with `/export` History compaction via `/compact` for efficiency nanoclaw-repl is a zero-dependency, session-aware REPL built on Claude for operating and extending the NanoClaw v2 AI agent. It features persistent markdown-backed sessions, dynamic skill loading, session branching, history compaction, and export capabilities to MD, JSON, and TXT formats.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Draculabo/AntigravityManager/openspec-continue-change', 'community', 'Draculabo', 'AntigravityManager', 'Draculabo/AntigravityManager', 'openspec-continue-change', 1001, 133, 60, '2026-03-05T11:34:38Z', '2026-03-06T06:26:13.174Z', '5fbcfc9f2fa055c153542d0fec06ffadd1321ab3aaeb76e4061756f490c16b1e', '{"id":"Draculabo/AntigravityManager/openspec-continue-change","name":"openspec-continue-change","description":{"en":"The openspec-continue-change skill enables seamless account switching and progress backup for Antigravity applications. It benefits developers working with Electron-based projects.","zh":"openspec-continue-change 是一个 Electron 应用程序，用于管理账户和进程。它提供了一个无缝的接口来切换账户、备份进度和控制应用程序生命周期","ja":"openspec-continue-change は、Electron アプリケーションのアカウントとプロセスを管理するための強力なツールです","ko":"openspec-continue-change는 Electron 애플리케이션의 계정 및 프로세스를 관리하는 강력한 도구입니다","es":"openspec-continue-change es una herramienta para continuar trabajando en un cambio creando el próximo artifacto. Permite seleccionar cambios y gestionar el ciclo de vida de la aplicación.","fr":"openspec-continue-change est un outil pour continuer à travailler sur une modification en créant le prochain artifact. Il permet de sélectionner des modifications et de gérer le cycle de vie de l''application.","de":"openspec-continue-change ist ein Tool, um an einer Änderung weiterzuarbeiten, indem das nächste Artifact erstellt wird. Es ermöglicht die Auswahl von Änderungen und die Verwaltung des Lebenszyklus der Anwendung.","pt":"O openspec-continue-change é uma ferramenta para continuar trabalhando em alterações com o Electron. Ele fornece uma interface para selecionar alterações e criar artefatos.","ru":"openspec-continue-change - это инструмент для продолжения работы над изменениями с помощью Electron и ИИ Агентов. Он предоставляет интерфейс для выбора изменений и создания 