INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Draculabo/AntigravityManager/openspec-continue-change', 'openspec-continue-change', 'Draculabo', 'AntigravityManager', 'community', 'openspec-continue-change Draculabo AntigravityManager community account-manager antigravity antigravity-ai antigravity-ide antigravity-tools antigravity2api electron gemini gemini-api gemini-pro The openspec-continue-change skill enables seamless account switching and progress backup for Antigravity applications. It benefits developers working with Electron-based projects. openspec-continue-change 是一个 Electron 应用程序，用于管理账户和进程。它提供了一个无缝的接口来切换账户、备份进度和控制应用程序生命周期 openspec-continue-change は、Electron アプリケーションのアカウントとプロセスを管理するための強力なツールです openspec-continue-change는 Electron 애플리케이션의 계정 및 프로세스를 관리하는 강력한 도구입니다 openspec-continue-change es una herramienta para continuar trabajando en un cambio creando el próximo artifacto. Permite seleccionar cambios y gestionar el ciclo de vida de la aplicación. openspec-continue-change est un outil pour continuer à travailler sur une modification en créant le prochain artifact. Il permet de sélectionner des modifications et de gérer le cycle de vie de l''application. openspec-continue-change ist ein Tool, um an einer Änderung weiterzuarbeiten, indem das nächste Artifact erstellt wird. Es ermöglicht die Auswahl von Änderungen und die Verwaltung des Lebenszyklus der Anwendung. O openspec-continue-change é uma ferramenta para continuar trabalhando em alterações com o Electron. Ele fornece uma interface para selecionar alterações e criar artefatos. openspec-continue-change - это инструмент для продолжения работы над изменениями с помощью Electron и ИИ Агентов. Он предоставляет интерфейс для выбора изменений и создания артефактов. openspec-continue-change هو أداة للاستمرار في العمل على التغييرات باستخدام Electron ووكلاء الذكاء الاصطناعي. يوفر واجهة لتحديد التغييرات وإنشاء الملفات المطلوبة. how to use openspec-continue-change openspec-continue-change setup guide what is openspec-continue-change openspec-continue-change alternative openspec-continue-change vs antigravity openspec-continue-change install electron-based application development antigravity application management account manager for antigravity openspec-continue-change Electron 应用程序 账户管理 进程管理 AI 工具 openspec list --json AskUserQuestion Runs `openspec list --json` to retrieve available changes sorted by most recently modified Utilizes the AskUserQuestion tool to prompt users for change selection Presents top 3-5 changes for user selection Optionally accepts a change name as input Infer change name from conversation context if not provided Supports Electron-based application lifecycle control openspec-continue-change is a skill that allows users to continue working on a change by creating the next artifact, utilizing the openspec list command and AskUserQuestion tool.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hw-native-sys/pypto/testing', 'community', 'hw-native-sys', 'pypto', 'hw-native-sys/pypto', 'testing', 17, 25, 60, '2026-02-26T03:55:31Z', '2026-03-06T06:42:31.555Z', '5c72eeb8fd9a8bda93e84368ed06c49f661bced0627b55d011957dafd83f0ff9', '{"id":"hw-native-sys/pypto/testing","name":"testing","description":{"en":"This testing skill is designed for developers to validate PyPTO code changes. It builds and tests the project to ensure code integrity.","zh":"PyPTO测试技能是一个社区驱动的Python实现，用于构建和测试PyPTO项目","ja":"PyPTOテストスキルは、PyPTOプロジェクトの構築とテストに使用されるコミュニティ駆動のPython実装です","ko":"PyPTO 테스트 스킬은 PyPTO 프로젝트를 구축하고 테스트하는 데 사용되는 커뮤니티 주도 Python 구현입니다","es":"El skill de pruebas de PyPTO es una implementación de prueba comunitaria que verifica los cambios de código","fr":"Le skill de test de PyPTO est une mise en œuvre de test communautaire qui vérifie les modifications de code","de":"Das PyPTO-Test-Skill ist eine communitygetriebene Testimplementierung, die Codeänderungen überprüft","pt":"O agente de testes de PyPTO é uma implementação comunitária que verifica alterações de código","ru":"Агент тестирования PyPTO - это comunidadная реализация для проверки изменений кода","ar":"وكيل اختبار PyPTO هو تطبيق مجتمعي يتحقق من تغييرات الكود"},"seo":{"title":{"en":"Testing: Automated PyPTO Validation for AI Agents | AI Ag...","zh":"AI测试工具：PyPTO测试技能设置指南","ja":"AIエージェントのテストスキル：PyPTOテストのベストプラクティス","ko":"AI 에이전트 테스트 스킬: PyPTO 테스트 설정 가이드","es":"Guía de configuración de pruebas de PyPTO","fr":"Guide de configuration des tests PyPTO","de":"Einrichtungsleitfaden für PyPTO-Tests","pt":"Guia de Configuração de Testes de PyPTO","ru":"Настройка тестирования PyPTO: ИИ Агенты","ar":"دليل إعداد اختبار PyPTO باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to automate PyPTO testing with this AI agent skill. Learn how to invoke tasks and validate code changes with ease.","zh":"了解PyPTO测试技能的设置和使用方法，确保代码变更不会破坏现有功能","ja":"PyPTOテストスキルの設定と使用方法を学び、コードの変更が機能に影響を与えないことを確認する","ko":"PyPTO 테스트 스킬의 설정과 사용 방법을 알아보고 코드 변경이 기능에 영향을 미치지 않는지 확인하세요","es":"Aprende a configurar y ejecutar pruebas para el proyecto PyPTO con esta guía paso a paso","fr":"Découvrez comment configurer et exécuter des tests pour le projet PyPTO avec ce guide étape par étape","de":"Erfahren Sie, wie Sie Tests für das PyPTO-Projekt konfigurieren und ausführen, mit diesem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar testes de PyPTO para verificar alterações de código com o agente de testes","ru":"Настройте тестирование PyPTO с помощью агента тестирования и ИИ Агентов","ar":"تعلم كيفية إعداد اختبار PyPTO باستخدام أدوات الذكاء الاصطناعي ووكلاء الاختبار"},"definition":{"en":"Testing is a community-driven PyPTO implementation that automates the validation of code changes through building and running tests.","zh":"PyPTO测试技能是一种用于验证代码变更的AI测试工具","ja":"PyPTOテストスキルは、コードの変更を検証するためのAIエージェントのテスト機能です","ko":"PyPTO 테스트 스킬은 코드 변경을 검증하기 위한 AI 에이전트의 테스트 기능입니다","es":"Un skill de pruebas es una herramienta de AI que verifica los cambios de código en un proyecto","fr":"Un skill de test est un outil d''IA qui vérifie les modifications de code dans un projet","de":"Ein Test-Skill ist ein AI-Tool, das Codeänderungen in einem Projekt überprüft","pt":"O que é teste de PyPTO? É uma ferramenta de teste comunitária para verificar alterações de código","ru":"Что такое тестирование PyPTO? Это comunidadная herramienta для проверки изменений кода","ar":"ما هو اختبار PyPTO؟ أداة اختبار مجتمعية لتحقق من تغييرات الكود"},"features":{"en":["Invokes Task tool with `subagent_type=\"testing\"` for specialized agent testing","Builds and runs all tests for the PyPTO project","Sources `.claude/skills/testing/testing.env` for environment setup","Utilizes bash commands for conditional environment setup","Runs tests to verify code changes haven''t broken existing functionality"],"zh":["构建PyPTO项目","运行所有测试","支持环境变量设置","使用Task工具进行测试","源自`.claude/skills/testing/testing.env`文件"],"ja":["PyPTOプロジェクトの構築","すべてのテストの実行","環境変数の設定をサポート","Taskツールを使用したテスト","`.claude/skills/testing/testing.env`ファイルからのソース"],"ko":["PyPTO 프로젝트 구축","모든 테스트 실행","환경 변수 설정 지원","Task 도구를 사용한 테스트","`.claude/skills/testing/testing.env` 파일에서 소스"],"es":["Implementación de pruebas comunitaria","Verificación de cambios de código","Ejecución de tests con `subagent_type=''testing''`","Configuración de entorno con `.claude/skills/testing/testing.env`","Compatibilidad con herramientas de tarea","Soporte para testing de proyecto PyPTO"],"fr":["Mise en œuvre de test communautaire","Vérification des modifications de code","Exécution de tests avec `subagent_type=''testing''`","Configuration de l''environnement avec `.claude/skills/testing/testing.env`","Compatibilité avec les outils de tâche","Prise en charge du test de projet PyPTO"],"de":["Communitygetriebene Testimplementierung","Überprüfung von Codeänderungen","Ausführung von Tests mit `subagent_type=''testing''`","Konfiguration der Umgebung mit `.claude/skills/testing/testing.env`","Kompatibilität mit Task-Tools","Unterstützung für PyPTO-Projekt-Tests"],"pt":["Implementação comunitária de PyPTO","Verificação de alterações de código","Uso de agente de testes especializado","Execução de testes com `subagent_type=\"testing\"`","Configuração de ambiente com `.claude/skills/testing/testing.env`"],"ru":["Сообщественная реализация PyPTO","Проверка изменений кода","Использование специализированного агента тестирования","Выполнение тестов с `subagent_type=\"testing\"`","Настройка среды с `.claude/skills/testing/testing.env`"],"ar":["تطبيق مجتمعي لاختبار PyPTO","التحقق من تغييرات الكود","استخدام وكلاء اختبار متخصصين","تشغيل الاختبارات مع `subagent_type=\"testing\"`","إعداد بيئة مع `.claude/skills/testing/testing.env`"]},"keywords":{"en":["how to use testing for PyPTO","what is testing in AI agents","testing alternative for PyPTO validation","testing vs manual validation","testing install guide for AI agents","testing setup for PyPTO projects","automated testing for AI agents","PyPTO testing best practices","testing for AI agent development"],"zh":["AI测试工具","PyPTO测试技能","Python测试","代码变更验证","Task工具","环境变量设置","AIエージェント"],"ja":["AIエージェントのテストスキル","PyPTOテスト","Pythonテスト","コードの変更を検証","Taskツール","環境変数の設定","AIツール"],"ko":["AI 에이전트 테스트 스킬","PyPTO 테스트","Python 테스트","코드 변경 검증","Task 도구","환경 변수 설정","AI 도구"],"es":["pruebas de PyPTO","herramientas de AI para pruebas","configuración de pruebas","testing de proyecto","subagent_type=testing","testing de código","herramientas de tarea para pruebas","pruebas comunitarias","PyPTO testing"],"fr":["tests de PyPTO","outils d''IA pour les tests","configuration des tests","test de projet","subagent_type=testing","test de code","outils de tâche pour les tests","tests communautaires","PyPTO test"],"de":["PyPTO-Tests","AI-Tools für Tests","Testkonfiguration","Projekt-Tests","subagent_type=testing","Code-Tests","Task-Tools für Tests","Community-Tests","PyPTO-Test"],"pt":["teste de PyPTO","agente de testes","configuração de testes","verificação de código","ferramentas de teste","desenvolvimento de software","Python"],"ru":["тестирование PyPTO","агент тестирования","настройка тестирования","проверка кода","инструменты тестирования","разработка программного обеспечения","Python","ИИ Агенты"],"ar":["اختبار PyPTO","وكيل اختبار","إعداد اختبار","التحقق من الكود","أدوات الاختبار","تطوير البرمجيات","Python","أدوات الذكاء الاصطناعي"]}},"owner":"hw-native-sys","repo":"pypto","repoPath":"hw-native-sys/pypto","stars":17,"forks":25,"updatedAt":"2026-02-26T03:55:31Z","topics":[],"category":"community","skillMd":{"name":"testing","description":"Verify testing coverage and run tests for PyPTO project. Use when running tests, checking test coverage, or when the user asks about testing.","bodyPreview":"# PyPTO Testing Skill\n\n## Overview\n\nBuild and test the PyPTO project to verify code changes haven''t broken anything.\n\n## How to Use\n\n1. Read agent instructions at [.claude/agents/testing/AGENT.md](.claude/agents/testing/AGENT.md)\n2. Invoke Task tool with `subagent_type=\"testing\"` (specialized agent)\n3. Agent will build project and run all tests\n\n## Environment Setup\n\n**If `.claude/skills/testing/testing.env` exists**: Source it before testing.\n\n```bash\n[ -f .claude/skills/testing/testing.env ] &","body":"# PyPTO Testing Skill\n\n## Overview\n\nBuild and test the PyPTO project to verify code changes haven''t broken anything.\n\n## How to Use\n\n1. Read agent instructions at [.claude/agents/testing/AGENT.md](.claude/agents/testing/AGENT.md)\n2. Invoke Task tool with `subagent_type=\"testing\"` (specialized agent)\n3. Agent will build project and run all tests\n\n## Environment Setup\n\n**If `.claude/skills/testing/testing.env` exists**: Source it before testing.\n\n```bash\n[ -f .claude/skills/testing/testing.env ] && source .claude/skills/testing/testing.env\n```\n\n**If doesn''t exist**: Skip and suggest creating one (see `testing.env.example`).\n\n## Testing Workflow\n\n```bash\n# 1. Activate environment (if testing.env exists)\n[ -f .claude/skills/testing/testing.env ] && source .claude/skills/testing/testing.env\n\n# 2. Build project\ncmake --build build\n\n# 3. Set PYTHONPATH\nexport PYTHONPATH=$(pwd)/python:$PYTHONPATH\n\n# 4. Run tests\npython -m pytest tests/ut/ -v\n```\n\n## Test Commands\n\n```bash\n# Run all tests\npython -m pytest tests/ut/ -v\n\n# Run specific test file\npython -m pytest tests/ut/test_ir_basic.py -v\n\n# Run specific test\npython -m pytest tests/ut/test_ir_basic.py::test_tensor_expr_creation -v\n\n# Run with coverage\npython -m pytest tests/ut/ --cov=pypto_core --cov-report=html\n```\n\n## Test Structure\n\n```text\ntests/ut/\n├── core/          # Core functionality\n├── ir/            # IR (nodes, expressions, operators, parser)\n└── pass/          # Pass manager\n```\n\n## Testing Checklist\n\n- [ ] Project builds without errors\n- [ ] No new compiler warnings\n- [ ] All existing tests pass\n- [ ] New features have tests\n- [ ] Bug fixes have regression tests\n- [ ] Tests in `tests/ut/` (not elsewhere)\n\n## Common Issues\n\n| Issue | Solution |\n| ----- | -------- |\n| `ImportError: No module named ''pypto_core''` | `export PYTHONPATH=$(pwd)/python:$PYTHONPATH` |\n| Tests fail after code changes | `cmake --build build` then re-run |\n| Tests in wrong location | Move to `tests/ut/` |\n\n## Output Format\n\n```text\n## Testing Summary\n**Status:** ✅ PASS / ⚠️ WARNINGS / ❌ FAIL\n\n### Build Results\n[Compiler output, warnings/errors]\n\n### Test Results\n- Total: X | Passed: X | Failed: X | Skipped: X\n\n### Failures\n[Failed test details if any]\n\n### Recommendations\n[Actions to fix issues]\n```\n\n## Decision Criteria\n\n| Status | Criteria |\n| ------ | -------- |\n| **PASS** | All tests pass, build succeeds, no new warnings |\n| **WARNINGS** | Tests pass but new warnings or skipped tests |\n| **FAIL** | Build fails or tests fail |\n\n## Important Notes\n\n- Always rebuild before running tests\n- Check both build and test output\n- Look for new warnings even if tests pass\n- Verify new features have corresponding tests\n\n## Related Skills\n\n- **`code-review`** - Code review (runs in parallel with testing)\n- **`git-commit`** - Complete commit workflow\n"},"lastSynced":"2026-03-06T06:42:31.555Z","agentAnalysis":{"suitability":{"en":"Perfect for PyPTO Development Agents needing automated code validation and testing capabilities.","zh":"非常适合需要自动代码验证和测试功能的PyPTO开发代理。","ja":"PyPTO開発エージェントが自動コード検証およびテスト機能を必要とする場合に最適です。","ko":"자동 코드 검증 및 테스트 기능이 필요한 PyPTO 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de PyPTO que necesitan capacidades de validación y prueba de código automatizadas.","fr":"Parfait pour les agents de développement PyPTO ayant besoin de capacités de validation et de test de code automatisées.","de":"Perfekt für PyPTO-Entwicklungsagenten, die automatisierte Code-Validierungs- und Testfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento PyPTO que necessitam de capacidades de validação e teste de código automatizadas.","ru":"Идеально подходит для агентов разработки PyPTO, которым требуются автоматические возможности проверки и тестирования кода.","ar":"مثالي لعميل التطوير PyPTO الذي يحتاج إلى إمكانيات التحقق والاختبار التلقائي للكود."},"recommendation":{"en":"Empowers agents to verify code integrity by building and testing PyPTO projects, ensuring seamless validation of code changes using specialized subagents and task tools, and supporting environment setup with `.claude/skills/testing/testing.env` files.","zh":"赋予代理验证代码完整性，通过构建和测试PyPTO项目，确保使用专用子代理和任务工具对代码更改进行无缝验证，并支持使用`.claude/skills/testing/testing.env`文件进行环境设置。","ja":"エージェントにコードの完全性を検証する機能を提供し、PyPTOプロジェクトのビルドとテストを実行し、専用のサブエージェントとタスクツールを使用してコードの変更をスムーズに検証し、`.claude/skills/testing/testing.env`ファイルを使用した環境設定をサポートします。","ko":"에이전트가 코드 무결성을 검증할 수 있도록 하며, PyPTO 프로젝트를 빌드하고 테스트하고, 전문적인 하위 에이전트 및 작업 도구를 사용하여 코드 변경 사항을 무결점으로 검증하며, `.claude/skills/testing/testing.env` 파일을 사용하여 환경 설정을 지원합니다.","es":"Habilita a los agentes a verificar la integridad del código mediante la creación y prueba de proyectos PyPTO, garantizando una validación fluida de los cambios de código mediante subagentes especializados y herramientas de tareas, y soportando la configuración del entorno con archivos `.claude/skills/testing/testing.env`.","fr":"Permet aux agents de vérifier l''intégrité du code en créant et en testant des projets PyPTO, en garantissant une validation fluide des modifications de code à l''aide de sous-agents spécialisés et d''outils de tâches, et en supportant la configuration de l''environnement avec des fichiers `.claude/skills/testing/testing.env`.","de":"Ermächtigt die Agenten, die Code-Integrität durch Erstellen und Testen von PyPTO-Projekten zu überprüfen, eine nahtlose Validierung von Code-Änderungen mit spezialisierten Subagenten und Aufgaben-Tools zu gewährleisten und die Umgebungs-Einrichtung mit Dateien `.claude/skills/testing/testing.env` zu unterstützen.","pt":"Habilita os agentes a verificar a integridade do código, construindo e testando projetos PyPTO, garantindo a validação sem problemas das alterações de código usando subagentes especializados e ferramentas de tarefas, e apoiando a configuração do ambiente com arquivos `.claude/skills/testing/testing.env`.","ru":"Наделяет агентов возможностью проверить целостность кода, создавая и тестируя проекты PyPTO, обеспечивая бесперебойную проверку изменений кода с помощью специализированных субагентов и инструментов задач, а также поддержку настройки окружения с помощью файлов `.claude/skills/testing/testing.env`.","ar":"تمكين الوكيل من التحقق من سلامة الكود من خلال بناء وتجريب مشاريع PyPTO، وضمان التحقق السلس لتحديثات الكود باستخدام وكلاء فرعيين متخصصين وأدوات مهام، ودعم إعداد البيئة باستخدام ملفات `.claude/skills/testing/testing.env`."},"useCases":{"en":["Validating PyPTO code changes","Automating project builds and tests","Ensuring code integrity with specialized subagents"],"zh":["验证PyPTO代码更改","自动化项目构建和测试","使用专用子代理确保代码完整性"],"ja":["PyPTOコードの変更を検証する","プロジェクトのビルドとテストを自動化する","専用のサブエージェントを使用してコードの完全性を確保する"],"ko":["PyPTO 코드 변경 사항 검증","프로젝트 빌드 및 테스트 자동화","전문적인 하위 에이전트를 사용하여 코드 무결성 보장"],"es":["Validar los cambios de código de PyPTO","Automatizar la creación y las pruebas de proyectos","Garantizar la integridad del código con subagentes especializados"],"fr":["Valider les modifications de code de PyPTO","Automatiser la création et les tests de projets","Assurer l''intégrité du code avec des sous-agents spécialisés"],"de":["PyPTO-Code-Änderungen validieren","Projekt-Erstellung und -Tests automatisieren","Code-Integrität mit spezialisierten Subagenten sicherstellen"],"pt":["Validar alterações de código PyPTO","Automatizar compilações e testes de projeto","Garantir a integridade do código com subagentes especializados"],"ru":["Проверка изменений кода PyPTO","Автоматизация сборки и тестирования проекта","Обеспечение целостности кода с помощью специализированных субагентов"],"ar":["التحقق من تحديثات كود PyPTO","تأهيل بناء وتجريب المشروع تلقائيًا","ضمان سلامة الكود باستخدام وكلاء فرعيين متخصصين"]},"limitations":{"en":["Requires `.claude/agents/testing/AGENT.md` instructions","PyPTO project specific","Environment setup required with `.claude/skills/testing/testing.env` file if present"],"zh":["需要`.claude/agents/testing/AGENT.md`说明","特定于PyPTO项目","如果存在，需要使用`.claude/skills/testing/testing.env`文件进行环境设置"],"ja":["`.claude/agents/testing/AGENT.md`の説明が必要","PyPTOプロジェクトに特有","存在する場合、`.claude/skills/testing/testing.env`ファイルを使用した環境設定が必要"],"ko":["`.claude/agents/testing/AGENT.md` 지침 필요","PyPTO 프로젝트에 특정","存在하는 경우 `.claude/skills/testing/testing.env` 파일을 사용하여 환경 설정이 필요"],"es":["Requiere instrucciones en `.claude/agents/testing/AGENT.md`","Específico del proyecto PyPTO","Configuración del entorno requerida con archivo `.claude/skills/testing/testing.env` si está presente"],"fr":["Nécessite des instructions dans `.claude/agents/testing/AGENT.md`","Spécifique au projet PyPTO","Configuration de l''environnement requise avec un fichier `.claude/skills/testing/testing.env` si présent"],"de":["Benötigt Anweisungen in `.claude/agents/testing/AGENT.md`","PyPTO-Projekt-spezifisch","Umgebungs-Einrichtung erforderlich mit Datei `.claude/skills/testing/testing.env`, wenn vorhanden"],"pt":["Requer instruções `.claude/agents/testing/AGENT.md`","Específico para projetos PyPTO","Configuração do ambiente necessária com arquivo `.claude/skills/testing/testing.env` se presente"],"ru":["Требует инструкций `.claude/agents/testing/AGENT.md`","Конкретно для проектов PyPTO","Настройка окружения требуется с помощью файла `.claude/skills/testing/testing.env`, если он присутствует"],"ar":["يتطلب تعليمات `.claude/agents/testing/AGENT.md`","محدد لمشاريع PyPTO","تكوين البيئة مطلوب باستخدام ملف `.claude/skills/testing/testing.env` إذا كان موجودًا"]},"version":4},"contentHash":"5c72eeb8fd9a8bda93e84368ed06c49f661bced0627b55d011957dafd83f0ff9","qualityScore":60}');
