INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hw-native-sys/pypto/testing', 'testing', 'hw-native-sys', 'pypto', 'community', 'testing hw-native-sys pypto community This testing skill is designed for developers to validate PyPTO code changes. It builds and tests the project to ensure code integrity. PyPTO测试技能是一个社区驱动的Python实现，用于构建和测试PyPTO项目 PyPTOテストスキルは、PyPTOプロジェクトの構築とテストに使用されるコミュニティ駆動のPython実装です PyPTO 테스트 스킬은 PyPTO 프로젝트를 구축하고 테스트하는 데 사용되는 커뮤니티 주도 Python 구현입니다 El skill de pruebas de PyPTO es una implementación de prueba comunitaria que verifica los cambios de código Le skill de test de PyPTO est une mise en œuvre de test communautaire qui vérifie les modifications de code Das PyPTO-Test-Skill ist eine communitygetriebene Testimplementierung, die Codeänderungen überprüft O agente de testes de PyPTO é uma implementação comunitária que verifica alterações de código Агент тестирования PyPTO - это comunidadная реализация для проверки изменений кода وكيل اختبار PyPTO هو تطبيق مجتمعي يتحقق من تغييرات الكود how to use testing for PyPTO what is testing in AI agents testing alternative for PyPTO validation testing vs manual validation testing install guide for AI agents testing setup for PyPTO projects automated testing for AI agents PyPTO testing best practices testing for AI agent development AI测试工具 PyPTO测试技能 Python测试 代码变更验证 Task工具 环境变量设置 AIエージェント Invokes Task tool with `subagent_type="testing"` for specialized agent testing Builds and runs all tests for the PyPTO project Sources `.claude/skills/testing/testing.env` for environment setup Utilizes bash commands for conditional environment setup Runs tests to verify code changes haven''t broken existing functionality Testing is a community-driven PyPTO implementation that automates the validation of code changes through building and running tests.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('attasec/tmdd/tmdd-threat-modeling', 'community', 'attasec', 'tmdd', 'attasec/tmdd', 'tmdd-threat-modeling', 16, 1, 60, '2026-03-01T20:41:46Z', '2026-03-06T06:43:39.131Z', '81365f89eccfe25b89d249a88288ff96da85373f8b0517157570ee8c007990dd', '{"id":"attasec/tmdd/tmdd-threat-modeling","name":"tmdd-threat-modeling","description":{"en":"tmdd-threat-modeling is a CLI tool for Continuous Threat Modeling, benefiting developers by automating threat modeling tasks. It supports creating, initializing, and scaffolding threat models.","zh":"TMDD 威胁建模工具是一种 CLI 工具，用于持续威胁建模。它可以帮助开发人员创建、初始化和运行威胁模型","ja":"TMDD 脅威モデリングツールは、継続的な脅威モデリングのための CLI ツールです。開発者が脅威モデルの作成、初期化、実行を支援します","ko":"TMDD 위협 모델링 도구는 지속적인 위협 모델링을 위한 CLI 도구입니다. 개발자가 위협 모델을 생성, 초기화 및 실행하는 것을 도와줍니다","es":"tmdd-threat-modeling es una herramienta de línea de comandos para el modelado de amenazas continuo, que se integra con su código para identificar vulnerabilidades","fr":"tmdd-threat-modeling est un outil en ligne de commande pour la modélisation de menaces continue, qui s''intègre à votre code pour identifier les vulnérabilités","de":"tmdd-threat-modeling ist ein CLI-Tool für kontinuierliches Bedrohungsmodellierung, das sich in Ihren Code integriert, um Schwachstellen zu identifizieren","pt":"O tmdd-threat-modeling é uma ferramenta CLI para modelagem de ameaças contínua, ajudando a identificar vulnerabilidades no código","ru":"ИИ Агент tmdd-threat-modeling - это инструмент постоянной threat modeling, помогающий выявлять уязвимости в коде","ar":"أداة نمذجة التهديدات المستمرة tmdd-threat-modeling هي أداة سطر أوامر لمواجهة التهديدات المستمرة، تساعد في تحديد نقاط الضعف في الكود"},"seo":{"title":{"en":"tmdd-threat-modeling: Threat Modeling Setup Guide | AI Ag...","zh":"TMDD 威胁建模工具：持续威胁建模的 CLI 解决方案","ja":"TMDD 脅威モデリングツール：継続的な脅威モデリングのための CLI ソリューション","ko":"TMDD 위협 모델링 도구: 지속적인 위협 모델링을 위한 CLI 솔루션","es":"Guía de configuración de tmdd-threat-modeling para modela...","fr":"Guide de mise en place de tmdd-threat-modeling pour la mo...","de":"Einrichtungsanleitung für tmdd-threat-modeling zur Bedroh...","pt":"Guia de Configuração do tmdd-threat-modeling: Ferramenta ...","ru":"Настройка ИИ Агента tmdd-threat-modeling: Инструмент Пост...","ar":"دليل إعداد tmdd-threat-modeling: أداة نمذجة التهديدات الم..."},"description":{"en":"Discover how tmdd-threat-modeling streamlines threat modeling with CLI tools and Architecture-First approach. Get started with our setup guide today!","zh":"使用 TMDD 威胁建模工具，实现持续威胁建模和代码安全性。了解如何创建、初始化和运行威胁模型","ja":"TMDD 脅威モデリングツールを使用して、継続的な脅威モデリングとコードのセキュリティを実現します。脅威モデルの作成、初期化、実行方法について学びます","ko":"TMDD 위협 모델링 도구를 사용하여 지속적인 위협 모델링과 코드 보안을 구현합니다. 위협 모델의 생성, 초기화 및 실행 방법에 대해 알아보세요","es":"Aprende a utilizar tmdd-threat-modeling, una herramienta de línea de comandos para el modelado de amenazas continuo, y mejora la seguridad de tu código","fr":"Découvrez comment utiliser tmdd-threat-modeling, un outil en ligne de commande pour la modélisation de menaces continue, et améliorez la sécurité de votre code","de":"Erfahren Sie, wie Sie tmdd-threat-modeling, ein CLI-Tool für kontinuierliches Bedrohungsmodellierung, verwenden können, um die Sicherheit Ihres Codes zu verb...","pt":"Aprenda a configurar o tmdd-threat-modeling, uma ferramenta CLI para modelagem de ameaças contínua, e melhore a segurança do seu código","ru":"Узнайте, как настроить ИИ Агент tmdd-threat-modeling, инструмент постоянной threat modeling, и повысьте безопасность вашего кода","ar":"تعرف على كيفية إعداد أداة نمذجة التهديدات المستمرة tmdd-threat-modeling و تحسين أمان kodك"},"definition":{"en":"tmdd-threat-modeling is a Continuous Threat Modeling CLI tool that grounds threat models in actual codebases, following an Architecture-First approach.","zh":"TMDD 威胁建模工具是一种基于架构的威胁建模方法，用于确保威胁模型与实际代码库保持一致","ja":"TMDD 脅威モデリングツールは、アーキテクチャに基づいた脅威モデリング方法であり、脅威モデルの実コードベースとの一致を保証する","ko":"TMDD 위협 모델링 도구는 아키텍처 기반의 위협 모델링 방법으로, 위협 모델이 실제 코드베이스와 일치하도록 보장합니다","es":"tmdd-threat-modeling es una herramienta de modelado de amenazas que se basa en la arquitectura del código para identificar vulnerabilidades","fr":"tmdd-threat-modeling est un outil de modélisation de menaces qui se base sur l''architecture du code pour identifier les vulnérabilités","de":"tmdd-threat-modeling ist ein Tool für Bedrohungsmodellierung, das auf der Architektur des Codes basiert, um Schwachstellen zu identifizieren","pt":"O que é tmdd-threat-modeling? É uma ferramenta de modelagem de ameaças contínua baseada em arquitetura","ru":"Что такое ИИ Агент tmdd-threat-modeling? Это инструмент постоянной threat modeling, основанный на архитектуре","ar":"ما هو tmdd-threat-modeling؟ هو أداة نمذجة التهديدات المستمرة القائمة على الهندسة المعمارية"},"features":{"en":["Creates, initializes, or scaffolds threat models","Adds features to existing threat models","Threat-models codebases, services, or features","Runs or fixes `tmdd lint` errors","Generates implementation prompts from threat models","Auto-activates when editing `.tmdd*.yaml` files"],"zh":["创建和初始化威胁模型","添加功能到现有的威胁模型","运行和修复 tmdd lint 错误","生成实现提示从威胁模型","支持 .tmdd*.yaml 文件编辑"],"ja":["脅威モデルの作成と初期化","既存の脅威モデルの機能追加","tmdd lint エラーの実行と修復","脅威モデルの実装のヒントの生成",".tmdd*.yaml ファイルの編集サポート"],"ko":["위협 모델의 생성과 초기화","기존 위협 모델에 기능 추가","tmdd lint 오류의 실행과 수정","위협 모델에서 구현提示 생성",".tmdd*.yaml 파일 편집 지원"],"es":["Modelado de amenazas continuo","Integración con código para identificar vulnerabilidades","Compatible con archivos `.tmdd*.yaml`","Ejecución de `tmdd lint` para detectar errores","Generación de implementaciones a partir de modelos de amenazas","Arquitectura-First Threat Modeling"],"fr":["Modélisation de menaces continue","Intégration avec le code pour identifier les vulnérabilités","Compatible avec les fichiers `.tmdd*.yaml`","Exécution de `tmdd lint` pour détecter les erreurs","Génération d''implémentations à partir de modèles de menaces","Modélisation de menaces basée sur l''architecture"],"de":["Kontinuierliches Bedrohungsmodellierung","Integration mit Code zur Identifizierung von Schwachstellen","Kompatibel mit Dateien `.tmdd*.yaml`","Ausführung von `tmdd lint` zur Fehlererkennung","Generierung von Implementierungen aus Bedrohungsmodellen","Architektur-First Bedrohungsmodellierung"],"pt":["Criação e inicialização de modelos de ameaças","Adição de recursos a modelos de ameaças existentes","Análise de código para identificar vulnerabilidades","Geração de prompts de implementação a partir de modelos de ameaças","Suporte a arquivos `.tmdd*.yaml`"],"ru":["Создание и инициализация моделей угроз","Добавление функций к существующим моделям угроз","Анализ кода для выявления уязвимостей","Генерация подсказок для реализации на основе моделей угроз","Поддержка файлов `.tmdd*.yaml`"],"ar":["إنشاء وتهيئة نماذج التهديدات","إضافة ميزات إلى نماذج التهديدات الحالية","تحليل الكود لتحديد نقاط الضعف","توليد تلميحات التنفيذ من نماذج التهديدات","دعم الملفات `.tmdd*.yaml`"]},"keywords":{"en":["how to use tmdd-threat-modeling","tmdd-threat-modeling setup guide","tmdd-threat-modeling alternative","tmdd-threat-modeling vs threat modeling tools","tmdd-threat-modeling install","what is tmdd-threat-modeling","tmdd-threat-modeling tutorial","tmdd-threat-modeling best practices","continuous threat modeling with tmdd-threat-modeling"],"zh":["TMDD 威胁建模","持续威胁建模","CLI 工具","代码安全性","架构 기반威胁建模","AI エージェント","威胁模型创建","tmdd lint"],"ja":["TMDD 脅威モデリング","継続的な脅威モデリング","CLI ツール","コードのセキュリティ","アーキテクチャに基づいた脅威モデリング","AI エージェント","脅威モデルの作成","tmdd lint"],"ko":["TMDD 위협 모델링","지속적인 위협 모델링","CLI 도구","코드 보안","아키텍처 기반 위협 모델링","AI 에이전트","위협 모델 생성","tmdd lint"],"es":["tmdd-threat-modeling","modelado de amenazas","seguridad de código","herramientas de línea de comandos","integración con código","identificación de vulnerabilidades","modelado de amenazas continuo","arquitectura-First Threat Modeling","Agente de Inteligencia Artificial para seguridad"],"fr":["tmdd-threat-modeling","modélisation de menaces","sécurité de code","outils en ligne de commande","intégration avec le code","identification de vulnérabilités","modélisation de menaces continue","modélisation de menaces basée sur l''architecture","Agent d''Intelligence Artificielle pour la sécurité"],"de":["tmdd-threat-modeling","Bedrohungsmodellierung","Codesicherheit","CLI-Tools","Integration mit Code","Identifizierung von Schwachstellen","kontinuierliches Bedrohungsmodellierung","Architektur-First Bedrohungsmodellierung","Künstliche Intelligenz Agent für Sicherheit"],"pt":["tmdd-threat-modeling","modelagem de ameaças contínua","ferramenta cli","segurança de código","arquitetura de software","desenvolvimento de software","testes de segurança","análise de código"],"ru":["ИИ Агент tmdd-threat-modeling","постоянная threat modeling","инструмент cli","безопасность кода","архитектура программного обеспечения","разработка программного обеспечения","тесты на безопасность","анализ кода"],"ar":["أداة نمذجة التهديدات المستمرة tmdd-threat-modeling","نمذجة التهديدات المستمرة","أداة سطر أوامر","أمان الكود","هندسة البرمجيات","تطوير البرمجيات","اختبارات الأمان","تحليل الكود"]}},"owner":"attasec","repo":"tmdd","repoPath":"attasec/tmdd","stars":16,"forks":1,"updatedAt":"2026-03-01T20:41:46Z","topics":[],"category":"community","skillMd":{"name":"tmdd-threat-modeling","description":"Create and manage TMDD threat models grounded in actual codebase architecture. Use when the user wants to threat-model a system, add a feature, create security threat mappings, run tmdd commands, or work with .tmdd/ YAML files.","bodyPreview":"# TMDD - Threat Modeling Driven Development\n\n## When to Use\n\nActivate when the user asks to:\n- Create, initialize, or scaffold a threat model\n- Add a feature to an existing threat model\n- Threat-model a codebase, service, or feature\n- Run or fix `tmdd lint` errors\n- Generate implementation prompts from a threat model\n\nAlso auto-activates when editing `.tmdd/**/*.yaml` files.\n\n## Core Principle: Architecture-First Threat Modeling\n\n**Every threat model MUST be grounded in the actual codebase.** Ne","body":"# TMDD - Threat Modeling Driven Development\n\n## When to Use\n\nActivate when the user asks to:\n- Create, initialize, or scaffold a threat model\n- Add a feature to an existing threat model\n- Threat-model a codebase, service, or feature\n- Run or fix `tmdd lint` errors\n- Generate implementation prompts from a threat model\n\nAlso auto-activates when editing `.tmdd/**/*.yaml` files.\n\n## Core Principle: Architecture-First Threat Modeling\n\n**Every threat model MUST be grounded in the actual codebase.** Never produce\ngeneric/textbook threats. Before writing any YAML, analyze the code to discover\nreal components, data flows, technologies, and attack surface.\n\n---\n\n## Phase 1 — Codebase Architecture Analysis\n\nBefore touching any `.tmdd/` file, perform these steps:\n\n### 1.1 Discover Project Structure\n\nScan the repository to identify:\n- **Language & framework** (package.json, requirements.txt, go.mod, Cargo.toml, pom.xml, etc.)\n- **Entry points** (main files, route definitions, CLI commands)\n- **Directory layout** (src/, api/, lib/, services/, models/, controllers/, etc.)\n\n### 1.2 Identify Architectural Components\n\nSearch the codebase for real building blocks. Map each to a TMDD component:\n\n| Look for | Maps to TMDD component type |\n|----------|----------------------------|\n| Route handlers, controllers, API endpoints | `api` |\n| Frontend pages, React/Vue/Angular components | `frontend` |\n| Database models, ORM schemas, migrations | `database` |\n| Background workers, cron jobs, queue consumers | `service` |\n| Redis/Memcached usage | `cache` |\n| Message broker publishers/consumers (Kafka, RabbitMQ, SQS) | `queue` |\n| Third-party API calls, SDK integrations | `external` |\n| Auth middleware, session management, token handling | `service` (auth) |\n\n**For each component, record:**\n- The actual technology (e.g., \"Express.js\", \"PostgreSQL via Prisma\", \"Redis\")\n- The trust boundary (`public` if internet-facing, `internal` if behind auth/VPN, `external` if third-party)\n- Key source files/directories it lives in\n\n### 1.3 Trace Real Data Flows\n\nFollow how data actually moves through the code:\n- HTTP requests from clients to API handlers\n- Database reads/writes from handlers to ORM/query layer\n- Inter-service calls (REST, gRPC, message queues)\n- External API calls (payment providers, email services, OAuth providers)\n- File uploads, websocket connections, SSE streams\n\n**For each flow, note:**\n- What data is transmitted (credentials, PII, tokens, user content)\n- Authentication mechanism (JWT, session cookie, API key, mTLS, none)\n- Protocol (HTTPS, gRPC, WebSocket, AMQP)\n\n### 1.4 Identify Security-Relevant Code Patterns\n\nScan for patterns that inform threats directly:\n- **Authentication**: How are users authenticated? (JWT, sessions, OAuth, API keys)\n- **Authorization**: Is there RBAC/ABAC? Where are permission checks?\n- **Input validation**: Is there schema validation (Zod, Joi, Pydantic)? Where?\n- **SQL/ORM usage**: Raw queries vs parameterized? Which ORM?\n- **File handling**: Uploads, path traversal risks, temp files?\n- **Secrets management**: Env vars, vault, hardcoded?\n- **Serialization**: JSON parsing, XML, YAML (deserialization attacks)?\n- **Cryptography**: Hashing algorithms, encryption at rest/in transit?\n- **Error handling**: Do errors leak stack traces or internal details?\n- **Logging**: What is logged? Are secrets filtered?\n- **Rate limiting**: Is there any? Where?\n- **CORS/CSP**: What''s the policy?\n\n---\n\n## Phase 2 — Threat Model Creation\n\n**IMPORTANT — Before editing any YAML file:**\n1. Check if `.tmdd/` already exists and contains populated YAML files\n2. If YES: you are in **incremental mode** — read each file first, then append new\n   entries or edit existing ones. NEVER rewrite a file from scratch. Skip `tmdd init`.\n   Go directly to Phase 3 if adding a feature, or follow Phase 2.2 in append mode.\n3. If NO: you are in **creation mode** — run `tmdd init`, then populate files per Phase 2.2\n\n### 2.1 New Project (no `.tmdd/` directory)\n\n```bash\ntmdd init .tmdd --template <template> -n \"System Name\" -d \"Description\"\n```\n\nTemplates: `minimal` (blank), `web-app` (7 web threats), `api` (OWASP API Top 10).\n\nAfter init, replace the template content with architecture-specific data from Phase 1.\n\n### 2.2 Populate YAML Files (in order)\n\n**YOU MUST EDIT THE FILES DIRECTLY. DO NOT JUST OUTPUT YAML.**\n\n**NEVER overwrite existing content.** Before editing any YAML file:\n1. Read the file first to see what entries already exist\n2. Append new entries — do not remove or rewrite existing ones unless\n   the user explicitly asks for changes to specific entries\n3. When adding threats/mitigations, continue the existing ID sequence\n   (e.g., if T005 exists, start new threats at T006)\n\nEdit these files using the analysis from Phase 1:\n\n#### 1. `components.yaml` — Map real code to components\n\n```yaml\ncomponents:\n  - id: api_backend            # REQUIRED, ^[a-z][a-z0-9_]*$\n    description: \"Express.js REST API handling user and order endpoints\"\n    type: api                  # frontend|api|service|database|queue|external|cache|other\n    technology: \"Node.js / Express\"\n    trust_boundary: public     # public|internal|external\n    source_paths:              # OPTIONAL - glob patterns mapping to source files\n      - \"src/routes/**\"\n      - \"src/middleware/**\"\n      - \"src/server.ts\"\n```\n\n**Rules:**\n- One component per distinct architectural unit discovered in Phase 1\n- `description` must mention the actual technology and what it does in this project\n- `trust_boundary` must reflect the real deployment (not assumed)\n- `source_paths` (optional) should list glob patterns for source files that belong to this\n  component. This enables deterministic PR-to-component mapping for threat review workflows.\n  Prefer specific globs over overly broad ones (e.g., `src/routes/**` over `src/**`).\n\n#### 2. `actors.yaml` — Real users and external systems\n\n```yaml\nactors:\n  - id: end_user               # REQUIRED, ^[a-z][a-z0-9_]*$\n    description: \"Authenticated user accessing the web dashboard\"\n```\n\n#### 3. `data_flows.yaml` — Traced from actual code paths\n\n```yaml\ndata_flows:\n  - id: df_user_to_api             # REQUIRED\n    source: end_user               # must exist in actors or components\n    destination: api_backend       # must exist in actors or components\n    data_description: \"Login credentials (email + password) and session tokens\"\n    protocol: HTTPS\n    authentication: JWT\n```\n\n**Rules:**\n- Every flow must correspond to a real code path you found in Phase 1.3\n- `data_description` must name the actual data types (not just \"API calls\")\n- Include protocol and auth method from the code\n\n#### 4. `threats/catalog.yaml` — Threats specific to THIS codebase\n\n```yaml\nthreats:\n  T001:                              # ^T\\d+$\n    name: \"SQL Injection via raw query in search endpoint\"\n    description: \"The /api/search endpoint in src/routes/search.ts uses string concatenation for the WHERE clause instead of parameterized queries\"\n    severity: high                   # low|medium|high|critical\n    stride: T                        # S|T|R|I|D|E\n    cwe: CWE-89\n    suggested_mitigations: [M001]    # each must exist in mitigations.yaml\n```\n\n**CRITICAL — Threat Quality Rules:**\n- `name` must reference the specific component, endpoint, or module affected\n- `description` must describe the concrete vulnerability in this codebase, not a textbook definition. Reference file paths when possible.\n- `severity` must be based on actual exploitability and impact in this system\n- Every threat must be traceable to a component or data flow from Phase 1\n\n**STRIDE analysis — apply to each component and data flow:**\n- **S**poofing: Can identities be faked? (check auth implementation)\n- **T**ampering: Can data be modified? (check input validation, CSRF protection)\n- **R**epudiation: Can actions be denied? (check audit logging)\n- **I**nformation Disclosure: Can data leak? (check error handling, logging, CORS)\n- **D**enial of Service: Can availability be impacted? (check rate limiting, resource limits)\n- **E**levation of Privilege: Can permissions be bypassed? (check authorization checks)\n\n#### 5. `threats/mitigations.yaml` — Actionable controls with code references\n\n```yaml\nmitigations:\n  # Simple format\n  M001: \"Use parameterized queries via Prisma ORM for all database access\"\n\n  # Rich format with code references (preferred — ties mitigation to implementation)\n  M002:\n    description: \"Zod schema validation on all API request bodies\"\n    references:\n      - file: \"src/middleware/validate.ts\"\n        lines: \"12-35\"\n      - file: \"src/schemas/user.ts\"\n```\n\n**Rules:**\n- Reference actual files/lines where the mitigation is (or should be) implemented\n- If the mitigation doesn''t exist yet, describe it concretely enough to implement\n- Use the rich format with `references` whenever a file location is known\n\n#### 6. `threats/threat_actors.yaml`\n\n```yaml\nthreat_actors:\n  TA001: \"External attacker\"    # ^TA\\d+$\n```\n\n#### 7. `features.yaml` — Features with threat-to-mitigation mapping\n\n```yaml\nfeatures:\n  - name: \"User Login\"            # REQUIRED\n    goal: \"Authenticate users\"    # REQUIRED\n    data_flows: [df_user_to_api]  # must exist in data_flows.yaml\n    threat_actors: [TA001]        # must exist in threat_actors.yaml\n    threats:                      # MUST be a dict, NOT a list\n      T001: default               # inherit suggested_mitigations from catalog\n      T002: [M003, M005]          # explicit mitigation override\n      T003: accepted              # risk deliberately accepted\n    last_updated: \"2026-02-22\"    # set by agent to today''s date\n    reviewed_at: \"2000-01-01\"     # SENTINEL — forces stale-review lint warning\n    # reviewed_by: — DO NOT SET. Only a human adds this after manual review.\n```\n\n**Threat mapping values:**\n- `default` — inherit `suggested_mitigations` from `threats/catalog.yaml` (preferred when suggestions fit)\n- `[M001, M002]` — explicit mitigation list (override when you need different controls)\n- `accepted` — risk deliberately accepted without mitigation\n\n**Review fields (human-only attestation):**\n- `reviewed_by` — name/username of the human analyst who verified the threat mappings.\n  **AI agents MUST NOT set this field.** Only a human adds it after manual review.\n- `reviewed_at` — date of last review (YYYY-MM-DD). AI agents MUST set this to `\"2000-01-01\"`\n  as a sentinel so that `last_updated > reviewed_at` always triggers a stale-review lint warning.\n  The human updates this to the real date when they review.\n- `last_updated` — date the feature was last created or modified (YYYY-MM-DD).\n  AI agents SHOULD set this to today''s date.\n- Features with `accepted` threats and no `reviewed_by` trigger a lint warning\n\n```yaml\n# CORRECT\nthreats:\n  T001: default\n  T002: [M001, M002]\n  T003: accepted\n\n# WRONG - will fail lint\nthreats: [T001, T002, T003]\n```\n\n---\n\n## Phase 3 — Adding a Feature (existing `.tmdd/` project)\n\nWhen adding a feature to an existing threat model:\n\n### 3.1 Analyze the feature''s code impact\n\nBefore editing YAML, answer:\n1. **What new code paths does this feature introduce?** (new endpoints, new DB tables, new external calls)\n2. **What existing components does it touch?**\n3. **What sensitive data does it handle?** (PII, credentials, financial data, tokens)\n4. **What new attack surface does it create?**\n\n### 3.2 Use the `tmdd feature` workflow\n\n```bash\n# Step 1: Generate threat modeling prompt (new feature)\ntmdd feature \"Feature Name\" -d \"What it does\"\n\n# Step 2: Read the generated prompt\n# .tmdd/out/<feature_name>.threatmodel.txt\n\n# Step 3: Edit YAML files using findings from 3.1 (follow order in 3.3 below)\n\n# Step 4: Validate\ntmdd lint .tmdd\n\n# Step 5: Generate implementation prompt (feature now exists)\ntmdd feature \"Feature Name\"\n```\n\n### 3.3 Edit files in order\n\n1. `components.yaml` — Add new components if the feature introduces new architectural units\n2. `actors.yaml` — Add new actors if the feature serves new user types\n3. `data_flows.yaml` — Add flows for new data paths the feature creates\n4. `threats/catalog.yaml` — Add threats specific to the feature''s code (not generic threats)\n5. `threats/mitigations.yaml` — Add mitigations referencing actual or planned implementation files\n6. `features.yaml` — Add the feature with full threat->mitigation mapping\n\n---\n\n## Phase 4 — Validation & Compilation\n\n```bash\n# Validate all cross-references\ntmdd lint .tmdd\n\n# Generate consolidated output\ntmdd compile .tmdd                        # Full system\ntmdd compile .tmdd --feature \"Login\"      # Single feature\n```\n\n---\n\n## ID Conventions\n\n| Type       | Pattern              | Example          |\n|------------|----------------------|------------------|\n| Entity     | `^[a-z][a-z0-9_]*$` | `api_backend`    |\n| Threat     | `^T\\d+$`            | `T001`           |\n| Mitigation | `^M\\d+$`            | `M001`           |\n| Threat Actor | `^TA\\d+$`         | `TA001`          |\n| Data Flow  | `df_{src}_to_{dst}` | `df_user_to_api` |\n\n## File Structure\n\n```\n.tmdd/\n  system.yaml            # System metadata\n  actors.yaml            # Who interacts with the system\n  components.yaml        # Architecture building blocks\n  data_flows.yaml        # Data movement between actors/components\n  features.yaml          # Features with threat->mitigation mappings\n  threats/\n    catalog.yaml         # Threat definitions (T001, T002...)\n    mitigations.yaml     # Security controls (M001, M002...)\n    threat_actors.yaml   # Adversary profiles (TA001, TA002...)\n```\n\n## Cross-Reference Rules (enforced by lint)\n\n1. `data_flows[].source/destination` must exist in actors or components\n2. `features[].data_flows[]` must exist in data_flows.yaml\n3. `features[].threat_actors[]` must exist in threat_actors.yaml\n4. `features[].threats` keys must exist in threats/catalog.yaml\n5. `features[].threats` mitigation values must exist in threats/mitigations.yaml\n6. `catalog[].suggested_mitigations[]` must exist in mitigations.yaml\n\n## Self-Validation Checklist\n\nBefore finishing edits, verify:\n- [ ] Phase 1 analysis was performed — components and data flows reflect actual code\n- [ ] All IDs follow naming conventions\n- [ ] Every ID referenced in features.yaml exists in its source file\n- [ ] features.yaml threats is a dict (not a list)\n- [ ] Threat names/descriptions reference specific components, endpoints, or files\n- [ ] Mitigations reference actual or planned implementation files where possible\n- [ ] data_flows source/destination exist in actors or components\n- [ ] Existing entries in all YAML files were preserved (no accidental overwrites)\n- [ ] Run `tmdd lint .tmdd` and fix all errors\n"},"lastSynced":"2026-03-06T06:43:39.131Z","agentAnalysis":{"suitability":{"en":"Perfect for Security Agents needing automated threat modeling and Architecture-First Threat Modeling capabilities.","zh":"非常适合需要自动化威胁建模和架构优先威胁建模功能的安全代理。","ja":"セキュリティ エージェントが自動化された脅威モデリングとアーキテクチャ優先の脅威モデリング機能を必要とする場合に最適です。","ko":"자동화된 위협 모델링 및 아키텍처 우선 위협 모델링 기능이 필요한 보안 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Seguridad que necesitan modelado de amenazas automatizado y capacidades de modelado de amenazas de arquitectura primero.","fr":"Parfait pour les agents de sécurité ayant besoin d''un modelage de menace automatisé et de capacités de modelage de menace de l''architecture d''abord.","de":"Perfekt für Sicherheitsagenten, die automatisiertes Bedrohungsmodellieren und Architektur-First-Bedrohungsmodellierungs-Funktionen benötigen.","pt":"Perfeito para Agentes de Segurança que necessitam de modelagem de ameaças automatizada e capacidades de Modelagem de Ameaças Arquitetura-Primeiro.","ru":"Идеально подходит для агентов безопасности, которым необходима автоматизированная модель угроз и возможности моделирования угроз на основе архитектуры.","ar":"مثالي لعمليات الوكيل الأمني التي تحتاج إلى نمذجة التهديدات الآلية وقدرات نمذجة التهديدات الأولى للبنية التحتية."},"recommendation":{"en":"Empowers agents to automate threat modeling tasks, create and scaffold threat models, and generate implementation prompts from threat models using YAML files and the tmdd CLI tool, supporting Continuous Threat Modeling and threat modeling driven development (TMDD).","zh":"赋予代理自动化威胁建模任务、创建和搭建威胁模型、使用YAML文件和tmdd CLI工具从威胁模型生成实现提示的能力，支持持续威胁建模和威胁建模驱动开发（TMDD）。","ja":"エージェントに、脅威モデリング タスクの自動化、脅威モデルの作成とスケルトン化、YAML ファイルとtmdd CLIツールを使用して脅威モデルの実装のヒントを生成する機能を提供し、継続的な脅威モデリングと脅威モデリング ドリブン開発（TMDD）をサポートします。","ko":"에이전트에게 자동화된 위협 모델링 작업, 위협 모델의 생성 및 스캐폴딩, YAML 파일 및 tmdd CLI 도구를 사용하여 위협 모델에서 구현提示를 생성하는 기능을 제공하여 지속적인 위협 모델링 및 위협 모델링 기반 개발(TMDD)을 지원합니다.","es":"Habilita a los agentes a automatizar tareas de modelado de amenazas, crear y generar modelos de amenazas, y generar instrucciones de implementación a partir de modelos de amenazas utilizando archivos YAML y la herramienta CLI de tmdd, lo que admite el modelado continuo de amenazas y el desarrollo impulsado por el modelado de amenazas (TMDD).","fr":"Permet aux agents d''automatiser les tâches de modélisation de menaces, de créer et de générer des modèles de menaces, et de générer des invites d''implémentation à partir de modèles de menaces en utilisant des fichiers YAML et l''outil CLI tmdd, ce qui prend en charge la modélisation continue de menaces et le développement piloté par la modélisation de menaces (TMDD).","de":"Ermächtigt Agenten, Bedrohungsmodellierungs-Aufgaben zu automatisieren, Bedrohungsmodelle zu erstellen und zu generieren, und Implementierungsanweisungen aus Bedrohungsmodellen mithilfe von YAML-Dateien und dem tmdd-CLI-Tool zu erzeugen, was kontinuierliches Bedrohungsmodellieren und bedrohungsmodellgetriebene Entwicklung (TMDD) unterstützt.","pt":"Habilita os agentes a automatizar tarefas de modelagem de ameaças, criar e estruturar modelos de ameaças, e gerar prompts de implementação a partir de modelos de ameaças usando arquivos YAML e a ferramenta CLI tmdd, suportando Modelagem de Ameaças Contínua e desenvolvimento dirigido por modelagem de ameaças (TMDD).","ru":"Наделяет агентов возможностью автоматизировать задачи моделирования угроз, создавать и располагать модели угроз, а также генерировать подсказки реализации из моделей угроз с помощью файлов YAML и инструмента CLI tmdd, поддерживая непрерывное моделирование угроз и разработку, управляемую моделированием угроз (TMDD).","ar":"تمكين الوكلاء من توفير مهام نمذجة التهديدات، وإنشاء هيكلة لنمذجة التهديدات، وتوليد إشارات تنفيذ من نمذجة التهديدات باستخدام ملفات YAML وأداة CLI tmdd، ودعم نمذجة التهديدات المستمرة وتطوير مدفوع بنمذجة التهديدات (TMDD)."},"useCases":{"en":["Automating threat modeling for codebases and services","Generating implementation prompts from existing threat models","Scaffolding new threat models for features and services","Running and fixing tmdd lint errors","Threat-modeling existing codebases and services"],"zh":["为代码库和服务自动化威胁建模","从现有的威胁模型生成实现提示","为功能和服务搭建新的威胁模型","运行和修复tmdd lint错误","对现有的代码库和服务进行威胁建模"],"ja":["コードベースとサービスに対する脅威モデリングの自動化","既存の脅威モデルの実装のヒントの生成","機能とサービスのための新しい脅威モデルの作成","tmdd lintエラーの実行と修復","既存のコードベースとサービスの脅威モデリング"],"ko":["코드베이스와 서비스에 대한 자동화된 위협 모델링","기존의 위협 모델에서 구현提示 생성","기능과 서비스를 위한 새로운 위협 모델의 스캐폴딩","tmdd lint 오류의 실행과 수정","기존의 코드베이스와 서비스에 대한 위협 모델링"],"es":["Automatizar el modelado de amenazas para bases de código y servicios","Generar instrucciones de implementación a partir de modelos de amenazas existentes","Crear nuevos modelos de amenazas para características y servicios","Ejecutar y corregir errores de tmdd lint","Realizar modelado de amenazas para bases de código y servicios existentes"],"fr":["Automatiser le modélisation de menaces pour les bases de code et les services","Générer des invites d''implémentation à partir de modèles de menaces existants","Créer de nouveaux modèles de menaces pour les fonctionnalités et les services","Exécuter et corriger les erreurs de tmdd lint","Réalisant la modélisation de menaces pour les bases de code et les services existants"],"de":["Automatisieren des Bedrohungsmodellierens für Codebasen und Dienste","Erzeugen von Implementierungsanweisungen aus vorhandenen Bedrohungsmodellen","Erstellen neuer Bedrohungsmodelle für Funktionen und Dienste","Ausführen und Korrigieren von tmdd-Lint-Fehlern","Durchführen von Bedrohungsmodellieren für vorhandene Codebasen und Dienste"],"pt":["Automatizar a modelagem de ameaças para codebases e serviços","Gerar prompts de implementação a partir de modelos de ameaças existentes","Estruturar novos modelos de ameaças para recursos e serviços","Executar e corrigir erros de lint do tmdd","Realizar modelagem de ameaças para codebases e serviços existentes"],"ru":["Автоматизировать моделирование угроз для кодовых баз и сервисов","Генерировать подсказки реализации из существующих моделей угроз","Располагать новые модели угроз для функций и сервисов","Выполнять и исправлять ошибки lint инструмента tmdd","Проводить моделирование угроз для существующих кодовых баз и сервисов"],"ar":["توفير نمذجة التهديدات الآلية لمجموعات الرموز والخدمات","توليد إشارات تنفيذ من نمذجة التهديدات الحالية","هيكلة نمذجة التهديدات الجديدة للميزات والخدمات","تشغيل وصيانة أخطاء أداة tmdd","إجراء نمذجة التهديدات لمجموعات الرموز والخدمات الحالية"]},"limitations":{"en":["Requires tmdd CLI tool installation","Limited to YAML file format for threat models","Dependent on accurate codebase architecture for effective threat modeling"],"zh":["需要安装tmdd CLI工具","仅限于YAML文件格式的威胁模型","依赖于准确的代码库架构以实现有效的威胁建模"],"ja":["tmdd CLIツールのインストールが必要","脅威モデルのYAMLファイル形式のみに対応","効果的な脅威モデリングには正確なコードベースアーキテクチャが必要"],"ko":["tmdd CLI 도구의 설치가 필요","위협 모델의 YAML 파일 형식만 지원","유효한 위협 모델링을 위해서는 정확한 코드베이스 아키텍처가 필요"],"es":["Requiere la instalación de la herramienta CLI de tmdd","Limitado al formato de archivo YAML para modelos de amenazas","Dependiente de una arquitectura de base de código precisa para un modelado de amenazas efectivo"],"fr":["Nécessite l''installation de l''outil CLI tmdd","Limité au format de fichier YAML pour les modèles de menaces","Dépendant d''une architecture de base de code précise pour une modélisation de menaces efficace"],"de":["Erfordert die Installation des tmdd-CLI-Tools","Begrenzt auf das YAML-Dateiformat für Bedrohungsmodelle","Abhängig von einer genauen Codebasis-Architektur für ein effektives Bedrohungsmodellieren"],"pt":["Requer a instalação da ferramenta CLI tmdd","Limitado ao formato de arquivo YAML para modelos de ameaças","Dependente da arquitetura precisa da codebase para modelagem de ameaças eficaz"],"ru":["Требует установки инструмента CLI tmdd","Ограничен форматом файла YAML для моделей угроз","Зависит от точной архитектуры кодовой базы для эффективного моделирования угроз"],"ar":["يتطلب تثبيت أداة CLI tmdd","محدود بالتنسيق ملف YAML لنمذجة التهديدات","يعتمد على بنية دقيقة لمجموعة الرموز من أجل نمذجة التهديدات الفعالة"]},"version":4},"contentHash":"81365f89eccfe25b89d249a88288ff96da85373f8b0517157570ee8c007990dd","qualityScore":60}');
