INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('attasec/tmdd/tmdd-threat-modeling', 'tmdd-threat-modeling', 'attasec', 'tmdd', 'community', 'tmdd-threat-modeling attasec tmdd community tmdd-threat-modeling is a CLI tool for Continuous Threat Modeling, benefiting developers by automating threat modeling tasks. It supports creating, initializing, and scaffolding threat models. TMDD 威胁建模工具是一种 CLI 工具，用于持续威胁建模。它可以帮助开发人员创建、初始化和运行威胁模型 TMDD 脅威モデリングツールは、継続的な脅威モデリングのための CLI ツールです。開発者が脅威モデルの作成、初期化、実行を支援します TMDD 위협 모델링 도구는 지속적인 위협 모델링을 위한 CLI 도구입니다. 개발자가 위협 모델을 생성, 초기화 및 실행하는 것을 도와줍니다 tmdd-threat-modeling es una herramienta de línea de comandos para el modelado de amenazas continuo, que se integra con su código para identificar vulnerabilidades tmdd-threat-modeling est un outil en ligne de commande pour la modélisation de menaces continue, qui s''intègre à votre code pour identifier les vulnérabilités tmdd-threat-modeling ist ein CLI-Tool für kontinuierliches Bedrohungsmodellierung, das sich in Ihren Code integriert, um Schwachstellen zu identifizieren O tmdd-threat-modeling é uma ferramenta CLI para modelagem de ameaças contínua, ajudando a identificar vulnerabilidades no código ИИ Агент tmdd-threat-modeling - это инструмент постоянной threat modeling, помогающий выявлять уязвимости в коде أداة نمذجة التهديدات المستمرة tmdd-threat-modeling هي أداة سطر أوامر لمواجهة التهديدات المستمرة، تساعد في تحديد نقاط الضعف في الكود how to use tmdd-threat-modeling tmdd-threat-modeling setup guide tmdd-threat-modeling alternative tmdd-threat-modeling vs threat modeling tools tmdd-threat-modeling install what is tmdd-threat-modeling tmdd-threat-modeling tutorial tmdd-threat-modeling best practices continuous threat modeling with tmdd-threat-modeling TMDD 威胁建模 持续威胁建模 CLI 工具 代码安全性 架构 기반威胁建模 AI エージェント 威胁模型创建 tmdd lint Creates, initializes, or scaffolds threat models Adds features to existing threat models Threat-models codebases, services, or features Runs or fixes `tmdd lint` errors Generates implementation prompts from threat models Auto-activates when editing `.tmdd*.yaml` files tmdd-threat-modeling is a Continuous Threat Modeling CLI tool that grounds threat models in actual codebases, following an Architecture-First approach.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AgentWorkforce/trajectories/creating-skills', 'community', 'AgentWorkforce', 'trajectories', 'AgentWorkforce/trajectories', 'creating-skills', 13, 0, 60, '2026-02-24T19:54:10Z', '2026-03-06T06:44:28.050Z', '2d5916eb2f7648cdb34fd17df7a5975a69eafd4f3265e96bc0f52b3b2d10df7a', '{"id":"AgentWorkforce/trajectories/creating-skills","name":"creating-skills","description":{"en":"The creating-skills documentation layer helps future Claude instances quickly find and apply proven techniques, patterns, or tools, making it a valuable resource for developers.","zh":"创建技能是为了帮助AI智能体快速找到和应用有效的方法，必须是可发现、可扫描和可执行的。","ja":"スキルはAIエージェントが効果的なアプローチを迅速に見つけて適用できるように設計されています。発見可能、スキャン可能、実行可能である必要があります。","ko":"스킬은 미래의 AI 에이전트가 효과적인 방법을 빠르게 찾고 적용할 수 있도록 설계되었습니다. 발견 가능, 스캔 가능, 실행 가능해야 합니다.","es":"Las habilidades son guías de referencia para técnicas, patrones y herramientas comprobados. Ayudan a los agentes de IA a encontrar y aplicar enfoques efectivos de manera rápida.","fr":"Les compétences sont des guides de référence pour des techniques, des modèles et des outils éprouvés. Ils aident les agents d''IA à trouver et à appliquer des approches efficaces rapidement.","de":"Fähigkeiten sind Referenzleitfäden für bewährte Techniken, Muster und Tools. Sie helfen KI-Agents, effektive Ansätze schnell zu finden und anzuwenden.","pt":"Criar habilidades para agentes de IA envolve escrever guias de referência para técnicas comprovadas, permitindo que futuras instâncias de Claude as encontrem e apliquem rapidamente","ru":"Создание навыков для ИИ агентов включает написание справочных руководств для проверенных техник, шаблонов или инструментов, чтобы будущие экземпляры Claude могли быстро их найти и применить","ar":"إنشاء مهارات لوكلاء الذكاء الاصطناعي يتضمن كتابة أدلة مرجعية للتقنيات المثبتة، مما يسمح لمثيلات كلود المستقبلية بالعثور عليها وتطبيقها بسرعة"},"seo":{"title":{"en":"Creating-Skills: Documentation Guide for AI Agents | AI A...","zh":"创建技能设置指南 - AI智能体技术","ja":"スキル作成ベストプラクティス - AIエージェント開発","ko":"스킬 생성 가이드 - AI 에이전트 개발 도구","es":"Creación de Habilidades para Agentes de IA: Guía de Confi...","fr":"Création de Compétences pour Agents d''IA : Guide de Mise ...","de":"Erstellung von Fähigkeiten für KI-Agents: Einrichtungslei...","pt":"Guia de Configuração para Criar Habilidades de Agente de IA","ru":"Настройка Навыков ИИ Агентов: Лучшие Практики","ar":"دليل إنشاء مهارات وكلاء الذكاء الاصطناعي"},"description":{"en":"Unlock efficient agent work with creating-skills. Discover how to write effective skills for future Claude instances and boost productivity now!","zh":"了解如何创建技能以帮助未来AI智能体快速找到和应用有效的方法。发现、扫描和执行有效的方法","ja":"AIエージェントが効果的なアプローチを迅速に見つけて適用できるようにスキルを作成する方法について学びます。発見、スキャン、実行可能なガイド","ko":"미래의 AI 에이전트가 효과적인 방법을 빠르게 찾고 적용할 수 있도록 스킬을 생성하는 방법에 대해 알아보세요. 발견, 스캔 및 실행 가능 가이드","es":"Aprende a crear habilidades para agentes de IA con nuestra guía de configuración. Mejora la eficiencia de tus agentes con técnicas y patrones comprobados.","fr":"Découvrez comment créer des compétences pour les agents d''IA avec notre guide de mise en place. Améliorez l''efficacité de vos agents avec des techniques et d...","de":"Erfahren Sie, wie Sie Fähigkeiten für KI-Agents erstellen, mit unserem Einrichtungsleitfaden. Verbessern Sie die Effizienz Ihrer Agents mit bewährten Technik...","pt":"Aprenda a criar habilidades para agentes de IA de forma eficaz, com dicas e práticas recomendadas para melhorar a descoberta e aplicação de técnicas comprovadas","ru":"Изучите, как создавать навыки для ИИ агентов, включая принципы обнаружения, сканирования и действий, для улучшения эффективности","ar":"اكتشف كيفية إنشاء مهارات فعالة لوكلاء الذكاء الاصطناعي، مع توجيهات لتحسين الاكتشاف والتطبيق"},"definition":{"en":"creating-skills is a reference guide for proven techniques, patterns, or tools, designed to be discoverable, scannable, and actionable for AI agents.","zh":"创建技能是指为AI智能体设计的参考指南，用于存储有效的技术、模式或工具","ja":"スキル作成は、AIエージェントのための効果的なアプローチを迅速に見つけて適用するための参考ガイドです","ko":"스킬 생성은 AI 에이전트를 위한 효과적인 방법을 빠르게 찾고 적용할 수 있도록 하는 참조 가이드입니다","es":"Una habilidad es una guía de referencia para técnicas y patrones comprobados que ayudan a los agentes de IA a trabajar de manera eficiente.","fr":"Une compétence est un guide de référence pour des techniques et des modèles éprouvés qui aident les agents d''IA à travailler de manière efficace.","de":"Eine Fähigkeit ist ein Referenzleitfaden für bewährte Techniken und Muster, die KI-Agents dabei helfen, effizient zu arbeiten.","pt":"Habilidades são guias de referência para técnicas comprovadas, padrões ou ferramentas, projetadas para serem descobertas, scaneadas e aplicadas por agentes de IA","ru":"Навыки - это справочные руководства для проверенных техник, шаблонов или инструментов, предназначенные для обнаружения, сканирования и применения ИИ агентами","ar":"المهارات هي أدلة مرجعية للتقنيات المثبتة، النماذج أو الأدوات، مصممة لتكون قابلة للاكتشاف والفحص والتطبيق بواسطة وكلاء الذكاء الاصطناعي"},"features":{"en":["Provides discoverable techniques for future Claude instances","Enables scannable content for quick evaluation","Offers actionable examples for effective approaches","Follows core principle of assuming Claude''s existing intelligence","Supports creation of skills for proven techniques and patterns"],"zh":["可发现的技能设计","快速扫描和评估","清晰的执行示例","核心原则：默认假设AI智能体已经很智能","仅添加AI智能体没有的上下文"],"ja":["発見可能なスキル設計","迅速なスキャンと評価","明確な実行例","コアプリンシプル：デフォルトでAIエージェントはすでに賢いと仮定","AIエージェントにないコンテキストのみを追加"],"ko":["발견 가능한 스킬 설계","빠른 스캔 및 평가","명확한 실행 예시","코어 원칙：기본적으로 AI 에이전트는 이미賢い 것으로 가정","AI 에이전트에 없는 컨텍스트만 추가"],"es":["Técnicas y patrones comprobados para agentes de IA","Guías de referencia para una implementación rápida","Diseñadas para ser descubribles, escaneables y ejecutables","Asunción de que el agente de IA ya es muy inteligente","Adición de contexto que el agente de IA no tiene"],"fr":["Techniques et modèles éprouvés pour les agents d''IA","Guides de référence pour une mise en place rapide","Conçus pour être découvrables, scannables et exécutables","Hypothèse que l''agent d''IA est déjà très intelligent","Ajout de contexte que l''agent d''IA n''a pas"],"de":["Bewährte Techniken und Muster für KI-Agents","Referenzleitfäden für eine schnelle Implementierung","Entworfen, um auffindbar, scannbar und ausführbar zu sein","Annahme, dass der KI-Agent bereits sehr intelligent ist","Hinzufügen von Kontext, den der KI-Agent nicht hat"],"pt":["Desenvolvimento de habilidades descobríveis por agentes de IA","Criação de guias de referência para técnicas comprovadas","Princípios de design para habilidades scanáveis e ação rápidas","Integração com tecnologias de IA para melhorar a eficácia","Utilização de padrões e ferramentas para melhorar a aplicação"],"ru":["Разработка навыков, обнаруживаемых ИИ агентами","Создание справочных руководств для проверенных техник","Принципы дизайна для навыков, сканируемых и быстро действующих","Интеграция с технологиями ИИ для улучшения эффективности","Использование шаблонов и инструментов для улучшения применения"],"ar":["تطوير مهارات قابلة للاكتشاف بواسطة وكلاء الذكاء الاصطناعي","إنشاء أدلة مرجعية للتقنيات المثبتة","مبادئ تصميم للمهارات القابلة للفحص والعمل السريع","التكامل مع تقنيات الذكاء الاصطناعي لتحسين الفعالية","استخدام النماذج والأدوات لتحسين التطبيق"]},"keywords":{"en":["how to use creating-skills","what is creating-skills","creating-skills documentation guide","creating-skills for AI agents","creating-skills setup guide","creating-skills alternative","creating-skills vs other documentation tools"],"zh":["AI智能体","创建技能","可发现的技能","快速扫描","清晰的执行示例","AI工具","智能体开发"],"ja":["AIエージェント","スキル作成","発見可能なスキル","迅速なスキャン","明確な実行例","AIエージェント開発","AIツール"],"ko":["AI 에이전트","스킬 생성","발견 가능한 스킬","빠른 스캔","명확한 실행 예시","AI 에이전트 개발","AI 도구"],"es":["creación de habilidades para agentes de IA","guía de configuración para agentes de IA","técnicas para agentes de IA","patrones para agentes de IA","agentes de IA inteligentes","contexto para agentes de IA","desarrollo de habilidades para agentes de IA"],"fr":["création de compétences pour les agents d''IA","guide de mise en place pour les agents d''IA","techniques pour les agents d''IA","modèles pour les agents d''IA","agents d''IA intelligents","contexte pour les agents d''IA","développement de compétences pour les agents d''IA"],"de":["Erstellung von Fähigkeiten für KI-Agents","Einrichtungsleitfaden für KI-Agents","Techniken für KI-Agents","Muster für KI-Agents","intelligente KI-Agents","Kontext für KI-Agents","Entwicklung von Fähigkeiten für KI-Agents"],"pt":["criar habilidades de agente de IA","desenvolver habilidades de IA","guias de referência para técnicas comprovadas","princípios de design para habilidades de IA","tecnologias de IA para agentes","aplicação de habilidades de IA","navegação de habilidades de IA","informações sobre habilidades de IA"],"ru":["создание навыков ИИ агентов","разработка навыков ИИ","справочные руководства для проверенных техник","принципы дизайна для навыков ИИ","технологии ИИ для агентов","применение навыков ИИ","навигация по навыкам ИИ","информация о навыках ИИ"],"ar":["إنشاء مهارات وكلاء الذكاء الاصطناعي","تطوير مهارات الذكاء الاصطناعي","أدلة مرجعية للتقنيات المثبتة","مبادئ تصميم للمهارات الذكاء الاصطناعي","تقنيات الذكاء الاصطناعي لوكلاء","تطبيق مهارات الذكاء الاصطناعي","تنقل بين مهارات الذكاء الاصطناعي","معلومات عن مهارات الذكاء الاصطناعي"]}},"owner":"AgentWorkforce","repo":"trajectories","repoPath":"AgentWorkforce/trajectories","stars":13,"forks":0,"updatedAt":"2026-02-24T19:54:10Z","topics":[],"category":"community","skillMd":{"name":"creating-skills","description":"Use when creating new Claude Code skills or improving existing ones - ensures skills are discoverable, scannable, and effective through proper structure, CSO optimization, and real examples","bodyPreview":"# Creating Skills\n\n## Overview\n\n**Skills are reference guides for proven techniques, patterns, or tools.** Write them to help future Claude instances quickly find and apply effective approaches.\n\nSkills must be **discoverable** (Claude can find them), **scannable** (quick to evaluate), and **actionable** (clear examples).\n\n**Core principle**: Default assumption is Claude is already very smart. Only add context Claude doesn''t already have.\n\n## When to Use\n\n**Create a skill when:**\n- Technique was","body":"# Creating Skills\n\n## Overview\n\n**Skills are reference guides for proven techniques, patterns, or tools.** Write them to help future Claude instances quickly find and apply effective approaches.\n\nSkills must be **discoverable** (Claude can find them), **scannable** (quick to evaluate), and **actionable** (clear examples).\n\n**Core principle**: Default assumption is Claude is already very smart. Only add context Claude doesn''t already have.\n\n## When to Use\n\n**Create a skill when:**\n- Technique wasn''t intuitively obvious\n- Pattern applies broadly across projects\n- You''d reference this again\n- Others would benefit\n\n**Don''t create for:**\n- One-off solutions specific to single project\n- Standard practices well-documented elsewhere\n- Project conventions (put those in `.claude/CLAUDE.md`)\n\n## Required Structure\n\n### Frontmatter (YAML)\n\n```yaml\n---\nname: skill-name-with-hyphens\ndescription: Use when [triggers/symptoms] - [what it does and how it helps]\ntags: relevant-tags\n---\n```\n\n**Rules:**\n- Only `name` and `description` fields supported (max 1024 chars total)\n- Name: letters, numbers, hyphens only (max 64 chars). Use gerund form (verb + -ing)\n- Avoid reserved words: \"anthropic\", \"claude\" in names\n- Description: Third person, starts with \"Use when...\" (max 1024 chars)\n- Include BOTH triggering conditions AND what skill does\n- Match specificity to task complexity (degrees of freedom)\n\n### Document Structure\n\n```markdown\n# Skill Name\n\n## Overview\nCore principle in 1-2 sentences. What is this?\n\n## When to Use\n- Bullet list with symptoms and use cases\n- When NOT to use\n\n## Quick Reference\nTable or bullets for common operations\n\n## Implementation\nInline code for simple patterns\nLink to separate file for heavy reference (100+ lines)\n\n## Common Mistakes\nWhat goes wrong + how to fix\n\n## Real-World Impact (optional)\nConcrete results from using this technique\n```\n\n## Degrees of Freedom\n\n**Match specificity to task complexity:**\n\n- **High freedom**: Flexible tasks requiring judgment\n  - Use broad guidance, principles, examples\n  - Let Claude adapt approach to context\n  - Example: \"Use when designing APIs - provides REST principles and patterns\"\n\n- **Low freedom**: Fragile or critical operations\n  - Be explicit about exact steps\n  - Include validation checks\n  - Example: \"Use when deploying to production - follow exact deployment checklist with rollback procedures\"\n\n**Red flag**: If skill tries to constrain Claude too much on creative tasks, reduce specificity. If skill is too vague on critical operations, add explicit steps.\n\n## Claude Search Optimization (CSO)\n\n**Critical:** Future Claude reads the description to decide if skill is relevant. Optimize for discovery.\n\n### Description Best Practices\n\n```yaml\n# ❌ BAD - Too vague, doesn''t mention when to use\ndescription: For async testing\n\n# ❌ BAD - First person (injected into system prompt)\ndescription: I help you with flaky tests\n\n# ✅ GOOD - Triggers + what it does\ndescription: Use when tests have race conditions or pass/fail inconsistently - replaces arbitrary timeouts with condition polling for reliable async tests\n\n# ✅ GOOD - Technology-specific with explicit trigger\ndescription: Use when using React Router and handling auth redirects - provides patterns for protected routes and auth state management\n```\n\n### Keyword Coverage\n\nUse words Claude would search for:\n- **Error messages**: \"ENOENT\", \"Cannot read property\", \"Timeout\"\n- **Symptoms**: \"flaky\", \"hanging\", \"race condition\", \"memory leak\"\n- **Synonyms**: \"cleanup/teardown/afterEach\", \"timeout/hang/freeze\"\n- **Tools**: Actual command names, library names, file types\n\n### Naming Conventions\n\n**Use gerund form (verb + -ing):**\n- ✅ `creating-skills` not `skill-creation`\n- ✅ `testing-with-subagents` not `subagent-testing`\n- ✅ `debugging-memory-leaks` not `memory-leak-debugging`\n- ✅ `processing-pdfs` not `pdf-processor`\n- ✅ `analyzing-spreadsheets` not `spreadsheet-analysis`\n\n**Why gerunds work:**\n- Describes the action you''re taking\n- Active and clear\n- Consistent with Anthropic conventions\n\n**Avoid:**\n- ❌ Vague names like \"Helper\" or \"Utils\"\n- ❌ Passive voice constructions\n\n## Code Examples\n\n**One excellent example beats many mediocre ones.**\n\n### Choose Language by Use Case\n\n- Testing techniques → TypeScript/JavaScript\n- System debugging → Shell/Python\n- Data processing → Python\n- API calls → TypeScript/JavaScript\n\n### Good Example Checklist\n\n- [ ] Complete and runnable\n- [ ] Well-commented explaining **WHY** not just what\n- [ ] From real scenario (not contrived)\n- [ ] Shows pattern clearly\n- [ ] Ready to adapt (not generic template)\n- [ ] Shows both BAD (❌) and GOOD (✅) approaches\n- [ ] Includes realistic context/setup code\n\n### Example Template\n\n```typescript\n// ✅ GOOD - Clear, complete, ready to adapt\ninterface RetryOptions {\n  maxAttempts: number;\n  delayMs: number;\n  backoff?: ''linear'' | ''exponential'';\n}\n\nasync function retryOperation<T>(\n  operation: () => Promise<T>,\n  options: RetryOptions\n): Promise<T> {\n  const { maxAttempts, delayMs, backoff = ''linear'' } = options;\n\n  for (let attempt = 1; attempt <= maxAttempts; attempt++) {\n    try {\n      return await operation();\n    } catch (error) {\n      if (attempt === maxAttempts) throw error;\n\n      const delay = backoff === ''exponential''\n        ? delayMs * Math.pow(2, attempt - 1)\n        : delayMs * attempt;\n\n      await new Promise(resolve => setTimeout(resolve, delay));\n    }\n  }\n\n  throw new Error(''Unreachable'');\n}\n\n// Usage\nconst data = await retryOperation(\n  () => fetchUserData(userId),\n  { maxAttempts: 3, delayMs: 1000, backoff: ''exponential'' }\n);\n```\n\n### Don''t\n\n- ❌ Implement in 5+ languages (you''re good at porting)\n- ❌ Create fill-in-the-blank templates\n- ❌ Write contrived examples\n- ❌ Show only code without comments\n\n## File Organization\n\n### Self-Contained (Preferred)\n\n```\ntypescript-type-safety/\n  SKILL.md    # Everything inline\n```\n\n**When:** All content fits in ~500 words, no heavy reference needed\n\n### With Supporting Files\n\n```\napi-integration/\n  SKILL.md           # Overview + patterns\n  retry-helpers.ts   # Reusable code\n  examples/\n    auth-example.ts\n    pagination-example.ts\n```\n\n**When:** Reusable tools or multiple complete examples needed\n\n### With Heavy Reference\n\n```\naws-sdk/\n  SKILL.md       # Overview + workflows\n  s3-api.md      # 600 lines API reference\n  lambda-api.md  # 500 lines API reference\n```\n\n**When:** Reference material > 100 lines\n\n## Token Efficiency\n\nSkills load into every conversation. Keep them concise.\n\n### Target Limits\n\n- **SKILL.md**: Keep under 500 lines\n- Getting-started workflows: <150 words\n- Frequently-loaded skills: <200 words total\n- Other skills: <500 words\n- Files > 100 lines: Include table of contents\n\n**Challenge each piece of information**: \"Does Claude really need this explanation?\"\n\n### Compression Techniques\n\n```markdown\n# ❌ BAD - Verbose (42 words)\nYour human partner asks: \"How did we handle authentication errors in React Router before?\"\nYou should respond: \"I''ll search past conversations for React Router authentication patterns.\"\nThen dispatch a subagent with the search query: \"React Router authentication error handling 401\"\n\n# ✅ GOOD - Concise (20 words)\nPartner: \"How did we handle auth errors in React Router?\"\nYou: Searching...\n[Dispatch subagent → synthesis]\n```\n\n**Techniques:**\n- Reference tool `--help` instead of documenting all flags\n- Cross-reference other skills instead of repeating content\n- Show minimal example of pattern\n- Eliminate redundancy\n- Use progressive disclosure (reference additional files as needed)\n- Organize content by domain for focused context\n\n## Workflow Recommendations\n\nFor multi-step processes, include:\n\n1. **Clear sequential steps**: Break complex tasks into numbered operations\n2. **Feedback loops**: Build in verification/validation steps\n3. **Error handling**: What to check when things go wrong\n4. **Checklists**: For processes with many steps or easy-to-miss details\n\n**Example structure:**\n```markdown\n## Workflow\n\n1. **Preparation**\n   - Check prerequisites\n   - Validate environment\n\n2. **Execution**\n   - Step 1: [action + expected result]\n   - Step 2: [action + expected result]\n\n3. **Verification**\n   - [ ] Check 1 passes\n   - [ ] Check 2 passes\n\n4. **Rollback** (if needed)\n   - Steps to undo changes\n```\n\n## Common Mistakes\n\n| Mistake | Why It Fails | Fix |\n|---------|--------------|-----|\n| Narrative example | \"In session 2025-10-03...\" | Focus on reusable pattern |\n| Multi-language dilution | Same example in 5 languages | One excellent example |\n| Code in flowcharts | `step1 [label=\"import fs\"]` | Use markdown code blocks |\n| Generic labels | helper1, helper2, step3 | Use semantic names |\n| Missing description triggers | \"For testing\" | \"Use when tests are flaky...\" |\n| First-person description | \"I help you...\" | \"Use when... - provides...\" |\n| Deeply nested file references | Multiple @ symbols, complex paths | Keep references simple and direct |\n| Windows-style file paths | `C:\\path\\to\\file` | Use forward slashes |\n| Offering too many options | 10 different approaches | Focus on one proven approach |\n| Punting error handling | \"Claude figures it out\" | Include explicit error handling in scripts |\n| Time-sensitive information | \"As of 2025...\" | Keep content evergreen |\n| Inconsistent terminology | Mixing synonyms randomly | Use consistent terms throughout |\n\n## Flowchart Usage\n\n**Only use flowcharts for:**\n- Non-obvious decision points\n- Process loops where you might stop too early\n- \"When to use A vs B\" decisions\n\n**Never use for:**\n- Reference material → Use tables/lists\n- Code examples → Use markdown blocks\n- Linear instructions → Use numbered lists\n\n## Cross-Referencing Skills\n\n```markdown\n# ✅ GOOD - Name only with clear requirement\n**REQUIRED:** Use superpowers:test-driven-development before proceeding\n\n**RECOMMENDED:** See typescript-type-safety for proper type guards\n\n# ❌ BAD - Unclear if required\nSee skills/testing/test-driven-development\n\n# ❌ BAD - Force-loads file, wastes context\n@skills/testing/test-driven-development/SKILL.md\n```\n\n## Advanced Practices\n\n### Iterative Development\n\n**Best approach**: Develop skills iteratively with Claude\n1. Start with minimal viable skill\n2. Test with real use cases\n3. Refine based on what works\n4. Remove what doesn''t add value\n\n### Build Evaluations First\n\nBefore extensive documentation:\n1. Create test scenarios\n2. Identify what good looks like\n3. Document proven patterns\n4. Skip theoretical improvements\n\n### Utility Scripts\n\nFor reliability, provide:\n- Scripts with explicit error handling (don''t defer errors to Claude)\n- Exit codes for success/failure\n- Clear error messages\n- Examples of usage\n- List required dependencies explicitly\n\n**Example:**\n```bash\n#!/bin/bash\nset -e  # Exit on error\n\nif [ ! -f \"config.json\" ]; then\n  echo \"Error: config.json not found\" >&2\n  exit 1\nfi\n\n# Script logic here\necho \"Success\"\nexit 0\n```\n\n### Verifiable Intermediate Outputs\n\nFor complex operations, create validation checkpoints:\n1. Have Claude produce a structured plan file\n2. Validate the plan with a script\n3. Execute only after validation passes\n\nThis catches errors before they compound.\n\n### Templates for Structured Output\n\nWhen skills produce consistent formats:\n```markdown\n## Output Template\n\n\\`\\`\\`typescript\ninterface ExpectedOutput {\n  status: ''success'' | ''error'';\n  data: YourDataType;\n  errors?: string[];\n}\n\\`\\`\\`\n\n**Usage**: Copy and adapt for your context\n```\n\n## Skill Creation Checklist\n\n**Before writing:**\n- [ ] Technique isn''t obvious or well-documented elsewhere\n- [ ] Pattern applies broadly (not project-specific)\n- [ ] I would reference this across multiple projects\n\n**Frontmatter:**\n- [ ] Name uses only letters, numbers, hyphens\n- [ ] Description starts with \"Use when...\"\n- [ ] Description includes triggers AND what skill does\n- [ ] Description is third person\n- [ ] Total frontmatter < 1024 characters\n\n**Content:**\n- [ ] Overview states core principle (1-2 sentences)\n- [ ] \"When to Use\" section with symptoms\n- [ ] Quick reference table for common operations\n- [ ] One excellent code example (if technique skill)\n- [ ] Common mistakes section\n- [ ] Keywords throughout for searchability\n\n**Quality:**\n- [ ] Word count appropriate for frequency (see targets above)\n- [ ] SKILL.md under 500 lines\n- [ ] No narrative storytelling\n- [ ] Flowcharts only for non-obvious decisions\n- [ ] Supporting files only if needed (100+ lines reference)\n- [ ] Cross-references use skill name, not file paths\n- [ ] No time-sensitive information\n- [ ] Consistent terminology throughout\n- [ ] Concrete examples (not templates)\n- [ ] Degrees of freedom match task complexity\n\n**Testing:**\n- [ ] Tested with Claude Haiku, Sonnet, and Opus (instructions effective for Opus may need more detail for Haiku)\n- [ ] Tested with subagent scenarios (if discipline-enforcing skill)\n- [ ] Addresses common rationalizations\n- [ ] Includes red flags list\n\n## Directory Structure\n\n```\nskills/\n  skill-name/\n    SKILL.md              # Required\n    supporting-file.*     # Optional\n    examples/             # Optional\n      example1.ts\n    scripts/              # Optional\n      helper.py\n```\n\n**Flat namespace** - all skills in one searchable directory\n\n## Real-World Impact\n\n**Good skills:**\n- Future Claude finds them quickly (CSO optimization)\n- Can be scanned in seconds (quick reference)\n- Provide clear actionable examples\n- Prevent repeating same research\n- Stay under 500 lines (token efficient)\n- Match specificity to task needs (right degrees of freedom)\n\n**Bad skills:**\n- Get ignored (vague description)\n- Take too long to evaluate (no quick reference)\n- Leave gaps in understanding (no examples)\n- Waste token budget (verbose explanations of obvious things)\n- Over-constrain creative tasks or under-specify critical operations\n- Include time-sensitive or obsolete information\n\n---\n\n**Remember:** Skills are for future Claude, not current you. Optimize for discovery, scanning, and action.\n\n**Golden rule:** Default assumption is Claude is already very smart. Only add context Claude doesn''t already have."},"lastSynced":"2026-03-06T06:44:28.050Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude, Cursor, and AutoGPT needing structured documentation for proven techniques and patterns.","zh":"非常适合像 Claude、Cursor 和 AutoGPT 这样的 AI Agents，它们需要结构化的文档来记录经过验证的技术和模式。","ja":"Claude、Cursor、AutoGPT などの AI エージェントが、検証済みのテクニックとパターンに構造化されたドキュメントを必要とする場合に最適です。","ko":"클라우드, 커서 및 오토지피티와 같은 AI 에이전트가 검증된 기술 및 패턴의 구조화된 문서가 필요한 경우에 적합합니다.","es":"Perfecto para agentes de IA como Claude, Cursor y AutoGPT que necesitan documentación estructurada para técnicas y patrones probados.","fr":"Parfait pour les agents IA comme Claude, Cursor et AutoGPT ayant besoin de documentation structurée pour des techniques et des modèles éprouvés.","de":"Perfekt für KI-Agents wie Claude, Cursor und AutoGPT, die strukturierte Dokumentation für bewährte Techniken und Muster benötigen.","pt":"Perfeito para Agentes de IA como Claude, Cursor e AutoGPT que necessitam de documentação estruturada para técnicas e padrões comprovados.","ru":"Идеально подходит для агентов ИИ, таких как Claude, Cursor и AutoGPT, которым необходима структурированная документация для проверенных методов и шаблонов.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Claude و Cursor و AutoGPT الذين يحتاجون إلى توثيق منظم للتكنولوجيا والنماذج المثبتة."},"recommendation":{"en":"Empowers agents to leverage discoverable, scannable, and actionable skills using reference guides, enabling them to quickly apply effective approaches and techniques, with a focus on providing context that complements their existing intelligence.","zh":"赋予代理使用参考指南发现、扫描和执行技能的能力，使其能够快速应用有效的方法和技术，并专注于提供补充其现有智能的上下文。","ja":"エージェントがリファレンス ガイドを使用して、発見可能な、スキャナブルな、実行可能なスキルを利用できるようにし、効果的なアプローチとテクニックを迅速に適用できるようにし、既存の知能を補完するコンテキストを提供することに重点を置きます。","ko":"대리인이 참고서를 사용하여 발견할 수 있는, 스캔할 수 있는, 실행 가능한 기술을 활용할 수 있도록 하여 효과적인 접근 방식 및 기술을 신속하게 적용할 수 있도록하며, 기존 지능을 보완하는 컨텍스트를 제공하는 데 중점을 둡니다.","es":"Habilita a los agentes a aprovechar habilidades descubribles, escaneables y accionables utilizando guías de referencia, lo que les permite aplicar rápidamente enfoques y técnicas efectivos, con un enfoque en proporcionar contexto que complementa su inteligencia existente.","fr":"Permet aux agents d''exploiter des compétences découvrables, scannables et actionnables en utilisant des guides de référence, leur permettant d''appliquer rapidement des approches et des techniques efficaces, avec un focus sur la fourniture de contexte qui complète leur intelligence existante.","de":"Ermächtigt die Agenten, entdeckbare, scannbare und handhabbare Fähigkeiten unter Verwendung von Referenzhandbüchern zu nutzen, sodass sie effektive Ansätze und Techniken schnell anwenden können, mit Fokus auf die Bereitstellung von Kontext, der ihre vorhandene Intelligenz ergänzt.","pt":"Habilita os agentes a aproveitar habilidades descobríveis, legíveis e ações usando guias de referência, permitindo que eles apliquem rapidamente abordagens e técnicas eficazes, com foco em fornecer contexto que complementa sua inteligência existente.","ru":"Наделяет агентов возможностью использовать открытия, сканируемые и действенные навыки с помощью справочных руководств, позволяя им быстро применять эффективные подходы и методы, с фокусом на предоставлении контекста, который дополняет их существующий интеллект.","ar":"تمكّن الوكيل من الاستفادة من مهارات يمكن اكتشافها وقراءتها وتطبيقها باستخدام دلائل مرجعية، مما يسمح لهم بتطبيق مقاربات وفنون فعالة بسرعة، مع التركيز على توفير السياق الذي يكمّل ذكاءهم الحالي."},"useCases":{"en":["Automating technique discovery","Generating actionable documentation","Enhancing agent intelligence with proven patterns"],"zh":["自动化技术发现","生成可执行的文档","使用验证的模式增强代理智能"],"ja":["テクニックの自動発見","アクション可能なドキュメントの生成","検証済みのパターンを使用したエージェントの知能の向上"],"ko":["기술 자동 발견","실행 가능한 문서 생성","검증된 패턴을 사용한 에이전트 지능 향상"],"es":["Automatización del descubrimiento de técnicas","Generación de documentación accionable","Mejora de la inteligencia del agente con patrones probados"],"fr":["Automatisation de la découverte de techniques","Génération de documentation actionnable","Amélioration de l''intelligence de l''agent avec des modèles éprouvés"],"de":["Automatisierung der Technikentdeckung","Generierung von handhabbarer Dokumentation","Verbesserung der Agentenintelligenz mit bewährten Mustern"],"pt":["Automatizar a descoberta de técnicas","Gerar documentação ação","Melhorar a inteligência do agente com padrões comprovados"],"ru":["Автоматизация открытия методов","Генерация документации действий","Улучшение интеллекта агента с помощью проверенных шаблонов"],"ar":["تأتمت اكتشاف التقنيات","توليد توثيق قابل للتنفيذ","تحسين ذكاء العميل باستخدام النماذج المثبتة"]},"limitations":{"en":["Requires adherence to core principle of assuming agent intelligence","Limited to techniques and patterns applicable to Claude instances"],"zh":["需要遵守代理智能的核心原则","仅限于适用于 Claude 实例的技术和模式"],"ja":["エージェントの知能の核心原則を遵守する必要がある","Claude インスタンスに適用可能なテクニックとパターンに限定される"],"ko":["에이전트 지능의 핵심 원칙을 준수해야 함","클라우드 인스턴스에 적용 가능한 기술 및 패턴으로 제한됨"],"es":["Requiere adherirse al principio básico de asumir la inteligencia del agente","Limitado a técnicas y patrones aplicables a instancias de Claude"],"fr":["Nécessite de s''assurer du principe de base consistant à supposer l''intelligence de l''agent","Limité aux techniques et modèles applicables aux instances de Claude"],"de":["Erfordert die Einhaltung des grundlegenden Prinzips, das die Annahme der Agentenintelligenz voraussetzt","Begrenzt auf Techniken und Muster, die auf Claude-Instanzen anwendbar sind"],"pt":["Exige adesão ao princípio central de assumir a inteligência do agente","Limitado a técnicas e padrões aplicáveis às instâncias do Claude"],"ru":["Требует соблюдения основного принципа предположения об интеллекте агента","Ограничен методами и шаблонами, применимыми к экземплярам Claude"],"ar":["يتطلب الالتزام بمبدأ أساسي افتراض ذكاء الوكيل","محدود بالتكنولوجيا والنماذج القابلة للتطبيق على مثيلات Claude"]},"version":4},"contentHash":"2d5916eb2f7648cdb34fd17df7a5975a69eafd4f3265e96bc0f52b3b2d10df7a","qualityScore":60}');
