INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AgentWorkforce/trajectories/creating-skills', 'creating-skills', 'AgentWorkforce', 'trajectories', 'community', 'creating-skills AgentWorkforce trajectories community The creating-skills documentation layer helps future Claude instances quickly find and apply proven techniques, patterns, or tools, making it a valuable resource for developers. 创建技能是为了帮助AI智能体快速找到和应用有效的方法，必须是可发现、可扫描和可执行的。 スキルはAIエージェントが効果的なアプローチを迅速に見つけて適用できるように設計されています。発見可能、スキャン可能、実行可能である必要があります。 스킬은 미래의 AI 에이전트가 효과적인 방법을 빠르게 찾고 적용할 수 있도록 설계되었습니다. 발견 가능, 스캔 가능, 실행 가능해야 합니다. Las habilidades son guías de referencia para técnicas, patrones y herramientas comprobados. Ayudan a los agentes de IA a encontrar y aplicar enfoques efectivos de manera rápida. Les compétences sont des guides de référence pour des techniques, des modèles et des outils éprouvés. Ils aident les agents d''IA à trouver et à appliquer des approches efficaces rapidement. Fähigkeiten sind Referenzleitfäden für bewährte Techniken, Muster und Tools. Sie helfen KI-Agents, effektive Ansätze schnell zu finden und anzuwenden. Criar habilidades para agentes de IA envolve escrever guias de referência para técnicas comprovadas, permitindo que futuras instâncias de Claude as encontrem e apliquem rapidamente Создание навыков для ИИ агентов включает написание справочных руководств для проверенных техник, шаблонов или инструментов, чтобы будущие экземпляры Claude могли быстро их найти и применить إنشاء مهارات لوكلاء الذكاء الاصطناعي يتضمن كتابة أدلة مرجعية للتقنيات المثبتة، مما يسمح لمثيلات كلود المستقبلية بالعثور عليها وتطبيقها بسرعة how to use creating-skills what is creating-skills creating-skills documentation guide creating-skills for AI agents creating-skills setup guide creating-skills alternative creating-skills vs other documentation tools AI智能体 创建技能 可发现的技能 快速扫描 清晰的执行示例 AI工具 智能体开发 Provides discoverable techniques for future Claude instances Enables scannable content for quick evaluation Offers actionable examples for effective approaches Follows core principle of assuming Claude''s existing intelligence Supports creation of skills for proven techniques and patterns creating-skills is a reference guide for proven techniques, patterns, or tools, designed to be discoverable, scannable, and actionable for AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('benbrastmckie/ModelChecker/skill-latex-implementation', 'community', 'benbrastmckie', 'ModelChecker', 'benbrastmckie/ModelChecker', 'skill-latex-implementation', 12, 3, 60, '2026-02-18T20:51:02Z', '2026-03-06T06:45:16.215Z', '08c02f9304160962985693b454cb2e55d8fe7aa83e645feb5cc653d5f0fcf4b1', '{"id":"benbrastmckie/ModelChecker/skill-latex-implementation","name":"skill-latex-implementation","description":{"en":"The skill-latex-implementation is a hyperintensional theorem prover for rapidly prototyping modular semantic theories, benefiting developers working with counterfactuals and semantics.","zh":"LaTeX 实现技能是一种超强智能定理证明工具，用于快速原型模块化语义理论。它支持 Z3-SMT 求解器和反事实等高级功能","ja":"LaTeX 実装スキルは、モジュラーな意味論理理論の迅速なプロトタイピングを可能にするハイパーインテンショナルの定理証明ツールです。Z3-SMT ソルバや反事実などの高度な機能をサポート","ko":"LaTeX 구현 스킬은 모듈화된 의미론 이론의 빠른 프로토 타이핑을 가능하게 하는 하이퍼인텐셔널 정리 증명 도구입니다. Z3-SMT 솔버 및 반사실 등의 고급 기능을 지원","es":"La habilidad skill-latex-implementation es un probador de teoremas hiperintensional para prototipar rápidamente teorías semánticas modulares","fr":"La compétence skill-latex-implementation est un prouveur de théorèmes hyperintensionnel pour prototyper rapidement des théories sémantiques modulaires","de":"Die Fähigkeit skill-latex-implementation ist ein hyperintensionaler Theorem-Beweiser für das schnelle Prototyping modularen semantischer Theorien","pt":"O skill-latex-implementation é uma ferramenta de provador de teoremas hiperintensional para prototipar teorias semânticas modulares.","ru":"ИИ Агент skill-latex-implementation является гиперинтенсиональным доказателем теорем для быстрого прототипирования модульных семантических теорий.","ar":"مهارة skill-latex-implementation هي أداة إثبات نظرية هائبة للتأمل في النظريات الدلالية المتعددة."},"seo":{"title":{"en":"skill-latex-implementation: Hyperintensional Theorem Prov...","zh":"LaTeX 实现指南：超强智能 LaTeX 证明工具","ja":"LaTeX 実装ガイド：ハイパーインテンショナルの定理証明ツール","ko":"LaTeX 구현 가이드: 하이퍼인텐셔널 정리 증명 도구","es":"Guía de Implementación de skill-latex-implementation para...","fr":"Guide d''Implémentation de skill-latex-implementation pour...","de":"Leitfaden für die Implementierung von skill-latex-impleme...","pt":"Guia de Implementação do skill-latex-implementation para ...","ru":"Настройка ИИ Агентов: skill-latex-implementation для быст...","ar":"دليل تنفيذ مهارة skill-latex-implementation لأدوات الذكاء..."},"description":{"en":"Discover how skill-latex-implementation simplifies modular semantic theories with z3-smt-solver. Learn to deploy this AI agent skill today!","zh":"了解 LaTeX 实现技能，快速原型模块化语义理论，并解决复杂的超强智能定理证明问题","ja":"LaTeX 実装スキルを学び、モジュラーな意味論理理論の迅速なプロトタイピングと複雑なハイパーインテンショナルの定理証明を実現","ko":"LaTeX 구현 스킬을 배우고 모듈화된 의미론 이론의 빠른 프로토 타이핑 및 복잡한 하이퍼인텐셔널 정리 증명을 달성","es":"Aprende a utilizar skill-latex-implementation para probar teorías semánticas modulares con el solucionador Z3 SMT","fr":"Découvrez comment utiliser skill-latex-implementation pour tester des théories sémantiques modulaires avec le solveur Z3 SMT","de":"Erfahren Sie, wie Sie skill-latex-implementation verwenden, um modulare semantische Theorien mit dem Z3-SMT-Solver zu testen","pt":"Aprenda a implementar o skill-latex-implementation para prototipar teorias semânticas modulares com o z3-smt-solver","ru":"Узнайте, как настроить skill-latex-implementation для быстрого прототипирования модульных семантических теорий с помощью z3-smt-solver","ar":"تعرف على كيفية تنفيذ مهارة skill-latex-implementation لتصميم نظريات دلالية متعددة باستخدام z3-smt-solver"},"definition":{"en":"skill-latex-implementation is a thin wrapper that delegates LaTeX document implementation to latex-implementation-agent subagent for hyperintensional theorem proving.","zh":"LaTeX 实现技能是一种用于快速原型模块化语义理论的超强智能定理证明工具","ja":"LaTeX 実装スキルは、モジュラーな意味論理理論の迅速なプロトタイピングを可能にするハイパーインテンショナルの定理証明ツール","ko":"LaTeX 구현 스킬은 모듈화된 의미론 이론의 빠른 프로토 타이핑을 가능하게 하는 하이퍼인텐셔널 정리 증명 도구","es":"Un probador de teoremas hiperintensional para prototipar teorías semánticas modulares","fr":"Un prouveur de théorèmes hyperintensionnel pour prototyper des théories sémantiques modulaires","de":"Ein hyperintensionaler Theorem-Beweiser für modulare semantische Theorien","pt":"O skill-latex-implementation é uma ferramenta de provador de teoremas que delega a implementação de documentos LaTeX para um subagente.","ru":"ИИ Агент skill-latex-implementation - это инструмент доказателя теорем, который делегирует реализацию документов LaTeX подагенту.","ar":"مهارة skill-latex-implementation هي أداة إثبات نظرية التي تفويض تنفيذ مستندات LaTeX إلى وكيل فرعي."},"features":{"en":["Delegates LaTeX document implementation to latex-implementation-agent subagent","Implements the skill-internal postflight pattern for streamlined operations","Handles postflight operations including status update, artifact linking, and git commit","Utilizes z3-smt-solver for efficient theorem proving","Supports context references via Path: .claude","Eliminates the ''continue'' prompt issue between skill return and orchestrator"],"zh":["支持 Z3-SMT 求解器","超强智能定理证明","模块化语义理论","反事实支持","快速原型开发"],"ja":["Z3-SMT ソルバをサポート","ハイパーインテンショナルの定理証明","モジュラーな意味論理理論","反事実をサポート","迅速なプロトタイピング"],"ko":["Z3-SMT 솔버 지원","하이퍼인텐셔널 정리 증명","모듈화된 의미론 이론","반사실 지원","빠른 프로토 타이핑"],"es":["Soporte para el solucionador Z3 SMT","Implementación de teorías semánticas modulares","Patrón de post-vuelo interno para operaciones de seguimiento","Compatibilidad con LaTeX para documentación","Implementación de la lógica de contrafácticos"],"fr":["Prise en charge du solveur Z3 SMT","Implémentation de théories sémantiques modulaires","Modèle de post-vol interne pour les opérations de suivi","Compatibilité avec LaTeX pour la documentation","Implémentation de la logique des contre-factuels"],"de":["Unterstützung für den Z3-SMT-Solver","Implementierung modularen semantischer Theorien","Internes Post-Flight-Muster für Nachverfolgungsoperationen","Kompatibilität mit LaTeX für Dokumentation","Implementierung der Logik von Kontrafaktika"],"pt":["Suporte ao z3-smt-solver para prototipagem de teorias semânticas","Implementação de documentos LaTeX via subagente","Padrão de pós-voo interno para operações de status e commit","Suporte a contrafatuais e hiperintensionalidade","Integração com o padrão de pós-voo para evitar problemas de prompt"],"ru":["Поддержка z3-smt-solver для быстрого прототипирования семантических теорий","Реализация документов LaTeX через подагента","Внутренний паттерн постполета для операций статуса и коммита","Поддержка контрофактуалов и гиперинтенсиональности","Интеграция с паттерном постполета для избежания проблем с промптом"],"ar":["دعم z3-smt-solver لتصميم النظريات الدلالية المتعددة","تنفيذ مستندات LaTeX عبر وكيل فرعي","نمط ما بعد الطيران الداخلي للعمليات الحالة والإلتزام","دعم الافتراضات والهيبرينتشنالية","دمج نمط ما بعد الطيران لتجنب مشاكل البرومبت"]},"keywords":{"en":["how to use skill-latex-implementation","skill-latex-implementation alternative","skill-latex-implementation setup guide","what is skill-latex-implementation","skill-latex-implementation vs latex-implementation-agent","hyperintensional theorem prover install","z3-smt-solver integration","modular semantic theories with skill-latex-implementation","skill-latex-implementation for counterfactuals and semantics"],"zh":["LaTeX 实现","超强智能定理证明","Z3-SMT 求解器","反事实","模块化语义理论","AI 工具","LaTeX 证明工具"],"ja":["LaTeX 実装","ハイパーインテンショナルの定理証明","Z3-SMT ソルバ","反事実","モジュラーな意味論理理論","AI エージェント","LaTeX 証明ツール"],"ko":["LaTeX 구현","하이퍼인텐셔널 정리 증명","Z3-SMT 솔버","반사실","모듈화된 의미론 이론","AI 툴","LaTeX 증명 도구"],"es":["skill-latex-implementation","prototipado rápido","teorías semánticas modulares","solucionador Z3 SMT","LaTeX","contrafácticos","herramientas de AI","agentes de AI","desarrollo de software"],"fr":["skill-latex-implementation","prototypage rapide","théories sémantiques modulaires","solveur Z3 SMT","LaTeX","contre-factuels","outils d''IA","agents d''IA","développement de logiciels"],"de":["skill-latex-implementation","schnelles Prototyping","modulare semantische Theorien","Z3-SMT-Solver","LaTeX","Kontrafaktika","KI-Tools","KI-Agenten","Softwareentwicklung"],"pt":["skill-latex-implementation","ferramentas de ia","z3-smt-solver","teorias semânticas","prototipagem","contrafatuais","hiperintensionalidade","laTeX","subagente"],"ru":["skill-latex-implementation","ии агенты","z3-smt-solver","семантические теории","быстрое прототипирование","контрофактуалы","гиперинтенсиональность","latex","подагент"],"ar":["مهارة skill-latex-implementation","أدوات الذكاء الاصطناعي","z3-smt-solver","نظريات دلالية","تصميم متعد","افتراضات","هيبرينتشنالية","لا텍س","وكيل فرعي"]}},"owner":"benbrastmckie","repo":"ModelChecker","repoPath":"benbrastmckie/ModelChecker","stars":12,"forks":3,"updatedAt":"2026-02-18T20:51:02Z","topics":["counterfactuals","hyperintensionality","semantics","z3-smt-solver"],"category":"community","skillMd":{"name":"skill-latex-implementation","description":"Implement LaTeX documents following a plan. Invoke for LaTeX-language implementation tasks.","bodyPreview":"# LaTeX Implementation Skill\n\nThin wrapper that delegates LaTeX document implementation to `latex-implementation-agent` subagent.\n\n**IMPORTANT**: This skill implements the skill-internal postflight pattern. After the subagent returns,\nthis skill handles all postflight operations (status update, artifact linking, git commit) before returning.\nThis eliminates the \"continue\" prompt issue between skill return and orchestrator.\n\n## Context References\n\nReference (do not load eagerly):\n- Path: `.claude","body":"# LaTeX Implementation Skill\n\nThin wrapper that delegates LaTeX document implementation to `latex-implementation-agent` subagent.\n\n**IMPORTANT**: This skill implements the skill-internal postflight pattern. After the subagent returns,\nthis skill handles all postflight operations (status update, artifact linking, git commit) before returning.\nThis eliminates the \"continue\" prompt issue between skill return and orchestrator.\n\n## Context References\n\nReference (do not load eagerly):\n- Path: `.claude/context/core/formats/return-metadata-file.md` - Metadata file schema\n- Path: `.claude/context/core/patterns/postflight-control.md` - Marker file protocol\n- Path: `.claude/context/core/patterns/file-metadata-exchange.md` - File I/O helpers\n- Path: `.claude/context/core/patterns/jq-escaping-workarounds.md` - jq escaping patterns (Issue #1132)\n\nNote: This skill is a thin wrapper with internal postflight. Context is loaded by the delegated agent.\n\n## Trigger Conditions\n\nThis skill activates when:\n- Task language is \"latex\"\n- /implement command targets a LaTeX task\n- Documents, papers, or formatted output needs to be created\n\n---\n\n## Execution\n\n### 0. Preflight Status Update\n\nBefore delegating to the subagent, update task status to \"implementing\".\n\n**Reference**: `@.claude/context/core/patterns/inline-status-update.md`\n\n**Update state.json**:\n```bash\njq --arg ts \"$(date -u +%Y-%m-%dT%H:%M:%SZ)\" \\\n   --arg status \"implementing\" \\\n   --arg sid \"$session_id\" \\\n  ''(.active_projects[] | select(.project_number == ''$task_number'')) |= . + {\n    status: $status,\n    last_updated: $ts,\n    session_id: $sid,\n    started: $ts\n  }'' specs/state.json > /tmp/state.json && mv /tmp/state.json specs/state.json\n```\n\n**Update TODO.md**: Use Edit tool to change status marker from `[PLANNED]` to `[IMPLEMENTING]`.\n\n**Update plan file** (if exists): Update the Status field in plan metadata:\n```bash\n# Find latest plan file (use padded directory number)\npadded_num=$(printf \"%03d\" \"$task_number\")\nplan_file=$(ls -1 \"specs/${padded_num}_${project_name}/plans/implementation-\"*.md 2>/dev/null | sort -V | tail -1)\nif [ -n \"$plan_file\" ] && [ -f \"$plan_file\" ]; then\n    sed -i \"s/^\\- \\*\\*Status\\*\\*: \\[.*\\]$/- **Status**: [IMPLEMENTING]/\" \"$plan_file\"\nfi\n```\n\n**Create Postflight Marker**:\n```bash\n# Ensure task directory exists\nmkdir -p \"specs/${padded_num}_${project_name}\"\n\ncat > \"specs/${padded_num}_${project_name}/.postflight-pending\" << EOF\n{\n  \"session_id\": \"${session_id}\",\n  \"skill\": \"skill-latex-implementation\",\n  \"task_number\": ${task_number},\n  \"operation\": \"implement\",\n  \"reason\": \"Postflight pending: status update, artifact linking, git commit\",\n  \"created\": \"$(date -u +%Y-%m-%dT%H:%M:%SZ)\",\n  \"stop_hook_active\": false\n}\nEOF\n```\n\n---\n\n### 1. Input Validation\n\nValidate required inputs:\n- `task_number` - Must be provided and exist in state.json\n- Task status must allow implementation (planned, implementing, partial)\n\n```bash\n# Lookup task\ntask_data=$(jq -r --arg num \"$task_number\" \\\n  ''.active_projects[] | select(.project_number == ($num | tonumber))'' \\\n  specs/state.json)\n\n# Validate exists\nif [ -z \"$task_data\" ]; then\n  return error \"Task $task_number not found\"\nfi\n\n# Extract fields\nlanguage=$(echo \"$task_data\" | jq -r ''.language // \"general\"'')\nstatus=$(echo \"$task_data\" | jq -r ''.status'')\nproject_name=$(echo \"$task_data\" | jq -r ''.project_name'')\ndescription=$(echo \"$task_data\" | jq -r ''.description // \"\"'')\n\n# Validate language\nif [ \"$language\" != \"latex\" ]; then\n  return error \"Task $task_number is not a LaTeX task\"\nfi\n\n# Validate status\nif [ \"$status\" = \"completed\" ]; then\n  return error \"Task already completed\"\nfi\n```\n\n### 2. Context Preparation\n\nPrepare delegation context:\n\n```json\n{\n  \"session_id\": \"sess_{timestamp}_{random}\",\n  \"delegation_depth\": 1,\n  \"delegation_path\": [\"orchestrator\", \"implement\", \"skill-latex-implementation\"],\n  \"timeout\": 3600,\n  \"task_context\": {\n    \"task_number\": N,\n    \"task_name\": \"{project_name}\",\n    \"description\": \"{description}\",\n    \"language\": \"latex\"\n  },\n  \"plan_path\": \"specs/{NNN}_{SLUG}/plans/implementation-{NNN}.md\",\n  \"metadata_file_path\": \"specs/{NNN}_{SLUG}/.return-meta.json\"\n}\n```\n\n### 3. Invoke Subagent\n\n**CRITICAL**: You MUST use the **Task** tool to spawn the subagent.\n\nThe `agent` field in this skill''s frontmatter specifies the target: `latex-implementation-agent`\n\n**Required Tool Invocation**:\n```\nTool: Task (NOT Skill)\nParameters:\n  - subagent_type: \"latex-implementation-agent\"\n  - prompt: [Include task_context, delegation_context, plan_path]\n  - description: \"Execute LaTeX implementation for task {N}\"\n```\n\n**DO NOT** use `Skill(latex-implementation-agent)` - this will FAIL.\nAgents live in `.claude/agents/`, not `.claude/skills/`.\nThe Skill tool can only invoke skills from `.claude/skills/`.\n\nThe subagent will:\n- Load LaTeX-specific context files (style guide, notation conventions, etc.)\n- Create/modify .tex files\n- Execute compilation loop (pdflatex/latexmk)\n- Handle bibliography processing (bibtex/biber)\n- Create implementation summary\n- Write metadata to `specs/{NNN}_{SLUG}/.return-meta.json`\n- Return a brief text summary (NOT JSON)\n\n### 3a. Validate Subagent Return Format\n\n**IMPORTANT**: Check if subagent accidentally returned JSON to console (v1 pattern) instead of writing to file (v2 pattern).\n\nIf the subagent''s text return parses as valid JSON, log a warning:\n\n```bash\n# Check if subagent return looks like JSON (starts with { and is valid JSON)\nsubagent_return=\"$SUBAGENT_TEXT_RETURN\"\nif echo \"$subagent_return\" | grep -q ''^{'' && echo \"$subagent_return\" | jq empty 2>/dev/null; then\n    echo \"WARNING: Subagent returned JSON to console instead of writing metadata file.\"\n    echo \"This indicates the agent may have outdated instructions (v1 pattern instead of v2).\"\n    echo \"The skill will continue by reading the metadata file, but this should be fixed.\"\nfi\n```\n\nThis validation:\n- Does NOT fail the operation (continues to read metadata file)\n- Logs a warning for debugging\n- Indicates the subagent instructions need updating\n- Allows graceful handling of mixed v1/v2 agents\n\n### 4. Parse Subagent Return (Read Metadata File)\n\nAfter subagent returns, read the metadata file:\n\n```bash\nmetadata_file=\"specs/${padded_num}_${project_name}/.return-meta.json\"\n\nif [ -f \"$metadata_file\" ] && jq empty \"$metadata_file\" 2>/dev/null; then\n    status=$(jq -r ''.status'' \"$metadata_file\")\n    artifact_path=$(jq -r ''.artifacts[0].path // \"\"'' \"$metadata_file\")\n    artifact_type=$(jq -r ''.artifacts[0].type // \"\"'' \"$metadata_file\")\n    artifact_summary=$(jq -r ''.artifacts[0].summary // \"\"'' \"$metadata_file\")\n    phases_completed=$(jq -r ''.metadata.phases_completed // 0'' \"$metadata_file\")\n    phases_total=$(jq -r ''.metadata.phases_total // 0'' \"$metadata_file\")\n\n    # Extract completion_data fields (if present)\n    completion_summary=$(jq -r ''.completion_data.completion_summary // \"\"'' \"$metadata_file\")\n    roadmap_items=$(jq -c ''.completion_data.roadmap_items // []'' \"$metadata_file\")\nelse\n    echo \"Error: Invalid or missing metadata file\"\n    status=\"failed\"\nfi\n```\n\nValidate the metadata contains required fields:\n- Status is one of: implemented, partial, failed, blocked\n- Summary is non-empty and <100 tokens\n- Artifacts array present (source files, compiled PDF, summary)\n- Metadata contains session_id, agent_type, delegation info\n\n### 5. Postflight Status Update\n\nAfter implementation, update task status based on result.\n\n**Reference**: `@.claude/context/core/patterns/inline-status-update.md`\n\n**If result.status == \"implemented\"**:\n\nUpdate state.json to \"completed\" and add completion_data fields (two-step pattern for Issue #1132):\n```bash\n# Step 1: Update status and timestamps\njq --arg ts \"$(date -u +%Y-%m-%dT%H:%M:%SZ)\" \\\n   --arg status \"completed\" \\\n  ''(.active_projects[] | select(.project_number == ''$task_number'')) |= . + {\n    status: $status,\n    last_updated: $ts,\n    completed: $ts\n  }'' specs/state.json > /tmp/state.json && mv /tmp/state.json specs/state.json\n\n# Step 2: Add completion_summary (always required for completed tasks)\nif [ -n \"$completion_summary\" ]; then\n    jq --arg summary \"$completion_summary\" \\\n      ''(.active_projects[] | select(.project_number == ''$task_number'')).completion_summary = $summary'' \\\n      specs/state.json > /tmp/state.json && mv /tmp/state.json specs/state.json\nfi\n\n# Step 3: Add roadmap_items (if present and non-empty)\nif [ \"$roadmap_items\" != \"[]\" ] && [ -n \"$roadmap_items\" ]; then\n    jq --argjson items \"$roadmap_items\" \\\n      ''(.active_projects[] | select(.project_number == ''$task_number'')).roadmap_items = $items'' \\\n      specs/state.json > /tmp/state.json && mv /tmp/state.json specs/state.json\nfi\n\n# Step 4: Filter out existing summary artifacts (use \"| not\" pattern to avoid != escaping - Issue #1132)\njq ''(.active_projects[] | select(.project_number == ''$task_number'')).artifacts =\n    [(.active_projects[] | select(.project_number == ''$task_number'')).artifacts // [] | .[] | select(.type == \"summary\" | not)]'' \\\n  specs/state.json > /tmp/state.json && mv /tmp/state.json specs/state.json\n\n# Step 5: Add new summary artifact\njq --arg path \"$artifact_path\" \\\n  ''(.active_projects[] | select(.project_number == ''$task_number'')).artifacts += [{\"path\": $path, \"type\": \"summary\"}]'' \\\n  specs/state.json > /tmp/state.json && mv /tmp/state.json specs/state.json\n```\n\nUpdate TODO.md:\n- Change status marker from `[IMPLEMENTING]` to `[COMPLETED]`\n- Add summary artifact link: `- **Summary**: [implementation-summary-{DATE}.md]({artifact_path})`\n\n**Update plan file** (if exists): Update the Status field to `[COMPLETED]` with verification:\n```bash\nplan_file=$(ls -1 \"specs/${padded_num}_${project_name}/plans/implementation-\"*.md 2>/dev/null | sort -V | tail -1)\nif [ -n \"$plan_file\" ] && [ -f \"$plan_file\" ]; then\n    # Try bullet pattern first, then non-bullet pattern\n    sed -i ''s/^\\- \\*\\*Status\\*\\*: \\[.*\\]$/- **Status**: [COMPLETED]/'' \"$plan_file\"\n    sed -i ''s/^\\*\\*Status\\*\\*: \\[.*\\]$/**Status**: [COMPLETED]/'' \"$plan_file\"\n    # Verify update\n    if grep -qE ''^\\*\\*Status\\*\\*: \\[COMPLETED\\]|^\\- \\*\\*Status\\*\\*: \\[COMPLETED\\]'' \"$plan_file\"; then\n        echo \"Plan file status updated to [COMPLETED]\"\n    else\n        echo \"WARNING: Could not verify plan file status update\"\n    fi\nelse\n    echo \"INFO: No plan file found to update (directory: specs/${padded_num}_${project_name}/plans/)\"\nfi\n```\n\n**If result.status == \"partial\"**:\n\nUpdate state.json with resume point (keep status as \"implementing\"):\n```bash\njq --arg ts \"$(date -u +%Y-%m-%dT%H:%M:%SZ)\" \\\n   --arg phase \"$completed_phase\" \\\n  ''(.active_projects[] | select(.project_number == ''$task_number'')) |= . + {\n    last_updated: $ts,\n    resume_phase: ($phase | tonumber + 1)\n  }'' specs/state.json > /tmp/state.json && mv /tmp/state.json specs/state.json\n```\n\nTODO.md stays as `[IMPLEMENTING]`.\n\n**Update plan file** (if exists): Update the Status field to `[PARTIAL]` with verification:\n```bash\nplan_file=$(ls -1 \"specs/${padded_num}_${project_name}/plans/implementation-\"*.md 2>/dev/null | sort -V | tail -1)\nif [ -n \"$plan_file\" ] && [ -f \"$plan_file\" ]; then\n    # Try bullet pattern first, then non-bullet pattern\n    sed -i ''s/^\\- \\*\\*Status\\*\\*: \\[.*\\]$/- **Status**: [PARTIAL]/'' \"$plan_file\"\n    sed -i ''s/^\\*\\*Status\\*\\*: \\[.*\\]$/**Status**: [PARTIAL]/'' \"$plan_file\"\n    # Verify update\n    if grep -qE ''^\\*\\*Status\\*\\*: \\[PARTIAL\\]|^\\- \\*\\*Status\\*\\*: \\[PARTIAL\\]'' \"$plan_file\"; then\n        echo \"Plan file status updated to [PARTIAL]\"\n    else\n        echo \"WARNING: Could not verify plan file status update\"\n    fi\nelse\n    echo \"INFO: No plan file found to update (directory: specs/${padded_num}_${project_name}/plans/)\"\nfi\n```\n\n**On failed**: Do NOT run postflight. Keep status as \"implementing\" for retry. Do not update plan file (leave as `[IMPLEMENTING]` for retry).\n\n### 6. Git Commit\n\nCommit changes with session ID:\n\n```bash\ngit add -A\ngit commit -m \"task ${task_number}: complete implementation\n\nSession: ${session_id}\n\nCo-Authored-By: Claude Opus 4.5 <noreply@anthropic.com>\"\n```\n\n### 7. Cleanup\n\nRemove marker and metadata files after postflight processing:\n\n```bash\nrm -f \"specs/${padded_num}_${project_name}/.postflight-pending\"\nrm -f \"specs/${padded_num}_${project_name}/.postflight-loop-guard\"\nrm -f \"specs/${padded_num}_${project_name}/.return-meta.json\"\n```\n\n### 8. Return Brief Summary\n\nReturn a brief text summary (NOT JSON) describing the implementation results.\n\n---\n\n## Return Format\n\nThis skill returns a **brief text summary** (NOT JSON). The JSON metadata is written to the file and processed internally.\n\nExample successful return:\n```\nLaTeX implementation completed for task 334:\n- All 4 phases executed, document compiles cleanly\n- Created 42-page PDF at docs/logos-manual.pdf\n- Created summary at specs/334_logos_docs/summaries/implementation-summary-20260118.md\n- Status updated to [COMPLETED]\n- Changes committed with session sess_1736700000_abc123\n```\n\nExample partial return:\n```\nLaTeX implementation partially completed for task 334:\n- Phases 1-2 of 3 executed\n- Phase 3 blocked: missing tikz-cd package\n- Partial summary at specs/334_logos_docs/summaries/implementation-summary-20260118.md\n- Status remains [IMPLEMENTING] - run /implement 334 to resume\n```\n\n---\n\n## Error Handling\n\n### Input Validation Errors\nReturn immediately with failed status if task not found, wrong language, or status invalid.\n\n### Subagent Errors\nPass through the subagent''s error return verbatim.\n\n### Timeout\nReturn partial status if subagent times out (default 3600s).\n"},"lastSynced":"2026-03-06T06:45:16.215Z","agentAnalysis":{"suitability":{"en":"Ideal for Theorem Proving Agents requiring rapid prototyping of modular semantic theories with LaTeX implementation","zh":"适用于需要快速原型开发模块化语义理论并使用 LaTeX 实现的定理证明代理","ja":"ラテックス実装を必要とするモジュラーな意味論理理論の迅速なプロトタイピングを必要とする定理証明エージェントに適している","ko":"라텍스 구현을 필요로 하는 모듈러 의미론 이론의 빠른 프로토 타이핑을 필요로하는 정리 증명 에이전트에 적합함","es":"Ideal para agentes de demostración de teoremas que requieren prototipado rápido de teorías semánticas modulares con implementación de LaTeX","fr":"Idéal pour les agents de preuve de théorèmes nécessitant un prototypage rapide de théories sémantiques modulaires avec mise en œuvre de LaTeX","de":"Ideal für Theoriebeweisagenten, die ein schnelles Prototyping modulare semantischer Theorien mit LaTeX-Implementierung erfordern","pt":"Ideal para Agentes de Prova de Teorema que requerem prototipagem rápida de teorias semânticas modulares com implementação LaTeX","ru":"Идеально для агентов теоремы, требующих быстрой разработки модульных семантических теорий с реализацией LaTeX","ar":"مثالي لعميل برهان المبرهنة الذي يتطلب إعدادًا سريعًا لنظريات دلالية متعددة مع تنفيذ LaTeX"},"recommendation":{"en":"Empowers agents to delegate LaTeX document implementation to a subagent, handling postflight operations like status updates, artifact linking, and git commits, while utilizing the skill-internal postflight pattern to avoid the ''continue'' prompt issue, all within a hyperintensional theorem prover framework","zh":"使得代理能够将 LaTeX 文档实现委托给子代理，处理后续操作，如状态更新、构件链接和 git 提交，同时利用技能内部的后续操作模式避免 ''继续'' 提示问题，所有这些都在超强语义定理证明框架内进行","ja":"エージェントがラテックス文書の実装をサブエージェントに委託し、ステータス更新、成果物リンク、gitコミットなどの後続作業を処理する同时、スキル内部の後続作業パターンを利用して ''続行'' 促告問題を避け、すべてを超拡張定理証明フレームワーク内で行うことができる","ko":"에이전트가 라텍스 문서 구현을 서브 에이전트에게 위임하고 상태 업데이트, 아티팩트 링크, 깃 커밋 등의 후속 작업을 처리하는 동시에, 스킬 내부의 후속 작업 패턴을 활용하여 ''계속'' 프롬프트 문제를 피하고, 모든 작업을 초과 확장 정리 증명 프레임워크 내에서 수행할 수 있음","es":"Habilita a los agentes a delegar la implementación de documentos de LaTeX a un subagente, manejar operaciones posteriores al vuelo como actualizaciones de estado, vinculación de artefactos y confirmaciones de git, mientras utiliza el patrón de postvuelo interno a la habilidad para evitar el problema de la solicitud de ''continuar'', todo dentro de un marco de demostración de teoremas hiperintensional","fr":"Permet aux agents de déléguer la mise en œuvre de documents LaTeX à un sous-agent, gérer les opérations post-vol comme les mises à jour de statut, le lien d''artefacts et les validations Git, tout en utilisant le modèle de post-vol interne à la compétence pour éviter le problème de la invite ''continuer'', le tout dans un cadre de preuve de théorèmes hyperintensionnel","de":"Ermächtigt Agenten, die LaTeX-Dokumentimplementierung an einen Subagenten zu delegieren, Nachflugoperationen wie Statusaktualisierungen, Artefaktverknüpfungen und Git-Commits zu verwalten, während die interne Nachflugmuster der Fähigkeit verwendet wird, um das Problem des ''Weiter'' Prompts zu vermeiden, all dies innerhalb eines hyperintensionalen Theoriebeweisframeworks","pt":"Habilita os agentes a delegar a implementação do documento LaTeX a um subagente, tratando operações pós-voo como atualizações de status, links de artefatos e commits git, enquanto utiliza o padrão de pós-voo interno à habilidade para evitar o problema do prompt ''continue'', tudo dentro de um framework de provador de teorema hiperintensional","ru":"Наделяет агентов возможностью делегировать реализацию документа LaTeX субагенту, обрабатывая после полетные операции, такие как обновления статуса, ссылки на артефакты и коммиты git, при этом используя внутренний шаблон после полета, чтобы избежать проблемы с приглашением ''continue'', все в рамках гиперінтенціонального фреймворка теоремы","ar":"تمكّن الوكلاء من تفويض تنفيذ وثيقة LaTeX إلى وكيل فرعي، معالجة عمليات ما بعد الطيران مثل تحديثات الحالة وروابط الملفات المرفقة والالتزامات git، مع استخدام نمط ما بعد الطيران الداخلي للمهارة لتجنب مشكلة استمرار المؤشر، كل ذلك داخل إطار عمل مبرهنات 超hyperintensional"},"useCases":{"en":["Rapidly prototyping modular semantic theories with counterfactuals and semantics","Delegating LaTeX document implementation to a subagent for efficient theorem proving","Handling postflight operations seamlessly with the skill-internal postflight pattern"],"zh":["快速原型开发模块化语义理论和反事实语义","将 LaTeX 文档实现委托给子代理以实现高效的定理证明","使用技能内部的后续操作模式无缝处理后续操作"],"ja":["反事実と意味論のモジュラーな意味論理理論の迅速なプロトタイピング","ラテックス文書の実装をサブエージェントに委託して効率的な定理証明を行う","スキル内部の後続作業パターンを利用して後続作業を無断に処理する"],"ko":["반실제와 의미론의 모듈러 의미론 이론의 빠른 프로토 타이핑","라텍스 문서 구현을 서브 에이전트에게 위임하여 효율적인 정리 증명 수행","스킬 내부의 후속 작업 패턴을 활용하여 후속 작업을 무중단으로 처리"],"es":["Prototipar rápidamente teorías semánticas modulares con contrafactuales y semántica","Delegar la implementación de documentos de LaTeX a un subagente para una demostración eficiente de teoremas","Manejar operaciones posteriores al vuelo de forma fluida con el patrón de postvuelo interno a la habilidad"],"fr":["Prototyper rapidement des théories sémantiques modulaires avec des contre-factuels et des sémantiques","Déleguer la mise en œuvre de documents LaTeX à un sous-agent pour une preuve de théorèmes efficace","Gérer les opérations post-vol de manière fluide avec le modèle de post-vol interne à la compétence"],"de":["Schnelles Prototyping modulare semantischer Theorien mit Kontrafaktoren und Semantik","Delegierung der LaTeX-Dokumentimplementierung an einen Subagenten für eine effiziente Theoriebeweis","Nahtloses Verwalten von Nachflugoperationen mit dem internen Nachflugmuster der Fähigkeit"],"pt":["Prototipar rapidamente teorias semânticas modulares com contrafactuais e semântica","Delegar a implementação do documento LaTeX a um subagente para provação de teorema eficiente","Tratar operações pós-voo de forma transparente com o padrão de pós-voo interno à habilidade"],"ru":["Быстрое прототипирование модульных семантических теорий с контратфактуальными и семантическими","Делегирование реализации документа LaTeX субагенту для эффективного доказательства теорем","Бесшовное xử lý после полетных операций с внутренним шаблоном после полета"],"ar":["إعداد سريع لنظريات دلالية متعددة مع ضد الحقائق والدلالات","تفويض تنفيذ وثيقة LaTeX إلى وكيل فرعي لبرهنة فعالة","معالجة عمليات ما بعد الطيران بسهولة مع نمط ما بعد الطيران الداخلي للمهارة"]},"limitations":{"en":["Requires latex-implementation-agent subagent","Implements skill-internal postflight pattern, which may require specific orchestrator compatibility"],"zh":["需要 latex-implementation-agent 子代理","实现技能内部的后续操作模式，可能需要特定的编排器兼容性"],"ja":["latex-implementation-agent サブエージェントが必要","スキル内部の後続作業パターンを実装するが、特定のオーケストレーターとの互換性が必要となる可能性がある"],"ko":["라텍스 구현 에이전트 서브 에이전트가 필요","스킬 내부의 후속 작업 패턴을 구현하지만, 특정 오케스트레이터와의 호환성이 필요할 수 있음"],"es":["Requiere subagente latex-implementation-agent","Implementa patrón de postvuelo interno a la habilidad, que puede requerir compatibilidad específica del orquestador"],"fr":["Nécessite un sous-agent latex-implementation-agent","Mette en œuvre le modèle de post-vol interne à la compétence, qui peut nécessiter une compatibilité spécifique de l''orchestrateur"],"de":["Benötigt latex-implementation-agent-Subagenten","Implementiert internes Nachflugmuster der Fähigkeit, das möglicherweise spezifische Orchestrierer-Kompatibilität erfordert"],"pt":["Requer o subagente latex-implementation-agent","Implementa o padrão de pós-voo interno à habilidade, o que pode requerer compatibilidade específica com o orquestrador"],"ru":["Требует субагента latex-implementation-agent","Реализует внутренний шаблон после полета, который может требовать специфической совместимости с оркестратором"],"ar":["يتطلب وكيل فرعي latex-implementation-agent","يطبق نمط ما بعد الطيران الداخلي للمهارة، الذي قد يتطلب توافقًا محددًا مع المنسق"]},"version":4},"contentHash":"08c02f9304160962985693b454cb2e55d8fe7aa83e645feb5cc653d5f0fcf4b1","qualityScore":60}');
