INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eighteyes/tx/mesh-builder', 'mesh-builder', 'eighteyes', 'tx', 'community', 'mesh-builder eighteyes tx community agentic ai claude-code The mesh-builder skill enables developers to create configurable agent meshes for reproducible AI behavior with steering and guiderails, utilizing the Claude Code SDK. It benefits developers working with TX V4. Mesh Builder是一个可配置的AI代理网格，用于创建可复制的AI行为，具有Steering和GuideRails功能，使用Claude Code SDK Mesh Builderは、AIエージェントのためのSteeringとガイダレールを備えた、再現可能なAI行動を実現するためのコンフィギュラブルなエージェントメッシュです Mesh Builder는 Claude Code SDK를 사용하여 가이드레일 및 스티어링 기능을 갖춘 재현 가능한 AI 행동을 위한 구성 가능한 에이전트 메시입니다 Mesh-builder permite crear meshes personalizables para comportamientos de IA reproducibles con Claude Code SDK Mesh-builder permet de créer des meshes personnalisables pour des comportements d''IA reproductibles avec Claude Code SDK Mesh-builder ermöglicht die Erstellung von konfigurierbaren Meshes für reproduzierbare KI-Verhaltensweisen mit Claude Code SDK O Mesh Builder é uma ferramenta para criar agentes de IA com comportamento reprodutível, utilizando a filosofia de ''Earn Your Keep'' e a tecnologia Claude Code SDK. Mesh Builder - это инструмент для создания ИИ Агентов с воспроизводимым поведением, использующий философию ''Earn Your Keep'' и технологию Claude Code SDK. مشغّل الشبكة هو أداة لإنشاء وكلاء ذكاء اصطناعي مع سلوك قابل للتكرار، باستخدام فلسفة ''الاستفادة من عملك'' وتكنولوجيا Claude Code SDK. how to use mesh-builder what is mesh-builder mesh-builder alternative mesh-builder vs claude code mesh-builder install mesh-builder setup guide configurable agent meshes reproducible AI behavior TX V4 integration Mesh Builder AI代理网格 可复制的AI行为 Steering和GuideRails Claude Code SDK AI开发 AI工具 Configurable agent meshes for reproducible AI behavior Supports steering and guiderails for controlled workflows Utilizes Claude Code SDK for seamless integration Follows a core philosophy of minimal complexity, adding only necessary config options Includes a default question for each field to ensure simplicity Supports dev_mode for end-to-end testing of new meshes mesh-builder is a configurable agent mesh skill for building reproducible AI behavior with steering and guiderails, following a core philosophy of minimal complexity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('matsuni-kk/agent_template_public/skeleton-generate', 'community', 'matsuni-kk', 'agent_template_public', 'matsuni-kk/agent_template_public', 'skeleton-generate', 9, 7, 60, '2026-01-24T14:06:21Z', '2026-03-06T06:47:43.891Z', '3e865423e60feb5d449da6b1828fc8c53eb998065e24faa41c6128ce75956d22', '{"id":"matsuni-kk/agent_template_public/skeleton-generate","name":"skeleton-generate","description":{"en":"skeleton-generate is a framework for generating domain-specific agent templates. It benefits developers by providing a structured approach to creating AI agents","zh":"Skeleton Generate是一个AIエージェント模板框架，用于生成域特定的AIエージェント，包括CLAUDE.md和.cursor/skills/目录","ja":"スケルトン生成は、ドメイン特定のAIエージェントを生成するためのエージェントテンプレートフレームワークです","ko":"스켈레톤 생성은 도메인 특정 AI 에이전트를 생성하기 위한 에이전트 템플릿 프레임워크입니다","es":"skeleton-generate es un workflow de CLI que automatiza la creación de agentes de IA específicos de dominio. Genera estructura de directorios completa con CLAUDE.md, configuración de .cursor/skills y valida requisitos mediante draft_requirements.md.","fr":"skeleton-generate est un workflow CLI automatisant la création d''agents IA spécialisés. Génère une structure de répertoires complète avec CLAUDE.md, configuration .cursor/skills et valide les exigences via draft_requirements.md.","de":"skeleton-generate ist ein CLI-Workflow zur Automatisierung der Erstellung domänenspezifischer KI-Agenten. Erzeugt vollständige Verzeichnisstruktur mit CLAUDE.md, .cursor/skills Konfiguration und validiert Anforderungen über draft_requirements.md.","pt":"O Skeleton Generate é um framework de modelo de agente para geração de agentes de IA específicos de domínio. Ele gera um diretório de saída personalizado com CLAUDE.md, .cursor/skills/ e .codex/","ru":"Skeleton Generate - это шаблонный фреймворк для создания ИИ Агентов для конкретных областей. Он генерирует настраиваемый выходной каталог с CLAUDE.md, .cursor/skills/ и .codex/","ar":"الهيكل العظمي هو إطار عمل لنمذجة العامل لإنشاء عوامل ذكية محددة المجال. أنه يولد دليل مخصص لخرج مع CLAUDE.md و .cursor/skills/ و .codex/"},"seo":{"title":{"en":"skeleton-generate: Agent Template Framework Setup Guide |...","zh":"Skeleton Generate 工作流程设置指南 - AIエージェント骨格生成","ja":"スケルトン生成ワークフロー設定ガイド - AIエージェント骨格生成","ko":"스켈레톤 생성 워크플로우 설정 가이드 - AI 에이전트 골격 생성","es":"Guía de skeleton-generate: Framework para Agentes de IA E...","fr":"Guide skeleton-generate : Framework de Génération d''Agent...","de":"skeleton-generate Leitfaden: Framework für Domain-spezifi...","pt":"Guia de Configuração do Skeleton Generate para Agentes de IA","ru":"Настройка ИИ Агентов с помощью Skeleton Generate","ar":"دليل إعداد الهيكل العظمي لتحليل العوامل الذكية"},"description":{"en":"Discover how to generate domain-specific agents with skeleton-generate. Learn to set up and use this powerful framework for AI agent development","zh":"了解如何使用Skeleton Generate工作流程创建域特定AIエージェント，包括CLAUDE.md和.cursor/skills/目录","ja":"スケルトン生成ワークフローを使用してドメイン特定のAIエージェントを生成する方法について学びます","ko":"스켈레톤 생성 워크플로우를 사용하여 도메인 특정 AI 에이전트를 생성하는 방법을 알아보세요","es":"Genera esqueletos de agentes de IA específicos de dominio con CLI y patrones predefinidos. Incluye CLAUDE.md, .cursor/skills y checklist de preflight.","fr":"Générez des squelettes d''agents IA spécialisés avec CLI et modèles prédéfinis. Inclut CLAUDE.md, .cursor/skills et checklist de pré-vérification.","de":"Erstellen Sie Skelette für domänenspezifische KI-Agenten mit CLI und vordefinierten Patterns. Enthält CLAUDE.md, .cursor/skills und Preflight-Checkliste.","pt":"Aprenda a configurar o Skeleton Generate para criar agentes de IA personalizados com nosso guia passo a passo","ru":"Откройте для себя, как настроить Skeleton Generate для создания индивидуальных ИИ Агентов с нашей пошаговой инструкцией","ar":"تعرف على كيفية إعداد الهيكل العظمي لإنشاء عوامل ذكية مخصصة باستخدام دليلنا التفصيلي"},"definition":{"en":"skeleton-generate is an agent template framework for domain-specific agent generation, producing output directories with CLAUDE.md, .cursor/skills/, and .codex/","zh":"Skeleton Generate是一种用于生成AIエージェント骨格的工作流程，输出域特定的AIエージェント目录","ja":"スケルトン生成は、ドメイン特定のAIエージェントを生成するためのワークフローです","ko":"스켈레톤 생성은 도메인 특정 AI 에이전트를 생성하기 위한 워크플로우입니다","es":"skeleton-generate es un framework técnico para generar agentes de IA específicos de dominio. Automatiza la creación de estructuras de directorios completas con documentación CLAUDE.md, configuración de herramientas .cursor/skills y validación de requisitos previos mediante checklist.","fr":"skeleton-generate est un framework technique pour générer des agents IA spécialisés. Automatise la création de structures de répertoires complètes avec documentation CLAUDE.md, configuration d''outils .cursor/skills et validation préalable des exigences via checklist.","de":"skeleton-generate ist ein technisches Framework zur Generierung domänenspezifischer KI-Agenten. Automatisiert die Erstellung vollständiger Verzeichnisstrukturen mit CLAUDE.md-Dokumentation, .cursor/skills Tool-Konfiguration und Preflight-Anforderungsvalidierung via Checkliste.","pt":"O que é Skeleton Generate? É um framework de agente de IA para geração de agentes personalizados","ru":"Что такое Skeleton Generate? Это фреймворк ИИ Агентов для создания индивидуальных агентов","ar":"ما هو الهيكل العظمي؟ إنه إطار عمل لعوامل الذكاء الاصطناعي لإنشاء عوامل مخصصة"},"features":{"en":["Generates output directories with CLAUDE.md, .cursor/skills/, and .codex/","Supports preflight checks using generate_checklist.md","Requires draft_requirements.md for domain name, agent display name, and description","Uses directory patterns such as Business, Coding, Data, DevOps, and Minimal","Checks for framework_research.md and user approval before generation"],"zh":["支持域特定的AIエージェント生成","包括CLAUDE.md和.cursor/skills/目录","具有Preflight检查功能","支持draft_requirements.md文件","具有framework_research.md文件检查功能"],"ja":["ドメイン特定のAIエージェントを生成する","CLAUDE.mdと.cursor/skills/ディレクトリを含む","Preflight確認機能を備える","draft_requirements.mdファイルをサポートする","framework_research.mdファイルの確認機能を備える"],"ko":["도메인 특정 AI 에이전트를 생성하는 기능","CLAUDE.md와 .cursor/skills/ 디렉토리를 포함","Preflight 확인 기능","draft_requirements.md 파일 지원","framework_research.md 파일 확인 기능"],"es":["Generación automática de estructura output/{domain}_agent/ con CLAUDE.md y .codex/","Soporte para patrones predefinidos: Business, Coding, Data, DevOps, Minimal","Validación preflight con generate_checklist.md y draft_requirements.md","Requisito de framework_research_done=true antes de la generación","Integración nativa con herramientas .cursor/skills para desarrollo","Validación de aprobación de usuario para requisitos de dominio"],"fr":["Génération automatique de structure output/{domain}_agent/ avec CLAUDE.md et .codex/","Support des modèles prédéfinis : Business, Coding, Data, DevOps, Minimal","Validation pré-vérification avec generate_checklist.md et draft_requirements.md","Exigence framework_research_done=true avant génération","Intégration native avec outils .cursor/skills pour développement","Validation d''approbation utilisateur pour exigences de domaine"],"de":["Automatische Generierung der output/{domain}_agent/ Struktur mit CLAUDE.md und .codex/","Unterstützung für vordefinierte Patterns: Business, Coding, Data, DevOps, Minimal","Preflight-Validierung mit generate_checklist.md und draft_requirements.md","Voraussetzung framework_research_done=true vor der Generierung","Native Integration mit .cursor/skills Tools für Entwicklung","Benutzerfreigabe-Validierung für Domänenanforderungen"],"pt":["Geração de diretório de saída personalizado","Suporte a padrões de diretório (Business, Coding, Data, DevOps, Minimal)","Verificação de pré-voo com checklist","Geração de CLAUDE.md e .cursor/skills/","Integração com framework_research.md"],"ru":["Генерация настраиваемого выходного каталога","Поддержка шаблонов каталогов (Business, Coding, Data, DevOps, Minimal)","Предполётная проверка с чек-листом","Генерация CLAUDE.md и .cursor/skills/","Интеграция с framework_research.md"],"ar":["توليد دليل مخصص لخرج","دعم أنماط الدلائل (Business و Coding و Data و DevOps و Minimal)","فحص ما قبل الطيران مع قائمة التحقق","توليد CLAUDE.md و .cursor/skills/","التكامل مع framework_research.md"]},"keywords":{"en":["how to use skeleton-generate","skeleton-generate setup guide","skeleton-generate alternative","skeleton-generate vs other frameworks","what is skeleton-generate","skeleton-generate install","domain-specific agent generation","AI agent template framework"],"zh":["AIエージェント骨格生成","Skeleton Generate","域特定AIエージェント","CLAUDE.md","cursor/skills/","Preflight检查","draft_requirements.md","framework_research.md"],"ja":["AIエージェント骨格生成","スケルトン生成","ドメイン特定AIエージェント","CLAUDE.md","cursor/skills/","Preflight確認","draft_requirements.md","framework_research.md"],"ko":["AI 에이전트 골격 생성","스켈레톤 생성","도메인 특정 AI 에이전트","CLAUDE.md",".cursor/skills/","Preflight 확인","draft_requirements.md","framework_research.md"],"es":["skeleton-generate CLI","agentes de IA específicos de dominio","generación esqueleto agente IA","CLAUDE.md template",".cursor/skills configuración","workflow preflight checklist","framework agentes IA","automatización desarrollo agentes","draft_requirements.md validación"],"fr":["skeleton-generate CLI","agents IA spécialisés domaine","génération squelette agent IA","template CLAUDE.md","configuration .cursor/skills","workflow checklist pré-vérification","framework agents IA","automatisation développement agents","validation draft_requirements.md"],"de":["skeleton-generate CLI","domänenspezifische KI-Agenten","KI-Agenten Skelettgenerierung","CLAUDE.md Vorlage",".cursor/skills Konfiguration","Preflight Checklist Workflow","KI-Agenten Framework","Agentenentwicklung Automatisierung","draft_requirements.md Validierung"],"pt":["Skeleton Generate","Agentes de IA","Geração de agentes","Framework de agente","Desenvolvimento de IA","Tecnologia de IA","Ferramentas de IA","Guia de configuração"],"ru":["Skeleton Generate","ИИ Агенты","Создание агентов","Фреймворк агентов","Разработка ИИ","Технология ИИ","Инструменты ИИ","Руководство по настройке"],"ar":["الهيكل العظمي","عوامل الذكاء الاصطناعي","إنشاء عوامل","إطار عمل العوامل","تطوير الذكاء الاصطناعي","تكنولوجيا الذكاء الاصطناعي","أدوات الذكاء الاصطناعي","دليل الإعداد"]}},"owner":"matsuni-kk","repo":"agent_template_public","repoPath":"matsuni-kk/agent_template_public","stars":9,"forks":7,"updatedAt":"2026-01-24T14:06:21Z","topics":[],"category":"community","skillMd":{"name":"skeleton-generate","description":"Skills版エージェント骨格（CLAUDE.md, .cursor/skills/, .codex/等）を生成し、初期設定を完了する。「スケルトン生成」「エージェント生成」「骨格作成」を依頼されたときに使用する。","bodyPreview":"# Skeleton Generate Workflow\n\nSkills版エージェント骨格生成ワークフロー。主成果物はoutput/{domain}_agent/ディレクトリ一式（CLAUDE.md, .cursor/skills/, .codex/含む）。\n\n## Instructions\n\n### 1. Preflight（事前確認）\n- `./assets/generate_checklist.md` を先に読み、必須項目を確認する。\n- draft_requirements.md を参照し、以下を確認する:\n  - ドメイン名（スネークケース）\n  - エージェント表示名\n  - 説明文（1-2文）\n  - 準拠フレームワーク\n  - **ディレクトリパターン（Business/Coding/Data/DevOps/Minimal）**\n- framework_research.md が存在し、framework_research_done=true が記録されているか確認する。\n- **要件定義へのユーザー承認が得られているか確認する。未承認なら生成しない。**\n- outp","body":"# Skeleton Generate Workflow\n\nSkills版エージェント骨格生成ワークフロー。主成果物はoutput/{domain}_agent/ディレクトリ一式（CLAUDE.md, .cursor/skills/, .codex/含む）。\n\n## Instructions\n\n### 1. Preflight（事前確認）\n- `./assets/generate_checklist.md` を先に読み、必須項目を確認する。\n- draft_requirements.md を参照し、以下を確認する:\n  - ドメイン名（スネークケース）\n  - エージェント表示名\n  - 説明文（1-2文）\n  - 準拠フレームワーク\n  - **ディレクトリパターン（Business/Coding/Data/DevOps/Minimal）**\n- framework_research.md が存在し、framework_research_done=true が記録されているか確認する。\n- **要件定義へのユーザー承認が得られているか確認する。未承認なら生成しない。**\n- output/配下に同名エージェントが存在しないか確認する。\n\n### 2. ディレクトリパターン選択\n- `./assets/directory_patterns.md` を参照し、用途に応じたパターンを選択する:\n  - **Business**: Flow/Stock/Archived（ビジネス/ドキュメント管理）\n  - **Coding**: src/tests/docs（ソフトウェア開発）\n  - **Data**: data/notebooks/src/models（データ分析/ML）\n  - **DevOps**: infra/scripts/configs（インフラ/運用）\n  - **Minimal**: src/scripts（最小構成）\n- ユーザーに確認し、パターンを確定する。\n\n### 3. ディレクトリ構造生成\n- 選択したパターンに応じてディレクトリを作成する。\n- 共通構造（全パターン必須）:\n  ```bash\n  mkdir -p output/{domain}_agent/.claude/{skills,agents,commands}\n  mkdir -p output/{domain}_agent/.codex/{skills,agents,prompts}\n  mkdir -p output/{domain}_agent/.cursor/rules\n  mkdir -p output/{domain}_agent/.github/{skills,prompts}\n  mkdir -p output/{domain}_agent/.gemini\n  mkdir -p output/{domain}_agent/.kiro/steering\n  mkdir -p output/{domain}_agent/scripts\n  ```\n- パターン別構造を追加（例: Business）:\n  ```bash\n  mkdir -p output/{domain}_agent/Flow\n  mkdir -p output/{domain}_agent/Stock/programs/core/{documents,images}\n  mkdir -p output/{domain}_agent/Archived\n  ```\n- 空ディレクトリに .gitkeep を配置する。\n\n### 4. マスターファイル生成\n- `./assets/claude_md_template.md` を使用して以下を生成する（テンプレートにはWF自動継続/テンプレートファースト/Next Action triggers参照ルールを含める）:\n  1. `CLAUDE.md` - プレースホルダを置換して生成\n  2. `AGENTS.md` - CLAUDE.mdと同内容\n  3. `.github/copilot-instructions.md` - CLAUDE.mdと同内容\n  4. `.gemini/GEMINI.md` - CLAUDE.mdと同内容\n  5. `.kiro/steering/KIRO.md` - CLAUDE.mdと同内容\n- `./assets/readme_template.md` を使用して `README.md` を生成する。\n- 元資料にない項目は省略せず「未記載」と明記する。\n\n### 5. スクリプト・共通Skillsコピー\n- `./assets/common_skills_template.md` に従い、以下をコピーする:\n  ```bash\n  # スクリプト\n  cp scripts/validate_skills.py output/{domain}_agent/scripts/\n  cp scripts/update_agent_master.py output/{domain}_agent/scripts/\n\n  # 共通Skills（必須）\n  cp -r .cursor/skills/skill-maintenance output/{domain}_agent/.cursor/skills/\n  cp -r .cursor/skills/subagent-maintenance output/{domain}_agent/.cursor/skills/\n\n  # 共通サブエージェント（推奨）\n  cp .claude/agents/skill-builder.md output/{domain}_agent/.claude/agents/\n  cp .claude/agents/skill-validator.md output/{domain}_agent/.claude/agents/\n  cp .claude/agents/qa-skill-qc.md output/{domain}_agent/.claude/agents/\n  cp .codex/agents/qa-skill-qc.md output/{domain}_agent/.codex/agents/\n  cp .claude/agents/qa-skeleton-generate.md output/{domain}_agent/.claude/agents/\n  ```\n\n### 6. 初期Skills準備\n- domain-skills-generate へ進む準備をする。\n- ドメイン固有のSkillsは次工程で作成。\n\n### 7. QC（必須）\n- `recommended_subagents` のQC Subagent（`qa-skill-qc`）に評価を委譲する。\n- Subagentは `./evaluation/skeleton_criteria.md` をReadし、QCを実施する。\n- 指摘を最小差分で反映する（最大3回）。\n- 指摘に対し「修正した/しない」と理由を成果物に残す。\n\n### 8. バックログ反映\n- 次アクション（Skills作成、バリデーション）をタスクリストへ追記する。\n- 生成完了を記録する。\n\nsubagent_policy:\n  - 品質ループ（QC/チェック/フィードバック）は必ずサブエージェントへ委譲する\n  - サブエージェントの指摘を反映し、反映結果（修正有無/理由）を成果物に残す\n\nrecommended_subagents:\n  - qa-skill-qc: ディレクトリ構造、CLAUDE.md、マルチプラットフォームファイル、スクリプト配置を検査\n\n## Resources\n- assets: ./assets/generate_checklist.md\n- assets: ./assets/directory_patterns.md\n- assets: ./assets/common_skills_template.md\n- assets: ./assets/claude_md_template.md\n- assets: ./assets/skills_structure_template.md\n- assets: ./assets/readme_template.md\n- evaluation: ./evaluation/skeleton_criteria.md\n- scripts: scripts/validate_skills.py\n- scripts: scripts/update_agent_master.py\n- triggers: ./triggers/next_action_triggers.md\n\n## Next Action\n- triggers: ./triggers/next_action_triggers.md\n\n起動条件に従い、条件を満たすSkillを自動実行する。\n"},"lastSynced":"2026-03-06T06:47:43.891Z","agentAnalysis":{"suitability":{"en":"Essential for Agent Development Platforms needing structured domain-specific template generation.","zh":"适用于需要结构化领域特定模板生成的Agent开发平台。","ja":"構造化されたドメイン固有のテンプレート生成を必要とするエージェント開発プラットフォームに適しています。","ko":"구조화된 도메인 특정 템플릿 생성이 필요한 에이전트 개발 플랫폼에 적합합니다.","es":"Esencial para plataformas de desarrollo de agentes que necesitan generación de plantillas específicas del dominio estructuradas.","fr":"Essentiel pour les plateformes de développement d''agents nécessitant une génération de modèles spécifiques au domaine structurés.","de":"Wesentlich für Agent-Entwicklungsplattformen, die eine strukturierte generierung von domänenspezifischen Vorlagen benötigen.","pt":"Essencial para Plataformas de Desenvolvimento de Agentes que necessitam de geração de modelos específicos de domínio estruturados.","ru":"Необходимо для Платформ Разработки Агентов, требующих структурированной области-специфической генерации шаблонов.","ar":"الأساسي لمنصات تطوير الوكيل التي تحتاج إلى توليد قوالب محددة لمنطقة معينة بشكل منظم."},"recommendation":{"en":"Generates complete agent skeleton directories including CLAUDE.md, .cursor/skills/, and .codex/ folders with framework-specific patterns. Requires preflight validation through generate_checklist.md and user-approved draft_requirements.md before execution.","zh":"生成包含CLAUDE.md、.cursor/skills/和.codex/文件夹的完整agent骨架目录，使用框架特定的模式。执行前需要通过generate_checklist.md进行预检验证，并需要用户批准draft_requirements.md。","ja":"CLAUDE.md、.cursor/skills/、.codex/フォルダを含む完全なエージェントスケルトンディレクトリを生成し、フレームワーク固有のパターンを使用します。generate_checklist.mdを介した事前検証と、ユーザーが承認したdraft_requirements.mdが必要です。","ko":"CLAUDE.md, .cursor/skills/, .codex/ 폴더를 포함하는 완전한 에이전트 스켈레톤 디렉토리를 생성하며, 프레임워크 특정 패턴을 사용합니다. generate_checklist.md를 통해 사전 검증을 수행하고, 사용자가 승인한 draft_requirements.md가 필요합니다.","es":"Genera directorios de esqueleto de agente completos, incluyendo carpetas CLAUDE.md, .cursor/skills/ y .codex/ con patrones específicos del framework. Requiere validación previa a través de generate_checklist.md y draft_requirements.md aprobados por el usuario antes de la ejecución.","fr":"Génère des répertoires de squelette d''agent complets, incluant des dossiers CLAUDE.md, .cursor/skills/ et .codex/ avec des modèles spécifiques au framework. Nécessite une validation préalable via generate_checklist.md et draft_requirements.md approuvés par l''utilisateur avant l''exécution.","de":"Generiert vollständige Agenten-Skelett-Verzeichnisse, einschließlich CLAUDE.md, .cursor/skills/ und .codex/-Ordnern mit framework-spezifischen Mustern. Erfordert eine Vorabvalidierung durch generate_checklist.md und user-genehmigte draft_requirements.md vor der Ausführung.","pt":"Gera diretórios de esqueleto de agente completos, incluindo pastas CLAUDE.md, .cursor/skills/, e .codex/ com padrões específicos do framework. Requer validação prévia por meio de generate_checklist.md e draft_requirements.md aprovado pelo usuário antes da execução.","ru":"Генерирует полные скелетные директории агентов, включая папки CLAUDE.md, .cursor/skills/, и .codex/ с шаблонами, специфичными для фреймворка. Требует предварительной проверки через generate_checklist.md и черновик требований, одобренный пользователем, до выполнения.","ar":"يتوليد مجلدات هيكل وكيل كاملة، بما في ذلك مجلدات CLAUDE.md، .cursor/skills/، و .codex/ بأطر عمل محددة. يتطلب التحقق المسبق من خلال generate_checklist.md و مشروع متطلبات موافق عليه من قبل المستخدم قبل التنفيذ."},"useCases":{"en":["Generating Business/Coding/Data/DevOps/Minimal agent directory patterns","Validating framework requirements through framework_research.md","Creating structured output/{domain}_agent/ directory structures"],"zh":["生成Business/Coding/Data/DevOps/Minimal agent目录模式","通过framework_research.md验证框架要求","创建结构化输出/{domain}_agent/目录结构"],"ja":["Business/Coding/Data/DevOps/Minimalエージェントディレクトリパターンを生成する","framework_research.mdを介したフレームワーク要件の検証","構造化された出力/{domain}_agent/ディレクトリ構造を作成する"],"ko":["Business/Coding/Data/DevOps/Minimal 에이전트 디렉토리 패턴을 생성합니다","framework_research.md를 통해 프레임워크 요구 사항을 검증합니다","구조화된 출력/{domain}_agent/ 디렉토리 구조를 생성합니다"],"es":["Generación de patrones de directorios de agente de negocio/codificación/datos/DevOps/mínimo","Validación de los requisitos del framework a través de framework_research.md","Creación de estructuras de directorios de salida/{dominio}_agente/ estructuradas"],"fr":["Génération de modèles de répertoires d''agent métier/codage/données/DevOps/minimal","Validation des exigences du framework via framework_research.md","Création de structures de répertoires de sortie/{domaine}_agent/ structurées"],"de":["Generierung von Agenten-Verzeichnismustern für Geschäft/Codierung/Daten/DevOps/Minimal","Validierung der Framework-Anforderungen durch framework_research.md","Erstellung von strukturierten Ausgabe-Verzeichnisstrukturen/{domäne}_agent/"],"pt":["Gerar padrões de diretórios de agente de Negócios/Codificação/Dados/DevOps/Minimais","Validar requisitos de framework por meio de framework_research.md","Criar estruturas de diretórios de saída/{domínio}_agente/ estruturadas"],"ru":["Генерировать шаблоны директорий агентов Бизнес/Кодирование/Данных/DevOps/Минимальных","Проверять требования фреймворка через framework_research.md","Создавать структуры выходных директорий/{домен}_агент/ структурированных"],"ar":["توليد أنماط مجلدات وكيل الأعمال/التدوين/البيانات/DevOps/الحد الأدنى","التحقق من متطلبات الإطار من خلال framework_research.md","إنشاء هياكل مجلدات الإخراج/{نطاق}_وكيل/ المنظمة"]},"limitations":{"en":["Requires user approval of draft_requirements.md before generation","Depends on framework_research_done=true flag","Needs preflight checklist completion"],"zh":["需要用户批准draft_requirements.md才能生成","依赖于framework_research_done=true标志","需要完成预检清单"],"ja":["生成する前にdraft_requirements.mdのユーザー承認が必要です","framework_research_done=trueフラグに依存しています","事前チェックリストの完了が必要です"],"ko":["생성하기 전에 draft_requirements.md의 사용자 승인이 필요합니다","framework_research_done=true 플래그에 종속됩니다","사전 체크리스트 완성이 필요합니다"],"es":["Requiere aprobación del usuario de draft_requirements.md antes de la generación","Depende de la marca framework_research_done=true","Necesita la finalización de la lista de verificación previa a la ejecución"],"fr":["Nécessite l''approbation de l''utilisateur de draft_requirements.md avant la génération","Dépend du flag framework_research_done=true","Nécessite l''achèvement de la liste de vérification préalable"],"de":["Erfordert die Genehmigung des Benutzers von draft_requirements.md vor der Generierung","Hängt von der Markierung framework_research_done=true ab","Benötigt die Vervollständigung der Vorab-Checkliste"],"pt":["Requer aprovação do usuário do draft_requirements.md antes da geração","Depende da flag framework_research_done=true","Precisa da conclusão da lista de verificação prévia"],"ru":["Требует одобрения пользователя черновика требований перед генерацией","Зависит от флага framework_research_done=true","Требует завершения предварительной проверки"],"ar":["يتطلب موافقة المستخدم على مشروع متطلبات قبل التوليد","يعتمد على علامة framework_research_done=true","يحتاج إلى إكمال قائمة التحقق المسبقة"]},"version":4},"contentHash":"3e865423e60feb5d449da6b1828fc8c53eb998065e24faa41c6128ce75956d22","qualityScore":60}');
