INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('matsuni-kk/agent_template_public/skeleton-generate', 'skeleton-generate', 'matsuni-kk', 'agent_template_public', 'community', 'skeleton-generate matsuni-kk agent_template_public community skeleton-generate is a framework for generating domain-specific agent templates. It benefits developers by providing a structured approach to creating AI agents Skeleton Generate是一个AIエージェント模板框架，用于生成域特定的AIエージェント，包括CLAUDE.md和.cursor/skills/目录 スケルトン生成は、ドメイン特定のAIエージェントを生成するためのエージェントテンプレートフレームワークです 스켈레톤 생성은 도메인 특정 AI 에이전트를 생성하기 위한 에이전트 템플릿 프레임워크입니다 skeleton-generate es un workflow de CLI que automatiza la creación de agentes de IA específicos de dominio. Genera estructura de directorios completa con CLAUDE.md, configuración de .cursor/skills y valida requisitos mediante draft_requirements.md. skeleton-generate est un workflow CLI automatisant la création d''agents IA spécialisés. Génère une structure de répertoires complète avec CLAUDE.md, configuration .cursor/skills et valide les exigences via draft_requirements.md. skeleton-generate ist ein CLI-Workflow zur Automatisierung der Erstellung domänenspezifischer KI-Agenten. Erzeugt vollständige Verzeichnisstruktur mit CLAUDE.md, .cursor/skills Konfiguration und validiert Anforderungen über draft_requirements.md. O Skeleton Generate é um framework de modelo de agente para geração de agentes de IA específicos de domínio. Ele gera um diretório de saída personalizado com CLAUDE.md, .cursor/skills/ e .codex/ Skeleton Generate - это шаблонный фреймворк для создания ИИ Агентов для конкретных областей. Он генерирует настраиваемый выходной каталог с CLAUDE.md, .cursor/skills/ и .codex/ الهيكل العظمي هو إطار عمل لنمذجة العامل لإنشاء عوامل ذكية محددة المجال. أنه يولد دليل مخصص لخرج مع CLAUDE.md و .cursor/skills/ و .codex/ how to use skeleton-generate skeleton-generate setup guide skeleton-generate alternative skeleton-generate vs other frameworks what is skeleton-generate skeleton-generate install domain-specific agent generation AI agent template framework AIエージェント骨格生成 Skeleton Generate 域特定AIエージェント CLAUDE.md cursor/skills/ Preflight检查 draft_requirements.md framework_research.md Generates output directories with CLAUDE.md, .cursor/skills/, and .codex/ Supports preflight checks using generate_checklist.md Requires draft_requirements.md for domain name, agent display name, and description Uses directory patterns such as Business, Coding, Data, DevOps, and Minimal Checks for framework_research.md and user approval before generation skeleton-generate is an agent template framework for domain-specific agent generation, producing output directories with CLAUDE.md, .cursor/skills/, and .codex/');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('niznik-dev/cruijff_kit/summarize-experiment', 'community', 'niznik-dev', 'cruijff_kit', 'niznik-dev/cruijff_kit', 'summarize-experiment', 9, 0, 60, '2026-02-27T22:31:04Z', '2026-03-06T06:47:55.064Z', 'e35305f77cbcb8a4e80640bd886b09592e3506dd2c5aed0fbd7703f2fd75681e', '{"id":"niznik-dev/cruijff_kit/summarize-experiment","name":"summarize-experiment","description":{"en":"The summarize-experiment skill generates a summary.md file capturing key metrics from completed experiments, benefiting AI researchers and developers. It automates the process of parsing run status, extracting training loss and accuracy, and logging the process.","zh":"summarize-experiment 是一个专门用于AI实验后处理的工具，能够自动解析实验状态文件，提取关键训练指标如最终损失和准确率，并生成结构化的实验总结报告。","ja":"summarize-experiment は、AI実験の後処理専用ツールです。実験ステータスファイルの自動解析、最終損失や精度などの主要トレーニング指標の抽出、構造化された実験サマリーレポートの生成を行います。","ko":"summarize-experiment은 AI 실험 후처리를 위한 전문 도구입니다. 실험 상태 파일 자동 파싱, 최종 손실 및 정확도 같은 주요 훈련 지표 추출, 구조화된 실험 요약 보고서 생성을 수행합니다.","es":"Summarize-experiment es una herramienta para generar resúmenes de experimentos de investigación social con LLMs, permitiendo el análisis de métricas clave como la pérdida de entrenamiento y la precisión","fr":"Summarize-experiment est un outil pour générer des résumés d''expériences de recherche sociale avec LLMs, permettant l''analyse de métriques clés comme la perte d''entraînement et la précision","de":"Summarize-experiment ist ein Tool zur Erstellung von Zusammenfassungen von Experimenten zur sozialen Forschung mit LLMs, ermöglicht die Analyse von Schlüsselmetriken wie Trainingsverlust und Genauigkeit","pt":"O Summarize Experiment é uma ferramenta para gerar resumos de experimentos de pesquisa social com LLMs, incluindo parse de status de execução e extração de métricas de treinamento","ru":"Summarize Experiment - это инструмент для создания сводок экспериментов социальных исследований с ИИ Агентами, включая парсинг статуса выполнения и извлечение метрик обучения","ar":"تجربة تلخيص هي أداة لإنشاء ملخصات تجارب بحث اجتماعي بالذكاء الاصطناعي، بما في ذلك تحليل حالة التشغيل واستخراج مقاييس التدريب"},"seo":{"title":{"en":"summarize-experiment: Automated Experiment Summarization ...","zh":"summarize-experiment 设置指南：AI实验总结工具","ja":"summarize-experiment セットアップガイド：AIエージェント実験サマリー","ko":"summarize-experiment 설정 가이드: AI 에이전트 실험 요약","es":"Guía de configuración de summarize-experiment para herram...","fr":"Guide de configuration de summarize-experiment pour les o...","de":"Konfigurationsleitfaden für summarize-experiment zur sozi...","pt":"Guia de Configuração do Summarize Experiment para Ferrame...","ru":"Руководство по настройке Summarize Experiment для социаль...","ar":"دليل إعداد تجربة تلخيص للأدوات الاجتماعية بالذكاء الاصطناعي"},"description":{"en":"Discover how to streamline experiment analysis with summarize-experiment. Learn to generate summary.md files and log processes with ease. Get started now!","zh":"专为AI实验设计的自动化总结工具。解析experiment_summary.yaml状态，提取SLURM stdout最终训练损失和inspect-ai评估文件准确率，生成summary.md报告并记录日志。","ja":"AI実験向け自動サマリーツール。experiment_summary.yamlのステータス解析、SLURM stdoutからの最終トレーニング損失とinspect-ai評価ファイルの精度抽出、summary.mdレポート生成とログ記録を実行。","ko":"AI 실험을 위한 자동화된 요약 도구입니다. experiment_summary.yaml 상태 파싱, SLURM stdout의 최종 훈련 손실 및 inspect-ai 평가 파일 정확도 추출, summary.md 보고서 생성 및 로깅을 수행합니다.","es":"Aprende a utilizar summarize-experiment para generar resúmenes de experimentos de investigación social con LLMs y mejora tus análisis de datos","fr":"Découvrez comment utiliser summarize-experiment pour générer des résumés d''expériences de recherche sociale avec LLMs et améliorer vos analyses de données","de":"Erfahren Sie, wie Sie summarize-experiment verwenden, um Zusammenfassungen von Experimenten zur sozialen Forschung mit LLMs zu erstellen und Ihre Datenanalys...","pt":"Aprenda a usar o Summarize Experiment para gerar resumos de experimentos de pesquisa social com LLMs e melhore seus resultados","ru":"Узнайте, как использовать Summarize Experiment для создания сводок экспериментов социальных исследований с ИИ Агентами","ar":"تعرف على كيفية استخدام تجربة تلخيص لإنشاء ملخصات تجارب بحث اجتماعي بالذكاء الاصطناعي"},"definition":{"en":"summarize-experiment is a tool for conducting social research with LLMs, generating lightweight summaries of experiment results in a summary.md file","zh":"summarize-experiment 是一个命令行工具，用于自动化生成AI实验结果的轻量级摘要。它类似于R语言的summary()函数，专门处理实验元数据、训练日志和评估输出，生成统一的总结文档。","ja":"summarize-experiment は、AI実験結果の軽量なサマリーを自動生成するCLIツールです。R言語のsummary()関数に似ており、実験メタデータ、トレーニングログ、評価出力を処理し、統一されたサマリードキュメントを生成します。","ko":"summarize-experiment은 AI 실험 결과의 경량 요약을 자동 생성하는 CLI 도구입니다. R 언어의 summary() 함수와 유사하며, 실험 메타데이터, 훈련 로그, 평가 출력을 처리하여 통합된 요약 문서를 생성합니다.","es":"Summarize-experiment es una herramienta de investigación social que genera resúmenes de experimentos con LLMs","fr":"Summarize-experiment est un outil de recherche sociale qui génère des résumés d''expériences avec LLMs","de":"Summarize-experiment ist ein Tool für soziale Forschung, das Zusammenfassungen von Experimenten mit LLMs erstellt","pt":"O Summarize Experiment é uma ferramenta de pesquisa social que gera resumos de experimentos com LLMs","ru":"Summarize Experiment - это инструмент социальных исследований, создающий сводки экспериментов с ИИ Агентами","ar":"تجربة تلخيص هي أداة بحث اجتماعي توليد ملخصات تجارب بالذكاء الاصطناعي"},"features":{"en":["Parses run status from experiment_summary.yaml files","Extracts final training loss from SLURM stdout","Extracts accuracy from inspect-ai .eval files","Generates summary.md files in the experiment directory","Logs the process in logs/summarize-experiment.log"],"zh":["解析 experiment_summary.yaml 文件中的实验运行状态","从 SLURM stdout 日志中提取最终训练损失值","从 inspect-ai .eval 文件中提取准确率指标","在实验目录中生成标准的 summary.md 总结报告","在 logs/summarize-experiment.log 中记录完整处理日志"],"ja":["experiment_summary.yaml ファイルからの実験実行ステータス解析","SLURM stdout ログからの最終トレーニング損失値抽出","inspect-ai .eval ファイルからの精度指標抽出","実験ディレクトリへの標準 summary.md サマリーレポート生成","logs/summarize-experiment.log への完全な処理ログ記録"],"ko":["experiment_summary.yaml 파일에서 실험 실행 상태 파싱","SLURM stdout 로그에서 최종 훈련 손실 값 추출","inspect-ai .eval 파일에서 정확도 지표 추출","실험 디렉토리에 표준 summary.md 요약 보고서 생성","logs/summarize-experiment.log에 완전한 처리 로깅"],"es":["Generación de resúmenes de experimentos en formato Markdown","Análisis de la pérdida de entrenamiento final desde SLURM stdout","Extracción de la precisión desde archivos de evaluación de inspect-ai","Registro del proceso en logs/summarize-experiment.log","Compatibilidad con archivos de configuración de experimento en YAML"],"fr":["Génération de résumés d''expériences au format Markdown","Analyse de la perte d''entraînement finale depuis SLURM stdout","Extraction de la précision depuis les fichiers d''évaluation de inspect-ai","Enregistrement du processus dans logs/summarize-experiment.log","Compatibilité avec les fichiers de configuration d''expérience au format YAML"],"de":["Erstellung von Experimentzusammenfassungen im Markdown-Format","Analyse des finalen Trainingsverlusts aus SLURM stdout","Extraktion der Genauigkeit aus inspect-ai-Bewertungsdateien","Protokollierung des Prozesses in logs/summarize-experiment.log","Unterstützung von Experimentkonfigurationsdateien im YAML-Format"],"pt":["Geração de resumos de experimentos em formato Markdown","Parse de status de execução de experimentos a partir de arquivos YAML","Extração de métricas de treinamento de modelos de LLMs","Geração de arquivos de log para acompanhamento do processo","Integração com ferramentas de análise de dados como SLURM e inspect-ai"],"ru":["Генерация сводок экспериментов в формате Markdown","Парсинг статуса выполнения экспериментов из файлов YAML","Извлечение метрик обучения моделей ИИ Агентов","Генерация файлов журнала для отслеживания процесса","Интеграция с инструментами анализа данных, такими как SLURM и inspect-ai"],"ar":["إنشاء ملخصات تجارب بالشكل Markdown","تحليل حالة التشغيل من الملفات YAML","استخراج مقاييس التدريب من نماذج الذكاء الاصطناعي","إنشاء ملفات سجل لمتابعة العملية","التكامل مع أدوات تحليل البيانات مثل SLURM و inspect-ai"]},"keywords":{"en":["how to use summarize-experiment","summarize-experiment alternative","summarize-experiment setup guide","what is summarize-experiment","summarize-experiment vs experiment tracking tools","summarize-experiment install","automated experiment summarization","LLM experiment analysis","experiment_summary.yaml parsing"],"zh":["AI实验总结工具","summarize-experiment 使用教程","SLURM stdout 解析","inspect-ai 评估文件处理","experiment_summary.yaml 解析","AI训练指标提取","机器学习实验报告","自动化实验分析"],"ja":["AIエージェント実験サマリーツール","summarize-experiment 使い方","SLURM stdout 解析","inspect-ai 評価ファイル処理","experiment_summary.yaml 解析","AIトレーニング指標抽出","機械学習実験レポート","自動実験分析"],"ko":["AI 에이전트 실험 요약 도구","summarize-experiment 사용법","SLURM stdout 파싱","inspect-ai 평가 파일 처리","experiment_summary.yaml 파싱","AI 훈련 지표 추출","머신러닝 실험 보고서","자동화 실험 분석"],"es":["herramientas de investigación social","LLMs para investigación social","análisis de métricas de experimentos","generación de resúmenes de experimentos","investigación social con LLMs","summarize-experiment"],"fr":["outils de recherche sociale","LLMs pour la recherche sociale","analyse de métriques d''expériences","génération de résumés d''expériences","recherche sociale avec LLMs","summarize-experiment"],"de":["Tools für soziale Forschung","LLMs für soziale Forschung","Analyse von Experimentmetriken","Erstellung von Experimentzusammenfassungen","soziale Forschung mit LLMs","summarize-experiment"],"pt":["Summarize Experiment","Ferramentas de pesquisa social","LLMs","Geração de resumos","Parse de status de execução","Extração de métricas de treinamento","Análise de dados","SLURM","inspect-ai"],"ru":["Summarize Experiment","Инструменты социальных исследований","ИИ Агенты","Генерация сводок","Парсинг статуса выполнения","Извлечение метрик обучения","Анализ данных","SLURM","inspect-ai"],"ar":["تجربة تلخيص","أدوات بحث اجتماعي","الذكاء الاصطناعي","إنشاء ملخصات","تحليل حالة التشغيل","استخراج مقاييس التدريب","تحليل البيانات","SLURM","inspect-ai"]}},"owner":"niznik-dev","repo":"cruijff_kit","repoPath":"niznik-dev/cruijff_kit","stars":9,"forks":0,"updatedAt":"2026-02-27T22:31:04Z","topics":[],"category":"community","skillMd":{"name":"summarize-experiment","description":"Create a lightweight summary of experiment results from a completed (fine-tuned and evaluated) experiment. Use after run-experiment to capture key metrics from the experiment in textual form.","bodyPreview":"# Summarize Experiment\n\nGenerate a `summary.md` file capturing key metrics from a completed experiment. Think R''s `summary()` for experiment results.\n\n## Your Task\n\nCreate a lightweight summary of experiment results:\n\n1. Parse run status from experiment_summary.yaml\n2. Extract final training loss from SLURM stdout\n3. Extract accuracy from inspect-ai .eval files\n4. Generate summary.md in experiment directory\n5. Log the process in logs/summarize-experiment.log\n\n## Prerequisites\n\n- experiment_summa","body":"# Summarize Experiment\n\nGenerate a `summary.md` file capturing key metrics from a completed experiment. Think R''s `summary()` for experiment results.\n\n## Your Task\n\nCreate a lightweight summary of experiment results:\n\n1. Parse run status from experiment_summary.yaml\n2. Extract final training loss from SLURM stdout\n3. Extract accuracy from inspect-ai .eval files\n4. Generate summary.md in experiment directory\n5. Log the process in logs/summarize-experiment.log\n\n## Prerequisites\n\n- experiment_summary.yaml exists\n- At least some runs have completed (partial results acceptable)\n- run-experiment has been executed (or manual SLURM jobs run)\n- **Conda environment activated** - The `parse_eval_log.py` script requires inspect-ai. Activate the conda environment from `claude.local.md` before running extraction commands.\n\n## Workflow\n\n### 1. Locate Experiment\n\nFind the experiment directory:\n- If in an experiment directory (contains experiment_summary.yaml): use current directory\n- Otherwise: ask user for path\n\n### 2. Parse Run Status\n\nRead experiment_summary.yaml to identify runs:\n\n**From `runs:` section:**\n- `name`: Run identifier\n- `type`: \"fine-tuned\" or \"control\"\n- `model`: Model name\n- `parameters`: Dict of hyperparameters (empty for control runs)\n\n**From `evaluation.matrix:` section:**\n- `run`: Run name\n- `tasks`: List of evaluation task names\n- `epochs`: List of epochs to evaluate (null for control runs)\n\n**Determine status by checking filesystem:**\n- Fine-tuning: Check for `{output_base}/ck-out-{run_name}/` and SLURM outputs\n- Evaluation: Check for `{run_dir}/eval/logs/*.eval` files\n\n### 3. Extract Training Loss\n\nFor each COMPLETED fine-tuning run:\n\n1. Find SLURM stdout in the **output directory**:\n   - Parse experiment_summary.yaml \"Output\" section for `output_dir_base`\n   - Look in: `{output_dir_base}/ck-out-{run_name}/slurm-*.out`\n   - If multiple files, use most recent by modification time\n2. Extract final loss using regex: `(\\d+)\\|(\\d+)\\|Loss: ([0-9.]+)`\n   - Pattern matches: `{epoch}|{step}|Loss: {value}`\n   - Take the LAST match to get final loss\n   - The step number (group 2) from the last match is the total training steps\n3. Record: run_name, final_loss, total_steps, epoch, step\n\n**Note:** Training SLURM outputs are in the output directory, NOT the run directory.\n\n**If SLURM stdout missing:**\n- Log warning\n- Record \"N/A\" for loss\n- Continue with other runs\n\n### 4. Extract Evaluation Accuracy\n\nFor each COMPLETED evaluation:\n\n1. Find .eval files: `{run_dir}/eval/logs/*.eval`\n2. For each .eval file, run:\n   ```bash\n   python tools/inspect/parse_eval_log.py {path}\n   ```\n3. Parse JSON output for accuracy\n4. **Map to epoch using SLURM job names** (see below)\n5. For binary tasks, also run `summary_binary.py` to get balanced accuracy and F1\n6. Record: run_name, task, epoch, accuracy, balanced_accuracy, f1, samples\n\n**Script output format:**\n```json\n{\n  \"status\": \"success\",\n  \"task\": \"capitalization\",\n  \"accuracy\": 0.85,\n  \"samples\": 100,\n  \"scorer\": \"exact_match\",\n  \"model\": \"...\"\n}\n```\n\n#### Mapping Epochs via SLURM Job Names\n\nThe `.eval` files don''t currently store epoch information directly. To reliably map each evaluation to its epoch:\n\n1. **Find SLURM output files** in the eval directory: `{run_dir}/eval/slurm-*.out`\n2. **Extract job IDs** from filenames (e.g., `slurm-2773062.out` → job ID 2773062)\n3. **Query job names via sacct:**\n   ```bash\n   sacct -j {job_ids} --format=JobID,JobName%50\n   ```\n4. **Parse epoch from job name** - scaffold-inspect names jobs like `eval-{task}-{run}-ep{N}`:\n   - `eval-general_eval-lowlr-ep0` → epoch 0\n   - `eval-general_eval-lowlr-ep9` → epoch 9\n5. **Extract accuracy from SLURM output:**\n   ```bash\n   grep -oP ''match/accuracy: \\K[0-9.]+'' slurm-{jobid}.out\n   ```\n\n**Example workflow:**\n```bash\n# Get job names for all eval jobs\nsacct -j 2773062,2773063,2773065 --format=JobID,JobName%50\n\n# Output shows epoch in job name:\n# 2773062  eval-general_eval-lowlr-ep0\n# 2773063  eval-general_eval-lowlr-ep1\n# 2773065  eval-general_eval-lowlr-ep2\n```\n\nThis approach is reliable because:\n- Job names are set by scaffold-inspect and include epoch info\n- Works regardless of submission order or timing\n- Survives job failures and resubmissions\n\n**If extraction fails:**\n- Script returns `{\"status\": \"error\", \"message\": \"...\"}`\n- Log the error\n- Record \"ERROR\" for accuracy\n- Continue with other evaluations\n\n#### Computing Balanced Accuracy and F1 (Binary Classification)\n\nFor binary classification tasks (0/1 targets), use `summary_binary.py` to compute additional metrics:\n\n```bash\npython tools/inspect/summary_binary.py {path_to_eval_file} --json\n```\n\n**JSON output format:**\n```json\n{\n  \"status\": \"success\",\n  \"path\": \"/path/to/file.eval\",\n  \"samples\": 100,\n  \"accuracy\": 0.85,\n  \"balanced_accuracy\": 0.83,\n  \"f1\": 0.82,\n  \"precision_1\": 0.80,\n  \"recall_1\": 0.84,\n  \"recall_0\": 0.82,\n  \"confusion_matrix\": {\"tp\": 42, \"tn\": 43, \"fp\": 7, \"fn\": 8, \"other\": 0}\n}\n```\n\n**Why these metrics matter for imbalanced data:**\n- **Balanced Accuracy** = (Recall_0 + Recall_1) / 2 — not inflated by majority class\n- **F1 Score** = harmonic mean of precision and recall — penalizes class imbalance\n\n**Note:** For non-binary tasks, only accuracy is reported (Bal. Acc and F1 shown as \"-\").\n\n### 5. Generate summary.md\n\nCreate `{experiment_dir}/summary.md` with the following structure:\n\n```markdown\n# Experiment Summary\n\n**Experiment:** `{experiment_name}` | **Generated:** {timestamp} | **Status:** {X}/{Y} complete\n\n## Run Status\n\n| Run | Type | Fine-tuning | Evaluation |\n|-----|------|-------------|------------|\n| rank4_lr1e-5 | Fine-tuned | COMPLETED | COMPLETED |\n| rank8_lr1e-5 | Fine-tuned | COMPLETED | COMPLETED |\n| base_model | Control | N/A | COMPLETED |\n\n## Training Results\n\n| Run | Final Loss | Total Steps | Epochs | Duration |\n|-----|------------|-------------|--------|----------|\n| rank4_lr1e-5 | 0.234 | 250 | 2 | 8m 15s |\n| rank8_lr1e-5 | 0.198 | 250 | 2 | 9m 02s |\n\n**Notes:**\n- Base model runs have no training loss (control)\n- Duration from SLURM elapsed time (if available)\n\n## Evaluation Results\n\n| Run | Task | Epoch | Accuracy | Bal. Acc | F1 | Samples |\n|-----|------|-------|----------|----------|------|---------|\n| rank4_lr1e-5 | capitalization | 0 | 0.85 | 0.83 | 0.82 | 100 |\n| rank4_lr1e-5 | capitalization | 1 | 0.88 | 0.86 | 0.85 | 100 |\n| rank8_lr1e-5 | capitalization | 0 | 0.82 | 0.80 | 0.78 | 100 |\n| rank8_lr1e-5 | capitalization | 1 | 0.91 | 0.89 | 0.88 | 100 |\n| base_model | capitalization | - | 0.45 | 0.50 | 0.31 | 100 |\n\n**Best performing:** rank8_lr1e-5 (epoch 1) with 89% balanced accuracy\n\n## Incomplete Runs\n\n| Run | Stage | Status | Notes |\n|-----|-------|--------|-------|\n| rank16_lr1e-5 | Fine-tuning | FAILED | Check slurm-12345.out |\n\n## Next Steps\n\n1. View detailed evaluation results: `inspect view --port=$(get_free_port)`\n2. Export raw data: `inspect log export {run_dir}/eval/logs/*.eval --format csv`\n3. Full analysis: `analyze-experiment` (when available)\n\n---\n*Generated by summarize-experiment skill*\n```\n\n### 6. Create Log\n\nDocument the process in `{experiment_dir}/logs/summarize-experiment.log`.\n\nSee [logging.md](logging.md) for action types and format.\n\n## Error Handling\n\n### If SLURM stdout missing\n- Log warning with action type `EXTRACT_LOSS`\n- Record \"N/A\" for loss in summary\n- Continue with other runs\n\n### If .eval file cannot be parsed\n- Log error with file path\n- Record \"ERROR\" for accuracy in summary\n- Continue with other evaluations\n\n### If all runs failed\n- Generate summary noting all failures\n- Include failure states in \"Incomplete Runs\" section\n- Suggest troubleshooting steps\n\n### If partial results\n- Generate summary with available data\n- Clearly indicate which runs are missing in \"Incomplete Runs\" section\n- Still identify best performing run from available data\n\n## Idempotency\n\nRunning summarize-experiment multiple times overwrites summary.md. This is intentional:\n- Allows re-running after fixing failed runs\n- Summary always reflects current state\n\n## Output Files\n\n```\n{experiment_dir}/\n├── summary.md                    # Human-readable summary (new)\n└── logs/\n    └── summarize-experiment.log  # Process log (new)\n```\n\n## Relationship to Other Skills\n\n- **After:** run-experiment (or manual execution)\n- **Before:** analyze-experiment (when available)\n- **Optional hook:** run-experiment can invoke this at completion\n\n## Future Compatibility\n\nWhen analyze-experiment is built, summarize-experiment can either:\n- Remain as a quick summary option (text only, no plots)\n- Be deprecated in favor of richer output\n- Become a first stage that analyze-experiment builds upon\n"},"lastSynced":"2026-03-06T06:47:55.064Z","agentAnalysis":{"suitability":{"en":"Ideal for Research Agents requiring automated experiment summarization and analysis of key metrics like training loss and accuracy.","zh":"非常适合需要自动生成实验摘要并分析关键指标（如训练损失和准确率）的研究型Agent。","ja":"トレーニング損失や精度などの主要メトリクスの自動実験要約と分析を必要とするリサーチエージェントに最適です。","ko":"훈련 손실 및 정확도와 같은 주요 메트릭의 자동화된 실험 요약 및 분석이 필요한 연구 에이전트에 이상적입니다.","es":"Ideal para agentes de investigación que requieren una resumen y análisis automático de experimentos y métricas clave como pérdida de entrenamiento y precisión.","fr":"Idéal pour les agents de recherche nécessitant une automatisation de la synthèse et de l''analyse d''expériences et de métriques clés comme la perte d''entraînement et la précision.","de":"Ideal für Forschungsagenten, die eine automatisierte Zusammenfassung und Analyse von Experimenten und Schlüsselmetriken wie Trainingsverlust und Genauigkeit erfordern.","pt":"Ideal para Agentes de Pesquisa que exigem a sumarização automática de experimentos e análise de métricas-chave como perda de treinamento e precisão.","ru":"Идеально подходит для агентов-исследователей, требующих автоматизированной суммирования экспериментов и анализа ключевых метрик, таких как потеря обучения и точность.","ar":"مثالي للوكلاء البحثية التي تتطلب تلخيص التجارب التلقائي وتحليل المetrics الرئيسية مثل فقدان التدريب ودقة."},"recommendation":{"en":"Empowers agents to parse run status from YAML files, extract metrics from SLURM stdout and inspect-ai .eval files, and generate summary.md files using Markdown formatting, streamlining the experiment analysis process with logging capabilities to logs/summarize-experiment.log.","zh":"使Agent能够从YAML文件解析运行状态，从SLURM stdout和inspect-ai .eval文件提取指标，并使用Markdown格式生成summary.md文件，通过记录到logs/summarize-experiment.log的功能简化实验分析过程。","ja":"エージェントがYAMLファイルから実行ステータスを解析し、SLURM stdoutとinspect-ai .evalファイルからメトリクスを抽出し、Markdownフォーマットを使用してsummary.mdファイルを生成することを可能にし、logs/summarize-experiment.logへのロギング機能により実験分析プロセスを効率化します。","ko":"에이전트가 YAML 파일에서 실행 상태를 구문 분석하고, SLURM stdout 및 inspect-ai .eval 파일에서 메트릭을 추출하며, Markdown 형식을 사용하여 summary.md 파일을 생성할 수 있도록 하여, logs/summarize-experiment.log에 로깅하는 기능으로 실험 분석 프로세스를 간소화합니다.","es":"Habilita a los agentes a analizar el estado de ejecución desde archivos YAML, extraer métricas desde SLURM stdout y archivos inspect-ai .eval, y generar archivos summary.md utilizando formato Markdown, simplificando el proceso de análisis de experimentos con capacidades de registro en logs/summarize-experiment.log.","fr":"Permet aux agents d''analyser le statut d''exécution à partir de fichiers YAML, d''extraire des métriques à partir de SLURM stdout et de fichiers inspect-ai .eval, et de générer des fichiers summary.md en utilisant la mise en forme Markdown, simplifiant le processus d''analyse d''expériences avec des capacités de journalisation dans logs/summarize-experiment.log.","de":"Ermöglicht es Agenten, den Ausführungsstatus aus YAML-Dateien zu parsen, Metriken aus SLURM stdout und inspect-ai .eval-Dateien zu extrahieren und summary.md-Dateien mit Markdown-Formatierung zu generieren, wodurch der Experimentanalyseprozess mit Protokollfunktionen in logs/summarize-experiment.log gestreamlined wird.","pt":"Habilita os agentes a analisar o status de execução a partir de arquivos YAML, extrair métricas do stdout do SLURM e arquivos .eval do inspect-ai, e gerar arquivos summary.md usando formatação Markdown, otimizando o processo de análise de experimentos com capacidades de registro em logs/summarize-experiment.log.","ru":"Позволяет агентам анализировать статус запуска из файлов YAML, извлекать метрики из stdout SLURM и файлов .eval inspect-ai, и генерировать файлы summary.md с использованием форматирования Markdown, оптимизируя процесс анализа экспериментов с возможностями ведения журнала в logs/summarize-experiment.log.","ar":"تمكين الوكلاء من تحليل حالة التشغيل من ملفات YAML ، و استخراج المetrics من stdout SLURM وملفات .eval inspect-ai ، وتوليد ملفات summary.md باستخدام تنسيق Markdown ، و تحسين عملية تحليل التجارب مع إمكانيات التسجيل في logs/summarize-experiment.log."},"useCases":{"en":["Automating experiment result summaries","Extracting training loss and accuracy metrics","Generating Markdown reports for experiment directories"],"zh":["自动化实验结果摘要","提取训练损失和准确率指标","为实验目录生成Markdown报告"],"ja":["実験結果の要約の自動化","トレーニング損失と精度メトリクスの抽出","実験ディレクトリのためのMarkdownレポートの生成"],"ko":["실험 결과 요약 자동화","훈련 손실 및 정확도 메트릭 추출","실험 디렉터리를 위한 Markdown 보고서 생성"],"es":["Automatización de resúmenes de resultados de experimentos","Extracción de métricas de pérdida de entrenamiento y precisión","Generación de informes Markdown para directorios de experimentos"],"fr":["Automatisation des synthèses de résultats d''expériences","Extraction de métriques de perte d''entraînement et de précision","Génération de rapports Markdown pour les répertoires d''expériences"],"de":["Automatisierung von Experimentergebniszusammenfassungen","Extraktion von Trainingsverlust- und Genauigkeitsmetriken","Generierung von Markdown-Berichten für Experimentverzeichnisse"],"pt":["Automatizar resumos de resultados de experimentos","Extrair métricas de perda de treinamento e precisão","Gerar relatórios Markdown para diretórios de experimentos"],"ru":["Автоматизировать сводки результатов экспериментов","Извлекать метрики потери обучения и точности","Генерировать отчеты Markdown для директорий экспериментов"],"ar":["أتمتة تلخيص نتائج التجارب","استخراج المetrics لفقدان التدريب ودقة","توليد تقارير Markdown لمسارات التجارب"]},"limitations":{"en":["Requires experiment_summary.yaml and SLURM stdout files","Dependent on inspect-ai .eval files for accuracy extraction","Logging requires access to logs directory"],"zh":["需要experiment_summary.yaml和SLURM stdout文件","依赖inspect-ai .eval文件进行准确率提取","记录日志需要访问logs目录"],"ja":["experiment_summary.yamlとSLURM stdoutファイルが必要","精度抽出にはinspect-ai .evalファイルに依存","ロギングにはlogsディレクトリへのアクセスが必要"],"ko":["experiment_summary.yaml 및 SLURM stdout 파일 필요","정확도 추출을 위해 inspect-ai .eval 파일에 의존","로깅에는 logs 디렉터리에 대한 액세스 필요"],"es":["Requiere archivos experiment_summary.yaml y SLURM stdout","Dependiente de archivos inspect-ai .eval para la extracción de precisión","El registro requiere acceso al directorio logs"],"fr":["Nécessite des fichiers experiment_summary.yaml et SLURM stdout","Dépend des fichiers inspect-ai .eval pour l''extraction de précision","La journalisation nécessite un accès au répertoire logs"],"de":["Benötigt experiment_summary.yaml- und SLURM-stdout-Dateien","Abhängig von inspect-ai .eval-Dateien für die Genauigkeitsextraktion","Das Protokollieren erfordert den Zugriff auf das Protokollverzeichnis"],"pt":["Exige arquivos experiment_summary.yaml e stdout do SLURM","Dependente de arquivos .eval do inspect-ai para extração de precisão","Registro exige acesso ao diretório logs"],"ru":["Требует файлов experiment_summary.yaml и stdout SLURM","Зависит от файлов .eval inspect-ai для извлечения точности","Ведение журнала требует доступа к директории logs"],"ar":["يتطلب ملفات experiment_summary.yaml و stdout SLURM","يعتمد على ملفات .eval inspect-ai لاستخراج الدقة","التسجيل يتطلب الوصول إلى مجلد السجلات"]},"version":4},"contentHash":"e35305f77cbcb8a4e80640bd886b09592e3506dd2c5aed0fbd7703f2fd75681e","qualityScore":60}');
